#!/bin/bash
# Boots RitterOS headless and checks the serial output and the screen.
# Usage: scripts/test.sh "<x86-64 qemu command>" "<aarch64 qemu command>" <disk image>
# (the disk image path appears in both commands and is replaced per test)
#
# TEST_ARCH=x86 or arm runs one half; by default (both) the two halves run
# side by side, each in its own working folder (build/test/x86_64,
# build/test/aarch64) with its own host ports, its output in
# build/test/<arch>.out (to follow a run), printed in order at the end.
#
# For each architecture (x86-64 and AArch64):
# 1. A normal boot (x86-64: the disk image itself, AArch64: a fresh copy).
# 2-8. Boots of fresh disk images: memory test, raw disk writes, damaged
#    metadata, RitterFS writing, crash torture, scrub and repair, the kernel
#    file on RitterFS (updated, missing, damaged).
# 9. One boot per crash test: "crash=<kind>" in \ritteros\cmdline.txt; the
#    kernel must print the right crash report.
# Test names of the AArch64 boots start with "arm-".
set -uo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
QEMU_X86="$1"
QEMU_ARM="$2"
DISK_X86="$3" DISK_ARM="$4"            # (55a: one disk per architecture)
TEST_ARCH="${TEST_ARCH:-both}"
TIMEOUT=60
failures=0
WAITS_RAN_OUT=0                     # waits of a session that ran out (boot)

cd "$ROOT"

# arch_setup x86|arm: the half's architecture: QEMU_CMD (used by boot()),
# P (the prefix of test names: "" or "arm-"), ARCH_NAME, WORK (its images,
# logs, QEMU's monitor socket and serial pipe) and the ports of the test
# servers on the Mac (PORT_BASE + n: the halves run side by side).
# The bootloader on this half's disk (55a: one architecture's per disk).
boot_loader_name() {
    if [ "$ARCH_NAME" = x86_64 ]; then echo BOOTX64; else echo BOOTAA64; fi
}

arch_setup() {
    if [ "$1" = arm ]; then
        QEMU_CMD="$QEMU_ARM" P="arm-" ARCH_NAME=aarch64 PORT_BASE=47630 DISK="$DISK_ARM"
    else
        QEMU_CMD="$QEMU_X86" P="" ARCH_NAME=x86_64 PORT_BASE=47530 DISK="$DISK_X86"
    fi
    WORK="$ROOT/build/test/$ARCH_NAME"
    mkdir -p "$WORK"
    NET_DNS_PORT=$((PORT_BASE + 1))         # scripts/testdns.py
    NET_UDP_PORT=$((PORT_BASE + 2))         # scripts/testnet.py's services
    NET_ECHO_PORT=$((PORT_BASE + 3))
    NET_SEND_PORT=$((PORT_BASE + 4))
    NET_RECV_PORT=$((PORT_BASE + 5))
    NET_CLOSED_PORT=$((PORT_BASE + 6))      # nobody listens there
    NET_FORWARD_PORT=$((PORT_BASE + 7))     # hostfwd to the guest's port 7000
    NET_SLOW_PORT=$((PORT_BASE + 8))
    NET_HTTP_PORT=$((PORT_BASE + 9))        # scripts/testhttp.py
    NET_SSH_PORT=$((PORT_BASE + 11))        # hostfwd to the guest's port 22
    NET_ROUTE_CONTROL=$((PORT_BASE + 12))   # scripts/testroute.py: commands,
    NET_ROUTE_A_HOST=$((PORT_BASE + 13))    # its hosts A and B and the
    NET_ROUTE_A_GUEST=$((PORT_BASE + 14))   # guest's ends of their networks
    NET_ROUTE_B_HOST=$((PORT_BASE + 15))
    NET_ROUTE_B_GUEST=$((PORT_BASE + 16))
    NET_DNSD_PORT=$((PORT_BASE + 17))       # hostfwd (UDP) to the guest's port 53
    NET_TLS_PORT=$((PORT_BASE + 18))        # openssl s_server (TLS): P-256, AES-128
    NET_TLS_RSA_PORT=$((PORT_BASE + 19))    # an RSA certificate, ChaCha20
    NET_TLS_OLD_PORT=$((PORT_BASE + 20))    # an expired certificate, AES-256
    NET_WIFI_GUEST=$((PORT_BASE + 21))      # the ritterwifi card's netdev (dgram)
    NET_WIFI_HOST=$((PORT_BASE + 22))       # scripts/testwifi.py (the test access point)
    NET_ORIGIN_PORT=$((PORT_BASE + 23))     # (27r) a second web origin: the CORS checks
    NET_V6_PORT=$((PORT_BASE + 24))         # (64c) the Mac's IPv6 server on ::1 (tcp6_test)
    NET_V6_HTTP_PORT=$((PORT_BASE + 25))    # (64d) a web server on the Mac's ::1 only
    NET_RATE_PORT=$((PORT_BASE + 26))       # (65e) testnet.py's tcp-send for netrate
    NET_RATE_UP_PORT=$((PORT_BASE + 27))    # (65e) testnet.py's tcp-recv for netrate send
}

# boot NAME IMAGE MARKER: boot IMAGE until MARKER appears on
# the serial port (or QEMU exits, or TIMEOUT), take a screenshot, and set TEXT
# to the serial output without ANSI escape sequences. QEMU_EXTRA: more QEMU
# arguments (e.g. USB sticks). If SERIAL_SCRIPT names
# a function, it runs after the marker (it can type with serial_type) and a
# second screenshot follows ($NAME-terminal.ppm).
#
# The serial port's output goes to $NAME.log; its input comes from a named
# pipe, kept open on file descriptor 7 so that QEMU never sees its end.
boot() {
    NAME="$1"
    local image="$2" marker="$3" started=$(date +%s)
    local log="$WORK/$NAME.log" mon="$WORK/monitor.sock" in="$WORK/serial.in"
    rm -f "$log" "$mon" "$in" "$WORK/gdb.sock" "$WORK/qmp.sock" "$WORK/$NAME.ppm" "$WORK/$NAME-terminal.ppm"
    SERIAL_LOG="$log"
    mkfifo "$in"
    exec 7<>"$in"

    local smp="-smp 2"                              # (65c-2) two cores, unless asked
    [[ "${QEMU_EXTRA:-}" == *-smp* ]] && smp=
    ${QEMU_CMD//$DISK/$image} $smp ${QEMU_EXTRA:-} -display none \
        -chardev "file,id=serial0,path=$log,input-path=$in" -serial chardev:serial0 \
        -monitor "unix:$mon,server,nowait" -qmp "unix:$WORK/qmp.sock,server=on,wait=off" \
        -gdb "unix:$WORK/gdb.sock,server=on,wait=off" \
        2>"$WORK/$NAME.stderr" &
    local pid=$! pages=0 i prompts
    QEMU_PID=$pid
    for ((i = 0; i < TIMEOUT * 4; i++)); do
        grep -qF -- "$marker" "$log" 2>/dev/null && break
        kill -0 $pid 2>/dev/null || break
        # Pager prompts ("-- more") are answered with a simulated space key.
        prompts=$(grep -oF -- "-- more" "$log" 2>/dev/null | wc -l)
        if [ "$prompts" -gt "$pages" ]; then
            echo "sendkey spc" | nc -w 3 -U "$mon" >/dev/null 2>&1
            pages=$((pages + 1))
        fi
        sleep 0.25
    done
    # (65e-37) The root file system's check runs beside the boot: its last
    # line comes after the marker. Waited for, so that every test sees the
    # check's lines and a session never has them in a command's output.
    if grep -qF "RitterFS check: beside the boot" "$log" 2>/dev/null; then
        for ((i = 0; i < TIMEOUT * 4; i++)); do
            grep -qF "RitterFS check: done in" "$log" 2>/dev/null && break
            kill -0 $pid 2>/dev/null || break
            sleep 0.25
        done
    fi
    if kill -0 $pid 2>/dev/null; then
        sleep 0.2      # let the last drawing reach the screen
        echo "screendump $WORK/$NAME.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
        sleep 0.5
        if [ -n "${SERIAL_SCRIPT:-}" ] && grep -qF -- "$marker" "$log"; then
            PROMPT_BASE=0
            WAITS_RAN_OUT=0
            [ "${LOG_IN:-yes}" = no ] || log_in        # (37g-1: no, a session at rescue>)
            $SERIAL_SCRIPT
            sleep 0.2
            echo "screendump $WORK/$NAME-terminal.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
            sleep 0.5
            # What was typed and never left the serial pipe: the machine
            # stopped reading its serial port.
            local waiting
            waiting=$(python3 -c "import fcntl, os, struct, sys, termios
fd = os.open(sys.argv[1], os.O_RDONLY | os.O_NONBLOCK)
print(struct.unpack('i', fcntl.ioctl(fd, termios.FIONREAD, b'0000'))[0])" "$in" 2>/dev/null)
            if [ "${waiting:-0}" -gt 0 ] || [ "$WAITS_RAN_OUT" -gt 0 ]; then
                if [ "${waiting:-0}" -gt 0 ]; then
                    echo "FAIL  $NAME: $waiting typed byte(s) never reached the machine (its serial input stopped)"
                    failures=$((failures + 1))
                else
                    echo "      $NAME: $WAITS_RAN_OUT wait(s) ran out; the machine's state follows"
                fi
                # Where its CPU is (QEMU's GDB stub answers when the monitor
                # does not): kept in $NAME.hang.
                # QEMU's own threads and open files, for when the stub does
                # not answer either: $NAME.sample, $NAME.lsof.
                sample "$pid" 2 -file "$WORK/$NAME.sample" >/dev/null 2>&1
                lsof -p "$pid" >"$WORK/$NAME.lsof" 2>&1
                python3 "$ROOT/scripts/gdbprobe.py" "$WORK/gdb.sock" "$ARCH_NAME" \
                        "$ROOT/build/system/$ARCH_NAME/kernel.elf" >"$WORK/$NAME.hang" 2>&1
                sed 's/^/      /' "$WORK/$NAME.hang"
            fi
        fi
    fi
    kill $pid 2>/dev/null
    # QEMU may hang on its way out (an ARM machine once sat 36 minutes after
    # "terminating on signal 15", its main loop never ending): give it 10 s.
    local stop
    for ((stop = 0; stop < 40; stop++)); do     # (not i: it holds the boot time)
        kill -0 $pid 2>/dev/null || break
        sleep 0.25
    done
    if kill -0 $pid 2>/dev/null; then
        echo "      $NAME: QEMU did not end 10 s after SIGTERM: killed"
        kill -9 $pid 2>/dev/null
    fi
    wait $pid 2>/dev/null
    QEMU_STATUS=$?                  # 0 if the guest switched the machine off
    exec 7>&-
    TEXT="$(perl -pe 's/[^\n]*\r(?=\e\[0K)//g; s/\e\[[0-9;]*[Hf]/\n/g; s/\e\[[0-9;?]*[A-Za-z]//g; s/\r//g' "$log" 2>/dev/null)"
    BOOT_SECONDS=$(awk "BEGIN{print $i/4}")
    local took=$(($(date +%s) - started))
    echo "TIME  $NAME: $took s"
    echo "$took $NAME" >>"$WORK/times.txt"
}

# serial_type TEXT: type TEXT on the serial port (printf escapes: \r Enter,
# \177 Backspace, \003 Ctrl-C, \033 ESC).
serial_type() {
    printf "$1" >&7
}

# The prompts: the shell's "ritteros:/path$ " and the rescue console's
# "rescue> " (a regular expression for grep -E and awk).
PROMPT_RE='ritteros:[^$ ]*\$ |rescue> '

# prompt_count: the prompts on the serial port so far. A prompt shown
# again after a message (44e: the terminal prints ESC [ 0 K before it) is
# the same prompt, not a new one.
prompt_count() {
    local all again
    all=$(grep -oE -- "$PROMPT_RE" "$SERIAL_LOG" | wc -l)
    again=$(grep -oE -- $'\e\\[0K('"$PROMPT_RE)" "$SERIAL_LOG" | wc -l)
    echo $((all - again))
}

# prompt_shown_again LOG TEXT: the line after the first one with TEXT (a
# message that came while the shell waited at its prompt) is the prompt
# shown again (44e), without a key pressed.
prompt_shown_again() {
    local again_line
    again_line=$(grep -A1 -F -- "$2" "$1" | sed -n 2p | tr -d '\r')
    check "the prompt shown again after '$2'" \
          "after '$2' came '$(cat -v <<<"$again_line")', not the prompt again" \
          test "$again_line" = $'\e[0Kritteros:/$ '
}

# expect_link MAC SPEED: the card's link came up at SPEED, on its boot
# line or after it ("eth0: link up, 1000 Mbit/s": the boot does not wait).
expect_link() {
    local link_mac="$1" link_speed="$2" link_card
    link_card=$(grep -F "MAC $link_mac, " <<<"$TEXT" | head -1 | sed -E 's/^ *(eth[0-9]+):.*/\1/')
    check "${link_card:-?} ($link_mac): link up, $link_speed Mbit/s" \
          "${link_card:-?} ($link_mac): no link up at $link_speed Mbit/s" \
          eval 'grep -qF "MAC $link_mac, link up, $link_speed Mbit/s" <<<"$TEXT" ||
                grep -qxF "$link_card: link up, $link_speed Mbit/s" <<<"$TEXT"'
}

# prompt_wait COUNT [SECONDS]: wait (up to 10 s) until COUNT prompts of the
# shell or the rescue console have appeared on the serial port, counted
# after the PROMPT_BASE prompts of the login (log_in).
PROMPT_BASE=0
prompt_wait() {
    local i
    for ((i = 0; i < ${2:-10} * 4; i++)); do
        [ "$(prompt_count)" -ge $(($1 + PROMPT_BASE)) ] && return
        sleep 0.25
    done
    WAITS_RAN_OUT=$((WAITS_RAN_OUT + 1))
}

# log_in [N]: answer login's N-th "login:" prompt (default 1) as root; a
# fresh system first asks for root's password. Root's shell starts in
# /home/root: "cd /" follows, and the sessions count their prompts from
# the one after it (PROMPT_BASE).
ROOT_PASSWORD='root-test-pw'
log_in() {
    local n=${1:-1} i prompts typed=0
    for ((i = 0; i < 160; i++)); do
        [ "$(grep -cE '^login: ([^/]|$)' "$SERIAL_LOG")" -ge "$n" ] && break
        # Typed once: typing again (it once did, for two hours) only hides
        # a machine that stopped reading its serial port.
        if [ $typed -eq 0 ] && grep -q '^New password for root: ' "$SERIAL_LOG" &&
           ! grep -q '^The password for root is set' "$SERIAL_LOG"; then
            typed=1
            serial_type "$ROOT_PASSWORD\r"
            serial_wait "Again: " 1
            serial_type "$ROOT_PASSWORD\r"
            serial_wait "The password for root is set." 1 30
        fi
        sleep 0.25
    done
    # With logd on (LOGD=on), its line comes now, not in a command's output.
    [ "$LOGD" = on ] && serial_wait "elvesd: logd started" "$n" 20
    serial_type 'root\r'
    serial_wait "Password: " "$n"
    # Counted before the password: the shell's first prompt may follow fast.
    PROMPT_BASE=0
    prompts=$(prompt_count)
    serial_type "$ROOT_PASSWORD\r"
    serial_wait "[root logged in]" "$n" 30
    prompt_wait $((prompts + 1)) 30
    serial_type 'cd /\r'
    prompt_wait $((prompts + 2))
    PROMPT_BASE=$((prompts + 1))
}

# login_wait COUNT [SECONDS]: wait until login has asked COUNT times.
login_wait() {
    local i
    for ((i = 0; i < ${2:-10} * 4; i++)); do
        [ "$(grep -cE '^login: ([^/]|$)' "$SERIAL_LOG")" -ge "$1" ] && return
        sleep 0.25
    done
}

# serial_wait TEXT COUNT [SECONDS]: wait (up to 10 s) until TEXT has
# appeared COUNT times on the serial port.
serial_wait() {
    local i
    for ((i = 0; i < ${3:-10} * 4; i++)); do
        [ "$(grep -oF -- "$1" "$SERIAL_LOG" | wc -l)" -ge "$2" ] && return
        sleep 0.25
    done
    WAITS_RAN_OUT=$((WAITS_RAN_OUT + 1))
}

expect() {
    if grep -qF -- "$1" <<<"$TEXT"; then
        echo "PASS  $NAME: $1"
    else
        echo "FAIL  $NAME: $1"
        failures=$((failures + 1))
    fi
}

# expect_line LINE: LINE must appear as a whole line.
expect_line() {
    if grep -qxF -- "$1" <<<"$TEXT"; then
        echo "PASS  $NAME: line '$1'"
    else
        echo "FAIL  $NAME: no line '$1'"
        failures=$((failures + 1))
    fi
}

reject() {
    if grep -qF -- "$1" <<<"$TEXT"; then
        echo "FAIL  $NAME: unexpected '$1'"
        failures=$((failures + 1))
    fi
}

# check PASS_MESSAGE FAIL_MESSAGE COMMAND...: a PASS or FAIL line, depending on
# whether COMMAND succeeds (use eval '...' for compound conditions).
check() {
    local yes="$1" no="$2"
    shift 2
    if "$@"; then
        echo "PASS  $NAME: $yes"
    else
        echo "FAIL  $NAME: $no"
        failures=$((failures + 1))
    fi
}

# check_screen MODE WIDTH HEIGHT [SCREENSHOT]
check_screen() {
    python3 "$ROOT/scripts/check_screen.py" "${4:-$WORK/$NAME.ppm}" "$2" "$3" "$1" |
        sed -E "s/^(PASS|FAIL)  screen/\1  $NAME: screen/"
    [ "${PIPESTATUS[0]}" -eq 0 ] || failures=$((failures + 1))
}

show_log_on_failure() {
    if [ "$failures" -ne "$1" ]; then
        echo "--- serial log of '$NAME' ($WORK/$NAME.log) ---"
        tail -40 <<<"$TEXT"
        echo "--- qemu stderr ---"
        cat "$WORK/$NAME.stderr"
    fi
}

guid() { python3 -c "import sys; sys.path.insert(0, '$ROOT/scripts'); import mkdisk; print(str(mkdisk.$1).upper())"; }
# (37e-1b) A settings file's path and the hash of its default text
# (common/settings_defaults.h through scripts/settingstext.py): NAME is
# CPU, POWER, ... as SETTINGS_NAME there.
settings_path() { python3 "$ROOT/scripts/settingstext.py" --list | awk -v n="$1" '$1 == n {print $2}'; }
settings_hash() { python3 "$ROOT/scripts/settingstext.py" "$1" | shasum -a 256; }

# make_image NAME CMDLINE [SYSTEM_DIR]: a fresh disk image (new RitterFS with
# the initial files and the kernels, or SYSTEM_DIR, in /system) with its own
# command line; prints the image path.
# Test boots run the kernel's self-tests too ("selftest", appended to every
# command line), (65a-5) check the order of its spinlocks ("lockcheck") and
# (65c-2) run on two cores ("cpus=2"; boot() gives QEMU two unless a test
# asks for its own -smp); SELFTEST= (empty) makes an image without these.
SELFTEST="selftest lockcheck cpus=2"
with_selftest() {
    echo "$1${1:+${SELFTEST:+ }}$SELFTEST"
}

# The elf logd is off on test images (45c: its writes would change what
# most tests compare); LOGD=on makes an image where login sets it up as on
# a real system (the logs test), and log_in then waits for it to start.
LOGD=
# (50h) netnamesd likewise: off on test images unless NETNAMESD=on (net up
# then sets it up as on a real system).
NETNAMESD=
make_image() {
    local esp="$WORK/esp-$1" image="$WORK/$1.img" off=1 names_off=1
    rm -rf "$esp" "$image"
    cp -R "$ROOT/build/esp" "$esp"
    with_selftest "$2" > "$esp/ritteros/cmdline.txt"
    [ "$LOGD" = on ] && off=
    [ "$NETNAMESD" = on ] && names_off=
    RITTEROS_TEST_LOGD_OFF=$off RITTEROS_TEST_NETNAMESD_OFF=$names_off \
        python3 "$ROOT/scripts/mkdisk.py" --arch "$ARCH_NAME" ${MKDISK_SIZE:+--size $MKDISK_SIZE} "$image" \
        "$esp" "${3:-$ROOT/build/system}" >/dev/null || exit 1
    echo "$image"
}

# set_cmdline NAME CMDLINE: change the command line of an existing test image;
# its RitterFS is kept.
set_cmdline() {
    with_selftest "$2" > "$WORK/esp-$1/ritteros/cmdline.txt"
    python3 "$ROOT/scripts/mkdisk.py" --arch "$ARCH_NAME" "$WORK/$1.img" "$WORK/esp-$1" \
        "$ROOT/build/system" >/dev/null || exit 1
}

RFS="python3 $ROOT/scripts/ritterfs.py"
RFS_PART="133120 1961984"           # the RitterOS partition: first LBA, sectors

# kernel_file_checks IMAGE [SUFFIX]: the bootloader loaded the kernel from
# RitterFS on IMAGE; the file size and the generation it reports must match
# the host's view of IMAGE. SUFFIX follows "checksums ok" on the Kernel line.
kernel_file_checks() {
    local path="/system/$ARCH_NAME/kernel.elf" size gen slot
    size=$($RFS ls "$1" $RFS_PART "$path" | awk '{ print $1 }')
    read -r gen slot <<<"$($RFS check "$1" $RFS_PART |
                           sed -n 's/^RitterFS check: generation \([0-9]*\) (slot \([AB]\)).*/\1 \2/p')"
    expect_line "RitterFS:  partition #2 of the boot disk, 'RitterOS', generation $gen (slot $slot)"
    expect_line "Kernel:    $path, $size bytes, checksums ok${2:-}"
    expect "kernel file:   $path on RitterFS, $size bytes, file system generation $gen"
}

# --- 1. checks shared by the normal boots ------------------------------------------

# boot_checks IMAGE: the parts of a normal boot's log that are the same on
# every architecture: memory, firmware information, NVMe, GPT, RitterFS (the
# kernel's mount and check must agree with the host's checker on IMAGE).
boot_checks() {
    # The console draws through its copy of the screen in RAM and reports
    # what drawing cost (the screen check below proves the pixels).
    expect "lines scrolled; drawing took "
    expect " screen updates ("
    expect "ms), batched every 20 ms"
    # RitterFS: phase times, and the block cache. The whole tree (over 4,600
    # blocks since 23e's root certificates) no longer fits in the 2048-block
    # cache, so the share of reads it serves falls as the disk grows (below
    # half after 23e: 4,439 of 9,142). What the cache must still do is read
    # each block from the disk about once: at most 1.25 disk reads per used
    # block, and some reads served from it.
    expect "RitterFS time: mount "
    # (65e-37) The check runs beside the boot, on the thread fscheck, and
    # says when it ended (boot() waits for that line).
    expect_line "  RitterFS check: beside the boot (the thread fscheck)"
    expect "  RitterFS check: done in "
    # /test/many (300 entries) is found through a directory index.
    expect_line "                  directory index: 300 lookups answered, 1 index(es) built"
    local fs_used fs_reads fs_hits fs_disk
    fs_used=$(sed -n 's/.*(slot [AB]), [0-9]* blocks of 4 KiB ([0-9]* MiB), \([0-9][0-9]*\) used.*/\1/p' <<<"$TEXT" | head -1)
    read -r fs_reads fs_hits fs_disk <<<"$(sed -n 's/.*RitterFS cache: \([0-9][0-9]*\) block reads, \([0-9][0-9]*\) from the cache ([0-9]*%), \([0-9][0-9]*\) from the disk.*/\1 \2 \3/p' <<<"$TEXT")"
    check "RitterFS cache: $fs_reads reads, $fs_hits from the cache, $fs_disk from the disk ($fs_used used blocks)" \
          "RitterFS cache: '${fs_reads:-?}' reads, '${fs_hits:-?}' cached, '${fs_disk:-?}' from the disk, '${fs_used:-?}' used" \
          eval '[ -n "$fs_disk" ] && [ -n "$fs_hits" ] && [ -n "$fs_used" ] && [ "$fs_hits" -gt 0 ] && [ $((fs_disk * 4)) -le $((fs_used * 5)) ] && [ $((fs_hits + fs_disk)) -eq "$fs_reads" ]'
    # Free memory after the allocator starts: usable RAM minus the first 1 MiB
    # (x86) and the bitmap, so slightly below the usable figure.
    local free_mib usable kernel_fs host_fs
    free_mib=$(sed -n 's/.*memory: *\([0-9]*\) MiB free.*/\1/p' <<<"$TEXT" | head -1)
    check "allocator has $free_mib MiB free (expected 3900-4096)" \
          "allocator has '${free_mib:-?}' MiB free (expected 3900-4096)" \
          test "${free_mib:-0}" -ge 3900 -a "${free_mib:-0}" -le 4096

    # Usable RAM reported by the kernel must be close to the 4 GiB given to the VM.
    usable=$(sed -n 's/.*usable RAM: *\([0-9]*\) MiB.*/\1/p' <<<"$TEXT" | tail -1)
    check "usable RAM $usable MiB (expected 3900-4096)" \
          "usable RAM '${usable:-?}' MiB (expected 3900-4096)" \
          test "${usable:-0}" -ge 3900 -a "${usable:-0}" -le 4096
    expect "self-test passed: 1000 pages allocated, written, verified, freed"
    expect "heap:          self-test passed: 2000 blocks"

    # Firmware information from the bootloader. The partition GUID is
    # ESP_GUID from scripts/mkdisk.py.
    expect "HD(1,GPT,$(guid ESP_GUID),0x800,0x20000)"
    expect "boot partition: #1, GPT, GUID $(guid ESP_GUID), sectors 2048-133119"
    expect "random seed:   32 bytes from the firmware RNG"
    expect "ACPI:          RSDP 0x"
    expect "    FACP  0x"
    expect "    APIC  0x"
    expect "    MCFG  0x"
    reject "bad checksum"
    expect "memory:      1 module, 4096 MiB installed"
    expect "UEFI time:     $(date -u +%Y)-"

    # NVMe driver and GPT: the GUIDs come from scripts/mkdisk.py itself.
    expect "model 'QEMU NVMe Ctrl', serial 'RITTEROS0001'"
    expect "nvme0n1: 2097152 blocks of 512 bytes (1024 MiB)"
    expect "GPT:           nvme0n1: protective MBR, disk GUID $(guid DISK_GUID)"
    expect "header CRC ok, entries 128 x 128 bytes at LBA 2, entries CRC ok, backup at LBA 2097151 ok"
    expect "#1  LBA 2048-133119     64 MiB  'EFI system partition'  type $(guid EFI_SYSTEM_TYPE)"
    expect "partition GUID $(guid ESP_GUID)"
    expect "#2  LBA 133120-2095103    958 MiB  'RitterOS'  type $(guid RITTEROS_TYPE) (RitterOS)"
    expect "partition GUID $(guid DATA_GUID)"
    expect "RitterOS partition: nvme0n1p2, 1961984 blocks"
    expect_line "  system partition: nvme0n1p2, where the bootloader found the kernel"

    # RitterFS: the kernel's mount and check must agree with the host's checker.
    expect "RitterFS:      nvme0n1p2 'RitterOS', UUID $(guid RITTERFS_UUID)"
    expect "all checksums ok (both copies), bitmap consistent"
    reject "problem:"
    expect "/test/data/large.bin                      1048699 bytes, tree height 2"
    expect "/test/data/sparse.bin                     2097152 bytes, tree height 2"
    expect "/test/docs/notes/deep/nested.txt               33 bytes, inline"
    expect "/test/many/  (300 entries)"
    expect "RitterFS files: 309 verified against /test/manifest.txt (3384 KiB): all match"
    expect "partial read across a block boundary: matches"
    expect "lookups of missing paths: correctly not found"
    kernel_fs=$(sed -n 's/.* \(generation [0-9]* (slot [AB])\), \([0-9]*\) blocks of 4 KiB.*, \([0-9]*\) used$/\1, \2 blocks, \3 used/p' <<<"$TEXT")
    host_fs=$(python3 "$ROOT/scripts/ritterfs.py" check "$1" 133120 1961984 |
              sed -n 's/^RitterFS check: \(generation [0-9]* (slot [AB]), [0-9]* blocks, [0-9]* used\).*all checksums ok.*/\1/p')
    check "kernel and host agree on RitterFS: $kernel_fs" \
          "RitterFS kernel '${kernel_fs:-?}' vs host '${host_fs:-?}'" \
          test -n "$kernel_fs" -a "$kernel_fs" = "$host_fs"
    reject "disk test:"

    # The scheduler: two kernel threads that never wait must take turns,
    # every 20 ms (15 turns in 300 ms; fewer if x86 emulation loses ticks).
    expect "  scheduler:     threads 'main' (this code) and 'idle', time slice 20 ms, preemptible kernel"
    local turns
    turns=$(sed -n 's/.*computing in the kernel for 300 ms took \([0-9][0-9]*\) turns.*/\1/p' <<<"$TEXT")
    check "preemption: 2 computing kernel threads took $turns turns in 300 ms (expected 5-20)" \
          "'${turns:-?}' turns in 300 ms (expected 5-20: without preemption 1-2)" \
          test "${turns:-0}" -ge 5 -a "${turns:-0}" -le 20

    # USB: the xHCI controller runs, a No-Op command makes the round trip
    # through the command ring, the doorbell, the event ring and an MSI-X
    # interrupt; on QEMU's first USB 2 port hang two hubs in a chain, the
    # keyboard behind them.
    expect "64 device slots, 8 ports, 16 interrupters, 32-byte contexts, 0 scratchpad pages"
    expect "USB 2.0: ports 5-8"
    expect "USB 3.0: ports 1-4"
    expect "No-Op command: completed, 1 interrupt(s)"
    # Enumeration: port reset, slot, address, then the descriptors as QEMU
    # describes its devices (serials end with the controller's PCI address
    # and the hub ports). QEMU's hubs are USB 1.1 hubs: full speed below them.
    expect_line "  usb0 port 5:   USB 2 device connected, port reset, full speed (12 Mbit/s)"
    expect_line "                 slot 1, address 1, endpoint 0: 8-byte packets"
    expect "                 'QEMU' 'QEMU USB Hub', serial '314159-0000:00:0"
    expect_line "                 interface 0: hub, class 09.00.00, 1 endpoint(s)"
    local hubs
    hubs=$(grep -cx "                 hub: 8 ports, no power switching, power good after 2 ms" <<<"$TEXT")
    check "2 hubs set up: 8 ports each" "$hubs hub(s) set up, expected 2" test "$hubs" = 2
    expect_line "  usb0 port 5.1: device connected (hub port 1), port reset, full speed (12 Mbit/s)"
    expect_line "                 slot 2, address 2, endpoint 0: 8-byte packets"
    expect_line "  usb0 port 5.1.1: device connected (hub port 1), port reset, full speed (12 Mbit/s)"
    expect_line "                 slot 3, address 3, endpoint 0: 8-byte packets"
    expect_line "                 device 0627:0001, USB 2.00, class 00 (see interfaces), version 0.00"
    expect "                 'QEMU' 'QEMU USB Keyboard', serial '68284-0000:00:0"
    expect "-1.1.1'"
    expect_line "                 configuration 1 of 1 'HID Keyboard': 1 interface(s), bus-powered, 100 mA, remote wakeup"
    expect_line "                 interface 0: HID keyboard (boot interface), class 03.01.01, 1 endpoint(s)"
    expect_line "                   endpoint 0x81: interrupt IN, max packet 8 bytes, every 10 ms"
    local usb_commands usb_interrupts
    read -r usb_commands usb_interrupts <<<"$(sed -n 's/.*usb0: *\([0-9][0-9]*\) commands, .* events .*, \([0-9][0-9]*\) interrupts.*/\1 \2/p' <<<"$TEXT")"
    # No-Op; Enable Slot and Address Device for 3 devices; Configure
    # Endpoint for 2 hubs, their status change endpoints and the keyboard's
    # endpoint.
    check "USB: $usb_commands command(s), $usb_interrupts interrupt(s)" \
          "USB: '${usb_commands:-?}' commands, '${usb_interrupts:-?}' interrupts (expected 12 and at least 12)" \
          test "${usb_commands:-0}" = 12 -a "${usb_interrupts:-0}" -ge 12
    reject "failed (completion code"
    # With interrupts, the tick still looks at the event ring (a safety net
    # for lost interrupts) and reports what it found first; any number is
    # fine, the interrupt and the tick may race.
    expect "interrupts, " ; expect " events found by the tick instead"
    expect_line "  kbd0:          USB keyboard on usb0 port 5.1.1, boot protocol, reports from endpoint 0x81, US layout"
    expect_line "  kbd0:          0 reports, 0 key presses"
    # x86 machines also have a PS/2 keyboard on the i8042, found after USB.
    if [ "$ARCH_NAME" = x86_64 ]; then
        expect "  kbd1:          PS/2 keyboard on the i8042 (I/O 0x60/0x64), IRQ 1 -> GSI 1 (IO APIC), vector 0x"
        expect ", scan code set 1, US layout"
        expect_line "  kbd1:          0 scan codes, 0 key presses"
    else
        reject "PS/2"
    fi
    reject "xHCI:          usb0:"

    # Interrupts: during a 500 ms busy wait on an independent clock, the
    # 100 Hz timer interrupt must arrive about 50 times. On x86 QEMU emulates
    # the CPU on the Mac's clock: when macOS does not run QEMU for a while,
    # timer interrupts that fell due meanwhile merge into one, so fewer may
    # arrive on a busy Mac. There, the calibration is checked directly (the
    # APIC timer measured against the PIT must be QEMU's 1 GHz / 16) and the
    # interrupts must arrive, never faster than 100 Hz.
    local counted uptime khz
    counted=$(sed -n 's/.*timer: *100 Hz tick, \([0-9][0-9]*\) ticks during a 500 ms busy wait.*/\1/p' <<<"$TEXT")
    if [ "$ARCH_NAME" = x86_64 ]; then
        khz=$(sed -n 's/.*timer \([0-9][0-9]*\) kHz (bus \/ 16, measured with the PIT).*/\1/p' <<<"$TEXT")
        check "APIC timer measured at $khz kHz (expected 62500 +- 2%)" \
              "APIC timer measured at '${khz:-?}' kHz (expected 61250-63750)" \
              test "${khz:-0}" -ge 61250 -a "${khz:-0}" -le 63750
        check "$counted timer interrupts in 500 ms (expected 1-52; 48-52 unless the Mac is busy)" \
              "'${counted:-?}' timer interrupts in 500 ms (expected 1-52)" \
              test "${counted:-0}" -ge 1 -a "${counted:-0}" -le 52
    else
        check "$counted timer interrupts in 500 ms (expected 48-52)" \
              "'${counted:-?}' timer interrupts in 500 ms (expected 48-52)" \
              test "${counted:-0}" -ge 48 -a "${counted:-0}" -le 52
    fi
    # The NVMe driver sleeps until the controller's interrupt: one per command.
    local nvme commands interrupts timeouts
    nvme=$(sed -n 's/.*nvme0n1: *\([0-9][0-9]*\) commands, \([0-9][0-9]*\) interrupts, \([0-9][0-9]*\) timeouts.*/\1 \2 \3/p' <<<"$TEXT")
    read -r commands interrupts timeouts <<<"$nvme"
    check "NVMe: $commands commands, $interrupts interrupts, ${timeouts} timeouts" \
          "NVMe: '${nvme:-?}' (commands, interrupts, timeouts; expected equal counts and no timeouts)" \
          test "${commands:-0}" -gt 1000 -a "${commands:-0}" = "${interrupts:-x}" -a "${timeouts:-x}" = 0

    uptime=$(sed -n 's/.*uptime: *\([0-9][0-9]*\)\.[0-9]* s since the timer started.*/\1/p' <<<"$TEXT")
    check "uptime ${uptime}+ s at the end of the boot (expected below 30)" \
          "uptime '${uptime:-?}' s at the end of the boot (expected below 30)" \
          test -n "$uptime" -a "${uptime:-99}" -lt 30

    expect "back from the breakpoint handler"
    expect "RitterOS kernel: boot complete"
    reject "RitterOS crash"
    reject "panic"
}

# terminal_session: the commands typed into a normal boot (SERIAL_SCRIPT):
# first into the shell, then, after "exit", into the kernel's rescue
# console; terminal_checks checks the answers. Each command is typed after
# the previous prompt appeared.
SHELL_INPUT=('help\r' 'echo Hello, RitterOS!\r' 'ecno\177\177\177cho edited\r'
             'uptime\r' 'mem\r' 'abc\003' '\033[A\033[Becho arrow\r'
             'ls /\r' 'ls /test\r' 'cat /readme.txt\r' 'cat /test/block.bin\r' 'ls /nope\r'
             'echo "two  spaces" kept\r'
             'cd /test\rabc\003' ''
             'cd /test/docs\r' 'pwd\r' 'ls\r'
             'cat notes/deep/nested.txt\r' 'cd ../..\r' 'cd /nope\r' 'nosuch\r'
             'ps\r' 'threads\r' 'pci\r' 'usb\r' 'drivers\r')
RESCUE_INPUT=('help\r' 'uptime\r' 'mem\r' 'ls /test/data\r' 'pci\r' 'usb\r' 'threads\r'
              'ps\r' 'drivers\r')
# Lines typed on the USB keyboard (QEMU's sendkey key names), one command
# each: Shift and punctuation, Backspace, Ctrl-C, Caps Lock, and a key held
# for a second ("x 1000": repeats after 500 ms).
USB_KEYBOARD_INPUT=('e c h o spc shift-u shift-s shift-b spc k e y b o a r d shift-1 ret'
                    'e c h o spc x y z backspace backspace ret'
                    'q w ctrl-c'
                    'e c h o spc caps_lock a b caps_lock spc c ret'
                    'e c h o spc x_1000 ret')
terminal_session() {
    local n=1 typed key
    prompt_wait $n
    for typed in "${SHELL_INPUT[@]}"; do
        serial_type "$typed"
        n=$((n + 1))
        prompt_wait $n
    done
    for typed in "${USB_KEYBOARD_INPUT[@]}"; do
        for key in $typed; do
            echo "sendkey ${key/_1000/ 1000}" | nc -w 3 -U "$WORK/monitor.sock" >/dev/null 2>&1
            [[ "$key" == *_1000 ]] && sleep 1.2
        done
        n=$((n + 1))
        prompt_wait $n
    done
    # A background job: the shell takes the next command meanwhile and
    # reports the job's end before a later prompt.
    serial_type "/system/$ARCH_NAME/test/counter bg 2 300 &\r"
    n=$((n + 1))
    prompt_wait $n
    serial_wait "counter bg: 2" 1
    sleep 0.5
    for typed in 'echo after the job\r' 'exit\r' "${RESCUE_INPUT[@]}" 'nosuch\r'; do
        serial_type "$typed"                    # 'nosuch' last: the screen check needs it
        if [ "$typed" = 'exit\r' ]; then
            login_wait 2                        # logged out: login asks again;
            serial_type '\004'                  # Ctrl-D ends it, the rescue console follows
        fi
        n=$((n + 1))
        prompt_wait $n
    done
}

# command_output COMMAND [N]: what was printed for COMMAND (the lines
# between its prompt and the next one), for its first (or N-th) occurrence.
command_output() {
    awk -v cmd="$1" -v want="${2:-1}" '
        function after_prompt(line) {
            if (match(line, /^ritteros:[^$ ]*\$ /) || match(line, /^rescue> /))
                return substr(line, RLENGTH + 1)
            return "\001"
        }
        { rest = after_prompt($0) }
        on && rest != "\001" { exit }
        rest == cmd && ++seen == want { on = 1; next }
        on' <<<"$TEXT"
}

# want_text VAR: VAR = standard input without its last line break. For
# expected texts with an apostrophe: macOS's bash 3.2 cannot parse one in
# a here document inside $(...).
want_text() {
    IFS= read -r -d '' "$1"
    printf -v "$1" '%s' "${!1%$'\n'}"
}

# compare NAME WANT GOT: PASS if the two texts are identical.
compare() {
    check "$1: identical ($(wc -l <<<"$3" | tr -d ' ') lines)" \
          "$1 differs: got '$(head -3 <<<"$3" | tr '\n' '|')', expected '$(head -3 <<<"$2" | tr '\n' '|')'" \
          test "$2" = "$3"
}

# terminal_checks ARCH WIDTH HEIGHT IMAGE
terminal_checks() {
    local rfs="python3 $ROOT/scripts/ritterfs.py"
    if [ "$1" = x86_64 ]; then
        expect_line "  input:         serial0, kbd0 and kbd1"
    else
        expect_line "  input:         serial0 and kbd0"
    fi
    expect_line "  login:         /system/$1/bin/login, process 1"
    # A fresh system: root chooses a password, then logs in (log_in).
    expect_line "RitterOS: first start. Choose a password for root, the administrator."
    expect_line "The password for root is set."
    expect_line "[root logged in]"
    reject "$ROOT_PASSWORD"                         # never shown
    # Typed on the USB keyboard.
    expect_line "USB keyboard!"
    expect_line "x"                             # "xyz", 2 x Backspace
    expect_line "ritteros:/$ qw^C"
    expect_line "AB c"                          # Caps Lock on for "ab"
    local repeated
    repeated=$(grep -E "^x{4,}$" <<<"$TEXT" | head -1)
    check "a key held for 1 s repeated: ${#repeated} characters (expected 8-30)" \
          "a key held for 1 s gave '${repeated:-nothing}' (expected 8-30 x)" \
          test "${#repeated}" -ge 8 -a "${#repeated}" -le 30
    # "cd /test", Enter, "abc", Ctrl-C typed in one go (the empty input
    # after it waits for the second prompt): the Ctrl-C arrives while the
    # shell still runs "cd", before it reads again. It must cancel "abc",
    # not get lost (it once did: "abcecho ...").
    expect_line "ritteros:/test$ abc^C"
    # The shell: built-in commands, programs, quotes, current directory.
    expect_line "Built into the shell:"
    expect_line "  cd [DIR]        change the current directory (default: your home)"
    expect_line "Programs (/system/$1/bin and /system/$1/apps):"
    expect_line "  ls [-l] [PATH]..."
    expect_line "                  list directories (default: the current one)"
    expect_line "  ps              list the processes"
    # A usage too long for the column: the description on the next line.
    expect_line "  snapshot [create NAME | delete NAME]"
    expect_line "                  list, take or delete file system snapshots (/.snapshots/NAME)"
    expect_line "  find [DIR] [-name PATTERN] [-attr KEY[=VALUE]]..."
    expect_line "                  search for files by name and attributes"
    # help lists every program on the disk (bin and apps), each with its help text.
    local programs listed_programs
    programs=$(( $($rfs ls "$4" 133120 1961984 "/system/$1/bin" | grep -vc '<dir>') +
                $($rfs ls "$4" 133120 1961984 "/system/$1/apps" | grep -c '<dir>.*\.program/$') ))   # (42b: apps' bundles)
    listed_programs=$(command_output help | sed -n '/^Programs (/,$p' | grep -c '^  [a-z]')
    check "help lists all $programs programs, each with a description" \
          "help lists $listed_programs programs, the disk has $programs" \
          test "$listed_programs" = "$programs"
    reject "(no description)"
    # The kernel's reports, from the shell: the same as in the rescue console.
    expect_line "    1       0      1  running  login"
    expect_line "    2       1      2  running  elvesd"  # (every boot: logd's elf file)
    expect_line "    3       1      3  running  sh"
    check "threads in the shell shows sh's thread" "no thread 'sh' in the shell's threads" \
          eval 'command_output threads | grep -qE "^ +[0-9]+  sh +waiting"'
    compare "pci: shell vs rescue console" "$(command_output pci 2)" "$(command_output pci)"
    compare "usb: shell vs rescue console" "$(command_output usb 2)" "$(command_output usb)"
    # (67a) The kernel's modules: none of their hardware on this machine.
    # Counts from the build: the module files, the exported names,
    # rtl8168's PCI table and its file's size. Proven by a loader that
    # keeps a module whose table matches nothing (the line said "rtl8168 ()
    # loaded; 0 not needed").
    compare "drivers: shell vs rescue console" "$(command_output drivers 2)" "$(command_output drivers)"
    local mods exports mod name usbmods
    mods=$(ls build/system/$1/drivers/*.mod | wc -l | tr -d ' ')
    usbmods=$(grep -l '^USB_MODULE(' drivers/*.c | wc -l | tr -d ' ')     # (67e: always loaded)
    exports=$(grep -c '^    { "' build/gen/exports.c)      # (67b: the driver headers' functions)
    expect_line "modules: usbnet (no device yet) loaded; $((mods - usbmods)) not needed"
    want="$mods module(s) in /system/$1/drivers, $usbmods loaded; the kernel exports $exports names to them"
    for mod in build/system/$1/drivers/*.mod; do       # (name order, as the kernel's)
        name=$(basename "$mod" .mod)
        if grep -q '^USB_MODULE(' drivers/$name.c; then
            want+=$'\n'"  $name.mod (USB)"           # (its line's address and sizes vary: below)
            continue
        fi
        want+=$(printf '\n  %-16s not needed: none of its %d PCI IDs is here (file %d KB)' "$name.mod" \
                "$(grep -oE '\{ 0x[0-9A-Fa-f]+, (0x[0-9A-Fa-f]+|MODULE_ANY) \}|MODULE_CLASS\(' drivers/$name.c | wc -l)" \
                $(( ($(wc -c < "$mod") + 1023) / 1024 )))
    done
    compare "drivers: none of the PCI modules needed here" "$want" \
            "$(command_output drivers | sed -E 's/^  ([a-z0-9]+\.mod) +[a-z0-9]+ at 0x.*USB IDs; took no device yet .*$/  \1 (USB)/')"
    check "drivers: usbnet loaded, waiting for its devices" "$(command_output drivers | grep usbnet)" \
          eval 'command_output drivers | grep -qE "^  usbnet\.mod +usbnet at 0x[0-9a-f]+: code [0-9]+ KB.*; 1 USB IDs; took no device yet \(it is offered every USB device plugged in\)$"'
    expect_line "two  spaces kept"
    expect_line "ritteros:/test/docs$ pwd"
    expect_line "/test/docs"
    expect_line "     <dir>  notes/"
    expect_line "Found me, four directories down."
    expect_line "ritteros:/$ cd /nope"
    expect_line "cd: /nope: No such file or directory"
    expect_line "sh: nosuch: command not found"
    expect "] done, exit code 0"
    expect_line "after the job"
    # exit: the kernel's rescue console takes over.
    expect_line "[root logged out]"
    expect_line "  login:         login ended (exit code 0)"
    expect_line "  rescue console: type 'help' for the commands"
    expect_line "RitterOS rescue console ($1), commands:"
    expect "  uptime    time since the timer started"
    expect_line "Hello, RitterOS!"
    expect_line "edited"                        # "ecno", 3 x Backspace, "cho edited"
    expect "timer ticks at 100 Hz)"
    expect "MiB free of"
    expect_line "ritteros:/$ abc^C"
    expect_line "arrow"                         # Up showed "mem", Down the empty line again (44l)
    expect "unknown command 'nosuch' (type 'help')"
    # The file system as the terminal shows it must match the host's view.
    # ls / also shows the directories the kernel makes up (/boot, /dev,
    # /volumes; not /.snapshots).
    compare "ls / vs host, and the made-up directories" \
            "$($rfs ls "$4" 133120 1961984 /; printf '     <dir>  boot/\n     <dir>  dev/\n     <dir>  volumes/')" \
            "$(command_output "ls /")"
    compare "ls /test vs host" "$($rfs ls "$4" 133120 1961984 /test)" "$(command_output "ls /test")"
    compare "cat /readme.txt vs host" "$($rfs cat "$4" 133120 1961984 /readme.txt)" \
            "$(command_output "cat /readme.txt")"
    compare "rescue: ls /test/data vs host" "$($rfs ls "$4" 133120 1961984 /test/data)" \
            "$(command_output "ls /test/data")"
    expect_line "    2       0      2  running  elvesd"  # the only process left
    expect_line "cat: /test/block.bin: binary file"
    expect_line "cat: exit code 1"
    expect_line "ls: /nope: No such file or directory"
    expect_line "ls: exit code 1"
    local scanned listed
    scanned=$(sed -n 's/.*PCI: .*buses [0-9]*-[0-9]*, \([0-9]*\) devices.*/\1/p' <<<"$TEXT")
    # After the boot only the terminal's thread, the idle thread and the
    # console's screen updater remain: the scheduler self-test's threads
    # have ended and were cleaned up. (37c-2a) acpi: the firmware's events.
    local threads want=7 names="main, idle, idle1, console, usb, elvesd, acpi"
    threads=$(command_output threads 2 | grep -cE '^ +[0-9]+  ')       # the rescue console's
    check "threads: $threads ($names)" \
          "threads lists $threads threads, expected $want (65c-2: two cores)" test "$threads" = $want
    expect "  acpi             waiting"
    expect "   0  main             running"
    expect "   1  idle             "
    expect "  console          waiting"
    expect "  usb              waiting"
    expect_line "3 USB device(s):"
    expect_line "    usb0 port 5      0409:55aa  full speed (12 Mbit/s)   hub, 'QEMU' 'QEMU USB Hub'"
    expect_line "    usb0 port 5.1    0409:55aa  full speed (12 Mbit/s)   hub, 'QEMU' 'QEMU USB Hub'"
    expect_line "    usb0 port 5.1.1  0627:0001  full speed (12 Mbit/s)   HID keyboard (boot interface), 'QEMU' 'QEMU USB Keyboard'"
    listed=$(command_output pci | grep -c "^    [0-9a-f][0-9a-f]:")
    check "pci lists $listed devices, as the boot scan found" \
          "pci lists ${listed:-?} devices, the boot scan found ${scanned:-?}" \
          test -n "$scanned" -a "$listed" = "$scanned"
    check_screen terminal "$2" "$3" "$WORK/$NAME-terminal.ppm"
}

# power_session: reboot, and after the second boot power off (SERIAL_SCRIPT).
power_session() {
    local i
    prompt_wait 1
    serial_type 'reboot\r'
    serial_wait "RitterOS kernel: boot complete" 2 60
    log_in 2                                    # the second boot: root has a password now
    prompt_wait 1
    serial_type 'poweroff\r'
    for ((i = 0; i < 40; i++)); do
        kill -0 "$QEMU_PID" 2>/dev/null || break
        sleep 0.25
    done
}

# quick_boot_test NORMAL_UPTIME: a boot without "selftest" (as on a real PC)
# skips the large self-tests, still checks RitterFS, and gets to the end of
# the boot sooner than the test boot with them.
quick_boot_test() {
    local image uptime_with="$1" uptime
    SELFTEST=
    image=$(make_image ${P}quick "")
    SELFTEST="selftest lockcheck cpus=2"
    before=$failures
    boot ${P}quick "$image" "RitterOS kernel: boot complete"
    expect "Cmdline:   (none)"
    expect_line "  self-tests:    skipped (\"selftest\" on the command line runs them)"
    expect "all checksums ok (both copies), bitmap consistent"
    reject "self-test passed"                       # memory and heap
    reject "2 threads computing in the kernel"      # the scheduler
    reject "testing exceptions"
    reject "RitterFS tree:"
    reject "PROBLEMS FOUND"
    expect "RitterOS kernel: boot complete"
    uptime=$(sed -n 's/^  uptime: *\([0-9][0-9]*\.[0-9][0-9]\) s since the timer started.*/\1/p' <<<"$TEXT")
    check "the boot without self-tests is quicker: ${uptime:-?} s (with them: ${uptime_with:-?} s)" \
          "uptime '${uptime:-?}' s without, '${uptime_with:-?}' s with the self-tests" \
          eval '[ -n "$uptime" ] && [ -n "$uptime_with" ] && awk "BEGIN { exit !($uptime < $uptime_with) }"'
    show_log_on_failure $before
}

# power_test REBOOT_MESSAGE POWEROFF_MESSAGE: the machine restarts and then
# switches itself off: QEMU exits on its own, with status 0.
power_test() {
    local image boots
    image=$(make_image ${P}power "")
    before=$failures
    SERIAL_SCRIPT=power_session
    boot ${P}power "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "$1"
    expect "$2"
    boots=$(grep -c "^RitterOS kernel: boot complete" <<<"$TEXT")
    check "rebooted ($boots boots), then powered off: QEMU exited by itself" \
          "$boots boot(s), QEMU exit status $QEMU_STATUS (expected 2 boots, status 0)" \
          test "$boots" = 2 -a "$QEMU_STATUS" = 0
    show_log_on_failure $before
}

# programs_session: commands typed into the terminal of the programs test.
# Ctrl-D and Ctrl-C are typed once the program waits for them. The programs
# run under a second shell, itself a program (22g): a program's zeroed data
# is made when first touched, so a shell that goes on running grows a page
# when a command first uses a new part of it ("exit code 1"); the inner
# shell's pages go with it, and the leak check stays close (within 8 pages, 65e).
programs_session() {
    local n=1 typed cats=0
    local t="/system/$ARCH_NAME/test"
    prompt_wait $n
    for typed in 'mem' 'sh' 'hello' 'false' "$t/kwrite" "$t/privileged" "$t/syscalls" \
                 "$t/spin" '/nope' '/readme.txt' 'echo Hello,   programs!' \
                 'cat /test/hello.txt /nope /test /test/docs/notes/deep/nested.txt' \
                 "$t/args one two  three" "$t/printf" "$t/files" \
                 'cat' "$t/loop" 'cat' "$t/family" "$t/tree" "$t/orphan" \
                 "$t/fpu" "$t/threads" "$t/threads fds" "$t/threads exit" "$t/threads fault" \
                 "$t/threads spin" \
                 'hello' 'exit 0' 'mem' 'exit' 'ps'; do
        serial_type "$typed\r"
        case "$typed" in
        cat)
            sleep 1
            cats=$((cats + 1))
            if [ $cats = 1 ]; then
                serial_type 'typed into cat\r'     # the first time: a line, then Ctrl-D
                sleep 0.5
                serial_type '\004'
            else
                serial_type '\003'                 # the second time: Ctrl-C while it reads
            fi ;;
        *loop)
            serial_wait "loop: running until Ctrl-C" 1
            sleep 0.5
            serial_type '\003' ;;                  # Ctrl-C while it computes
        *tree)
            serial_wait "tree: parent" 1
            sleep 0.5
            serial_type '\003' ;;                  # Ctrl-C stops parent and child
        *orphan)
            serial_wait "counter orphan: 3" 1 ;;   # the orphan has ended
        exit)
            login_wait 2                           # logged out: Ctrl-D at login's prompt
            serial_type '\004' ;;                  # gives the rescue console
        *"threads spin")
            serial_wait "threads: 3 threads computing forever" 2   # (the exit run printed it too)
            sleep 0.5
            serial_type '\003' ;;                  # Ctrl-C ends all its threads
        esac
        n=$((n + 1))
        prompt_wait $n 30
    done
}

# programs_test KWRITE_FAULT PRIVILEGED_FAULT PRIVILEGED_SIGNAL: programs in user mode, run
# from the terminal. A program that writes into the kernel or uses a
# privileged instruction is stopped with the given report (the CPU's view
# differs per architecture); the kernel checks system call arguments;
# timer interrupts arrive while a program computes; no memory is lost.
programs_test() {
    local image before free_before free_after
    image=$(make_image ${P}programs "")
    before=$failures
    SERIAL_SCRIPT=programs_session
    boot ${P}programs "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect_line "Hello from user mode!"
    # (22l: programs and stacks at random places, so only their ranges)
    check "hello's code is somewhere above 4 GiB" "$(grep -a 'my code is at' <<<"$TEXT" | head -1)" \
          eval 'grep -aqE "^  my code is at  0x0000[0-9A-F]{12}$" <<<"$TEXT" &&
                ! grep -aq "my code is at  0x00000000004" <<<"$TEXT"'
    expect "  my stack is at 0x00007FFF"
    expect_line "false: exit code 1"
    expect_line "kwrite: writing to the kernel at 0xFFFFFFFF80000000"
    expect "kwrite: $1 at pc 0x"
    expect ", address 0xFFFFFFFF80000000: program stopped"
    reject "the write went through"
    expect_line "privileged: reading the kernel's page table register"
    expect "privileged: $2 at pc 0x"
    reject "privileged: it worked"
    expect_line "syscalls: write to stdout returned 3"
    expect_line "syscalls: a message to standard error"
    expect_line "syscalls: write to fd 7 returned -9"
    expect_line "syscalls: write from a kernel address returned -14"
    expect_line "syscalls: write from an unmapped address returned -14"
    expect_line "syscalls: system call 1000 returned -38"
    expect_line "/system/$ARCH_NAME/test/syscalls: exit code 3"
    expect_line "spin: done, sum 4999999950000000"
    expect_line "sh: /nope: No such file or directory"
    expect_line "sh: /readme.txt: Permission denied"        # (52g: 0644, no program)
    # The C library, arguments, files and the terminal as standard input.
    expect_line "Hello, programs!"
    expect_line "Hello from RitterFS!"
    expect_line "cat: /nope: No such file or directory"
    expect_line "cat: /test: Is a directory"
    expect_line "Found me, four directories down."
    expect_line "cat: exit code 1"
    expect_line "args: argc 4"
    expect_line "args: argv[0] '/system/$ARCH_NAME/test/args'"
    expect_line "args: argv[3] 'three'"
    expect_line "args: argv[4] is null"
    expect_line "printf: 42 -7 4294967295 ff FF 10"
    expect_line "printf: -9000000000 18446744073709551615 deadbeefcafe"
    expect_line "printf: [   42] [42   ] [00042] [left    ] [   right] [abc] [   7] [x] [%]"
    expect_line "printf: 0x0000000000400000 (null)"
    expect_line "printf: snprintf wrote 'a long string-1', wanted 19, length 15"
    expect_line "printf: UTF-8 Grüße ☃ split über"
    expect_line "printf: 3.000000 3.142 -2.8 [    1.50] 42 0.000000"
    expect_line "files: open /readme.txt: 3"
    expect_line "files: first 10 bytes 'Welcome to'"
    expect_line "files: next 9 bytes ' RitterFS'"
    expect_line "files: read after close: -1, Bad file descriptor"
    expect_line "files: /test/hello.txt: 21 bytes: Hello from RitterFS!"
    expect_line "files: read at the end: 0"
    expect_line "files: open /nope: -1, No such file or directory"
    expect_line "files: open readme.txt (relative): 3"
    expect_line "files: open in /.snapshots for writing: -1, Read-only file system"
    expect_line "files: read a directory: -1, Is a directory"
    expect_line "files: open with a kernel address: -1, Bad address"
    expect_line "files: opened /readme.txt 253 more times, then: Too many open files"   # (52k: 256 a program)
    check "a line typed into cat came back (typed, then printed by cat)" \
          "'typed into cat' appeared $(grep -c '^typed into cat$' <<<"$TEXT") time(s), expected 2" \
          test "$(grep -c '^typed into cat$' <<<"$TEXT")" = 2
    expect_line "loop: running until Ctrl-C"
    check "Ctrl-C stopped a computing program, one waiting for input, a job of two and a program's threads" \
          "'^C' appeared $(grep -c '^\^C$' <<<"$TEXT") time(s) on a line of its own, expected 4" \
          test "$(grep -c '^\^C$' <<<"$TEXT")" = 4
    # Processes: children side by side, statuses, errors (user/test/family.c).
    expect "family: I am process "
    expect_line "family: started counters A and B"
    expect_line "family: both counters ended (ok)"
    local line_of
    line_of() { grep -nx -- "$1" <<<"$TEXT" | head -1 | cut -d: -f1; }
    check "counters A and B ran side by side (their lines interleave)" \
          "counter lines do not interleave" \
          eval '[ "$(line_of "counter B: 1")" -lt "$(line_of "counter A: 4")" ] &&
                [ "$(line_of "counter A: 1")" -lt "$(line_of "counter B: 4")" ]'
    expect_line "counter C: 2"
    expect_line "family: counter C exited with code 0"
    expect_line "family: kill loop: 0"
    expect_line "family: loop was stopped by signal 9"
    expect_line "family: false exited with code 1"
    expect_line "family: kwrite was stopped by signal 11"
    expect_line "family: privileged was stopped by signal $3"
    expect_line "family: spawn /nope: -1, No such file or directory"
    expect_line "family: spawn /readme.txt: -1, Permission denied"
    expect_line "family: wait without children: -1, No child processes"
    expect_line "family: kill 9999: -1, No such process"
    # A job of two processes stopped by Ctrl-C; an orphan that goes on and
    # is cleaned up; no process left.
    expect "tree: parent "
    expect "orphan: started child "
    expect "counter orphan: 3"
    check "no process left but elvesd" "$(command_output ps | tr '\n' '|')" \
          eval '[ "$(command_output ps | grep -c "  running  ")" = 1 ] &&
                command_output ps | grep -q "  running  elvesd$"'
    # Floating point in three programs at once: every result bit-exact
    # (without saving FP/SIMD registers per program, all three are wrong).
    expect_line "fpu: pi = 3.141592654 (Nilakantha series)"
    expect_line "fpu: worker 1: correct"
    expect_line "fpu: worker 2: correct"
    expect_line "fpu: worker 3: correct"
    expect_line "fpu: 3 workers computed at the same time: 3 correct"
    # Threads of one program: parallel FP work bit-identical to the same
    # work alone, an atomic counter, all 16 numbers, joining; exit() from
    # main, a fault in a thread and Ctrl-C each end all threads.
    expect_line "threads: 4 workers (numbers 1 2 3 4), results returned, 4 of 4 sums identical, counter 400000 of 400000"
    expect_line "threads: 255 started at once, the next one refused (EAGAIN), all joined; joining again: no such thread"
    expect_line "/system/$ARCH_NAME/test/threads: exit code 7"
    check "a thread's fault at address 0 stopped the program" "no fault report from the threads program" \
          eval 'grep -qE "^threads: .* address 0x0000000000000000: program stopped$" <<<"$TEXT"'
    # The shared descriptor table (49b): concurrent open/socket/close by the
    # threads of one program never cross their slots, and a socket closed
    # while another thread blocks in recvfrom survives (held across the call).
    expect_line "threads: fds: $((4 * 40)) opens and sockets across 4 threads, 0 slot mismatches, 0 socket errors"
    expect_line "threads: fds: close of a socket under a blocked recvfrom: closed, recv survived (timed out)"
    reject "WRONG"
    check "the second hello ran too" "hello ran $(grep -c '^Hello from user mode!$' <<<"$TEXT") time(s), expected 2" \
          test "$(grep -c '^Hello from user mode!$' <<<"$TEXT")" = 2
    # Every page a program had (tables, code, data, stack, kernel stack) is
    # free again: the same count before and after the programs (and the
    # shell they ran under).
    # (65e) Both looks at a prompt: until 65e the inner shell ended after its
    # first command (it could not take the terminal back), the second mem
    # went to login's prompt and the check compared the first with itself.
    compare "the leak check's two looks, the second after the inner shell's exit 0" 2 \
            "$(grep -cE '^ritteros:[^$ ]*\$ mem$' <<<"$TEXT")"
    free_before=$(command_output mem | sed -n 's/.*(\([0-9]*\) of [0-9]* pages.*/\1/p' | head -1)
    free_after=$(grep -A1 -E '^ritteros:[^$ ]*\$ mem$' <<<"$TEXT" | sed -n 's/.*(\([0-9]*\) of [0-9]* pages.*/\1/p' | tail -1)
    # (65e) Within 8 pages: blocks that live across the programs lie in
    # other slabs (and, on two cores, other cores' caches) each time; three
    # runs in a row gave -2, 0, -1 pages on one core and -3, +2, -4 on two:
    # no steady loss. A page lost per program (30 of them) still fails.
    check "no memory lost: $free_after pages free after the programs, $free_before before (8 allowed)" \
          "free pages before '${free_before:-?}', after '${free_after:-?}'" \
          test -n "$free_before" -a -n "$free_after" -a "$((${free_after:-0} + 8))" -ge "${free_before:-1}"
    reject "RitterOS crash"
    reject "panic"
    show_log_on_failure $before
}

# --- 2-7. tests on fresh disk images ------------------------------------------------

# fswrite_host_check IMAGE KERNEL_CRC: the host reads /work as the kernel's
# write test (kernel/fstest.c) left it and checks it independently.
fswrite_host_check() {
    local host crc="$2"
    host=$(python3 - "$1" <<'PY'
import struct, sys
sys.path.insert(0, "scripts")
import ritterfs
with open(sys.argv[1], "r+b") as f:
    part = ritterfs.Partition(f, 133120, 1961984)
    ok, summary = ritterfs.check(part)
    reader = ritterfs.Reader(part)
    big = reader.content(reader.lookup("/work/big.bin")[1])
    hello = reader.content(reader.lookup("/work/hello.txt")[1])
# The same pattern as kernel/fstest.c: xorshift64 from the seed "RITTERFS".
s, out, mask = 0x5249545445524653, bytearray(), (1 << 64) - 1
for _ in range(600 * 1024 // 8):
    s ^= (s << 13) & mask; s ^= s >> 7; s ^= (s << 17) & mask
    out += struct.pack("<Q", s)
out[150000:150100] = b"X" * 100
want_hello = bytes(ord("a") + i % 26 for i in range(199)) + b"\n"
print("ok" if ok else "BAD", "%08X" % ritterfs.crc32c(big), big == bytes(out),
      hello == want_hello, summary.split(";")[0])
PY
)
    check "host check ok, big.bin and hello.txt as expected (crc32c $crc)" \
          "host says '$host' (kernel crc32c '$crc')" \
          eval '[[ "$host" == "ok $crc True True generation 6 (slot A)"* ]]'
}

# damage IMAGE [data]: flip a byte in six metadata copies of different kinds
# and, with "data", in one block of file data (stored once). Prints the disk
# block of the damaged data and its object ID.
damage() {
    python3 - "$1" "${2:-}" <<'PY'
import sys
sys.path.insert(0, "scripts")
import ritterfs as r
with open(sys.argv[1], "r+b") as f:
    part = r.Partition(f, 133120, 1961984)
    reader = r.Reader(part)

    def child(ptr, i):                  # pointer i of an indirect block
        return r.Pointer.unpack(part.read(ptr.address)[i * 32:(i + 1) * 32])

    def flip(block):
        data = bytearray(part.read(block))
        data[123] ^= 0xFF
        part.write(block, bytes(data))

    table = reader.sb.table.root                      # height 1: an indirect block
    bitmap = reader.inodes[r.OBJ_BITMAP].root         # height 1
    large = reader.lookup("/test/data/large.bin")[1].root     # height 2
    many_id, many = reader.lookup("/test/many")       # two blocks, height 1
    medium_id, medium = reader.lookup("/test/data/medium.bin")
    targets = [child(table, 0).address2,              # object table data block, copy 2
               child(bitmap, 0).address,              # bitmap block, copy 1
               large.address,                         # file's top indirect block, copy 1
               child(large, 0).address2,              # file's next indirect block, copy 2
               child(many.root, 1).address2,          # directory block, copy 2
               table.address]                         # object table indirect block, copy 1
    if sys.argv[2] == "data":
        targets.append(child(medium.root, 5).address) # file data, the only copy
    for b in targets:
        flip(b)
    print(child(medium.root, 5).address, medium_id)
PY
}

# host_errors IMAGE: the host checker's errors, one per line
host_errors() {
    python3 - "$1" <<'PY'
import sys
sys.path.insert(0, "scripts")
import ritterfs as r
with open(sys.argv[1], "rb") as f:
    part = r.Partition(f, 133120, 1961984)
    sb, _ = r.mount(part)
    checker = r.Checker(part, sb)
    try:
        checker.run()
    except r.CheckError as e:
        checker.errors.append(str(e))
    print(f"generation {sb.generation}")
    print("\n".join(checker.errors))
PY
}

# login_session: root adds anna; anna logs in (login_shell_test).
login_session() {
    local n=1 typed
    prompt_wait $n
    serial_type 'useradd anna\r'
    n=$((n + 1)); prompt_wait $n
    serial_type 'passwd anna\r'
    serial_wait "New password: " 1
    serial_type 'anna-pw-1\r'
    serial_wait "Again: " 1
    serial_type 'anna-pw-1\r'
    n=$((n + 1)); prompt_wait $n 30
    serial_type 'exit\r'                        # root logs out
    login_wait 2
    serial_type 'anna\r'
    serial_wait "Password: " 2
    serial_type 'wrong-pw\r'
    login_wait 3 30
    serial_type 'nobody\r'
    serial_wait "Password: " 3
    serial_type 'anna-pw-1\r'
    login_wait 4 30
    serial_type 'anna\r'
    serial_wait "Password: " 4
    serial_type 'anna-pw-1\r'
    serial_wait "[anna logged in]" 1 30
    n=$((n + 1)); prompt_wait $n 30
    for typed in 'id' 'pwd' 'touch /system/x' 'touch here.txt' 'ls -l' 'cd /' 'cd' 'pwd' \
                 'snapshot create mine' 'poweroff' 'ls /home/root' 'exit'; do
        serial_type "$typed\r"
        if [ "$typed" = exit ]; then
            login_wait 5
            serial_type '\004'                  # Ctrl-D: the rescue console
        fi
        n=$((n + 1))
        prompt_wait $n 30
    done
}

# login_shell_test: logging in as a user, wrong passwords, logging out.
login_shell_test() {
    local image before
    image=$(make_image ${P}loginshell "")
    before=$failures
    SERIAL_SCRIPT=login_session
    boot ${P}loginshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect_line "passwd: password for anna set"
    expect_line "[root logged out]"
    check "a wrong password and an unknown user: Login incorrect (twice)" \
          "'Login incorrect.' $(grep -c '^Login incorrect.$' <<<"$TEXT") time(s)" \
          test "$(grep -c '^Login incorrect.$' <<<"$TEXT")" = 2
    expect_line "[anna logged in]"
    compare "id as anna" "uid=1000(anna) gid=1000" "$(command_output 'id')"
    compare "anna's shell starts at home" "/home/anna" "$(command_output 'pwd')"
    expect_line "touch: /system/x: Permission denied"
    compare "her new file is hers" \
            "$(printf 'drwx------   1  1000  1000      <dir>  .config/\n-rw-r--r--   1  1000  1000          0  here.txt')" \
            "$(command_output 'ls -l')"
    compare "cd alone: home" "/home/anna" "$(command_output 'pwd' 2)"
    expect_line "snapshot: mine: Operation not permitted"
    expect_line "poweroff: the machine could not be switched off: Operation not permitted"
    expect_line "ls: /home/root: Permission denied"
    expect_line "[anna logged out]"
    expect_line "  login:         login ended (exit code 0)"
    reject "anna-pw-1"                              # passwords are never shown
    reject "wrong-pw"
    reject "$ROOT_PASSWORD"
    reject "panic"
    show_log_on_failure $before
}

# term_session: the term test program (term_shell_test): raw input from
# the serial port and the USB keyboard, lines again, then two screenshots
# of the escape sequences; afterwards the shell must look normal again.
term_session() {
    local mon="$WORK/monitor.sock"
    prompt_wait 1
    serial_type "/system/$ARCH_NAME/test/term\r"
    serial_wait "term: raw 0" 1
    sleep 0.3
    serial_type 'a'
    sleep 0.3
    echo "sendkey up" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    serial_type '\003\004q'                        # Ctrl-C and Ctrl-D as bytes, then q
    serial_wait "term: lines again" 1
    sleep 0.3
    serial_type 'xyz\r'
    serial_wait "term: drawn" 1
    sleep 0.5
    echo "screendump $WORK/$NAME-drawn.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    serial_type ' '
    serial_wait "term: hidden" 1
    sleep 0.5
    echo "screendump $WORK/$NAME-hidden.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    serial_type ' '
    prompt_wait 2
    serial_type 'echo after\r'
    prompt_wait 3
    sleep 0.5
    echo "screendump $WORK/$NAME-after.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    # clear: an empty screen, the prompt at the top.
    serial_type 'ls /\r'
    prompt_wait 4
    serial_type 'clear\r'
    prompt_wait 5
    serial_type 'echo again\r'
    prompt_wait 6
}

# term_shell_test: the terminal for full-screen programs (SYS_TERMINAL and
# the console's escape sequences).
term_shell_test() {
    local image before width height
    if [ "$ARCH_NAME" = x86_64 ]; then width=1280 height=800; else width=800 height=600; fi
    image=$(make_image ${P}termshell "")
    before=$failures
    SERIAL_SCRIPT=term_session
    boot ${P}termshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect_line "term: size $(( (height - 48 - 16 - 4) / 15 )) rows, $(( (width - 24) / 9 )) columns"
    # Raw: the bytes as typed (the USB keyboard's up arrow is ESC [ A),
    # nothing echoed in between.
    compare "raw input, not echoed" "$(printf 'term: raw 0\nterm: read 61 1b 5b 41 03 04 71')" \
            "$(grep -A1 '^term: raw' <<<"$TEXT")"
    compare "lines again: echoed and edited" "$(printf 'xyz\nterm: line '"'"'xyz'"'"'')" \
            "$(grep -A1 '^term: lines again' <<<"$TEXT" | tail -1; grep "^term: line '" <<<"$TEXT")"
    check_screen term-drawn $width $height "$WORK/$NAME-drawn.ppm"
    check_screen term-hidden $width $height "$WORK/$NAME-hidden.ppm"
    check_screen term-after $width $height "$WORK/$NAME-after.ppm"
    check_screen term-cleared $width $height "$WORK/$NAME-terminal.ppm"
    reject "panic"
    show_log_on_failure $before
}

# typing_session: characters beyond ASCII and Ctrl-L (typing_shell_test).
typing_session() {
    local mon="$WORK/monitor.sock" n=1 key
    prompt_wait $n
    for typed in 'echo Gr\xc3\xbc\xc3\x9fe \xe2\x80\x93 \xe2\x9c\x93 \xe2\x82\xac' 'echo a\xc3\xa9\x7f\x7fb' \
                 'echo hi > /home/root/Gr\xc3\xbc\xc3\x9fe.txt' 'ls /home/root' "ls /system/$ARCH_NAME/bin"; do
        serial_type "$typed\r"
        n=$((n + 1))
        prompt_wait $n
    done
    # A line in UTF-8, then Ctrl-L: the screen again with only it.
    serial_type 'echo Gr\xc3\xbc\xc3\x9fe \xe2\x80\x93 \xe2\x9c\x93 \xe2\x82\xac'
    sleep 0.5
    serial_type '\014'
    sleep 1
    echo "screendump $WORK/$NAME-ctrll.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    serial_type '\r'
    n=$((n + 1))
    prompt_wait $n
    # The USB keyboard, US International: dead keys, then AltGr.
    for key in e c h o spc apostrophe e shift-apostrophe u shift-grave_accent n shift-6 o \
               grave_accent a apostrophe c spc shift-6 spc x spc shift-6 b ret; do
        echo "sendkey $key" | nc -w 3 -U "$mon" >/dev/null 2>&1
    done
    n=$((n + 1))
    prompt_wait $n
    for key in e c h o spc alt_r-n alt_r-slash alt_r-5 alt_r-s shift-alt_r-n alt_r-1 ret; do
        echo "sendkey $key" | nc -w 3 -U "$mon" >/dev/null 2>&1
    done
    n=$((n + 1))
    prompt_wait $n
}

# typing_shell_test: text beyond ASCII. UTF-8 typed on the serial port
# (echoed whole, a two-byte character erased whole by Backspace, a file
# name); Ctrl-L (a screenshot: the line again at the top of an empty
# screen, its glyphs drawn); the USB keyboard as US International: dead
# keys (' e -> é, " u -> ü, ~ n -> ñ, ^ o -> ô, ` a -> à, ' c -> ç, ^ and
# a space -> ^, ^ and b -> ^b) and AltGr (ñ ¿ € ß Ñ ¡).
typing_shell_test() {
    local image before width height
    if [ "$ARCH_NAME" = x86_64 ]; then width=1280 height=800; else width=800 height=600; fi
    image=$(make_image ${P}typing "")
    before=$failures
    SERIAL_SCRIPT=typing_session
    boot ${P}typing "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    compare "UTF-8 typed: echoed and printed" "Grüße – ✓ €" \
            "$(command_output 'echo Grüße – ✓ €')"
    expect_line "b"                                 # a, é, two Backspaces, b
    compare "a file name in UTF-8 (beside ~/.config, 15l)" \
            "$(printf '     <dir>  .config/\n         3  Grüße.txt')" "$(command_output 'ls /home/root')"
    check_screen term-ctrl-l $width $height "$WORK/$NAME-ctrll.ppm"
    compare "Ctrl-L: the line runs afterwards" "Grüße – ✓ €" \
            "$(command_output 'echo Grüße – ✓ €' 3)"
    compare "dead keys" "éüñôàç ^x ^b" "$(command_output 'echo éüñôàç ^x ^b')"
    compare "AltGr" "ñ¿€ßÑ¡" "$(command_output 'echo ñ¿€ßÑ¡')"
    reject "panic"
    show_log_on_failure $before
}

# edit_session: the editor (edit_shell_test). Keys as a terminal sends
# them: ESC [ B down, ESC [ F End, ESC [ 3 ~ Delete, \023 Ctrl-S, \021
# Ctrl-Q; some from the USB keyboard (sendkey).
edit_session() {
    local mon="$WORK/monitor.sock" n=1
    prompt_wait $n
    for typed in 'edit /test' 'edit'; do
        serial_type "$typed\r"
        n=$((n + 1))
        prompt_wait $n
    done
    # A new file: two lines, saved, a screenshot, quit.
    serial_type 'edit /notes.txt\r'
    serial_wait "New file." 1
    serial_type 'Hello\rworld'
    sleep 0.3
    serial_type '\023'
    serial_wait "Saved: 2 lines, 12 bytes." 1
    sleep 0.5
    echo "screendump $WORK/$NAME-edit.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    serial_type '\021'
    n=$((n + 1))
    prompt_wait $n
    serial_type 'cat /notes.txt\r'
    n=$((n + 1))
    prompt_wait $n
    # Changing it: Delete, End, arrows, Backspace, Enter; Ctrl-S and some
    # moves from the USB keyboard.
    serial_type 'edit /notes.txt\r'
    serial_wait "2 lines, 12 bytes." 2
    serial_type '\033[3~J'                          # "Hello" -> "Jello"
    sleep 0.3
    echo "sendkey down" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.3
    echo "sendkey end" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.3
    serial_type '!\rthirx\177d\033[D\033[D_'       # "world!", "thi_rd"
    sleep 0.3
    echo "sendkey ctrl-s" | nc -w 3 -U "$mon" >/dev/null 2>&1
    serial_wait "Saved: 3 lines, 20 bytes." 1
    serial_type '\021'
    n=$((n + 1))
    prompt_wait $n
    serial_type 'cat /notes.txt\r'
    n=$((n + 1))
    prompt_wait $n
    # Unsaved changes: the first Ctrl-Q asks, the second quits.
    serial_type 'edit /notes.txt\r'
    serial_wait "3 lines, 20 bytes." 2
    serial_type 'zzz\021'
    serial_wait "Unsaved changes: Ctrl-Q again quits without saving" 1
    serial_type '\021'
    n=$((n + 1))
    prompt_wait $n
    serial_type 'cat /notes.txt\r'
    n=$((n + 1))
    prompt_wait $n
    # Saving fails: the message says why.
    serial_type 'edit /nope/x.txt\r'
    serial_wait "New file." 2
    serial_type 'x\023'
    serial_wait "Not saved: No such file or directory." 1
    serial_type '\021\021'
    n=$((n + 1))
    prompt_wait $n
    # A long file: two pages down, then End.
    serial_type 'edit /test/text/lorem.txt\r'
    serial_wait "100 lines, 6200 bytes." 1
    serial_type '\033[6~'
    sleep 0.3
    serial_type '\033[6~'
    sleep 0.3
    serial_type '\033[F'
    sleep 0.5
    serial_type '\021'
    n=$((n + 1))
    prompt_wait $n
    # (50i) A file with CR LF line breaks: no CR shown, kept when saved.
    serial_type 'edit /crlf.txt\r'
    serial_wait "2 lines, 14 bytes, CR LF line breaks." 1
    serial_type '\033[B\033[F\1772'               # "key = 1" -> "key = 2"
    sleep 0.3
    serial_type '\023'
    serial_wait "Saved: 2 lines, 14 bytes, CR LF line breaks." 1
    serial_type '\021'
    n=$((n + 1))
    prompt_wait $n
}

# edit_shell_test: the text editor edit.
edit_shell_test() {
    local image before width height page host
    if [ "$ARCH_NAME" = x86_64 ]; then width=1280 height=800; else width=800 height=600; fi
    page=$(( (height - 48 - 16 - 4) / 15 - 2 ))     # text rows: the screen minus the two bars
    image=$(make_image ${P}editshell "")
    printf '# a\r\nkey = 1\r\n' >"$WORK/${P}crlf.txt"
    $RFS put "$image" $RFS_PART /crlf.txt "$WORK/${P}crlf.txt" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=edit_session
    boot ${P}editshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect_line "edit: /test: Is a directory"
    expect_line "usage: edit FILE"
    compare "a new file, typed and saved" "$(printf 'Hello\nworld')" "$(command_output 'cat /notes.txt')"
    check_screen edit $width $height "$WORK/$NAME-edit.ppm"
    compare "changed: Delete, End, Enter, Backspace, arrows (serial and USB keyboard)" \
            "$(printf 'Jello\nworld!\nthi_rd')" "$(command_output 'cat /notes.txt' 2)"
    compare "quit without saving: unchanged" "$(printf 'Jello\nworld!\nthi_rd')" \
            "$(command_output 'cat /notes.txt' 3)"
    expect "line $((1 + 2 * page))/101, column 62 "
    host=$($RFS cat "$image" $RFS_PART /notes.txt | od -c | head -3)
    compare "the host reads the file, ending in a line break" \
            "$(printf 'Jello\nworld!\nthi_rd\n' | od -c | head -3)" "$host"
    # (50i) the CR LF file: the bar says so, no ? for the CRs, saved as CR LF
    expect " edit: /crlf.txt  CRLF"
    reject "key = 1?"
    reject "# a?"
    compare "a CR LF file is saved with CR LF" "$(printf '# a\r\nkey = 2\r\n' | od -c)" \
            "$($RFS cat "$image" $RFS_PART /crlf.txt | od -c)"
    reject "panic"
    show_log_on_failure $before
}

# make_fat_stick FILE: a 64 MiB stick with an MBR and one FAT32 partition
# from 1 MiB on (mkdisk's FAT32 code, the label changed to STICK).
make_fat_stick() {
    rm -rf "$WORK/emptydir"
    mkdir -p "$WORK/emptydir"
    python3 -c "
import struct, sys
sys.path.insert(0, '$ROOT/scripts')
import mkdisk
first, count = 2048, 64 * 2048 - 2048
fs = bytearray(mkdisk.make_fat32('$WORK/emptydir', count, first)[0])
fs[71:82] = b'STICK      '
mbr = bytearray(512)
mbr[446:462] = struct.pack('<B3sB3sII', 0, b'\x00\x02\x00', 0x0C, b'\xff\xff\xff', first, count)
mbr[510:512] = b'\x55\xaa'
with open('$1', 'wb') as f:
    f.write(mbr); f.seek(first * 512); f.write(fs)
" || exit 1
}

# make_blank FILE: a 16 MiB stick of zeros.
make_blank() {
    rm -f "$1"
    python3 -c "open('$1', 'wb').truncate(16 * 1024 * 1024)" || exit 1
}

# disks_session: devices and the program disks (disks_shell_test); a
# blank stick plugged in behind the first hub and unplugged again.
disks_session() {
    local mon="$WORK/monitor.sock" n=1 typed
    local -a typed_lines=('disks' 'ls -l /dev' 'cd /dev' 'ls' 'cd /' 'ls /dev/nope' 'mkdir /dev/x'
                          'rm /dev/usbdisk0' "/system/$ARCH_NAME/test/devread nvme0n1p1 0 512"
                          "/system/$ARCH_NAME/test/devread usbdisk1 1048576 4096"
                          "/system/$ARCH_NAME/test/devread usbdisk0p2 4096 4096"
                          "/system/$ARCH_NAME/test/devread nope 0 1" 'ls /dev')
    prompt_wait $n
    for typed in "${typed_lines[@]}"; do
        serial_type "$typed\r"
        n=$((n + 1))
        prompt_wait $n 30
    done
    echo "drive_add 0 if=none,id=hotblank,file=$WORK/${P}hotblank.img,format=raw" | nc -w 3 -U "$mon" >/dev/null 2>&1
    echo "device_add usb-storage,bus=xhci.0,port=1.2,drive=hotblank,id=hotblank,serial=HOTBLANK" |
        nc -w 3 -U "$mon" >/dev/null 2>&1
    serial_wait "usbdisk3:      no partition table: empty" 1 20
    # The kernel's messages came after the prompt: Enter gives a new one,
    # so that the command starts a line (command_output).
    serial_type '\r'
    n=$((n + 1))
    prompt_wait $n
    serial_type 'disks\r'
    n=$((n + 1))
    prompt_wait $n
    echo "device_del hotblank" | nc -w 3 -U "$mon" >/dev/null 2>&1
    serial_wait "usbdisk3:      removed" 1 20
    serial_type '\r'
    n=$((n + 1))
    prompt_wait $n
    serial_type 'ls /dev\r'
    n=$((n + 1))
    prompt_wait $n
}

# disks_shell_test: /dev and disks with three more USB sticks: a RitterOS
# image (GPT), an MBR stick with FAT32, a blank one; the host computes
# what disks must print and the raw bytes devread must find.
disks_shell_test() {
    local image rstick fatstick blank before expected model="QEMU QEMU HARDDISK" i dev offset length file at
    image=$(make_image ${P}disksshell "")
    rstick=$(make_image ${P}rstick "")
    fatstick="$WORK/${P}fatstick.img" blank="$WORK/${P}blank.img"
    rm -rf "$WORK/emptydir"
    mkdir -p "$WORK/emptydir"
    make_fat_stick "$fatstick"
    make_blank "$blank"
    make_blank "$WORK/${P}hotblank.img"
    QEMU_EXTRA="-drive if=none,id=rstick,format=raw,file=$rstick
                -device usb-storage,bus=xhci.0,port=2,drive=rstick,serial=RSTICK
                -drive if=none,id=fatstick,format=raw,file=$fatstick
                -device usb-storage,bus=xhci.0,port=3,drive=fatstick,serial=FATSTICK
                -drive if=none,id=blank,format=raw,file=$blank
                -device usb-storage,bus=xhci.0,port=4,drive=blank,serial=BLANK"
    before=$failures
    SERIAL_SCRIPT=disks_session
    boot ${P}disksshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect_line "  usbdisk1p1:    MBR #1, 63 MiB, type 0x0C (FAT32 (LBA)): FAT32 'STICK'"
    expect_line "  usbdisk2:      no partition table: empty"
    expected=$(python3 "$ROOT/scripts/expect_disks.py" "nvme0n1,NVMe,QEMU NVMe Ctrl,$image,system" \
               "usbdisk0,USB,$model,$rstick,mounted=/volumes/RitterOS" "usbdisk1,USB,$model,$fatstick,p1=/volumes/STICK" \
               "usbdisk2,USB,$model,$blank")
    compare "disks: GPT, MBR, no table; RitterFS, FAT32, empty (as the host reads the images)" \
            "$expected" "$(command_output 'disks')"
    compare "ls -l /dev: every disk and partition, then null, zero, tty (52l)" \
            "$(awk '{print $1}' <<<"$expected"; printf '%s\n' null zero tty)" \
            "$(command_output 'ls -l /dev' | awk '{print $NF}')"
    check "ls -l /dev: block devices, mode 600, owner root; the others c, 666" \
          "$(command_output 'ls -l /dev' | grep -cv '^brw-------   1     0     0 \|^crw-rw-rw-   1     0     0          0  ') other line(s)" \
          test "$(command_output 'ls -l /dev' | grep -cv '^brw-------   1     0     0 \|^crw-rw-rw-   1     0     0          0  ')" = 0
    compare "ls in /dev (relative)" "$(command_output 'ls /dev')" "$(command_output 'ls')"
    expect_line "ls: /dev/nope: No such file or directory"
    expect_line "mkdir: /dev/x: Read-only file system"
    expect_line "rm: /dev/usbdisk0: Read-only file system"
    for i in "nvme0n1p1 0 512 $image 1048576" "usbdisk1 1048576 4096 $fatstick 1048576" \
             "usbdisk0p2 4096 4096 $rstick $((133120 * 512 + 4096))"; do
        read -r dev offset length file at <<<"$i"
        expect_line "devread: /dev/$dev at $offset, $length bytes: sha256 $(python3 -c "
import hashlib
f = open('$file', 'rb'); f.seek($at); print(hashlib.sha256(f.read($length)).hexdigest())")"
    done
    expect_line "devread: stat: block device, 67108864 bytes, mode 600, owner 0"
    # Writing: allowed for the FAT stick's whole disk (its partition's
    # blocks are checked at each write), refused for the mounted RitterOS
    # partition and the system's EFI partition (mounted at /boot).
    expect_line "devread: open for writing: 3, opened"
    check "devread: open for writing refused twice" \
          "$(grep -cxF 'devread: open for writing: -1, Device or resource busy' <<<"$TEXT") time(s)" \
          test "$(grep -cxF 'devread: open for writing: -1, Device or resource busy' <<<"$TEXT")" = 2
    expect_line "devread: as user 1000: -1, Permission denied"
    expect_line "devread: /dev/nope: No such file or directory"
    # Plugged in: listed; unplugged: gone again.
    compare "a stick plugged in behind the hub appears" \
            "$(printf '%s\nusbdisk3        16.0 MiB  USB '"'"'%s'"'"', no partition table: empty' "$expected" "$model")" \
            "$(command_output 'disks' 2)"
    compare "unplugged: /dev as before" "$(command_output 'ls /dev' 1)" "$(command_output 'ls /dev' 2)"
    reject "panic"
    show_log_on_failure $before
}

# volumes_session: mounted volumes (volumes_shell_test); then a third
# RitterOS stick plugged in and pulled out, and disks in the rescue console.
volumes_session() {
    local mon="$WORK/monitor.sock" n=1 typed
    local -a typed_lines=('mount' 'ls /volumes' 'ls /volumes/RitterOS' 'cat /volumes/RitterOS/readme.txt'
                          'echo hi > /volumes/RitterOS/hi.txt' 'cat /volumes/RitterOS/hi.txt'
                          'cp /test/hello.txt /volumes/RitterOS-2/' 'cp -r /test/docs /volumes/RitterOS-2/docs'
                          'mv /volumes/RitterOS/hi.txt /home/root/' 'cat /home/root/hi.txt'
                          'cd /volumes/RitterOS' 'pwd' 'unmount /volumes/RitterOS' 'cd /'
                          'unmount /volumes/RitterOS' 'ls /volumes' 'ls /volumes/RitterOS'
                          'mkdir /mnt' 'touch /mnt/hidden' 'mount usbdisk0p2 /mnt' 'ls /mnt' 'mount'
                          'mount usbdisk0p2' 'unmount usbdisk0p2' 'ls /mnt' 'mount usbdisk2p1' 'mount nvme0n1p2'
                          'mount nope' 'unmount /nope' 'mkdir /volumes/x' 'rm -r /volumes/RitterOS-2'
                          'mv /volumes/RitterOS-2 /home/root/x' 'mkdir -p /work/m' 'mount usbdisk0p2 /work/m'
                          'rm -r /work' 'ls /work/m' 'unmount /work/m' 'mount usbdisk0p2'
                          "/system/$ARCH_NAME/test/mountuser usbdisk0p2 /volumes/RitterOS-2")
    prompt_wait $n
    for typed in "${typed_lines[@]}"; do
        serial_type "$typed\r"
        n=$((n + 1))
        prompt_wait $n 30
    done
    # A third stick with the same label: RitterOS-3; pulled out while mounted.
    echo "drive_add 0 if=none,id=hotvol,file=$WORK/${P}rstick3.img,format=raw" | nc -w 3 -U "$mon" >/dev/null 2>&1
    echo "device_add usb-storage,bus=xhci.0,port=1.2,drive=hotvol,id=hotvol,serial=HOTVOL" |
        nc -w 3 -U "$mon" >/dev/null 2>&1
    serial_wait "usbdisk3p2:    mounted at /volumes/RitterOS-3" 1 30
    serial_type '\r'
    n=$((n + 1))
    prompt_wait $n
    for typed in 'ls /volumes' 'cat /volumes/RitterOS-3/test/hello.txt'; do
        serial_type "$typed\r"
        n=$((n + 1))
        prompt_wait $n
    done
    echo "device_del hotvol" | nc -w 3 -U "$mon" >/dev/null 2>&1
    serial_wait "unmounted (usbdisk3 is gone)" 1 20
    serial_type '\r'
    n=$((n + 1))
    prompt_wait $n
    for typed in 'ls /volumes' 'disks'; do
        serial_type "$typed\r"
        n=$((n + 1))
        prompt_wait $n
    done
    serial_type 'exit\r'
    login_wait 2
    serial_type '\004'                              # Ctrl-D at login: the rescue console
    n=$((n + 1))
    prompt_wait $n
    serial_type 'disks\r'
    n=$((n + 1))
    prompt_wait $n
}

# volumes_shell_test: two RitterOS sticks with the same label and a FAT32
# one: mounted at /volumes/RitterOS and RitterOS-2 at the boot; reading,
# writing, copying and moving between volumes (the host checks the stick
# images afterwards), unmount and mount (busy, another place, refusals),
# rm and mv refusing a volume, hot plug, disks in the rescue console.
volumes_shell_test() {
    local image stick1 stick2 fatstick before model="QEMU QEMU HARDDISK" host
    image=$(make_image ${P}volumesshell "")
    stick1=$(make_image ${P}vstick1 "")
    stick2=$(make_image ${P}vstick2 "")
    make_image ${P}rstick3 "" >/dev/null
    fatstick="$WORK/${P}vfatstick.img"
    make_fat_stick "$fatstick"
    QEMU_EXTRA="-drive if=none,id=vstick1,format=raw,file=$stick1
                -device usb-storage,bus=xhci.0,port=2,drive=vstick1,serial=VSTICK1
                -drive if=none,id=vstick2,format=raw,file=$stick2
                -device usb-storage,bus=xhci.0,port=3,drive=vstick2,serial=VSTICK2
                -drive if=none,id=vfat,format=raw,file=$fatstick
                -device usb-storage,bus=xhci.0,port=4,drive=vfat,serial=VFAT"
    before=$failures
    SERIAL_SCRIPT=volumes_session
    boot ${P}volumesshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect_line "  usbdisk0p2:    mounted at /volumes/RitterOS"
    expect_line "  usbdisk1p2:    mounted at /volumes/RitterOS-2"
    compare "mount: the mounted file systems" "$(cat <<'LINES'
nvme0n1p1    on /boot (FAT32 'EFI', read only)
nvme0n1p2    on / (RitterFS 'RitterOS', read-write)
usbdisk0p2   on /volumes/RitterOS (RitterFS 'RitterOS', read-write)
usbdisk1p2   on /volumes/RitterOS-2 (RitterFS 'RitterOS', read-write)
usbdisk2p1   on /volumes/STICK (FAT32 'STICK', read-write)
LINES
)" "$(command_output 'mount')"
    compare "ls /volumes: one name per volume, the second with -2, by name" \
            "$(printf '     <dir>  RitterOS/\n     <dir>  RitterOS-2/\n     <dir>  STICK/')" \
            "$(command_output 'ls /volumes')"
    compare "ls of a volume, as the host lists the stick" "$($RFS ls "$stick1" $RFS_PART /)" \
            "$(command_output 'ls /volumes/RitterOS')"
    compare "cat on a volume" "$($RFS cat "$stick1" $RFS_PART /readme.txt)" \
            "$(command_output 'cat /volumes/RitterOS/readme.txt')"
    compare "written on a volume and read back" "hi" "$(command_output 'cat /volumes/RitterOS/hi.txt')"
    compare "mv from a volume to the system disk (copied, then removed)" "hi" \
            "$(command_output 'cat /home/root/hi.txt')"
    compare "the current directory inside a volume" "/volumes/RitterOS" "$(command_output 'pwd')"
    expect_line "unmount: /volumes/RitterOS: in use (a program has a file open there, or its current directory)"
    compare "unmounted: gone from /volumes" "$(printf '     <dir>  RitterOS-2/\n     <dir>  STICK/')" \
            "$(command_output 'ls /volumes' 2)"
    expect_line "ls: /volumes/RitterOS: No such file or directory"
    expect_line "mount: usbdisk0p2 at /mnt"
    compare "mounted on a directory: the volume, not what the directory holds" \
            "$($RFS ls "$stick1" $RFS_PART /)" "$(command_output 'ls /mnt')"
    compare "mount lists it" "usbdisk0p2   on /mnt (RitterFS 'RitterOS', read-write)" \
            "$(command_output 'mount' 2 | grep usbdisk0p2)"
    expect_line "mount: usbdisk0p2: mounted already, at /mnt"
    compare "unmounted: the directory's own content again" "         0  hidden" "$(command_output 'ls /mnt' 2)"
    expect_line "mount: usbdisk2p1: mounted already, at /volumes/STICK"
    expect_line "mount: nvme0n1p2: mounted already, at /"
    expect_line "mount: nope: No such file or directory"
    expect_line "unmount: /nope: not mounted"
    expect_line "mkdir: /volumes/x: Read-only file system"
    expect_line "rm: /volumes/RitterOS-2: a mounted volume (unmount it first)"
    expect_line "mv: /volumes/RitterOS-2: a mounted volume (unmount it, or mount it elsewhere)"
    expect_line "rm: /work/m: a mounted volume (unmount it first)"
    compare "rm -r stopped at the volume inside: it is complete" "$($RFS ls "$stick1" $RFS_PART /)" \
            "$(command_output 'ls /work/m')"
    expect_line "mount: usbdisk0p2 at /volumes/RitterOS"
    expect_line "mountuser: mount as user 1000: -1, Operation not permitted"
    expect_line "mountuser: unmount as user 1000: -1, Operation not permitted"
    expect_line "  usbdisk3p2:    mounted at /volumes/RitterOS-3"
    compare "a stick plugged in: mounted as RitterOS-3" \
            "$(printf '     <dir>  RitterOS/\n     <dir>  RitterOS-2/\n     <dir>  RitterOS-3/\n     <dir>  STICK/')" \
            "$(command_output 'ls /volumes' 3)"
    compare "read from it" "Hello from RitterFS!" "$(command_output 'cat /volumes/RitterOS-3/test/hello.txt')"
    expect_line "  /volumes/RitterOS-3: unmounted (usbdisk3 is gone)"
    compare "pulled out: gone from /volumes" "$(printf '     <dir>  RitterOS/\n     <dir>  RitterOS-2/\n     <dir>  STICK/')" \
            "$(command_output 'ls /volumes' 4)"
    compare "disks: what the host finds, with the mounts" \
            "$(python3 "$ROOT/scripts/expect_disks.py" "nvme0n1,NVMe,QEMU NVMe Ctrl,$image,system" \
                   "usbdisk0,USB,$model,$stick1,mounted=/volumes/RitterOS" \
                   "usbdisk1,USB,$model,$stick2,mounted=/volumes/RitterOS-2" \
                   "usbdisk2,USB,$model,$fatstick,p1=/volumes/STICK")" \
            "$(command_output 'disks')"
    compare "disks in the rescue console: the same" "$(command_output 'disks')" "$(command_output 'disks' 2)"
    # The sticks as the host reads them.
    compare "the host: hi.txt moved off the first stick" "" \
            "$($RFS ls "$stick1" $RFS_PART / | grep hi.txt)"
    compare "the host: the file copied to the second stick" "Hello from RitterFS!" \
            "$($RFS cat "$stick2" $RFS_PART /hello.txt)"
    compare "the host: the directory copied there" "Found me, four directories down." \
            "$($RFS cat "$stick2" $RFS_PART /docs/notes/deep/nested.txt)"
    for host in "$stick1" "$stick2"; do
        check "host check of $(basename "$host")" "$($RFS check "$host" $RFS_PART | tail -1)" \
              eval "$RFS check '$host' $RFS_PART | grep -q 'all checksums ok'"
    done
    reject "panic"
    show_log_on_failure $before
}

# answer_lines LINE...: type each line at the shell and wait for the next
# prompt; a line "= ANSWER" answers the confirmation question of the
# command before it ("Type the disk's name ...", "Type the device's
# name ..."). Counts with the caller's n (prompts so far) and asked
# (questions so far).
answer_lines() {
    local -a lines=("$@")
    local i typed next
    for ((i = 0; i < ${#lines[@]}; i++)); do
        typed=${lines[$i]}
        if [ "${typed#= }" != "$typed" ]; then
            asked=$((asked + 1))
            serial_wait "Type the d" $asked 30
            serial_type "${typed#= }\r"
        else
            serial_type "$typed\r"
            n=$((n + 1))
        fi
        # A command that asks first: no prompt until it is answered.
        next=${lines[$((i + 1))]:-}
        [ "${next#= }" != "$next" ] || prompt_wait $n 30
    done
}

# partitions_session: changing partition tables (partitions_shell_test).
partitions_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test/devwrite"
    prompt_wait $n
    answer_lines 'disks' 'disks usbdisk0' 'disks add usbdisk0 10M' \
                 'disks init usbdisk0' '= no' 'disks init usbdisk0' '= usbdisk0' \
                 'disks add usbdisk0 16M' '= usbdisk0' \
                 'disks add usbdisk0 rest data Photos' '= usbdisk0' \
                 'disks add usbdisk0 1M' 'disks rename usbdisk0p2 Pictures' '= usbdisk0' \
                 'disks delete usbdisk0p1' '= usbdisk0' 'disks delete usbdisk1p2' \
                 'disks init usbdisk1' 'disks add usbdisk2 1M' 'disks add usbdisk0 5M nope' \
                 'disks delete nvme0n1p2' 'disks nvme0n1' \
                 "$t busy usbdisk1 usbdisk1p2" "$t text usbdisk0 1049076 RitterOS-was-here" \
                 "$t text nvme0n1p2 0 x" 'unmount /volumes/RitterOS' \
                 "$t mount usbdisk1 usbdisk1p2" 'disks delete usbdisk1p2' '= usbdisk1' \
                 'ls /volumes' 'disks add usbdisk1 rest' '= usbdisk1' 'ls /volumes' \
                 'cat /volumes/RitterOS/test/hello.txt' "$t text usbdisk1 1024 X" 'disks usbdisk1' \
                 "$t text usbdisk1 $(((2097152 - 33) * 512)) X" 'disks' \
                 'cat /volumes/RitterOS/test/hello.txt' 'unmount /volumes/RitterOS' \
                 'ls /dev' 'unmount /volumes/STICK' 'disks init usbdisk2' '= usbdisk2' 'disks'
}

# partitions_shell_test: disks changing GPTs on a blank stick (init, add,
# rename, delete; the host checks both copies of the table), refusals
# (mounted, MBR, bad sizes and types), the kernel's guards for raw writes
# (devwrite), a RitterOS partition deleted and added again (mounted again),
# and a table damaged under a mounted partition (the first copy: the one at
# the end is read; both: the partition stays until it is unmounted).
partitions_shell_test() {
    local image rstick fatstick blank before host want
    image=$(make_image ${P}partsshell "")
    rstick=$(make_image ${P}pstick "")
    fatstick="$WORK/${P}pfatstick.img" blank="$WORK/${P}pblank.img"
    make_fat_stick "$fatstick"
    rm -f "$blank"
    python3 -c "open('$blank', 'wb').truncate(64 * 1024 * 1024)" || exit 1
    QEMU_EXTRA="-drive if=none,id=pblank,format=raw,file=$blank
                -device usb-storage,bus=xhci.0,port=2,drive=pblank,serial=PBLANK
                -drive if=none,id=pstick,format=raw,file=$rstick
                -device usb-storage,bus=xhci.0,port=3,drive=pstick,serial=PSTICK
                -drive if=none,id=pfat,format=raw,file=$fatstick
                -device usb-storage,bus=xhci.0,port=4,drive=pfat,serial=PFAT"
    before=$failures
    SERIAL_SCRIPT=partitions_session
    boot ${P}partsshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    want_text want <<'LINES'
usbdisk0        64.0 MiB  USB 'QEMU QEMU HARDDISK', no partition table: empty
  blocks of 512 bytes; no partition table (disks init makes one)
LINES
    compare "disks DISK: no table" "$want" "$(command_output 'disks usbdisk0')"
    expect_line "disks: usbdisk0: no partition table (disks init usbdisk0 makes one)"
    want_text want <<'LINES'
usbdisk0: a new, empty GPT partition table
Type the disk's name (usbdisk0) to write the new table: no
Nothing written.
LINES
    compare "disks init: not confirmed" "$want" "$(command_output 'disks init usbdisk0' 1 | grep -v 'exit code')"
    want_text want <<'LINES'
usbdisk0: a new, empty GPT partition table
Type the disk's name (usbdisk0) to write the new table: usbdisk0
usbdisk0        64.0 MiB  USB 'QEMU QEMU HARDDISK', GPT, 0 partitions
  blocks of 512 bytes; partitions may use 34-131038
  (free)        62.9 MiB  2048-131038
LINES
    compare "disks init: a new GPT, one free area from 1 MiB" "$want" "$(command_output 'disks init usbdisk0' 2)"
    want_text want <<'LINES'
usbdisk0: new partition #1 (usbdisk0p1): 16.0 MiB, blocks 2048-34815, RitterOS
Type the disk's name (usbdisk0) to write the new table: usbdisk0
usbdisk0        64.0 MiB  USB 'QEMU QEMU HARDDISK', GPT, 1 partition
  blocks of 512 bytes; partitions may use 34-131038
  usbdisk0p1    16.0 MiB  2048-34815            #1 RitterOS: empty
  (free)        46.9 MiB  34816-131038
LINES
    compare "disks add: 16 MiB at 1 MiB" "$want" "$(command_output 'disks add usbdisk0 16M')"
    want_text want <<'LINES'
usbdisk0: new partition #2 (usbdisk0p2): 46.9 MiB, blocks 34816-131038, Microsoft basic data 'Photos'
Type the disk's name (usbdisk0) to write the new table: usbdisk0
usbdisk0        64.0 MiB  USB 'QEMU QEMU HARDDISK', GPT, 2 partitions
  blocks of 512 bytes; partitions may use 34-131038
  usbdisk0p1    16.0 MiB  2048-34815            #1 RitterOS: empty
  usbdisk0p2    46.9 MiB  34816-131038          #2 Microsoft basic data 'Photos': empty
LINES
    compare "disks add: the rest, with a type and a name" "$want" "$(command_output 'disks add usbdisk0 rest data Photos')"
    expect_line "disks: usbdisk0: no free area of 1.0 MiB"
    expect_line "  usbdisk0p2    46.9 MiB  34816-131038          #2 Microsoft basic data 'Pictures': empty"
    want_text want <<'LINES'
usbdisk0: delete partition usbdisk0p1 (16.0 MiB, #1 RitterOS: empty)
Type the disk's name (usbdisk0) to write the new table: usbdisk0
usbdisk0        64.0 MiB  USB 'QEMU QEMU HARDDISK', GPT, 1 partition
  blocks of 512 bytes; partitions may use 34-131038
  (free)        16.0 MiB  2048-34815
  usbdisk0p2    46.9 MiB  34816-131038          #2 Microsoft basic data 'Pictures': empty
LINES
    compare "disks delete: the area is free again" "$want" "$(command_output 'disks delete usbdisk0p1')"
    expect_line "disks: usbdisk1p2 is mounted at /volumes/RitterOS (unmount it first)"
    check "disks init refused while a partition is mounted" \
          "$(command_output 'disks init usbdisk1')" \
          test "$(command_output 'disks init usbdisk1')" = "disks: usbdisk1p2 is mounted at /volumes/RitterOS (unmount it first)
disks: exit code 1"
    expect_line "disks: usbdisk2: an MBR; disks changes GPT tables only (disks init usbdisk2 makes one)"
    expect_line "disks: nope: not a type (ritteros, efi, data, linux, swap, or a GUID)"
    expect_line "disks: nvme0n1p2 is mounted at / (unmount it first)"
    expect "  nvme0n1p2    958.0 MiB  133120-2095103        #2 RitterOS: RitterFS 'RitterOS', generation "
    # The kernel's guards.
    expect_line "devwrite: open usbdisk1p2 for writing: -1, Device or resource busy"
    expect_line "devwrite: write usbdisk1p2's first block through usbdisk1: -1, Device or resource busy"
    expect_line "devwrite: 17 bytes at 1049076 on usbdisk0: done, closed: done"
    expect_line "devwrite: nvme0n1p2: Device or resource busy"
    expect_line "devwrite: mount usbdisk1p2 while usbdisk1 is open for writing: -1, Device or resource busy"
    # Deleted and added again: the RitterFS is found and mounted.
    want_text want <<'LINES'
GPT ok
#2 34816-131038 EBD0A0A2-B9E5-4433-87C0-68B6B72699C7 'Pictures'
LINES
    compare "deleted: not mounted" "     <dir>  STICK/" "$(command_output 'ls /volumes' 1)"
    expect_line "  usbdisk1p2:    mounted at /volumes/RitterOS"
    compare "added again: mounted" "$(printf '     <dir>  RitterOS/\n     <dir>  STICK/')" \
            "$(command_output 'ls /volumes' 2)"
    compare "read from it" "Hello from RitterFS!" "$(command_output 'cat /volumes/RitterOS/test/hello.txt' 1)"
    # The first copy of the table damaged: the copy at the end serves.
    check "first GPT damaged: the copy at the disk's end is read" \
          "$(command_output 'disks usbdisk1' | head -1)" \
          eval 'command_output "disks usbdisk1" | head -1 | grep -q "GPT, 2 partitions$" &&
                command_output "disks usbdisk1" | grep -q "usbdisk1p2 .*mounted at /volumes/RitterOS$"'
    # Both damaged, under a mounted partition: it stays.
    expect_line "  usbdisk1p2: no longer in the partition table, still mounted at /volumes/RitterOS"
    check "disks: still listed while mounted" "$(command_output 'disks' 2 | grep usbdisk1)" \
          eval 'command_output disks 2 | grep -q "^  usbdisk1p2 .*mounted at /volumes/RitterOS$"'
    compare "and still readable" "Hello from RitterFS!" "$(command_output 'cat /volumes/RitterOS/test/hello.txt' 2)"
    check "unmounted: gone from /dev" "$(command_output 'ls /dev' | grep usbdisk1)" \
          test "$(command_output 'ls /dev' | grep -c usbdisk1p)" = 0
    compare "disks: as the host reads the images" \
            "$(python3 "$ROOT/scripts/expect_disks.py" "nvme0n1,NVMe,QEMU NVMe Ctrl,$image,system" \
                   "usbdisk0,USB,QEMU QEMU HARDDISK,$blank" "usbdisk1,USB,QEMU QEMU HARDDISK,$rstick" \
                   "usbdisk2,USB,QEMU QEMU HARDDISK,$fatstick")" \
            "$(command_output 'disks' 3)"
    # The host checks the tables RitterOS wrote: both copies, checksums,
    # the protective MBR.
    compare "the host: the blank stick's GPT" "$want" "$(python3 "$ROOT/scripts/gptcheck.py" "$blank")"
    compare "the host: the FAT stick's new GPT" "GPT ok" "$(python3 "$ROOT/scripts/gptcheck.py" "$fatstick" | head -1)"
    compare "the host: the RitterOS stick's partition 2 reaches the end" \
            "#2 133120-2097118 B5CA1B3E-6278-48F0-BBEF-87907326A8B3 'RitterOS'" \
            "$(python3 - "$rstick" <<'PY'
import struct, sys, uuid
f = open(sys.argv[1], 'rb'); f.seek(2 * 512 + 128); e = f.read(128)
lo, hi = struct.unpack_from('<QQ', e, 32)
print(f"#2 {lo}-{hi} {str(uuid.UUID(bytes_le=e[:16])).upper()} '{e[56:128].decode('utf-16-le').split(chr(0))[0]}'")
PY
)"
    compare "the host: raw bytes written across a block boundary" \
            "b'\\x00RitterOS-was-here\\x00'" \
            "$(python3 -c "f = open('$blank', 'rb'); f.seek(1049075); print(f.read(19))")"
    check "the host: the RitterFS on it is whole" "$($RFS check "$rstick" $RFS_PART | tail -1)" \
          eval "$RFS check '$rstick' $RFS_PART | grep -q 'all checksums ok'"
    reject "panic"
    show_log_on_failure $before
}

# grow_session: a disk image on a bigger stick (grow_shell_test).
grow_session() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines 'disks usbdisk0' 'disks add usbdisk0 rest data' '= usbdisk0' 'disks usbdisk0'
}

# grow_shell_test: like the user's 28.8 GiB stick with the 1 GiB image
# copied onto it: a RitterOS image on a 2 GiB stick, its GPT (and the
# table's copy) made for 1 GiB. disks shows the free space up to the
# disk's end and says why; adding a partition fits the table to the whole
# disk (the copy at the end, the protective MBR), as the host checks.
grow_shell_test() {
    local image stick before
    image=$(make_image ${P}growshell "")
    stick=$(make_image ${P}growstick "")
    python3 -c "open('$stick', 'r+b').truncate(2 << 30)" || exit 1
    QEMU_EXTRA="-drive if=none,id=grow,format=raw,file=$stick
                -device usb-storage,bus=xhci.0,port=2,drive=grow,serial=GROW"
    before=$failures
    SERIAL_SCRIPT=grow_session
    boot ${P}growshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect_line "  blocks of 512 bytes; partitions may use 34-4194270"
    expect_line "  the table was made for a smaller disk (it covers 1023.9 MiB of 2.0 GiB);"
    expect_line "  (free)         1.0 GiB  2095104-4194270"
    expect_line "usbdisk0: the table is fitted to the whole disk: partitions may use 34-4194270 (before: 34-2097118)"
    expect_line "usbdisk0: new partition #3 (usbdisk0p3): 1.0 GiB, blocks 2095104-4194270, Microsoft basic data"
    check "fitted: no word of a smaller disk any more" \
          "$(command_output 'disks usbdisk0' 2 | grep -c 'smaller disk') line(s)" \
          test "$(command_output 'disks usbdisk0' 2 | grep -c 'smaller disk')" = 0
    expect_line "  usbdisk0p3     1.0 GiB  2095104-4194270       #3 Microsoft basic data: empty"
    compare "the host: the GPT fills the disk (both copies, the protective MBR)" \
            "$(printf 'GPT ok\n#3 2095104-4194270 EBD0A0A2-B9E5-4433-87C0-68B6B72699C7 '"'"'Microsoft basic data'"'"'')" \
            "$(python3 "$ROOT/scripts/gptcheck.py" "$stick" | grep -E '^GPT ok|^#3 ')"
    check "the host: the RitterFS on it untouched" "$($RFS check "$stick" $RFS_PART | tail -1)" \
          eval "$RFS check '$stick' $RFS_PART | grep -q 'all checksums ok'"
    reject "panic"
    show_log_on_failure $before
}

# clone FROM TO: a copy of a disk image; on APFS a clone (instant, and a
# sparse 20 GiB image stays sparse).
clone() {
    rm -f "$2"
    cp -c "$1" "$2" 2>/dev/null || cp "$1" "$2"
}

# format_session: format (format_shell_test); then two of the sticks pulled
# out and plugged in again.
format_session() {
    local n=1 asked=0 mon="$WORK/monitor.sock"
    prompt_wait $n
    answer_lines 'disks init usbdisk0' '= usbdisk0' 'disks add usbdisk0 16M' '= usbdisk0' \
                 'disks add usbdisk0 rest data' '= usbdisk0' \
                 'format usbdisk0p1 Photos' '= usbdisk0p1' 'format usbdisk0p2' '= no' \
                 'format usbdisk0p2' '= usbdisk0p2' 'ls /volumes' 'echo hello > /volumes/Photos/a.txt' \
                 'format usbdisk1p2' 'format nvme0n1' 'format usbdisk0p1 x/y' 'format usbdisk9' \
                 'unmount /volumes/RitterOS' 'format usbdisk1p2 Big' '= usbdisk1p2' \
                 'disks init usbdisk2' '= usbdisk2' 'format usbdisk2 Huge' '= usbdisk2' 'disks' 'mount'
    # Pulled out and plugged in again: found by their content and mounted.
    # Copies, behind the hub (the serial numbers give the old names); the
    # monitor commands of each group over one connection: with one
    # connection per command in quick succession, an nc once waited
    # forever (the monitor takes one client at a time).
    { echo "device_del fblank"; sleep 1; echo "device_del fhuge"; sleep 1; } |
        nc -w 3 -U "$mon" >/dev/null 2>&1
    serial_wait "usbdisk0:      removed" 1 20
    serial_wait "usbdisk2:      removed" 1 20
    clone "$WORK/${P}fblank.img" "$WORK/${P}fblank2.img"
    clone "$WORK/${P}fhuge.img" "$WORK/${P}fhuge2.img"
    { echo "drive_add 0 if=none,id=fblank2,file=$WORK/${P}fblank2.img,format=raw"; sleep 1
      echo "device_add usb-storage,bus=xhci.0,port=1.2,drive=fblank2,id=fblank2,serial=FBLANK"; sleep 1
      echo "drive_add 0 if=none,id=fhuge2,file=$WORK/${P}fhuge2.img,format=raw"; sleep 1
      echo "device_add usb-storage,bus=xhci.0,port=1.3,drive=fhuge2,id=fhuge2,serial=FHUGE"; sleep 1
    } | nc -w 3 -U "$mon" >/dev/null 2>&1
    serial_wait "usbdisk0p1:    mounted at /volumes/Photos" 2 30
    serial_wait "usbdisk0p2:    mounted at /volumes/RitterFS" 2 30
    serial_wait "usbdisk2:      mounted at /volumes/Huge" 2 30
    serial_type '\r'
    n=$((n + 1))
    prompt_wait $n
    answer_lines 'mount' 'cat /volumes/Photos/a.txt'
}

# format_shell_test: format on a blank stick's two partitions (one of the
# type "data"), on a RitterOS stick's partition (958 MiB: a bitmap tree of
# height 1) and on a whole 20 GiB stick with a GPT (height 2: its table,
# both copies, must go); the refusals; the new file systems mounted at once
# and again when the sticks are plugged in again (by their content); the
# host checks each one and finds it identical to what scripts/ritterfs.py
# makes for the same label, UUID and time (scripts/samefs.py).
format_shell_test() {
    local image rstick blank huge before gen want
    image=$(make_image ${P}formatshell "")
    rstick=$(make_image ${P}fstick "")
    blank="$WORK/${P}fblank.img" huge="$WORK/${P}fhuge.img"
    rm -f "$blank" "$huge"
    python3 -c "open('$blank', 'wb').truncate(64 << 20); open('$huge', 'wb').truncate(20 << 30)" || exit 1
    gen=$($RFS check "$rstick" $RFS_PART | sed -n 's/.*generation \([0-9][0-9]*\).*/\1/p' | head -1)
    QEMU_EXTRA="-drive if=none,id=fblank,format=raw,file=$blank
                -device usb-storage,bus=xhci.0,port=2,drive=fblank,id=fblank,serial=FBLANK
                -drive if=none,id=fstick,format=raw,file=$rstick
                -device usb-storage,bus=xhci.0,port=3,drive=fstick,id=fstick,serial=FSTICK
                -drive if=none,id=fhuge,format=raw,file=$huge
                -device usb-storage,bus=xhci.0,port=4,drive=fhuge,id=fhuge,serial=FHUGE"
    before=$failures
    SERIAL_SCRIPT=format_session
    boot ${P}formatshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect_line "usbdisk0p1: a new RitterFS 'Photos', 16.0 MiB (4096 blocks of 4 KiB)"
    expect_line "Type the device's name (usbdisk0p1) to format it: usbdisk0p1"
    expect_line "usbdisk0p1: formatted, mounted at /volumes/Photos"
    want_text want <<'LINES'
usbdisk0p2: a new RitterFS 'RitterFS', 46.9 MiB (12027 blocks of 4 KiB)
Type the device's name (usbdisk0p2) to format it: no
Nothing written.
format: exit code 1
LINES
    compare "format: not confirmed" "$want" "$(command_output 'format usbdisk0p2' 1)"
    expect_line "usbdisk0p2: formatted, mounted at /volumes/RitterFS"
    compare "formatted: mounted at once" "$(printf '     <dir>  Photos/\n     <dir>  RitterFS/\n     <dir>  RitterOS/')" \
            "$(command_output 'ls /volumes')"
    expect_line "format: usbdisk1p2 is mounted at /volumes/RitterOS (unmount it first)"
    expect_line "format: nvme0n1: its partition nvme0n1p1 is mounted at /boot (unmount it first)"
    expect_line "format: 'x/y': not a label (1-63 plain characters, no '/')"
    expect_line "format: usbdisk9: No such file or directory"
    expect_line "usbdisk1p2: a new RitterFS 'Big', 958.0 MiB (245248 blocks of 4 KiB)"
    expect_line "What it holds now is lost: RitterFS 'RitterOS', generation $gen."
    expect_line "usbdisk1p2: formatted, mounted at /volumes/Big"
    expect_line "usbdisk2: a new RitterFS 'Huge', 20.0 GiB (5242880 blocks of 4 KiB)"
    expect_line "It replaces the whole disk's GPT partition table with 0 partitions."
    expect_line "usbdisk2: formatted, mounted at /volumes/Huge"
    # The kernel's check of each new file system (bitmap trees of height
    # 0, 1 and 2).
    expect "check: 3 objects, 20 blocks in use, root directory 0 entries: all checksums ok (both copies), bitmap consistent"
    expect "check: 3 objects, 36 blocks in use, root directory 0 entries: all checksums ok (both copies), bitmap consistent"
    expect "check: 3 objects, 344 blocks in use, root directory 0 entries: all checksums ok (both copies), bitmap consistent"
    reject "created 1970"
    want_text want <<'LINES'
usbdisk0        64.0 MiB  USB 'QEMU QEMU HARDDISK', GPT, 2 partitions
  usbdisk0p1    16.0 MiB  #1 RitterOS: RitterFS 'Photos', generation 2, mounted at /volumes/Photos
  usbdisk0p2    46.9 MiB  #2 Microsoft basic data: RitterFS 'RitterFS', generation 1, mounted at /volumes/RitterFS
usbdisk1         1.0 GiB  USB 'QEMU QEMU HARDDISK', GPT, 2 partitions
  usbdisk1p1    64.0 MiB  #1 EFI system partition: FAT32 'EFI'
  usbdisk1p2   958.0 MiB  #2 RitterOS: RitterFS 'Big', generation 1, mounted at /volumes/Big
usbdisk2        20.0 GiB  USB 'QEMU QEMU HARDDISK', no partition table: RitterFS 'Huge', generation 1, mounted at /volumes/Huge
LINES
    compare "disks: the new file systems" "$want" "$(command_output 'disks' | grep -v '^ *nvme')"
    # Plugged in again: mounted by their content (also the "data" partition
    # and the whole disk), the file written before still there.
    compare "plugged in again: the data partition mounted" \
            "usbdisk0p2   on /volumes/RitterFS (RitterFS 'RitterFS', read-write)" \
            "$(command_output 'mount' 2 | grep usbdisk0p2)"
    compare "plugged in again: the whole disk mounted" \
            "usbdisk2     on /volumes/Huge (RitterFS 'Huge', read-write)" \
            "$(command_output 'mount' 2 | grep usbdisk2)"
    compare "plugged in again: the file is there" "hello" "$(command_output 'cat /volumes/Photos/a.txt')"
    # The host: each file system whole, and identical to its own format.
    check "the host: Photos whole, with the file" "$($RFS check "$blank" 2048 32768 | tail -1)" \
          eval "$RFS check '$blank' 2048 32768 | grep -q 'all checksums ok' &&
                test \"\$($RFS cat '$blank' 2048 32768 /a.txt)\" = hello"
    compare "the host: the data partition as ritterfs.py formats it" "identical: 6 blocks" \
            "$(python3 "$ROOT/scripts/samefs.py" "$blank" 34816 96223)"
    compare "the host: the 958 MiB one as ritterfs.py formats it" "identical: 22 blocks" \
            "$(python3 "$ROOT/scripts/samefs.py" "$rstick" $RFS_PART)"
    compare "the host: the 20 GiB disk as ritterfs.py formats it" "identical: 330 blocks" \
            "$(python3 "$ROOT/scripts/samefs.py" "$huge" 0 41943040)"
    compare "the host: no partition table left on the whole disk" "" \
            "$(python3 "$ROOT/scripts/gptcheck.py" "$huge" | grep '^GPT ok')"
    reject "panic"
    show_log_on_failure $before
}

# make_fat_sticks PREFIX: three sticks made on the host by scripts/fat.py
# from one tree ($FAT_TREE, JSON): FAT32 with an MBR ($FAT32_IMG), FAT16
# and FAT12 on the whole disk ($FAT16_IMG, $FAT12_IMG). Long, Unicode and
# lower-case short names, a directory of 60 entries over several clusters,
# a 320 KB file in pieces, an empty and a read-only file.
make_fat_sticks() {
    FAT_TREE="$WORK/$1tree.json" FAT32_IMG="$WORK/${1}32.img" FAT16_IMG="$WORK/${1}16.img"
    FAT12_IMG="$WORK/${1}12.img"
    python3 - "$FAT_TREE" <<'PY' || exit 1
import json, sys
many = {f"Entry number {i:02d} with a long name.txt": f"entry {i}\n" for i in range(60)}
tree = {
    "README.TXT": "Plain 8.3 name.\n",
    "notes.txt": "A lower-case short name.\n",
    "A long file name with spaces.txt": "Long names work.\n",
    "Ünïcödé – ✓.txt": "Unicode.\n",
    "Docs": {"Deep": {"deeper": {"end.txt": "Found me, four directories down on FAT.\n"},
                      "Grüße – ✓.txt": "Grüße.\n"},
             "many": many},
    "big.bin": {"repeat": "0123456789abcdef", "times": 20000},
    "empty.txt": "",
    "readonly.txt": "Cannot be changed.\n",
}
json.dump(tree, open(sys.argv[1], "w"), ensure_ascii=False)
PY
    rm -f "$FAT32_IMG" "$FAT16_IMG" "$FAT12_IMG"
    python3 -c "open('$FAT32_IMG', 'wb').truncate(64 << 20); open('$FAT16_IMG', 'wb').truncate(32 << 20)
open('$FAT12_IMG', 'wb').truncate(3 << 20)" || exit 1
    python3 "$ROOT/scripts/fat.py" make "$FAT32_IMG" 2048 129024 32 STICK32 "$FAT_TREE" mbr &&
        python3 "$ROOT/scripts/fat.py" make "$FAT16_IMG" 0 65536 16 STICK16 "$FAT_TREE" &&
        python3 "$ROOT/scripts/fat.py" make "$FAT12_IMG" 0 6144 12 STICK12 "$FAT_TREE" || exit 1
}

# fat_session: FAT volumes read (fat_shell_test).
fat_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test/filesha"
    prompt_wait $n
