                 'cat /volumes/STICK32/readme.txt' 'cat /volumes/STICK32/NOTES.TXT' \
                 'cat "/volumes/STICK32/A long file name with spaces.txt"' \
                 'cat /volumes/STICK16/docs/deep/DEEPER/end.txt' 'ls /volumes/STICK12/Docs/many' \
                 "$t /volumes/STICK12/big.bin" "$t /volumes/STICK16/big.bin" "$t /volumes/STICK32/big.bin" \
                 'cat /volumes/STICK32/empty.txt' 'attr /volumes/STICK32/notes.txt' \
                 'cp /volumes/STICK32/big.bin /home/root/big.bin' "$t /home/root/big.bin" \
