# fat_format_test: format -t fat makes FAT32: on a "data" partition of 47
# MiB (clusters of 512 bytes) and on a whole 9 GiB stick (8 KiB, as
# Windows chooses); a 16 MiB partition and a too long label refused. The
# new volumes are mounted at once (upper-case labels) and written to; the
# host finds them clean (scripts/fat.py check, macOS's fsck_msdos) with
# the boot sector Windows expects.
fat_format_test() {
    local image small big before fsck="/sbin/fsck_msdos" part first target
    image=$(make_image ${P}fatformat "")
    small="$WORK/${P}ff64.img" big="$WORK/${P}ff9g.img"
    rm -f "$small" "$big"
    python3 -c "open('$small', 'wb').truncate(64 << 20); open('$big', 'wb').truncate(9 << 30)" || exit 1
    QEMU_EXTRA="-drive if=none,id=ff64,format=raw,file=$small
                -device usb-storage,bus=xhci.0,port=2,drive=ff64,serial=FF64
                -drive if=none,id=ff9g,format=raw,file=$big
                -device usb-storage,bus=xhci.0,port=3,drive=ff9g,serial=FF9G"
    before=$failures
    SERIAL_SCRIPT=fat_format_session
    boot ${P}fatformat "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect_line "format: usbdisk0p1: 16.0 MiB does not suit FAT32 (from about 33 MiB to 2 TiB)"
    expect_line "usbdisk0p2: a new FAT32 'SHARE', 46.9 MiB (94687 clusters of 512 bytes)"
    expect_line "usbdisk0p2: formatted, mounted at /volumes/SHARE"
    compare "written to the new volume" "$(printf '         6  hello.txt\n     <dir>  A Folder/')" \
            "$(command_output 'ls /volumes/SHARE')"
    expect_line "usbdisk1: a new FAT32 'BIG', 9.0 GiB (1178494 clusters of 8.0 KiB)"
    expect_line "usbdisk1: formatted, mounted at /volumes/BIG"
    expect "format: 'way too long label': not a FAT label (at most 11 letters"
    expect_line "usage: format [-t fat|exfat] DEVICE [LABEL]"
    expect_line "usbdisk1     on /volumes/BIG (FAT32 'BIG', read-write)"
    for part in "$small 34816" "$big 0"; do
        read -r part first <<<"$part"
        compare "the host: $(basename "$part") consistent (scripts/fat.py)" "FAT ok" \
                "$(python3 "$ROOT/scripts/fat.py" check "$part" "$first")"
        if [ -x "$fsck" ]; then
            target="$part"                          # a whole disk: the image itself
            if [ "$first" != 0 ]; then
                target="$WORK/${P}fsck.img"
                dd if="$part" of="$target" bs=512 skip="$first" 2>/dev/null
            fi
            check "the host: $(basename "$part") consistent (macOS fsck_msdos)" \
                  "$("$fsck" -n "$target" 2>&1 | grep -v '^\*\*' | tr '\n' '|')" \
                  "$fsck" -n "$target"
            rm -f "$WORK/${P}fsck.img"
        fi
    done
    compare "the host: the copied file" "Hello from RitterFS!" \
            "$(python3 "$ROOT/scripts/fat.py" cat "$small" 34816 "/A Folder/copied file.txt")"
    compare "the host: the boot sector as Windows expects it" \
            "MSWIN4.1 512 16 32 2 FAT32    BIG" \
            "$(python3 -c "
import struct
b = open('$big', 'rb').read(512)
print(b[3:11].decode(), struct.unpack_from('<H', b, 11)[0], b[13], struct.unpack_from('<H', b, 14)[0],
      b[16], b[82:90].decode(), b[71:82].decode().strip())")"
    reject "panic"
    show_log_on_failure $before
}

