    local n=1 asked=0
    prompt_wait $n
    answer_lines 'disks init usbdisk0' '= usbdisk0' 'disks add usbdisk0 16M' '= usbdisk0' \
                 'disks add usbdisk0 rest data' '= usbdisk0' 'format -t exfat usbdisk0p1' '= usbdisk0p1' \
                 'format -t exfat usbdisk0p2 Shared' '= usbdisk0p2' 'echo hello > /volumes/Shared/hello.txt' \
                 'mkdir "/volumes/Shared/A Folder"' \
