}

# exfat_promised IMAGE FIRST DEVICE LABEL: the line format prints for the
# exFAT at sector FIRST of IMAGE, from what its boot sector says (length,
# clusters, their size).
exfat_promised() {
    python3 -c "
import struct, sys
f = open(sys.argv[1], 'rb')
f.seek(int(sys.argv[2]) * 512)
b = f.read(512)
length = struct.unpack_from('<Q', b, 72)[0] << b[108]
clusters = struct.unpack_from('<I', b, 92)[0]
def size(n):
    units, u, tenths = ['bytes', 'KiB', 'MiB', 'GiB', 'TiB'], 0, 0
    while n >= 1024 and u < 4:
        tenths, n, u = n % 1024 * 10 // 1024, n // 1024, u + 1
    return '%d.%d %s' % (n, tenths, units[u])
label = \" '%s'\" % sys.argv[4] if sys.argv[4] else ''
print('%s: a new exFAT%s, %s (%d clusters of %s)' % (sys.argv[3], label, size(length), clusters,
                                                    size(512 << b[109])))" "$@"
}

# exfat_format_test: format -t exfat: a 16 MiB partition without a label
# (clusters of 4 KiB; mounted by the device's name), a "data" partition of
# about 496 MiB (32 KiB) and a whole 40 GiB stick (128 KiB, a label beyond
# ASCII), the cluster sizes Windows chooses; a too long label and one with
# a ':' refused. The new volumes are mounted at once and written to; the
# host finds them clean (scripts/exfat.py check, macOS's fsck_exfat), reads
# what was written and the label, and finds the layout of the
# specification in the boot sectors (one FAT, from 1 MiB on beyond 64 MiB,
# the heap on a cluster boundary, the root after the bitmap and the
# up-case table).
exfat_format_test() {
    local image small big before part first dev label shift fat file want
    image=$(make_image ${P}exfatformat "")
    small="$WORK/${P}ef512.img" big="$WORK/${P}ef40g.img"
    rm -f "$small" "$big"
    python3 -c "open('$small', 'wb').truncate(512 << 20); open('$big', 'wb').truncate(40 << 30)" || exit 1
    QEMU_EXTRA="-drive if=none,id=ef512,format=raw,file=$small
                -device usb-storage,bus=xhci.0,port=2,drive=ef512,serial=EF512
                -drive if=none,id=ef40g,format=raw,file=$big
                -device usb-storage,bus=xhci.0,port=3,drive=ef40g,serial=EF40G"
    before=$failures
    SERIAL_SCRIPT=exfat_format_session
    boot ${P}exfatformat "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    for part in "$small 2048 usbdisk0p1 - 3 24 /small.txt small" \
                "$small 34816 usbdisk0p2 Shared 6 2048 /hello.txt hello" \
                "$big 0 usbdisk1 Fotos_Señor 8 2048 /big.txt big"; do
        read -r part first dev label shift fat file want <<<"$part"
        label=${label//_/ }
        [ "$label" = - ] && label=
        expect_line "$(exfat_promised "$part" "$first" "$dev" "$label")"
        expect_line "$dev: formatted, mounted at /volumes/${label:-$dev}"
        compare "the host: $dev's boot sector (shifts, FATs, the FAT's place, the heap's alignment)" \
                "EXFAT    9 $shift 1 $fat aligned 1.00 root after bitmap and table" \
                "$(python3 -c "
import struct
f = open('$part', 'rb')
f.seek($first * 512)
b = f.read(512)
fat_offset, fat_length, heap, clusters, root = struct.unpack_from('<IIIII', b, 80)
per = 1 << b[109]
bitmap = ((clusters + 7) // 8 + (512 << b[109]) - 1) // (512 << b[109])
print(b[3:11].decode(), b[108], b[109], b[110], fat_offset, 'aligned' if heap % per == 0 else heap,
      '%d.%02d' % (b[105], b[104]), 'root after bitmap and table' if root > 2 + bitmap else root)")"
        compare "the host: $dev consistent (scripts/exfat.py)" "exFAT ok" \
                "$(python3 "$ROOT/scripts/exfat.py" check "$part" "$first")"
        compare "the host: $dev's label" "$label" \
                "$(python3 -c "import sys; sys.path.insert(0, '$ROOT/scripts'); import exfat
print(exfat.Reader('$part', $first).label())")"
        compare "the host: $dev's $file" "$want" "$(python3 "$ROOT/scripts/exfat.py" cat "$part" "$first" "$file")"
        exfat_fsck "$part" "$first" "$dev"
    done
    compare "written to the new volume" \
            "$(printf '         6  hello.txt\n     <dir>  A Folder/')" "$(command_output 'ls /volumes/Shared')"
    compare "the host: the copied file" "Hello from RitterFS!" \
            "$(python3 "$ROOT/scripts/exfat.py" cat "$small" 34816 "/A Folder/copied file.txt")"
    expect "format: 'way too long label': not an exFAT label (at most 11 characters"
    expect "format: 'a:b': not an exFAT label"
    expect_line "usage: format [-t fat|exfat] DEVICE [LABEL]"
    expect_line "usbdisk1     on /volumes/Fotos Señor (exFAT 'Fotos Señor', read-write)"
    reject "panic"
    show_log_on_failure $before
}

