# osinstall_test: osinstall (48a) puts RitterOS on a second disk (x86: a
# SATA disk, as the J1900's SSD; ARM: a second NVMe drive, as the
# laptop's) holding an exFAT that is mounted: unmounted first, then a new
# GPT (EFI system partition of 64 MiB, FAT32 'EFI'; RitterFS 'RitterOS' on
# the rest) with GUIDs of its own, the bootloader at the fallback path, the
# command line without "selftest", /system/<arch> without its test
# programs, and a firmware boot entry 'RitterOS' first in the boot order
# (48c; the test machines get a copy of the firmware's variables). The
# host checks the disk (gptcheck.py, fat.py, ritterfs.py: every program
# there and the same, nothing else; the test copies its program efivar to
# /). Then the machine boots from that disk alone, without a boot order
# from QEMU: the firmware starts the entry (BootCurrent), the first start
# asks for root's password, the system partition is the new disk's, the
# shell runs.
osinstall_test() {
    local image target before host last count names want saved="$QEMU_CMD" boot_file
    local disk_extra vars entry esp_guid entry_line
    image=$(make_image ${P}osinstall "")
    target="$WORK/${P}osinstall-target.img"
    rm -f "$target"
    python3 -c "open('$target', 'wb').truncate(1 << 30)" || exit 1
    echo '{"old.txt": "what was there before"}' >"$WORK/${P}osinstall-old.json"
    python3 "$ROOT/scripts/exfat.py" make "$target" 2048 65536 OLDDATA "$WORK/${P}osinstall-old.json" mbr || exit 1
    if [ "$ARCH_NAME" = x86_64 ]; then
        OSINSTALL_DISK=sata0 boot_file=BOOTX64.EFI
        disk_extra="-drive if=none,id=target,format=raw,file=$target -device ide-hd,drive=target,bus=ide.0"
    else
        OSINSTALL_DISK=nvme1n1 boot_file=BOOTAA64.EFI
        disk_extra="-drive if=none,id=target,format=raw,file=$target -device nvme,drive=target,serial=TARGET0001"
    fi
    local p1=${OSINSTALL_DISK}p1 p2=${OSINSTALL_DISK}p2
    [ "$ARCH_NAME" = x86_64 ] && p1=sata0p1 p2=sata0p2
    vars="$WORK/${P}osinstall-vars.fd"
    cp "$ROOT/build/$ARCH_NAME/vars.fd" "$vars" || exit 1
    QEMU_CMD="${saved//build\/$ARCH_NAME\/vars.fd/$vars}"
    before=$failures
    QEMU_EXTRA="$disk_extra"
    SERIAL_SCRIPT=osinstall_session
    boot ${P}osinstall "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect_line "Nothing written."
    expect_line "'nosuch' is not one of the disks above."
    check "osinstall lists $OSINSTALL_DISK, not the disk it runs from" \
          "$(grep -E '^  [0-9]+  ' <<<"$TEXT" | tr '\n' '|')" \
          eval 'grep -qE "^  1  $OSINSTALL_DISK +1\.0 GiB  (SATA|NVMe) .*: MBR, 1 partition$" <<<"$TEXT" &&
                ! grep -qE "^  [0-9]+  nvme0n1 " <<<"$TEXT"'
    expect_line "Mounted now, unmounted first: $p1 at /volumes/OLDDATA"
    expect_line "osinstall: $p1 unmounted from /volumes/OLDDATA"
    expect_line "osinstall: $OSINSTALL_DISK: a new GPT partition table"
    expect_line "osinstall: $p1: FAT32 'EFI', 64.0 MiB"
    expect_line "osinstall: $p2: RitterFS 'RitterOS', 958.9 MiB"
    expect_line "osinstall: the bootloader copied (\\EFI\\BOOT\\$boot_file, $(stat -f %z "$ROOT/build/esp/EFI/BOOT/$boot_file") bytes), command line \"\""
    expect_line "osinstall: /system/$ARCH_NAME copied: the kernel and $(( $(ls "$ROOT/build/system/$ARCH_NAME/bin" | wc -l) + $(ls "$ROOT/build/system/$ARCH_NAME/apps" | grep -c '\.program$') )) programs"
    expect "RitterOS is installed on $OSINSTALL_DISK. Remove the stick and restart"
    reject ": unmounting "
    reject "no firmware boot entry"
    entry=$(sed -n "s/^osinstall: the firmware's boot entry \(Boot[0-9A-F]\{4\}\) 'RitterOS', first in its boot order$/\1/p" <<<"$TEXT")
    check "osinstall: the firmware's boot entry ${entry:-?} 'RitterOS', first in its boot order" \
          "osinstall wrote no boot entry" test -n "$entry"
    esp_guid=$(python3 -c "
import uuid
f = open('$target', 'rb')
f.seek(1024)
print(str(uuid.UUID(bytes_le=f.read(32)[16:32])).upper())")
    entry_line="$entry: active, 'RitterOS', HD(1,GPT,$esp_guid,0x800,0x20000)/\\EFI\\BOOT\\$boot_file"
    expect_line "BootOrder: ${entry#Boot}$(command_output "/system/$ARCH_NAME/test/efivar" | sed -n 's/^BootOrder: [0-9A-F]*//p')"
    expect_line "$entry_line"
    # The disk on the host.
    host=$(python3 "$ROOT/scripts/gptcheck.py" "$target")
    last=$(sed -n 's/^#2 133120-\([0-9][0-9]*\) .*/\1/p' <<<"$host")
    want_text want <<'LINES'
GPT ok
#1 2048-133119 C12A7328-F81F-11D2-BA4B-00A0C93EC93B 'EFI system partition'
LINES
    compare "the host: the new GPT (scripts/gptcheck.py)" "$want
#2 133120-2097118 B5CA1B3E-6278-48F0-BBEF-87907326A8B3 'RitterOS'" "$host"
    compare "the host: GUIDs of its own (not the stick's)" "differ differ differ" "$(python3 -c "
import struct, sys, uuid
sys.path.insert(0, '$ROOT/scripts')
import mkdisk
f = open('$target', 'rb')
f.seek(512)
h = f.read(92)
f.seek(1024)
e = f.read(256)
mine = [uuid.UUID(bytes_le=h[56:72]), uuid.UUID(bytes_le=e[16:32]), uuid.UUID(bytes_le=e[144:160])]
stick = [mkdisk.DISK_GUID, mkdisk.ESP_GUID, mkdisk.DATA_GUID]
print(' '.join('differ' if a != b else 'same' for a, b in zip(mine, stick)))")"
    compare "the host: the EFI partition (scripts/fat.py)" "FAT ok" "$(python3 "$ROOT/scripts/fat.py" check "$target" 2048)"
    compare "the host: the bootloader at the fallback path" \
            "$(shasum -a 256 <"$ROOT/build/esp/EFI/BOOT/$boot_file")" \
            "$(python3 "$ROOT/scripts/fat.py" cat "$target" 2048 "/EFI/BOOT/$boot_file" | shasum -a 256)"
    compare "the host: the command line (no selftest)" "" \
            "$(python3 "$ROOT/scripts/fat.py" cat "$target" 2048 /ritteros/cmdline.txt | tr -d '\n')"
    count=$((last - 133120 + 1))
    compare "the host: the new RitterFS (scripts/ritterfs.py)" "all checksums ok, bitmap consistent" \
            "$($RFS check "$target" 133120 $count | tail -1 | sed 's/.*; //')"
    compare "the host: / holds the system, the Unix folders (57b) and the test's efivar" \
            "$({ printf '     <dir>  system/\n     <dir>  usr/\n     <dir>  tmp/\n%10s  efivar\n' \
                        "$(stat -f %z "$ROOT/build/system/$ARCH_NAME/test/efivar")"
                 printf '    <link>  %s\n' "bin -> /system/$ARCH_NAME/bin" "lib -> /system/$ARCH_NAME/lib" \
                        'etc -> /system/config'; } | sort)" \
            "$($RFS ls "$target" 133120 $count / | sort)"
    compare "the host: /system holds this architecture, config, fonts, certs, firmware, include, sdk, doc" \
            "$(printf '     <dir>  %s/\n     <dir>  config/\n     <dir>  fonts/\n     <dir>  certs/\n     <dir>  firmware/\n     <dir>  include/\n     <dir>  sdk/\n     <dir>  doc/' \
                      "$ARCH_NAME" | sort)" \
            "$($RFS ls "$target" 133120 $count /system | sort)"
    compare "the host: the SDK on the machine, the same (63f)" "$(cat "$ROOT/sdk/ritteros.mk" | shasum -a 256)" \
            "$($RFS cat "$target" 133120 $count /system/sdk/ritteros.mk | shasum -a 256)"
    # (37e-1b) no settings files: the new system writes its own at its
    # first start (never the running system's: its sudo names its users)
    compare "the host: /system/config holds only its README" \
            "$(printf '%10d  README' "$($RFS cat "$target" 133120 $count /system/config/README | wc -c)")" \
            "$($RFS ls "$target" 133120 $count /system/config)"
    compare "the host: the root certificates, the same" "$(shasum -a 256 <"$ROOT/certs/cacert.pem")" \
            "$($RFS cat "$target" 133120 $count /system/certs/cacert.pem | shasum -a 256)"
    compare "the host: the Wi-Fi firmware, the same" \
            "$(cat "$ROOT"/firmware/*.bin | shasum -a 256)" \
            "$(for f in WIFI_MT7961_patch_mcu_1_2_hdr.bin WIFI_RAM_CODE_MT7961_1.bin; do $RFS cat "$target" 133120 $count /system/firmware/$f; done | shasum -a 256)"
    names=$($RFS ls "$target" 133120 $count "/system/$ARCH_NAME/bin" | awk '{print $2}' | sort)
    compare "the host: every program, no test programs" "$(ls "$ROOT/build/system/$ARCH_NAME/bin" | sort)" "$names"
    compare "the host: the kernel, the same" "$(shasum -a 256 <"$ROOT/build/system/$ARCH_NAME/kernel.elf")" \
            "$($RFS cat "$target" 133120 $count "/system/$ARCH_NAME/kernel.elf" | shasum -a 256)"
    compare "the host: the programs, the same" \
            "$(cd "$ROOT/build/system/$ARCH_NAME/bin" && cat $(ls | sort) | shasum -a 256)" \
            "$(for f in $names; do $RFS cat "$target" 133120 $count "/system/$ARCH_NAME/bin/$f"; done | shasum -a 256)"
    appnames=$($RFS ls "$target" 133120 $count "/system/$ARCH_NAME/apps" | awk '{print $2}' | sed 's|/$||' | sort)
    compare "the host: the windowed apps installed" "$(ls "$ROOT/build/system/$ARCH_NAME/apps" | sort)" "$appnames"
    local appfiles                                  # (42b) every file of every bundle
    appfiles=$(cd "$ROOT/build/system/$ARCH_NAME/apps" && find . -type f | sed 's|^\./||' | LC_ALL=C sort)
    compare "the host: the apps, the same" \
            "$(cd "$ROOT/build/system/$ARCH_NAME/apps" && cat $appfiles | shasum -a 256)" \
            "$(for f in $appfiles; do $RFS cat "$target" 133120 $count "/system/$ARCH_NAME/apps/$f"; done | shasum -a 256)"
    local modules                                   # (the kernel's modules, 67a: copied since 42b's fix)
    modules=$($RFS ls "$target" 133120 $count "/system/$ARCH_NAME/drivers" | awk '{print $2}' | sort)
    compare "the host: the drivers installed" "$(ls "$ROOT/build/system/$ARCH_NAME/drivers" | sort)" "$modules"
    compare "the host: the drivers, the same" \
            "$(cd "$ROOT/build/system/$ARCH_NAME/drivers" && cat $(ls | sort) | shasum -a 256)" \
            "$(for f in $modules; do $RFS cat "$target" 133120 $count "/system/$ARCH_NAME/drivers/$f"; done | shasum -a 256)"
    reject "panic"
    show_log_on_failure $before

    # The installed disk alone.
    before=$failures
    local saved_logd="$LOGD"
    LOGD=on
    SERIAL_SCRIPT=osinstalled_session
    # No bootindex: QEMU then gives the firmware no boot order of its own,
    # and the firmware follows its variables (osinstall's entry first).
    if [ "$ARCH_NAME" = x86_64 ]; then
        QEMU_CMD="${QEMU_CMD/-drive if=none,id=disk0,format=raw,file=$DISK -device nvme,drive=disk0,serial=RITTEROS0001,bootindex=0/}"
        QEMU_EXTRA="-drive if=none,id=target,format=raw,file=$target -device ide-hd,drive=target,bus=ide.0"
    else
        QEMU_CMD="${QEMU_CMD/,bootindex=0/}"
    fi
    boot ${P}osinstalled "$target" "RitterOS kernel: boot complete"
    QEMU_CMD="$saved"
    QEMU_EXTRA=
    SERIAL_SCRIPT=
    LOGD="$saved_logd"
    local system_disk=$OSINSTALL_DISK
    [ "$ARCH_NAME" = aarch64 ] && system_disk=nvme0n1
    expect_line "  system partition: ${system_disk}p2, where the bootloader found the kernel"
    expect "self-tests:    skipped"
    expect_line "The password for root is set."
    expect "[root logged in]"
    local listed
    listed=$(command_output 'ls /system')
    check "the installed system: /system holds $ARCH_NAME and config, no other architecture" \
          "the installed system: /system is '$(tr '\n' '|' <<<"$listed")'" \
          eval 'grep -qxF "     <dir>  $ARCH_NAME/" <<<"$listed" && grep -qxF "     <dir>  config/" <<<"$listed" &&
                ! grep -qE "x86_64|aarch64" <<<"$(grep -vxF "     <dir>  $ARCH_NAME/" <<<"$listed")"'
    compare "the installed system: its kernel, programs, apps, libraries and drivers, no test programs" \
            "$(printf '     <dir>  apps/\n     <dir>  bin/\n     <dir>  drivers/\n     <dir>  lib/\n%10s  kernel.elf' "$(stat -f %z "$ROOT/build/system/$ARCH_NAME/kernel.elf")" | sort)" \
            "$(command_output "ls /system/$ARCH_NAME" | sort)"
    expect_line "BootCurrent: ${entry#Boot}"
    expect_line "$entry_line"
    # (37e-1b) its first start wrote its settings files, with their defaults
    expect_line "  settings:      missing, written with their defaults: cpu, power, displays, swap (/system/config)"
    local setting
    for setting in CPU POWER DISPLAYS SWAP TIME SERVICES SUDO; do
        compare "the installed system: $(settings_path $setting) written with its defaults" \
                "$(settings_hash $setting)" \
                "$($RFS cat "$target" 133120 $count "$(settings_path $setting)" | shasum -a 256)"
    done
    reject "panic"
    show_log_on_failure $before
}

# settings_session_1, _2 / settings_test (37e-1b, the user's rule): every
# settings file is written with its defaults (common/settings_defaults.h)
# by whoever reads it, when it is missing. A new disk has none: its first
# start writes the kernel's four (cpu, power, displays, swap) after the
# boot's check, and login time, services and sudo (net up's routing:
# dhcp_shell_test, a machine with a card). The session removes
# power, swap, time and root's ~/.config/windows, adds a line to
# cpu, starts windowd (it writes the user's windows file back) and sets the
# country with no radio file (wifi starts from its default text). The
# second start writes exactly power and swap again, leaves cpu as it was,
# and login writes time again; the host compares every file with its text.
# Proven by a kernel that writes nothing, a login without its three files,
# a windowd that does not write the user's file and a wifi that writes only
# its own line.
settings_session_1() {
    local n=1
    prompt_wait $n
    answer_lines 'rm /home/root/.config/windows'
    serial_type 'windowd &\r'
    n=$((n + 1))
    serial_wait "windowd: listening on /run/windowd" 1 15
    # windowd's own file kept aside before the next start: login writes a
    # missing ~/.config file too, at every login
    # (42a) the user's file types: written back by window_app_for (open's
    # lookup), kept aside, then removed again for login to write
    answer_lines 'rm /home/root/.config/filetypes' 'open /system/doc/manual.md' \
                 'cp /home/root/.config/filetypes /home/root/filetypes-by-open' \
                 'rm /home/root/.config/filetypes'
    answer_lines 'kill $!' 'cp /home/root/.config/windows /home/root/windows-by-windowd' \
                 'echo "# mine" >> /system/config/cpu' 'rm /system/config/power' \
                 'rm /system/config/swap' 'rm /system/config/time' \
                 'wifi country de' 'ls /system/config' 'ls /system/config/wifi'
}

settings_session_2() {
    local n=1
    prompt_wait $n
    answer_lines 'ls /system/config'
}

settings_test() {
    local image before setting
    image=$(make_image ${P}settings "")
    before=$failures
    SERIAL_SCRIPT=settings_session_1
    boot ${P}settings-1 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect_line "  settings:      missing, written with their defaults: cpu, power, displays, swap (/system/config)"
    expect_line "wifi: country DE (saved; takes effect when wifid restarts)"
    reject "panic"
    show_log_on_failure $before
    before=$failures
    SERIAL_SCRIPT=settings_session_2
    boot ${P}settings-2 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect_line "  settings:      missing, written with their defaults: power, swap (/system/config)"
    expect "cpu:           clock = performance (/system/config/cpu): "
    for setting in POWER DISPLAYS SWAP TIME SERVICES SUDO; do
        compare "$(settings_path $setting): its default text" "$(settings_hash $setting)" \
                "$($RFS cat "$image" $RFS_PART "$(settings_path $setting)" | shasum -a 256)"
    done
    compare "/system/config/cpu: kept as changed (its text and the line added)" \
            "$({ python3 "$ROOT/scripts/settingstext.py" CPU; echo '# mine'; } | shasum -a 256)" \
            "$($RFS cat "$image" $RFS_PART /system/config/cpu | shasum -a 256)"
    compare "/system/config/wifi/radio: its default text with the country set" \
            "$(python3 "$ROOT/scripts/settingstext.py" WIFI_RADIO | sed 's/^country = 00$/country = DE/' | shasum -a 256)" \
            "$($RFS cat "$image" $RFS_PART /system/config/wifi/radio | shasum -a 256)"
    compare "/home/root/.config/windows: written back by windowd (the user's own; copied before the second start)" \
            "$(settings_hash USER_WINDOWS)" \
            "$($RFS cat "$image" $RFS_PART /home/root/windows-by-windowd | shasum -a 256)"
    compare "/home/root/.config/filetypes: written back by window_app_for (open's lookup; 42a)" \
            "$(settings_hash USER_FILETYPES)" \
            "$($RFS cat "$image" $RFS_PART /home/root/filetypes-by-open | shasum -a 256)"
    compare "/home/root/.config/filetypes: written by login when missing (42a)" \
            "$(settings_hash USER_FILETYPES)" \
            "$($RFS cat "$image" $RFS_PART /home/root/.config/filetypes | shasum -a 256)"
    reject "panic"
    show_log_on_failure $before
}

# config_session: /system/config (config_shell_test).
config_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test/configget" f=/home/root/net
    prompt_wait $n
    answer_lines 'ls /system/config' 'cat /system/config/users' 'ls /system' \
                 "echo '# the network' > $f" "echo 'address = dhcp' >> $f" \
                 "echo '  dns  =  1.1.1.1  ' >> $f" "echo 'name=box' >> $f" \
                 "$t $f address" "$t $f dns" "$t $f name" "$t $f gateway" "$t /nope address"
}

# logs_session: the logs (logs_shell_test).
logs_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test/logtest"
    prompt_wait $n
    serial_type 'cat\r'                             # a line typed for a program: the kernel echoes it
    sleep 1
    serial_type 'typed-secret\r'
    sleep 1
    serial_type '\004'
    n=$((n + 1))
    prompt_wait $n
    answer_lines 'echo secret-word' "$t as mylog hello-log" "$t write other a-line" \
                 "$t write big rotate-me" "$t fill flood 20000" "$t term" \
                 'elf add chatty echo chatty-line'
    serial_wait "elvesd: chatty ended (exit code 0)" 1 20
    answer_lines '' 'elf remove chatty'
    sleep 11                                        # logd writes every 10 s
    answer_lines '' 'cat /system/logs/kernel.log' 'cat /system/logs/login.log' \
                 'cat /system/logs/mylog.log' 'cat /system/logs/other.log' 'cat /system/logs/chatty.log' \
                 'cat /system/logs/elvesd.log' 'ls /system/logs/big.log' 'ls /system/logs/big.log.old' \
                 'cat /system/logs/big.log' 'cat /system/logs/flood.log' \
                 "$t write last last-words" 'elf stop logd'
    serial_wait "elvesd: logd stopped" 1 20
    sleep 1
    answer_lines '' 'cat /system/logs/last.log' 'ls /system/logs'
}

# logs_shell_test: the logs (45b-45c): logd writes /system/logs/NAME.log;
# the kernel's messages from its first line, each with its time, without a
# line typed for cat (the kernel's echo) or programs' output; login's
# line; a program's output in the log it named, a written line; an elf's
# output in its own log, elvesd's lines in elvesd's; a log past 64 KiB
# becomes NAME.log.old; a full ring's loss noted; asked to stop, logd
# writes what is left first; SIGTERM ignored interrupts a sleep.
logs_shell_test() {
    local image before t="/system/$ARCH_NAME/test/logtest" kernel
    LOGD=on
    image=$(make_image ${P}logs "")
    head -c 65530 /dev/zero | tr '\0' 'x' >"$WORK/${P}biglog"
    $RFS put "$image" $RFS_PART /system/logs/big.log "$WORK/${P}biglog" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=logs_session
    boot ${P}logs "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    LOGD=
    expect_line "login: /system/config/elves/logd made: the elf logd keeps the logs in /system/logs"
    kernel=$(command_output 'cat /system/logs/kernel.log')
    check "kernel.log: the boot, dated" "$(head -3 <<<"$kernel" | tr '\n' '|')" \
          eval 'grep -Eq "^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2} .*boot complete" <<<"$kernel"'
    check "kernel.log: its first line, before the clock" "$(head -1 <<<"$kernel")" \
          eval 'head -1 <<<"$kernel" | grep -Eq "^boot \+0\.[0-9]{2} s RitterOS kernel started"'
    check "kernel.log: neither typed text nor programs' output" \
          "$(grep -E "secret|login: *$" <<<"$kernel" | tr '\n' '|')" \
          eval '! grep -q "secret" <<<"$kernel" && ! grep -Eq "login: *$" <<<"$kernel"'
    check "login.log: root's login" "$(command_output 'cat /system/logs/login.log')" \
          eval 'command_output "cat /system/logs/login.log" | grep -Eq "^[0-9-]{10} [0-9:]{8} root logged in on the console$"'
    check "a program's output in the log it named" "$(command_output 'cat /system/logs/mylog.log')" \
          eval 'command_output "cat /system/logs/mylog.log" | grep -Eq "^[0-9-]{10} [0-9:]{8} hello-log$"'
    check "a written line" "$(command_output 'cat /system/logs/other.log')" \
          eval 'command_output "cat /system/logs/other.log" | grep -Eq "^[0-9-]{10} [0-9:]{8} a-line$"'
    check "an elf's output in its log" "$(command_output 'cat /system/logs/chatty.log' | head -2 | tr '\n' '|')" \
          eval 'command_output "cat /system/logs/chatty.log" | grep -Eq "^[0-9-]{10} [0-9:]{8} chatty-line$"'
    check "elvesd's lines in its log" "$(command_output 'cat /system/logs/elvesd.log' | head -2 | tr '\n' '|')" \
          eval 'command_output "cat /system/logs/elvesd.log" | grep -Eq "^[0-9-]{10} [0-9:]{8} elvesd: logd started \(process [0-9]+\)$"'
    compare "past 64 KiB: the old log kept as big.log.old" "     65530  /system/logs/big.log.old" \
            "$(command_output 'ls /system/logs/big.log.old')"
    check "and a new big.log begun" "$(command_output 'cat /system/logs/big.log')" \
          eval 'command_output "cat /system/logs/big.log" | grep -Eq "^[0-9-]{10} [0-9:]{8} rotate-me$"'
    check "a full ring: the loss noted" "$(command_output 'cat /system/logs/flood.log' | head -2 | tr '\n' '|')" \
          eval 'command_output "cat /system/logs/flood.log" | head -1 | grep -Eq "^\([0-9]+ bytes lost here: the log was full\)$"'
    check "stopped, logd wrote what was left first" "$(command_output 'cat /system/logs/last.log')" \
          eval 'command_output "cat /system/logs/last.log" | grep -Eq "^[0-9-]{10} [0-9:]{8} last-words$"'
    expect_line "logtest: SIGTERM interrupted the sleep"
    expect_line "logtest: the child ended with exit code 0"
    reject "panic"
    show_log_on_failure $before
}

# syntax_session: ';' and '*' typed into the shell (syntax_shell_test).
syntax_session() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines 'echo one; echo two' 'cd /test; pwd' 'echo /test/*.txt' 'echo /system/*/bin/sh' \
                 'echo /test/*/' 'echo t*' 'echo nomatch*' "echo '*'" 'echo /test/many/*' \
                 'echo many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* | wc -w' 'echo many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/*' \
                 "sh -c 'exec echo many/*' | wc -w" "echo '#!/bin/sh' > /tmp/args" \
                 "echo 'echo \$#' >> /tmp/args; chmod 755 /tmp/args; /tmp/args many/*" \
                 'uptime; echo after' 'echo a;;echo b;' \
                 'echo first' 'echo second' '\033[A\033[A' 'echo abd\033[Dc' 'cho home\033[He' \
                 'cho en\033[He\033[Fd' 'echo xyz\033[D\033[D\033[3~' 'echo abX\033[D\177' \
                 'echo dr\033[A\033[B\033[Dx'
}

# syntax_shell_test: commands one after the other (';'), names matching
# '*' (in one part of a path, in several, directories only with a
# trailing '/', relative to the current directory; no match and quotes
# leave the word as typed; (37g-5a-2) up to 4096 words through the shell,
# spawn, exec and a #! script, more refused), uptime. Proven by the
# kernel's ARGC_MAX left at 128 (echo of 301 words: Argument list too
# long) and by its pointers' first page not grown when they do not fit.
syntax_shell_test() {
    local image before
    image=$(make_image ${P}syntax "")
    before=$failures
    SERIAL_SCRIPT=syntax_session
    boot ${P}syntax "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    compare "echo one; echo two" "$(printf 'one\ntwo')" "$(command_output 'echo one; echo two')"
    compare "cd /test; pwd" "/test" "$(command_output 'cd /test; pwd')"
    compare "* in the last part (sorted; a name with a space and UTF-8)" \
            "/test/Grüße ☃.txt /test/empty.txt /test/hello.txt /test/manifest.txt" \
            "$(command_output 'echo /test/*.txt')"
    compare "* in a middle part" "/system/$ARCH_NAME/bin/sh" \
            "$(command_output 'echo /system/*/bin/sh')"
    compare "*/: directories only" "/test/data/ /test/docs/ /test/many/ /test/text/" \
            "$(command_output 'echo /test/*/')"
    compare "* relative to the current directory" "text" "$(command_output 'echo t*')"
    compare "no match: as typed" "nomatch*" "$(command_output 'echo nomatch*')"
    compare "quoted: as typed" "*" "$(command_output "echo '*'")"
    compare "300 names, sorted" "$(printf '/test/many/file-%03d\n' $(seq 0 299) | paste -sd ' ' -)" \
            "$(command_output 'echo /test/many/*')"
    compare "3,900 words to a program (55 KB: past a page of pointers and of strings)" "3900" \
            "$(command_output 'echo many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* | wc -w' | tr -d ' ')"
    compare "4,200 names: too many" "sh: many/*: too many names (at most 4096 words)" \
            "$(command_output 'echo many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/* many/*')"
    compare "300 words through exec" "300" \
            "$(command_output "sh -c 'exec echo many/*' | wc -w" | tr -d ' ')"
    compare "300 words to a #! script (spawn puts its interpreter first)" "300" \
            "$(command_output "echo 'echo \$#' >> /tmp/args; chmod 755 /tmp/args; /tmp/args many/*")"
    check "uptime; echo after" "$(command_output 'uptime; echo after' | tr '\n' '|')" \
          eval 'command_output "uptime; echo after" | head -1 | grep -Eq "^up [0-9]+\.[0-9]{2} s \([0-9]+ timer ticks at 100 Hz\)$" &&
                [ "$(command_output "uptime; echo after" | tail -1)" = after ]'
    compare "empty commands are skipped" "$(printf 'a\nb')" "$(command_output 'echo a;;echo b;')"
    # The line editor (44l).
    check "Up, Up: the command before the last one again" "'first' $(grep -cx first <<<"$TEXT") time(s)" \
          test "$(grep -cx first <<<"$TEXT")" = 2
    expect_line "abcd"                              # Left, then typed in the middle
    expect_line "home"                              # Home, then typed at the start
    expect_line "end"                               # Home and typed, End and typed
    expect_line "xz"                                # Delete under the cursor
    expect_line "aX"                                # Backspace in the middle
    expect_line "dxr"                               # Up, Down: the half-typed line back
    reject "panic"
    show_log_on_failure $before
}

# config_shell_test: /system/config. A disk in the layout from before
# (users and passwords in /system, made on the host with root's password
# and a user anna): login moves both into /system/config, root's password
# still works, nothing is left behind; the README is there. The reader of
# "key = value" files (config_get) on a file written in the shell.
config_shell_test() {
    local image before hash
    image=$(make_image ${P}configshell "")
    hash=$(python3 -c "
import hashlib
salt = bytes(range(16))
print('root:100000:' + salt.hex() + ':' +
      hashlib.pbkdf2_hmac('sha256', b'$ROOT_PASSWORD', salt, 100000).hex())")
    printf '%s\n' "$hash" >"$WORK/${P}oldpasswords"
    printf 'anna:1000:1000:/home/anna\n' >"$WORK/${P}oldusers"
    # (64t) The processor's clock setting, written unusually: the kernel
    # reads it at the start (QEMU's processors have no CPPC, so it is not
    # used, but the value read is named; without the file: performance).
    printf '# fastest\n\t  clock\t=  top   # (a comment)\n' >"$WORK/${P}cpu"
    $RFS put "$image" $RFS_PART /system/passwords "$WORK/${P}oldpasswords" >/dev/null &&
        $RFS put "$image" $RFS_PART /system/users "$WORK/${P}oldusers" >/dev/null &&
        $RFS put "$image" $RFS_PART /system/config/cpu "$WORK/${P}cpu" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=config_session
    boot ${P}configshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "cpu:           clock = top (/system/config/cpu): not used, this processor's clock is the firmware's"
    reject "first start"                            # root's password was there
    expect_line "login: /system/users moved to /system/config/users"
    expect_line "login: /system/passwords moved to /system/config/passwords"
    # (37e-1b) with the settings files the start wrote (the kernel's after
    # its check, login's), in the order written: sorted here
    compare "/system/config: README, cpu (64t, the test's), elves/ (the test image's), users, passwords (moved), the settings files written at the start (no card: no net up, no routing)" \
            "$({ printf '%10d  README\n%10d  cpu\n     <dir>  elves/\n%10d  users\n%10d  passwords\n' \
                     "$($RFS cat "$image" $RFS_PART /system/config/README | wc -c)" \
                     "$($RFS cat "$image" $RFS_PART /system/config/cpu | wc -c)" 26 "$((${#hash} + 1))"
                 for setting in POWER DISPLAYS SWAP TIME SERVICES SUDO; do
                     printf '%10d  %s\n' "$(python3 "$ROOT/scripts/settingstext.py" $setting | wc -c)" \
                            "$(settings_path $setting | sed 's|^/system/config/||')"
                 done; } | LC_ALL=C sort)" \
            "$(command_output 'ls /system/config' | LC_ALL=C sort)"
    compare "the users file moved" "anna:1000:1000:/home/anna" \
            "$(command_output 'cat /system/config/users')"
    check "nothing left in /system" "$(command_output 'ls /system' | tr '\n' '|')" \
          eval '! command_output "ls /system" | grep -qE " (users|passwords)$"'
    expect_line "configget: address = 'dhcp'"
    expect_line "configget: dns = '1.1.1.1'"
    expect_line "configget: name = 'box'"
    expect_line "configget: gateway: not set"
    expect_line "configget: /nope: No such file or directory"
    reject "panic"
    show_log_on_failure $before
}

# net_session: the network (net_shell_test).
net_session() {
    local n=1 asked=0
    prompt_wait $n
    dnsd_wait
    answer_lines 'net' 'cat /system/config/network/eth0' 'ping 10.0.2.2' 'ping -c 2 10.0.2.15' 'ping -c 1 127.0.0.1' \
                 'ping -c 1 10.0.2.99' 'ping nope' 'ping -c 1 gateway.test' \
                 'ping -c 1 Alias.Test' 'ping -c 1 localhost' 'ping -c 1 gateway.test' \
                 'ping -6 -c 1 10.0.2.2' 'ping -4 -c 1 ::1' 'ping -4 -c 1 localhost' 'net'
    serial_type 'exit\r'
    login_wait 2
    serial_type '\004'                              # Ctrl-D at login: the rescue console
    n=$((n + 1))
    prompt_wait $n
    serial_type 'net\r'
    n=$((n + 1))
    prompt_wait $n
}

# net_shell_test: the network on QEMU's user network (its gateway
# 10.0.2.2 answers ARP and ping): the e1000 card found (MAC, link),
# /system/config/network (put on the disk by the host as a single file, as
# before step 42d: net up moves it into /system/config/network/eth0)
# applied by login at the start, ping to the gateway (through ARP), to our own address and
# 127.0.0.1 (the loopback: our echo replies), to an address nobody has, a
# name nobody knows; names through DNS (a test server on the Mac, set as
# dns = 10.0.2.2:PORT): an A record, a CNAME (in other letter case),
# localhost, and the cache (asked once only); net shows the settings,
# counters and the ARP cache, as the rescue console does.
net_shell_test() {
    local image before dns
    image=$(make_image ${P}netshell "")
    printf 'address = 10.0.2.15/24\ngateway = 10.0.2.2\ndns = 10.0.2.2:%s\n' $NET_DNS_PORT \
           >"$WORK/${P}network"
    $RFS put "$image" $RFS_PART /system/config/network "$WORK/${P}network" >/dev/null || exit 1
    python3 "$ROOT/scripts/testdns.py" $NET_DNS_PORT gateway.test=10.0.2.2 'alias.test>gateway.test' \
            >"$WORK/${P}testdns.log" 2>&1 &
    dns=$!
    host_service_wait "$WORK/${P}testdns.log" listening
    QEMU_EXTRA="-netdev user,id=net0 -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=net_session
    boot ${P}netshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $dns 2>/dev/null
    wait $dns 2>/dev/null
    expect_link 52:54:00:12:34:56 1000
    expect_line "net: /system/config/network: moved into one file per card in /system/config/network/ (forward: /system/config/routing)"
    compare "the settings moved into eth0's file" \
            "$(printf 'address = 10.0.2.15/24\ngateway = 10.0.2.2\ndns = 10.0.2.2:%s' $NET_DNS_PORT)" \
            "$(command_output 'cat /system/config/network/eth0')"
    expect_line "net: eth0: 10.0.2.15/24, gateway 10.0.2.2, DNS 10.0.2.2:$NET_DNS_PORT"
    check "ping 10.0.2.2: four answers" \
          "$(command_output 'ping 10.0.2.2' | grep -c '^64 bytes from 10.0.2.2: seq=[1-4] time=') answer(s)" \
          test "$(command_output 'ping 10.0.2.2' | grep -c '^64 bytes from 10.0.2.2: seq=[1-4] time=')" = 4
    expect "--- 10.0.2.2: 4 sent, 4 received, 0% lost; round trip min/avg/max "
    expect "--- 10.0.2.15: 2 sent, 2 received, 0% lost"
    expect "--- 127.0.0.1: 1 sent, 1 received, 0% lost"
    expect_line "seq=1: No route to host"
    expect_line "--- 10.0.2.99: 1 sent, 0 received, 100% lost"
    expect_line "ping: nope: Name not found"
    expect_line "PING gateway.test (10.0.2.2): 56 data bytes"
    expect_line "PING Alias.Test (10.0.2.2): 56 data bytes"
    # (64d) Names as every program takes them: IPv6 first (QEMU's router
    # gave eth0 an fec0:: address), so localhost is ::1 (-4: 127.0.0.1); an
    # address keeps its family, a flag of the other family refuses it.
    compare "localhost: the loopback, without DNS" "PING localhost (::1): 56 data bytes" \
            "$(command_output 'ping -c 1 localhost' | head -1)"
    compare "localhost with -4" "PING localhost (127.0.0.1): 56 data bytes" \
            "$(command_output 'ping -4 -c 1 localhost' | head -1)"
    expect_line "ping: 10.0.2.2: not an IPv6 address"
    expect_line "ping: ::1: not an IPv4 address"
    check "gateway.test answered twice (the second from the cache)" \
          "$(command_output 'ping -c 1 gateway.test' 2 | grep -c '^64 bytes from 10.0.2.2:') answer(s)" \
          test "$(command_output 'ping -c 1 gateway.test' 2 | grep -c '^64 bytes from 10.0.2.2:')" = 1
    want_text want <<'LINES'
question nope type 28: no such name
question nope type 1: no such name
question gateway.test type 28: no records
question gateway.test type 1: answered
question Alias.Test type 28: no records
question Alias.Test type 1: answered
LINES
    compare "the DNS server's questions (each once a name: since 64k no records is kept too)" "$want" \
            "$(grep '^question' "$WORK/${P}testdns.log")"
    expect_line "       address 10.0.2.15/24, gateway 10.0.2.2, DNS 10.0.2.2:$NET_DNS_PORT"
    expect_line "arp: 10.0.2.2        is 52:55:0a:00:02:02"
    expect_line "lo     the loopback, 127.0.0.1/8"
    expect_line "route: 10.0.2.0/24 on eth0"
    expect_line "route: default via 10.0.2.2 on eth0"
    compare "the rescue console's net: the same card" "$(command_output 'net' 2 | grep -A1 '^eth0')" \
            "$(command_output 'net' 3 | grep -A1 '^eth0')"
    reject "panic"
    show_log_on_failure $before
}

# tap_session: virtual cards (tap_shell_test).
tap_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test/taptest"
    prompt_wait $n
    answer_lines 'net tap add user nobody' 'net tap add' 'net tap add' 'ls /dev' 'net up'
    serial_wait " rule(s) loaded (in = " 1 30     # guardd's: until then nothing comes in
    answer_lines '' 'ls /system/config/network' \
                 "$t tap0 192.168.77.2 6 & sleep 1; ping -c 3 192.168.77.2; sleep 6" 'net' \
                 "$t open tap0" 'guard insert 1 drop out icmp on tap0' \
                 "sleep 3; $t tap0 192.168.77.2 4 & sleep 1; ping -c 2 192.168.77.2; sleep 3" 'guard' \
                 'guard remove 1' 'guard add allow forward icmp in eth0 out br3' 'sleep 3; guard' 'guard remove 4' \
                 "$t tap0 192.168.77.2 3 & sleep 1; net tap remove tap0; sleep 3" \
                 'net tap remove tap1' 'net tap remove tap1' 'net tap remove tap7' 'ls /dev' \
                 'net tap add' 'net tap remove tap0' 'net' 'rm /system/config/network/tap0' 'net up'
}

# tap_shell_test (38a): virtual cards on a machine without a card. net tap
# add makes tap0 and tap1 (root's: /dev/tapN), net up gives tap0 the
# address its settings file says (the host wrote it; a tap gets none made)
# and taptest, holding /dev/tap0, is 192.168.77.2 there: it answers ARP
# and the stack's pings, and the frame it wrote for another MAC is dropped
# (counted in net). The link is up while it holds the card, down after;
# a second open is refused, as is another user's; a tap held open is not
# removed; a removed one leaves /dev and net, and its number is the next
# one made.
tap_shell_test() {
    local image before mac line
    image=$(make_image ${P}tap "")
    printf 'address = 192.168.77.1/24\n' >"$WORK/${P}tap0"
    $RFS put "$image" $RFS_PART /system/config/network/tap0 "$WORK/${P}tap0" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=tap_session
    boot ${P}tap "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect_line "net: nobody: no such user"
    expect_line "net: tap0: a virtual card; /dev/tap0 is root's"
    expect_line "net: tap1: a virtual card; /dev/tap1 is root's"
    expect "tap0: a virtual card for user 0, MAC "
    compare "/dev lists the taps" "tap0|tap1|" \
            "$(command_output 'ls /dev' | awk '$NF ~ /^tap/ { print $NF }' | tr '\n' '|')"
    expect_line "net: tap0: 192.168.77.1/24, gateway none, DNS none"
    # (38b-3) a tap's settings file as any card's: tap1 had none, net up made it
    expect_line "net: tap1: /system/config/network/tap1 made (address = dhcp)"
    compare "net up made tap1's settings file as any card's" "tap0|tap1|" \
            "$(command_output 'ls /system/config/network' | awk '$NF ~ /^tap/ { print $NF }' | tr '\n' '|')"
    expect_line "taptest: tap0: 192.168.77.2 is 02:00:00:00:00:02"
    line=$(grep -ac '^64 bytes from 192.168.77.2: seq=[1-3] time=' <<<"$TEXT")
    check "three pings answered by the program on tap0" "$line answer(s)" test "$line" = 3
    expect "--- 192.168.77.2: 3 sent, 3 received, 0% lost"
    line=$(grep -a '^taptest: tap0: [0-9]* frame(s) read' <<<"$TEXT" | head -1)
    check "taptest answered one ARP request and three pings: $line" "taptest: '$line'" \
          eval '[[ "$line" =~ ^taptest:\ tap0:\ [0-9]+\ frame\(s\)\ read,\ 1\ ARP\ answer\(s\),\ 3\ echo\ answer\(s\) ]]'
    expect_line "tap0: link up, 10000 Mbit/s"
    expect_line "tap0: link down"
    mac=$(grep -ao 'tap0: a virtual card for user 0, MAC [0-9a-f:]*' <<<"$TEXT" | head -1 | sed 's/.* //')
    expect_line "tap0   $mac  no link, virtual card (tap at /dev/tap0)"
    expect_line "       address 192.168.77.1/24, gateway none, DNS none"
    expect_line "       the program's side: /dev/tap0, user 0, not open; 0 bytes waiting, 1 frame(s) for other cards dropped"
    expect_line "taptest: first open: ok"
    expect_line "taptest: second open: Device or resource busy"
    expect_line "taptest: open as uid 4242: Permission denied"
    # (38b) the firewall's rules name taps and bridges: a rule on tap0 stops
    # the pings, its drops say tap0; a forward rule names br3
    expect "--- 192.168.77.2: 2 sent, 0 received, 100% lost"
    line=$(command_output 'guard' 1 | grep '^  1  drop out icmp on tap0 ')
    check "guard: the rule on tap0 dropped the two pings: $line" "guard: '$line'" \
          eval '[[ "$line" =~ ^\ \ 1\ \ drop\ out\ icmp\ on\ tap0\ +2\ packet\(s\)$ ]]'
    expect "  out icmp from 192.168.77.1 to 192.168.77.2 on tap0 (rule 1)"
    expect_line "guard: rule 4: allow forward icmp in eth0 out br3; guardd loads it within 2 s"
    line=$(command_output 'sleep 3; guard' | grep '^  4  ')
    check "guard reads the forward rule on br3 back: $line" "guard: '$line'" \
          eval '[[ "$line" =~ ^\ \ 4\ \ allow\ forward\ icmp\ in\ eth0\ out\ br3\ +0\ packet\(s\)$ ]]'
    expect_line "net: tap0: a program has it open"
    expect_line "net: tap1 removed"
    expect_line "net: tap1: no such virtual card"
    expect_line "net: tap7: no such virtual card"
    compare "/dev without tap1" "tap0|" \
            "$(command_output 'ls /dev' 2 | awk '$NF ~ /^tap/ { print $NF }' | tr '\n' '|')"
    compare "the next tap made is tap1 again" "net: tap1: a virtual card; /dev/tap1 is root's" \
            "$(command_output 'net tap add' 3 | grep '^net:')"
    expect_line "net: tap0 removed"
    compare "net lists only tap1 now" "tap1" \
            "$(command_output 'net' 2 | grep -o '^tap[0-9]*')"
    # (38d) a removed tap is no card for net up: no settings file made for it
    reject "net: tap0: /system/config/network/tap0 made"
    reject "panic"
    show_log_on_failure $before
}

# bridge_session: a bridge of a real card and two taps (bridge_test).
bridge_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test/taptest"
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    answer_lines 'net tap add' 'net tap add' 'net bridge add br5 tap0' 'net bridge add eth0 tap0 tap1' \
                 'net bridge add br0 eth0' 'net bridge add br0 tap5' 'net bridge add br0 lo' 'net up'
    serial_wait "dhclient: br0: 10.0.2.15/" 1 30
    answer_lines '' 'ping -c 3 10.0.2.2' "net | sed -n '/^br0 /,/link asked/p' | tail -1" \
                 "fetch -o /dev/null http://10.0.2.2:$NET_HTTP_PORT/big.bin" "net | sed -n '/^br0 /,/link asked/p' | tail -1" \
                 'net default br0' 'net default' 'net default auto' \
                 "$t tap1 10.0.2.41 12 & sleep 1; $t tap0 10.0.2.40 5 10.0.2.2; $t tap0 10.0.2.40 5 10.0.2.41; sleep 3" \
                 'net' 'net bridge remove br0 tap1' 'net bridge remove br0 tap1' 'net bridge remove br0'
    serial_wait "dhclient: eth0: 10.0.2.15/" 2 30
    answer_lines '' 'ping -c 2 10.0.2.2' 'net' 'net bridge add eth0 tap0'
    # (38d) made again at once (the J1900's br0 got no IPv4 lease then)
    serial_wait "dhclient: br0: 10.0.2.15/" 2 30
    answer_lines '' 'ping -c 2 10.0.2.2'
}

# bridge_test (38b): br0 joins eth0 (QEMU's e1000 on its user network) and
# two taps. br0 takes eth0's MAC address and, through DHCP, its address
# (eth0 itself gives its own up: a port carries no traffic of its own); the
# machine pings the gateway through br0. A program on tap0 with a MAC of
# its own (02:00:00:00:00:28) asks ARP for the gateway and pings it: the
# answers come to the e1000 for that MAC, which only promiscuous mode lets
# in; then it pings the program on tap1 (10.0.2.41): port to port, the
# addresses learned. The refusals: a port twice, no such card, no such
# bridge, lo. Ports leave one by one, then the bridge goes and eth0 asks
# DHCP again by itself. Proven by an e1000 whose set_promiscuous did
# nothing: the gateway's answers to tap0's program never came in.
bridge_test() {
    local image before line web a1 r1 a2 r2
    image=$(make_image ${P}bridge "")
    python3 "$ROOT/scripts/testhttp.py" $NET_HTTP_PORT >"$WORK/${P}testhttp.log" 2>&1 &
    web=$!
    host_service_wait "$WORK/${P}testhttp.log" listening
    QEMU_EXTRA="-netdev user,id=net0 -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=bridge_session
    boot ${P}bridge "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $web 2>/dev/null
    wait $web 2>/dev/null
    expect_line "br0: a bridge, MAC 52:54:00:12:34:56 (eth0's)"
    expect_line "net: br0: a bridge (its MAC address eth0's)"
    expect_line "net: br0: eth0 is its port"
    expect_line "net: br0: tap0 is its port"
    expect_line "net: br0: tap1 is its port"
    expect_line "net: eth0: a bridge's port already"
    expect_line "net: tap5: no such network card"
    expect_line "net: br5: no such bridge"
    expect_line "net: lo: no such network card"
    expect_line "br0: link up, 1000 Mbit/s"
    expect "--- 10.0.2.2: 3 sent, 3 received, 0% lost"
    # (38b-3) a bridge is named as any card: the default route's order
    expect_line "net: the default route: br0, then any card with a gateway"
    expect_line "net: the default route: br0, then any card with a gateway; now via 10.0.2.2 on br0"
    expect_line "net: the default route: the first card with a gateway (auto)"
    expect_line "taptest: tap0: 10.0.2.40 is 02:00:00:00:00:28"
    expect_line "taptest: tap0: 10.0.2.2 is 52:55:0a:00:02:02"
    expect_line "taptest: tap0: 10.0.2.2: 1 ARP question(s), 3 of 3 echo request(s) answered"
    expect_line "taptest: tap0: 10.0.2.41 is 02:00:00:00:00:29"
    expect_line "taptest: tap0: 10.0.2.41: 1 ARP question(s), 3 of 3 echo request(s) answered"
    line=$(grep -a '^taptest: tap1: [0-9]* frame(s) read' <<<"$TEXT" | head -1)
    check "the program on tap1 answered tap0's ARP question and three pings: $line" "taptest: '$line'" \
          eval '[[ "$line" =~ ^taptest:\ tap1:\ [0-9]+\ frame\(s\)\ read,\ 1\ ARP\ answer\(s\),\ 3\ echo\ answer\(s\) ]]'
    expect_line "br0    52:54:00:12:34:56  link up, 1000 Mbit/s, bridge (bridge at its ports)"
    expect "       address 10.0.2.15/24 (DHCP, lease "
    line=$(grep -a '^       bridge: ports ' <<<"$TEXT" | head -1)
    check "net: br0's ports and its counts: $line" "net: '$line'" \
          eval '[[ "$line" =~ ^\ +bridge:\ ports\ eth0\ tap0\ tap1\;\ [3-9]\ address\(es\)\ known\;\ [1-9][0-9]*\ frame\(s\)\ passed\ on ]]'
    expect_line "       a port of br0: its frames are the bridge's"
    # (38d) the stack asks for a card's link several times a packet; net_link
    # asks the driver (often a read of the chip) at most once a tick: over a
    # download of 1,000,000 bytes through br0 (its ACKs ask, some 240 times),
    # br0's driver was read fewer times than it was asked (without that,
    # every time)
    read -r a1 r1 <<<"$(command_output "net | sed -n '/^br0 /,/link asked/p' | tail -1" 1 | sed -E 's/.*asked ([0-9]+) times.*, ([0-9]+) of them.*/\1 \2/')"
    read -r a2 r2 <<<"$(command_output "net | sed -n '/^br0 /,/link asked/p' | tail -1" 2 | sed -E 's/.*asked ([0-9]+) times.*, ([0-9]+) of them.*/\1 \2/')"
    check "the download asked br0's link $((${a2:-0} - ${a1:-0})) times, its driver read $((${r2:-0} - ${r1:-0})) times" \
          "asked ${a1:-?} -> ${a2:-?}, read ${r1:-?} -> ${r2:-?}" \
          eval '[ $((a2 - a1)) -gt 100 ] && [ $((r2 - r1)) -lt $((a2 - a1)) ]'
    expect_line "net: br0: tap1 is no longer its port"
    expect_line "net: tap1: not a port of br0, or no such bridge"
    expect_line "br0: eth0 is no longer its port"
    expect_line "net: br0 removed"
    expect "--- 10.0.2.2: 2 sent, 2 received, 0% lost"
    # (38d) br0 made again at once gets its address by DHCP again: dhclient
    # forgets a lease when its card goes or loses the address (before, it
    # kept the removed br0's lease and asked nothing for hours)
    expect_line "net: br0: a bridge (its MAC address eth0's)"
    check "br0's second lease, after it was made again" \
          "$(grep -ac 'dhclient: br0: 10.0.2.15/' <<<"$TEXT") lease(s)" \
          test "$(grep -ac 'dhclient: br0: 10.0.2.15/' <<<"$TEXT")" -ge 2
    reject "dhclient: eth0: Device or resource busy"
    compare "net after the bridge: eth0 with its address again, no br0" \
            "eth0|       address 10.0.2.15/24 (DHCP, lease 86400 s), gateway 10.0.2.2, DNS 10.0.2.3|" \
            "$(command_output 'net' 2 | grep -A1 '^eth0\|^br0' | grep -v '^eth0 ' | sed 's/^eth0 .*/eth0/' | tr '\n' '|' | sed 's/^/eth0|/')"
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# virtual_session_1..3: virtual_test's three starts.
virtual_session_1() {
    local n=1 asked=0
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    answer_lines 'cat /system/config/network/virtual' 'net tap add' 'net tap add' \
                 'net bridge add eth0 tap0' 'net tap remove tap1' 'cat /system/config/network/virtual'
}
virtual_session_2() {
    local n=1 asked=0
    prompt_wait $n
    serial_wait "dhclient: br0: 10.0.2.15/" 1 30
    answer_lines '' 'ping -c 2 10.0.2.2' 'net bridge remove br0 tap0' 'cat /system/config/network/virtual'
}
virtual_session_3() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines 'net'
}

# virtual_test (38c): /system/config/network/virtual keeps the taps and
# bridges for the next start. The first start's net up (login's) writes
# it with its default text; net tap add/remove and net bridge add change
# only their lines (tap1's line goes again). At the second start login's
# net up makes tap0 and br0 = eth0 tap0 again before the cards' settings:
# br0 gets eth0's address by DHCP, and eth0, a port, is said to be one
# (not "DHCP"); removing a port changes the bridge's line. The third
# start has no card at all: login still runs net up for the file, which
# makes tap0 and passes over eth0 (not there), so br0 is not made.
virtual_test() {
    local image before want
    image=$(make_image ${P}virtual "")
    before=$failures
    QEMU_EXTRA="-netdev user,id=net0 -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    SERIAL_SCRIPT=virtual_session_1
    boot ${P}virtual-1 "$image" "RitterOS kernel: boot complete"
    compare "net up wrote the file with its default text" \
            "$(python3 "$ROOT/scripts/settingstext.py" VIRTUAL)" \
            "$(command_output 'cat /system/config/network/virtual')"
    compare "the commands changed only their lines" \
            "$(python3 "$ROOT/scripts/settingstext.py" VIRTUAL; printf 'tap0 = user root\nbr0 = eth0 tap0')" \
            "$(command_output 'cat /system/config/network/virtual' 2)"
    SERIAL_SCRIPT=virtual_session_2
    boot ${P}virtual-2 "$image" "RitterOS kernel: boot complete"
    expect_line "net: tap0: a virtual card; /dev/tap0 is root's"
    expect_line "net: br0: a bridge (its MAC address eth0's)"
    expect_line "net: br0: eth0 is its port"
    expect_line "net: br0: tap0 is its port"
    expect_line "net: eth0: a port of br0: its own settings are not used"
    reject "net: eth0: DHCP"
    expect "--- 10.0.2.2: 2 sent, 2 received, 0% lost"
    expect_line "net: br0: tap0 is no longer its port"
    compare "the bridge's line follows its ports" \
            "$(python3 "$ROOT/scripts/settingstext.py" VIRTUAL; printf 'tap0 = user root\nbr0 = eth0')" \
            "$(command_output 'cat /system/config/network/virtual')"
    QEMU_EXTRA=
    SERIAL_SCRIPT=virtual_session_3
    boot ${P}virtual-3 "$image" "RitterOS kernel: boot complete"
    expect_line "net: tap0: a virtual card; /dev/tap0 is root's"
    expect_line "net: eth0: no such network card (not made a port)"
    reject "net: br0: a bridge"
    check "net: tap0 there, no br0" "$(command_output 'net' | grep -o '^[a-z]*[0-9]' | tr '\n' ' ')" \
          test "$(command_output 'net' | grep -o '^[a-z]*[0-9]' | tr '\n' ' ')" = "tap0 "
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# usbnet_session: a USB NCM Ethernet adapter plugged in through QEMU's
# monitor after the boot (OVMF hangs binding its own NCM driver if the
# adapter is there at the boot, so we hot-plug it; this also tests that a
# network card hot-plugs). net up then configures it (DHCP). Then it is
# unplugged and plugged in again: the same adapter gets eth0 back, and
# dhclient asks again when its link comes.
usbnet_session() {
    local mon="$WORK/monitor.sock"
    monitors() {
        local c
        for c in "$@"; do echo "$c"; sleep 0.5; done | nc -w 3 -U "$mon" >>"$WORK/${NAME}-monitor.txt" 2>&1
    }
    local n=1 asked=0
    prompt_wait $n 30
    monitors "netdev_add user,id=net0" \
             "device_add usb-ncm,id=ncm0,netdev=net0,bus=xhci.0,port=2,mac=52:54:00:12:34:59"
    serial_wait "USB NCM Ethernet on" 1 15
    serial_type 'net up\r'
    n=$((n + 1)); prompt_wait $n 30
    dhcp_wait eth0 10.0.2.15
    answer_lines 'net' 'usb' 'ping 10.0.2.2'
    # (64m) a frame of 484 bytes: its NTB is 512 bytes, one full packet, so a
    # zero-length packet must end the transfer (442 bytes of UDP data)
    answer_lines "/system/$ARCH_NAME/test/net6test udp 10.0.2.2 $NET_UDP_PORT \"\$(cat /z442)\"" \
                 'ping 10.0.2.2' 'net'
    monitors "device_del ncm0"
    serial_wait "USB NCM Ethernet eth0 removed" 1 15
    sleep 2                             # out as long as a person's replug: dhclient sees the link go
    # (64n) plugged in again as an adapter sending two NTBs in one transfer
    monitors "device_add usb-ncm,id=ncm0,netdev=net0,bus=xhci.0,port=2,mac=52:54:00:12:34:59,split=on"
    serial_wait "as eth0 again" 1 15
    serial_wait "dhclient: eth0: 10.0.2.15/24" 2 40
    serial_type '\r'                    # the messages came after the prompt: a fresh one
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'ping 10.0.2.2' "fetch -o /a.bin http://10.0.2.2:$NET_HTTP_PORT/big.bin" 'ls -l /a.bin' 'net' \
                 'drivers'
}

# usbnet_shell_test: our USB CDC-NCM adapter (the QEMU model usb-ncm) is
# plugged into the xHCI after the boot; the kernel enumerates it, usbnet.c
# makes it eth0, and net up gives it DHCP (10.0.2.15 on QEMU's user
# network); it then pings the gateway. The Ethernet frames ride in NCM
# transfer blocks on the bulk endpoints; the receive thread keeps a read
# pending (the model answers NAK while idle, as real devices do), and the
# model has a serial port's CDC Data interface after NCM's, as the
# PlutoSDR does (50d). Unplugged and plugged in again, the adapter is eth0
# again with its address, and pings again. Proven (50d) by the old kernel:
# it took the serial port's data interface (SET_INTERFACE failed), and with
# that fixed, its reads blocked the controller (no DHCP answer).
usbnet_shell_test() {
    local image before web
    image=$(make_image ${P}usbnet "")
    printf 'address = dhcp\n' >"$WORK/${P}eth0"
    $RFS put "$image" $RFS_PART /system/config/network/eth0 "$WORK/${P}eth0" >/dev/null || exit 1
    printf 'z%.0s' $(seq 442) >"$WORK/${P}z442"         # (64m) a UDP payload making a 512-byte NTB
    $RFS put "$image" $RFS_PART /z442 "$WORK/${P}z442" >/dev/null || exit 1
    python3 "$ROOT/scripts/testhttp.py" $NET_HTTP_PORT >"$WORK/${P}testhttp.log" 2>&1 &
    web=$!
    host_service_wait "$WORK/${P}testhttp.log" listening
    before=$failures
    SERIAL_SCRIPT=usbnet_session
    boot ${P}usbnet "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    kill $web 2>/dev/null; wait $web 2>/dev/null
    expect "USB NCM Ethernet on"                        # the driver attached on hot-plug
    # (67e) The driver is a module, loaded at the boot without a device (the
    # adapter comes later); it took the adapter when it was plugged in, and
    # again after the replug. Proven by a loader that never offers a USB
    # device (no NCM line, no eth0).
    expect "modules: usbnet (no device yet) loaded"
    check "drivers: usbnet took the adapter plugged in after the boot" \
          "$(command_output drivers | grep usbnet)" \
          eval 'command_output drivers | grep -qE "^  usbnet\.mod +usbnet at 0x[0-9a-f]+: .*; 1 USB IDs; took usb0 port [0-9.]+ \(0525:a4a5\)$"'
    expect_line "dhclient: eth0: 10.0.2.15/24 from 10.0.2.2, gateway 10.0.2.2, DNS 10.0.2.3, lease 86400 s"
    check "the NCM adapter is eth0, driver usbnet, with its DHCP address" \
          "$(command_output 'net' | grep -E '^eth0' || echo MISSING)" \
          eval 'command_output "net" | grep -qE "^eth0 .*\(usbnet" && command_output "net" | grep -q "10.0.2.15/24"'
    check "the USB device shows as a 0525:a4a5 adapter" \
          "$(command_output 'usb' | grep -i '0525:a4a5' || echo MISSING)" \
          eval 'command_output "usb" | grep -qi "0525:a4a5"'
    check "ping 10.0.2.2 over NCM: four answers" \
          "$(command_output 'ping 10.0.2.2' | grep -c '^64 bytes from 10.0.2.2: seq=[1-4] time=') answer(s)" \
          test "$(command_output 'ping 10.0.2.2' | grep -c '^64 bytes from 10.0.2.2: seq=[1-4] time=')" = 4
    expect "--- 10.0.2.2: 4 sent, 4 received, 0% lost"
    # (64m) the 512-byte NTB ended with a zero-length packet, and the pings
    # after it still came back; the driver's and the endpoints' counts are in
    # net (proven by the old controller code, which refused the empty packet)
    check "a 512-byte NTB ended with a zero-length packet" \
          "$(command_output 'net' 2 | grep 'usbnet: read' || echo MISSING)" \
          eval 'command_output "net" 2 | grep -Eq "usbnet: read [0-9]+ NTB\(s\) .*sent [0-9]+ \([1-9][0-9]* zero-length end\(s\)\), 0 failed"'
    check "pings after the zero-length packet: four answers" \
          "$(command_output 'ping 10.0.2.2' 2 | grep -c '^64 bytes from 10.0.2.2: seq=[1-4] time=') answer(s)" \
          test "$(command_output 'ping 10.0.2.2' 2 | grep -c '^64 bytes from 10.0.2.2: seq=[1-4] time=')" = 4
    check "the bulk endpoints' counts in net: no errors" \
          "$(command_output 'net' 2 | grep 'usbnet: bulk' || echo MISSING)" \
          eval '[ "$(command_output "net" 2 | grep -c "usbnet: bulk .* 0 error(s)")" = 2 ]'
    expect "USB NCM Ethernet eth0 removed (no link now)"
    expect "as eth0 again, MAC 52:54:00:12:34:59"
    check "plugged in again: dhclient gives eth0 its address again" \
          "$(grep -c 'dhclient: eth0: 10.0.2.15/24' <<<"$TEXT") address line(s)" \
          test "$(grep -c 'dhclient: eth0: 10.0.2.15/24' <<<"$TEXT")" -ge 2
    check "ping 10.0.2.2 after plugging in again: four answers" \
          "$(command_output 'ping 10.0.2.2' 3 | grep -c '^64 bytes from 10.0.2.2: seq=[1-4] time=') answer(s)" \
          test "$(command_output 'ping 10.0.2.2' 3 | grep -c '^64 bytes from 10.0.2.2: seq=[1-4] time=')" = 4
    # (64n) with two NTBs in a transfer, the second is found too: the
    # download is whole and no read began without a header (proven by the
    # old driver, which read only the first NTB of each transfer: the
    # download stalled)
    check "two NTBs in one transfer: the 1,000,000-byte download is whole" \
          "$(command_output 'ls -l /a.bin' | grep a.bin || echo MISSING)" \
          eval 'command_output "ls -l /a.bin" | grep -q " 1000000 "'
    check "the driver counted the NTBs that came after another, and no read without a header" \
          "$(command_output 'net' 3 | grep 'usbnet: read' || echo MISSING)" \
          eval 'command_output "net" 3 | grep -Eq "usbnet: read [0-9]+ NTB\(s\) \([0-9]+ frames, 0 skipped; [1-9][0-9]* after another in one read\), 0 read\(s\) failed, 0 without a header"'
    reject "without an NTB header"
    reject "panic"
    show_log_on_failure $before
}

# usbserial_session: the NCM model again, now with its serial port (CDC
# ACM) connected to a responder on the Mac (a QEMU chardev on a local
# socket): /dev lists the port, cu talks through it and leaves with ~., echo
# writes to it, and an unplug while cu runs ends it.
usbserial_session() {
    local mon="$WORK/monitor.sock"
    monitors() {
        local c
        for c in "$@"; do echo "$c"; sleep 0.5; done | nc -w 3 -U "$mon" >>"$WORK/${NAME}-monitor.txt" 2>&1
    }
    local n=1 asked=0
    prompt_wait $n 30
    monitors "chardev-add socket,id=acm0,path=$WORK/${P}acm.sock" \
             "netdev_add user,id=net0" \
             "device_add usb-ncm,id=ncm0,netdev=net0,chardev=acm0,bus=xhci.0,port=2,mac=52:54:00:12:34:59"
    serial_wait "USB serial port on" 1 15
    serial_type '\r'                    # the hot plug's lines came after the prompt: a fresh one
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'ls /dev' 'threads' 'sleep 3' 'threads'
    serial_type 'cu usbserial0\r'
    serial_wait "Connected to /dev/usbserial0" 1 15
    serial_wait "pluto login: " 1 15
    serial_type 'hello\r'
    serial_wait "HELLO" 1 15
    serial_wait "OK" 1 15
    serial_type '~~x\r'                 # ~~ at a line's start: one ~ goes
    serial_wait "~X" 1 15
    serial_type '\003'                  # Ctrl-C goes to the device, not to cu
    sleep 1
    serial_type '\r'                    # ~. counts at a line's start only
    serial_wait "OK" 3 15
    serial_type '~.'
    serial_wait "Disconnected." 1 15
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'echo ping > /dev/usbserial0'
    serial_type 'cu /dev/usbserial0\r'
    serial_wait "Connected to /dev/usbserial0" 2 15
    monitors "device_del ncm0"
    serial_wait "Disconnected: the device is gone." 1 15
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'ls /dev'
}

# usbserial_shell_test (50e): the USB CDC ACM driver, /dev/usbserial0 and
# cu, on the serial port of our NCM model (the PlutoSDR's shape) connected
# to scripts' responder: it greets with "pluto login: " as soon as QEMU
# connects (the bytes wait in the port's ring until cu opens it), echoes
# what comes in capitals, answers each Enter with OK, and logs every byte
# so the escapes can be checked (~~x sends ~x, ~. sends nothing, Ctrl-C is
# a byte 3). Proven by a driver that drops what it receives.
usbserial_shell_test() {
    local image before responder bytes
    image=$(make_image ${P}usbserial "")
    rm -f "$WORK/${P}acm.sock" "$WORK/${P}acm-bytes.txt"
    cat >"$WORK/${P}acmserver.py" <<'PY'
import os, socket, sys
path, log = sys.argv[1], sys.argv[2]
s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
s.bind(path)
s.listen(1)
print("listening", flush=True)
c, _ = s.accept()
c.sendall(b"pluto login: ")
with open(log, "wb") as f:
    while True:
        data = c.recv(4096)
        if not data:
            break
        f.write(data)
        f.flush()
        out = b""
        for b in data:
            if b == 13:
                out += b"\r\nOK\r\n"
            elif b == 3:
                out += b"^C"
            else:
                out += bytes([b]).upper()
        c.sendall(out)
PY
    python3 -u "$WORK/${P}acmserver.py" "$WORK/${P}acm.sock" "$WORK/${P}acm-bytes.txt" \
            >"$WORK/${P}acmserver.log" 2>&1 &
    responder=$!
    host_service_wait "$WORK/${P}acmserver.log" listening
    before=$failures
    SERIAL_SCRIPT=usbserial_session
    boot ${P}usbserial "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    kill $responder 2>/dev/null
    wait $responder 2>/dev/null
    expect "USB serial port on usb0 port"
    # (65e) The port's pending read waits on its endpoint's own queue: the
    # controller's events and ticks (100 a second) do not wake it. Proven
    # by the old wait on the controller's queue: about 300 switches in 3 s.
    local sw1 sw2
    sw1=$(command_output threads | awk '$2 == "usbserial0" {print $NF}')
    sw2=$(command_output threads 2 | awk '$2 == "usbserial0" {print $NF}')
    check "usbserial0 idle for 3 s: woken at most 20 times (${sw1:-?} then ${sw2:-?} switches)" \
          "usbserial0 switches: ${sw1:-?} then ${sw2:-?}" \
          eval '[ -n "$sw1" ] && [ -n "$sw2" ] && [ $((sw2 - sw1)) -le 20 ]'
    check "/dev lists usbserial0" \
          "$(command_output 'ls /dev' | grep -c ' usbserial0$') line(s)" \
          test "$(command_output 'ls /dev' | grep -c ' usbserial0$')" = 1
    expect "Connected to /dev/usbserial0 (~. leaves)."
    expect "pluto login: "
    expect "HELLO"
    expect "~X"
    expect "^C"
    expect_line "Disconnected."
    bytes=$(od -An -c "$WORK/${P}acm-bytes.txt" 2>/dev/null | tr -s ' \n' ' ')
    check "the device got hello, ~x (one ~), Ctrl-C, Enter and ping, and nothing of ~." \
          "bytes: $bytes" \
          test "$(cat "$WORK/${P}acm-bytes.txt" 2>/dev/null | tr '\r\003\n' 'RCN')" = "helloR~xRCRpingN"
    expect "Disconnected: the device is gone."
    expect "USB serial port usbserial0 removed"
    check "after the unplug /dev has no usbserial0" \
          "$(command_output 'ls /dev' 2 | grep -c ' usbserial0$') line(s)" \
          test "$(command_output 'ls /dev' 2 | grep -c ' usbserial0$')" = 0
    reject "panic"
    show_log_on_failure $before
}

# netnames sessions (50f): wait for the elf netnamesd (net up at login made
# its file), give it time to record the cards, then look.
netnames_session_1() {
    local n=1 asked=0
    serial_wait "elvesd: netnamesd started" 1 30
    sleep 3
    serial_type '\r'                    # elves' lines came after the prompt: a fresh one
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'net names'
}

netnames_session_2() {
    local n=1 asked=0
    serial_wait "elvesd: netnamesd started" 1 30
    sleep 3
    serial_type '\r'
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'net names' 'net forget eth1' 'net forget eth0' 'net names' 'ls /system/config/network'
}

netnames_session_3() {
    local n=1 asked=0
    serial_wait "elvesd: netnamesd started" 1 30
    sleep 3
    serial_type '\r'
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'net names' 'net'
}

# netnames_session_0 (50h): a machine without a card: net up at login sets
# up netnamesd anyway; then an adapter is plugged in, and with no net up it
# is named, recorded, gets its settings file and its address.
netnames_session_0() {
    local n=1 asked=0
    serial_wait "elvesd: netnamesd started" 1 30
    serial_type '\r'
    n=$((n + 1)); prompt_wait $n 30
    { echo "netdev_add user,id=nu"; sleep 0.5
      echo "device_add usb-ncm,id=ncm0,netdev=nu,bus=xhci.0,port=2,mac=52:54:00:12:34:59"; sleep 0.5; } |
        nc -w 3 -U "$WORK/monitor.sock" >>"$WORK/${NAME}-monitor.txt" 2>&1
    serial_wait "USB NCM Ethernet on" 1 15
    serial_wait "dhclient: eth0: 10.0.2.15/" 1 40
    serial_wait "guardd: 3 rule(s) loaded" 1 15
    serial_type '\r'
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'net names' 'cat /system/config/network/eth0' 'ping 10.0.2.2' 'guard'
}

# netnames_shell_test (50f, the user's design): network cards keep their
# names by MAC address. One image, three starts with QEMU's e1000 cards A
# (…:61), B (…:62) and C (…:63): first A and B (eth0, eth1, recorded by
# netnamesd in /system/config/network/names); then B alone, which stays
# eth1 (not eth0 as the order found would make it), eth0 shown as not here,
# `net forget eth1` refused (plugged in) and `net forget eth0` freeing the
# name and removing its settings file; then the host renames B to eth5 in
# the file and adds C, found first: C takes the free eth0, B is eth5.
# (50h) Before that, an image of its own with no card: netnamesd is set up
# anyway, and an adapter plugged in later gets its name, settings and
# address without net up; (36d-3) and, as net up was never run, the other
# network elves' files (dnsd, sshd, guardd), so the firewall's first rules
# let ping, ssh and DNS in. NETNAMESD=on: test images have it off.
netnames_shell_test() {
    local image before names
    local a="52:54:00:12:34:61" b="52:54:00:12:34:62" c="52:54:00:12:34:63"
    before=$failures
    # (50h) First a machine without a card, on an image of its own.
    NETNAMESD=on
    image=$(make_image ${P}netnames0 "")
    SERIAL_SCRIPT=netnames_session_0
    boot ${P}netnames-0 "$image" "RitterOS kernel: boot complete"
    expect_line "login: /system/config/elves/netnamesd made: the elf netnamesd records new network cards"
    expect "USB NCM Ethernet on usb0 port 6 as eth0, MAC 52:54:00:12:34:59"
    names=$($RFS cat "$image" $RFS_PART /system/config/network/names 2>/dev/null)
    check "the adapter is recorded as eth0" "the file: $(tr '\n' '|' <<<"$names")" \
          eval 'grep -qx "eth0 = 52:54:00:12:34:59" <<<"$names"'
    compare "netnamesd made its settings file" "$(printf '# This card'"'"'s settings (net up applies them; see the manual):\n#   address = dhcp, or ADDRESS/PREFIX with gateway = ... and dns = ...\naddress = dhcp')" \
            "$(command_output 'cat /system/config/network/eth0')"
    expect "dhclient: eth0: 10.0.2.15/24 from 10.0.2.2"
    expect "--- 10.0.2.2: 4 sent, 4 received, 0% lost"
    local elves
    elves=$($RFS ls "$image" $RFS_PART /system/config/elves 2>/dev/null | awk '{print $NF}' | tr '\n' ' ')
    check "netnamesd made the network elves' files" "the folder: $elves" \
          eval 'grep -qw dhclient <<<"$elves" && grep -qw dnsd <<<"$elves" &&
                grep -qw sshd <<<"$elves" && grep -qw guardd <<<"$elves"'
    expect_line "guardd: /system/config/guard made: in = drop, out = allow; let in: icmp, tcp 22 (sshd), udp 53 (dnsd)"
    check "guard: the firewall on with its first rules" "$(command_output 'guard' | head -4 | tr '\n' '|')" \
          eval 'command_output guard | grep -q "^firewall: on" &&
                command_output guard | grep -qE "^ +2  allow in tcp 22 "'

    image=$(make_image ${P}netnames "")
    NETNAMESD=
    QEMU_EXTRA="-netdev user,id=na -device e1000,netdev=na,mac=$a -netdev user,id=nb -device e1000,netdev=nb,mac=$b"
    SERIAL_SCRIPT=netnames_session_1
    boot ${P}netnames-1 "$image" "RitterOS kernel: boot complete"
    names=$($RFS cat "$image" $RFS_PART /system/config/network/names 2>/dev/null)
    check "netnamesd recorded A as eth0 and B as eth1" "the file: $(tr '\n' '|' <<<"$names")" \
          eval 'grep -qx "eth0 = $a" <<<"$names" && grep -qx "eth1 = $b" <<<"$names"'
    check "each card once, in the order found, under its own comment" \
          "the file: $(tr '\n' '|' <<<"$names")" \
          eval '[ "$(sed 1,4d <<<"$names" | tr "\n" "|" | sed -E "s/e1000 at [0-9a-f:.]+/P/g; s/found [0-9-]+/D/g")" = \
                 "# eth0: Intel 82540EM (P), D|eth0 = $a|# eth1: Intel 82540EM (P), D|eth1 = $b|" ]'
    check "net names: both here" "$(command_output 'net names' | tr '\n' '|')" \
          eval '[ "$(command_output "net names" | grep -c " here ")" = 2 ]'

    QEMU_EXTRA="-netdev user,id=nb -device e1000,netdev=nb,mac=$b"
    SERIAL_SCRIPT=netnames_session_2
    boot ${P}netnames-2 "$image" "RitterOS kernel: boot complete"
    # (67c) The cards' drivers are modules, started after the names file is
    # read: B is named eth1 at its start (its announcement line), never
    # renamed (until 67c it was eth0 first, then "is eth1 now").
    check "B named eth1 from the file at its start" "$(grep -a "$b" <<<"$TEXT" | head -2 | tr '\n' '|')" \
          eval 'grep -qE "^  eth1: +Intel 82540EM at [0-9a-f:.]+ \(e1000\), MAC $b, " <<<"$TEXT"'
    reject "is eth1 now"
    check "B alone is still eth1" "$(command_output 'net' 2>/dev/null | grep "$b")" \
          eval 'command_output "net names" | grep -qE "^eth1 +$b  here "'
    check "net names: eth0 (A) not here" "$(command_output 'net names' | tr '\n' '|')" \
          eval 'command_output "net names" | grep -qE "^eth0 +$a  not here "'
    expect "net: eth1 is plugged in (Intel"
    expect_line "net: eth0 ($a) forgotten: the name is free; removed /system/config/network/eth0"
    check "net names after the forget: only eth1, still described" \
          "$(command_output 'net names' 2 | tr '\n' '|')" \
          eval '[ "$(command_output "net names" 2 | grep -c .)" = 1 ] &&
                command_output "net names" 2 | grep -qE "^eth1 +$b  here +Intel 82540EM \(e1000 at .*\), found 20"'
    check "eth0's settings file is gone, eth1's stays" \
          "$(command_output 'ls /system/config/network' | tr '\n' '|')" \
          eval '! command_output "ls /system/config/network" | grep -qE " eth0$" &&
                command_output "ls /system/config/network" | grep -qE " eth1$"'

    names=$($RFS cat "$image" $RFS_PART /system/config/network/names 2>/dev/null)
    sed "s/^eth1 = /eth5 = /; s/^# eth1: /# eth5: /" <<<"$names" >"$WORK/${P}netnames-edited"
    $RFS put "$image" $RFS_PART /system/config/network/names "$WORK/${P}netnames-edited" >/dev/null || exit 1
    QEMU_EXTRA="-netdev user,id=nc -device e1000,netdev=nc,mac=$c -netdev user,id=nb -device e1000,netdev=nb,mac=$b"
    SERIAL_SCRIPT=netnames_session_3
    boot ${P}netnames-3 "$image" "RitterOS kernel: boot complete"
    QEMU_EXTRA=
    SERIAL_SCRIPT=
    check "B named eth5 from the edited file at its start" "$(grep -a "$b" <<<"$TEXT" | head -2 | tr '\n' '|')" \
          eval 'grep -qE "^  eth5: +Intel 82540EM at [0-9a-f:.]+ \(e1000\), MAC $b, " <<<"$TEXT"'
    reject "is eth5 now"
    check "the new card C takes the free eth0, B is eth5 (the hand edit)" \
          "$(command_output 'net names' | tr '\n' '|')" \
          eval 'command_output "net names" | grep -qE "^eth0 +$c  here " &&
                command_output "net names" | grep -qE "^eth5 +$b  here "'
    names=$($RFS cat "$image" $RFS_PART /system/config/network/names 2>/dev/null)
    check "netnamesd recorded C as eth0" "the file: $(tr '\n' '|' <<<"$names")" \
          eval 'grep -qx "eth0 = $c" <<<"$names" && grep -qx "eth5 = $b" <<<"$names"'

    reject "panic"
    show_log_on_failure $before
}

# defaultroute_session (50g): the routing file's order at login, a cable
# pulled and put back, then net default by hand.
defaultroute_session() {
    local n=1 asked=0
    serial_wait "dhclient: eth1: 10.0.3.15/" 1 30
    dhcp_wait eth0 10.0.2.15
    answer_lines 'net default'
    echo "set_link nb off" | nc -w 3 -U "$WORK/monitor.sock" >/dev/null 2>&1
    sleep 2
    answer_lines 'net default'
    echo "set_link nb on" | nc -w 3 -U "$WORK/monitor.sock" >/dev/null 2>&1
    serial_wait "dhclient: eth1: 10.0.3.15/" 2 40
    answer_lines '' 'net default' 'net default eth0' 'net default' 'net default auto' 'net default' \
                 'net default bogus'
}

# defaultroute_shell_test (50g, the user's names): two cards with a gateway
# each (QEMU networks 10.0.2.0/24 and 10.0.3.0/24); /system/config/routing
# says `default = eth1`. At login the default route is eth1's; with eth1's
# cable out it falls back to eth0 (the first other card with a gateway) and
# comes back with the cable; `net default eth0` and `net default auto`
# change it at once; a name that is not a card's is refused.
defaultroute_shell_test() {
    local image before
    image=$(make_image ${P}defaultroute "")
    printf 'default = eth1\n' >"$WORK/${P}routing"
    $RFS put "$image" $RFS_PART /system/config/routing "$WORK/${P}routing" >/dev/null || exit 1
    QEMU_EXTRA="-netdev user,id=na -device e1000,netdev=na,mac=52:54:00:12:34:71 -netdev user,id=nb,net=10.0.3.0/24 -device e1000,netdev=nb,mac=52:54:00:12:34:72"
    before=$failures
    SERIAL_SCRIPT=defaultroute_session
    boot ${P}defaultroute "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect_line "net: the default route: eth1, then any card with a gateway"
    compare "at login: eth1's gateway" \
            "net: the default route: eth1, then any card with a gateway; now via 10.0.3.2 on eth1" \
            "$(command_output 'net default' 1)"
    compare "eth1's cable out: eth0's" \
            "net: the default route: eth1, then any card with a gateway; now via 10.0.2.2 on eth0" \
            "$(command_output 'net default' 2)"
    compare "the cable back: eth1's again" \
            "net: the default route: eth1, then any card with a gateway; now via 10.0.3.2 on eth1" \
            "$(command_output 'net default' 3)"
    compare "net default eth0" "net: the default route: eth0, then any card with a gateway" \
            "$(command_output 'net default eth0')"
    compare "then eth0's" \
            "net: the default route: eth0, then any card with a gateway; now via 10.0.2.2 on eth0" \
            "$(command_output 'net default' 4)"
    compare "net default auto" "net: the default route: the first card with a gateway (auto)" \
            "$(command_output 'net default auto')"
    compare "auto: the first card with a gateway" \
            "net: the default route: the first card with a gateway (auto); now via 10.0.2.2 on eth0" \
            "$(command_output 'net default' 5)"
    expect_line "net: bogus: not a card's name (ethN, wlanN, tapN or brN)"
    reject "panic"
    show_log_on_failure $before
}

# man_session (50j): pages through a pipe (no pager), then the pager on a
# long page, left with q.
man_session() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines 'man tee | cat' 'man [ | cat' 'man install | cat' 'man -k archive | cat' \
                 'man nope' 'man a/b' 'man | grep -c .'
    serial_type 'man sh\r'
    serial_wait "-- line " 1 20
    serial_type ' '
    serial_wait "-- line " 2 20
    serial_type 'q'
    n=$((n + 1)); prompt_wait $n 20
}

# man_shell_test (50j): the manual on the machine. On the host: every
# program has its page (docs/commands/NAME.md) with its help text's title
# and usage, and the index lists them all (scripts/doccheck.py). In the
# guest: `man` shows pages exactly as the same man.c built on the Mac
# renders the tree's docs/, `[` is test's page, a topic (install), a
# search, the messages, the list of all pages, and the pager.
man_shell_test() {
    local image before host_man dir="$WORK/${P}manhost" pages doccheck_rc=0
    python3 "$ROOT/scripts/doccheck.py" >"$WORK/${P}doccheck.txt" || doccheck_rc=1
    rm -rf "$dir"; mkdir -p "$dir/inc"
    printf '#define PROGRAM_HELP(a, b)\nstatic inline int ritteros_terminal_size(int *r, int *c) { *r = 24; *c = 80; return 0; }\n' \
        >"$dir/inc/ritteros.h"
    mkdir -p "$dir/doc"
    cp -R "$ROOT/docs/commands" "$dir/doc/commands"
    cp "$ROOT/docs/install.md" "$ROOT/docs/manual.md" "$dir/doc/"
    sed "s|#define DOC_DIR     \"/system/doc\"|#define DOC_DIR \"$dir/doc\"|" "$ROOT/user/bin/man.c" >"$dir/man.c"
    cc -std=c11 -I"$dir/inc" -o "$dir/man" "$dir/man.c" 2>"$dir/cc.txt" || { echo "FAIL  ${P}man: the Mac's build of man: $(head -3 "$dir/cc.txt")"; failures=$((failures + 1)); return; }
    pages=$(ls "$ROOT/docs/commands" | grep -c '\.md$')
    image=$(make_image ${P}man "")
    before=$failures
    SERIAL_SCRIPT=man_session
    boot ${P}man "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    check "every program has its page, title and usage as its help says (doccheck.py)" \
          "$(tail -5 "$WORK/${P}doccheck.txt" | tr '\n' '|')" \
          test "$doccheck_rc" = 0
    compare "man tee as on the Mac" "$("$dir/man" tee)" "$(command_output 'man tee | cat')"
    compare "man [ is test's page" "$("$dir/man" test)" "$(command_output 'man [ | cat')"
    compare "man install, the install guide" "$("$dir/man" install)" "$(command_output 'man install | cat')"
    check "man -k archive finds ar and tar" "$(command_output 'man -k archive | cat' | tr '\n' '|')" \
          eval 'command_output "man -k archive | cat" | grep -q "^ar " && command_output "man -k archive | cat" | grep -q "^tar "'
    expect_line "man: no page for nope (man -k WORD searches the titles)"
    expect_line "usage: man [-k WORD] [NAME]"
    compare "man lists every page (and its heading and topics lines)" "$((pages - 1 + 2))" \
            "$(command_output 'man | grep -c .')"
    expect "-- line "
    reject "panic"
    show_log_on_failure $before
}

# mouse_inject: move the pointer right and down and give one left click,
# through QEMU's QMP socket. The old HMP mouse_move/mouse_button commands
# were removed, so the pointer is driven with input-send-event over QMP
# (a greeting, then qmp_capabilities, then the events). The only handler
# that takes relative-motion events gets them: on ARM the USB mouse, on x86
# (no USB mouse attached) the i8042 PS/2 mouse.
mouse_inject() {
    local q="$WORK/qmp.sock" rel btn c
    rel='{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}'
    btn='{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}'
    {
        echo '{"execute":"qmp_capabilities"}'; sleep 0.3
        for c in "$(printf "$rel" x 120)" "$(printf "$rel" y 80)" \
                 "$(printf "$btn" true)" "$(printf "$btn" false)"; do
            echo "$c"; sleep 0.2
        done
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
}

# A mouse that reported, moved and clicked (the shared check for both the
# USB and PS/2 mouse tests): some mouseN line of the `mouse` command shows a
# nonzero report count, at least one move and at least one click.
check_mouse_moved() {
    check "$1" \
          "$(command_output 'mouse' | grep -E '^  mouse[0-9]:' || echo MISSING)" \
          eval 'command_output "mouse" |
                grep -qE "^  mouse[0-9]:.*[1-9][0-9]* [a-z]+, pointer at [0-9]+,[0-9]+, [1-9][0-9]* move.*[1-9][0-9]* click"'
}

# mouse_usb_session / mouse_usb_test: a USB HID mouse (QEMU's usb-mouse) on
# the xHCI. The kernel makes it mouse0; after the pointer is moved and
# clicked (QMP), the rescue console's `mouse` command shows the motion and
# the click. ARM only: on x86 the always-present i8042 PS/2 mouse would also
# take the injected events, so the routing is not deterministic there (the
# PS/2 mouse is covered by ps2mouse_test); the USB mouse driver is the same
# code on both architectures.
mouse_usb_session() {
    local n=1
    prompt_wait $n
    serial_type 'exit\r'
    login_wait 2
    serial_type '\004'                              # Ctrl-D at login: the rescue console
    n=$((n + 1)); prompt_wait $n
    mouse_inject
    sleep 0.5
    serial_type 'mouse\r'
    n=$((n + 1)); prompt_wait $n
}

mouse_usb_test() {
    local image before
    image=$(make_image ${P}mouse "")
    QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=mouse_usb_session
    boot ${P}mouse "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "USB mouse on"                            # the driver attached on enumeration
    check "mouse0 is the USB mouse (counts reports)" \
          "$(command_output 'mouse' | grep -E '^  mouse0:' || echo MISSING)" \
          eval 'command_output "mouse" | grep -qE "^  mouse0:.*reports, pointer at"'
    check_mouse_moved "the USB mouse (mouse0) reported the pointer move and the click"
    reject "panic"
    show_log_on_failure $before
}

# ps2mouse_session / ps2mouse_test: the i8042's PS/2 mouse (port 2), always
# present on QEMU's q35. No USB mouse is attached, so the pointer injected
# over QMP reaches the PS/2 mouse (mouse0). x86 only: ARM machines have no
# i8042.
ps2mouse_session() {
    local n=1
    prompt_wait $n
    serial_type 'exit\r'
    login_wait 2
    serial_type '\004'
    n=$((n + 1)); prompt_wait $n
    mouse_inject
    sleep 0.5
    serial_type 'mouse\r'
    n=$((n + 1)); prompt_wait $n
}

ps2mouse_test() {
    local image before
    image=$(make_image ps2mouse "")
    before=$failures
    SERIAL_SCRIPT=ps2mouse_session
    boot ps2mouse "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "PS/2 mouse on the i8042 (port 2)"        # the driver attached
    check "mouse0 is the PS/2 mouse (counts packets)" \
          "$(command_output 'mouse' | grep -E '^  mouse0:' || echo MISSING)" \
          eval 'command_output "mouse" | grep -qE "^  mouse0:.*packets, pointer at"'
    check_mouse_moved "the PS/2 mouse (mouse0) reported the pointer move and the click"
    reject "panic"
    show_log_on_failure $before
}

# tablet_session / tablet_test: a USB HID absolute pointer (QEMU's usb-tablet,
# the pointer UTM and QEMU use so the host/guest cursors align without
# capturing the mouse). The kernel reads its HID report descriptor and makes it
# mouse0; an absolute move + click (QMP `abs`/`btn`) is shown by the `mouse`
# rescue command. Both architectures: an abs event reaches only the absolute
# device, so even x86's always-present PS/2 mouse does not interfere. The tablet
# enumerates over USB before the i8042, so it is mouse0 on x86 too.
tablet_session() {
    local n=1 q="$WORK/qmp.sock"
    prompt_wait $n
    serial_type 'exit\r'
    login_wait 2
    serial_type '\004'                              # Ctrl-D at login: the rescue console
    n=$((n + 1)); prompt_wait $n
    {
        echo '{"execute":"qmp_capabilities"}'; sleep 0.3
        echo '{"execute":"input-send-event","arguments":{"events":[{"type":"abs","data":{"axis":"x","value":6000}},{"type":"abs","data":{"axis":"y","value":6000}}]}}'; sleep 0.2
        echo '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":true}}]}}'; sleep 0.2
        echo '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":false}}]}}'; sleep 0.2
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    sleep 0.5
    serial_type 'mouse\r'
    n=$((n + 1)); prompt_wait $n
}

tablet_test() {
    local image before
    image=$(make_image ${P}tablet "")
    QEMU_EXTRA="-device usb-tablet,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=tablet_session
    boot ${P}tablet "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "USB tablet on"                           # the driver attached from the report descriptor
    check "mouse0 is the USB tablet (counts reports)" \
          "$(command_output 'mouse' | grep -E '^  mouse0:' || echo MISSING)" \
          eval 'command_output "mouse" | grep -qE "^  mouse0:.*reports, pointer at"'
    check_mouse_moved "the USB tablet (mouse0) reported the absolute move and the click"
    reject "panic"
    show_log_on_failure $before
}

# host_service_wait LOG TEXT: wait (up to 10 s) until a service on the Mac
# has written TEXT to its log (it is listening).
host_service_wait() {
    local i
    for ((i = 0; i < 40; i++)); do
        grep -q -- "$2" "$1" 2>/dev/null && return
        sleep 0.25
    done
}

# local_session / local_shell_test: local (Unix-domain) stream sockets
# (step 15b), no network needed. `local pair` runs a listener in one thread
# and a client in another of the same program: the client connects by name,
# sends a message, the server reads it and sends it back with "echo: ".
local_session() {
    local n=1 t="/system/$ARCH_NAME/test/local"
    prompt_wait $n
    serial_type "$t pair /run/talk hello\r"
    n=$((n + 1))
    prompt_wait $n
}

local_shell_test() {
    local image before
    image=$(make_image ${P}local "")
    before=$failures
    SERIAL_SCRIPT=local_session
    boot ${P}local "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "local: listening on /run/talk"          # the listener bound its name
    expect "server got: hello"                       # the message crossed the connection
    expect "client got: echo: hello"                 # and the reply came back
    reject "panic"
    show_log_on_failure $before
}

# share_session / share_shell_test: shared buffers (step 15c). One program's
# two threads share a buffer passed over a local socket: the client fills a
# pattern, the server checks it (same memory) and changes a byte the client
# then sees (shared both ways).
share_session() {
    local n=1 t="/system/$ARCH_NAME/test/share"
    prompt_wait $n
    serial_type "$t\r"
    n=$((n + 1))
    prompt_wait $n
}

share_shell_test() {
    local image before
    image=$(make_image ${P}share "")
    before=$failures
    SERIAL_SCRIPT=share_session
    boot ${P}share "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "server: pattern ok (8192 bytes)"         # the receiver sees the client's pattern
    expect "client: server's change seen"            # and the client sees the receiver's change
    reject "mismatch"
    reject "panic"
    show_log_on_failure $before
}

# display_session / display_shell_test: the display handoff (step 15d). The
# test program takes the screen from the console, fills it red, waits for the
# screenshot, then gives it back (the console redraws). Both screenshots are
# checked: the red fill while the program owns the screen, and the console's
# title bar after it releases.
display_session() {
    local n=1 t="/system/$ARCH_NAME/test/display" mon="$WORK/monitor.sock"
    prompt_wait $n
    serial_type "$t\r"
    serial_wait "filled red" 1 10
    sleep 0.3
    echo "screendump $WORK/${NAME}-fill.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    serial_type '\r'                                # let the program release and exit
    serial_wait "display: released" 1 10
    n=$((n + 1))
    prompt_wait $n
    sleep 0.3
    echo "screendump $WORK/${NAME}-restored.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    answer_lines "$t modes" displays "$t vblank" "$t flip" "$t buffers"   # (65e-34, 66a, 66c-3, 66d)
    # (66b-2) displays set: QEMU's graphics have no driver, so no outputs.
    answer_lines 'displays set hdmi0 1920x1080; echo "rc $?"' \
                 'displays set hdmi0 1920x1080@60x; echo "rc $?"' 'displays set; echo "rc $?"' \
                 'displays sleep; echo "rc $?"' 'displays sleep now; echo "rc $?"'   # (37g-5c-2)
}

display_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}display "")
    # (66b-6) A mode at every start: QEMU's graphics have no driver, so the
    # boot says why each line is not used (and nothing else changes).
    printf '# the screens (a comment)\n  hdmi0\t= 1920x1080@60   # HDMI\nvga0 1024x768\nhdmi0123 = 800x600\n' \
        >"$WORK/${P}displays"
    $RFS put "$image" $RFS_PART /system/config/displays "$WORK/${P}displays" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=display_session
    boot ${P}display "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "filled red"
    expect "display: released"
    check_screen fill-255-0-0 $w $h "$WORK/${P}display-fill.ppm"     # windowd's pixels reached the screen
    check_screen restored $w $h "$WORK/${P}display-restored.ppm"     # the console came back on release
    # (65e-34) DISPLAY_MODES: QEMU's firmware gives no EDID (edid_host_test
    # checks the parser), so the screen's size and the firmware's modes, as
    # many as the bootloader counted ("Display: EDID 0 bytes, N modes").
    local modes listed
    modes=$(grep -a -o 'EDID 0 bytes, [0-9]* modes' "$WORK/${P}display.log" | head -1 | sed 's/EDID 0 bytes, \([0-9]*\) modes/\1/')
    expect "  display:       no EDID from the firmware (none on the screen's handle); ${modes:-?} modes it can set"
    expect "display: now ${w}x${h}; no EDID"
    listed=$(command_output "/system/$ARCH_NAME/test/display modes" | sed -n 's/^display: \([0-9]*\) modes:.*/\1/p')
    compare "display modes: the firmware's modes, as the bootloader found them" "${modes:-?}" "${listed:-none}"
    check "display modes: the screen's mode among them" "$(command_output "/system/$ARCH_NAME/test/display modes" | tail -1)" \
          eval 'command_output "/system/$ARCH_NAME/test/display modes" | grep -q " ${w}x${h}\( \|$\)"'
    # (66a) displays: no driver for QEMU's graphics (x86: the Bochs display
    # on PCI; ARM: ramfb, not on PCI); the J1900's Intel graphics are
    # checked on the J1900 itself.
    local want
    if [ "$ARCH_NAME" = x86_64 ]; then
        want=$(printf 'screen: %sx%s, the firmware'"'"'s mode\n00:01.0 1234:1111: no driver for these graphics yet' $w $h)
    else
        want=$(printf 'screen: %sx%s, the firmware'"'"'s mode\nno graphics device on PCI' $w $h)
    fi
    compare "displays: the screen and the graphics devices" "$want" "$(command_output displays)"
    # (66c-3) DISPLAY_VBLANK: no driver here tells the vertical blank (the
    # J1900's does: 60 in 1000 ms). Proven by a kernel without the call.
    compare "display vblank: none without a graphics driver" \
            "display: no vertical blank here (No such device)
/system/$ARCH_NAME/test/display: exit code 1" \
            "$(command_output "/system/$ARCH_NAME/test/display vblank")"
    # (66d-1) DISPLAY_FLIP: no driver here flips (the J1900's does). Proven
    # by a kernel without the call.
    compare "display flip: none without a graphics driver" \
            "display: no flipping here (No such device)
/system/$ARCH_NAME/test/display: exit code 1" \
            "$(command_output "/system/$ARCH_NAME/test/display flip")"
    # (66d-2) DISPLAY_BUFFERS: no driver here has screen buffers. Proven by
    # a kernel without the call.
    compare "display buffers: none without a graphics driver" \
            "display: no screen buffers here (No such device)
/system/$ARCH_NAME/test/display: exit code 1" \
            "$(command_output "/system/$ARCH_NAME/test/display buffers")"
    # (66b-6) /system/config/displays at the start. Proven by a kernel
    # that does not read it.
    expect_line "  displays:      hdmi0 in /system/config/displays: no such output"
    expect_line "  displays:      line 3 of /system/config/displays: not OUTPUT = WxH[@HZ]"
    expect_line "  displays:      line 4 of /system/config/displays: not OUTPUT = WxH[@HZ]"
    # (66b-2) Setting a mode: the request reaches the kernel, which answers
    # why not (no driver here, so no output of that name); wrong arguments
    # are the program's. Proven by a kernel that leaves `said` empty.
    compare "displays set: no such output here" "displays: hdmi0: no such output
rc 1" "$(command_output 'displays set hdmi0 1920x1080; echo "rc $?"')"
    compare "displays set: a mode that is not WxH[@HZ]" "usage: displays [set OUTPUT WxH[@HZ] | sleep]
rc 2" "$(command_output 'displays set hdmi0 1920x1080@60x; echo "rc $?"')"
    compare "displays set: without its arguments" "usage: displays [set OUTPUT WxH[@HZ] | sleep]
rc 2" "$(command_output 'displays set; echo "rc $?"')"
    # (37g-5c-2) displays sleep: REPORT_DISPLAY_SLEEP reaches the graphics
    # layer, where no driver here keeps registers over a sleep (the AMD
    # Cezanne's does: checked on the Acer). Proven by a kernel without the
    # report (displays exits 1, nothing printed).
    compare "displays sleep: no driver here keeps registers" "no graphics driver here keeps its registers over a sleep
rc 0" "$(command_output 'displays sleep; echo "rc $?"')"
    compare "displays sleep: no arguments after it" "usage: displays [set OUTPUT WxH[@HZ] | sleep]
rc 2" "$(command_output 'displays sleep now; echo "rc $?"')"
    # (66a) The kernel's printf with widths as arguments (%*s, as gpu.c's
    # lines): without them the J1900's boot crashed on its graphics line.
    # Proven by kvsnprintf without '*' widths.
    expect "kprintf:       self-test passed: widths and precisions as arguments"
    reject "panic"
    show_log_on_failure $before
}

# atomhost_host_test (37g-5a): amdgpu's AtomBIOS interpreter
# (drivers/amdgpu_atom.c) against Linux's (atom.c, fetched by
# setup-toolchain.sh) on the Mac, ours under ASan and UBSan:
# scripts/atomhost.c runs every command table of 100 video BIOS images of
# its own making (random code of every opcode both define alike) through
# both on a simulated machine, three rounds of parameters, and compares
# every register read and write, wait, result, parameter and scratch dword
# (the laptops' own images are their vendors': run by hand, never here).
# Proven by an xor that also flipped bit 0 for a source with bit 31 set
# (31 tables different) and indirect I/O moves to bits 16-31 landing 16
# lower (12 different in 20 images). (37g-5c) A sequence of calls on one
# machine (-c, as a driver's bring-up runs them) on 100 images: proven by
# atom_run not resetting the register block between calls (25 different).
atomhost_host_test() {
    local out dir="$WORK/atomhost" oracle
    NAME=${P}atomhost                       # (no boot names it)
    mkdir -p "$dir"
    oracle=$(ls -d "$ROOT"/tools/src/atom-* 2>/dev/null | head -1)
    if [ -z "$oracle" ] || ! /usr/bin/clang -std=gnu11 -O1 -g -w -fsanitize=address \
            -I "$ROOT/scripts/atomoracle" -I "$oracle" -c -o "$dir/oracle.o" \
            "$ROOT/scripts/atomoracle/oracle.c" 2>"$dir/oracle.err"; then
        check "Linux's atom.c builds on the Mac (scripts/setup-toolchain.sh)" \
              "$(head -3 "$dir/oracle.err" 2>/dev/null)" false
        return
    fi
    if ! /usr/bin/clang -std=c11 -O1 -g -Wall -Wextra -Werror -fsanitize=address,undefined \
            -fno-sanitize-recover=all -DATOM_STEP=atomhost_step -I "$ROOT/drivers" \
            -o "$dir/atomhost" "$ROOT/scripts/atomhost.c" "$ROOT/drivers/amdgpu_atom.c" \
            "$dir/oracle.o" 2>"$dir/atomhost.err"; then
        check "atomhost builds on the Mac" "$(head -3 "$dir/atomhost.err")" false
        return
    fi
    out=$("$dir/atomhost" -r 3 -f 100 2>&1; echo "rc $?")
    check "AtomBIOS: ours as Linux's on 100 images ($(grep '^atomhost: 100' <<<"$out"))" "$out" \
          eval 'grep -qE "^atomhost: 100 images from seed 1: 1100 tables, 3 rounds: 3300 the same, 0 different" <<<"$out" && tail -1 <<<"$out" | grep -qx "rc 0"'
    check "AtomBIOS: every opcode the images have ran ($(grep 'opcodes ran' <<<"$out" | cut -c1-40))" \
          "$out" eval 'grep -qE "^atomhost: 88 opcodes ran" <<<"$out"'
    out=$("$dir/atomhost" -f 100 -c 0:0x700 -c 3:0x12,0x34 -c 0:5,6,7 -c 7:0x1000 2>&1; echo "rc $?")
    check "AtomBIOS: a sequence of calls on one machine as Linux's ($(tail -2 <<<"$out" | head -1))" \
          "$out" eval 'grep -qx "atomhost: 100 images from seed 1, 4 calls each: 0 different" <<<"$out" && tail -1 <<<"$out" | grep -qx "rc 0"'
    # (37g-5c-2) -i: both machines start from the registers given (the
    # images' code uses registers below 0x3000); proven by presets given
    # to ours only (42 different).
    awk 'BEGIN { for (i = 1; i < 4096; i++) printf "0x%x 0x%x\n", i, i * 2654435761 % 4294967296 }' \
        >"$dir/presets"
    out=$("$dir/atomhost" -i "$dir/presets" -f 50 -c 0:0x700 -c 1:0x3,0x4 -c 0:9 2>&1; echo "rc $?")
    check "AtomBIOS: a sequence from given registers as Linux's ($(tail -2 <<<"$out" | head -1))" \
          "$out" eval 'grep -qx "atomhost: 50 images from seed 1, 3 calls each: 0 different" <<<"$out" && tail -1 <<<"$out" | grep -qx "rc 0"'
}

# edid_host_test (65e-34): the kernel's EDID parser (kernel/edid.c) on the
# Mac under ASan and UBSan, with EDIDs built from known timings, damaged
# ones and random ones (scripts/edidtest.c). QEMU's firmware passes no EDID,
# so this is where the parsing is checked. Proven by a refresh without the
# horizontal blanking and by extension blocks left unread.
# avxas_host_test (32c): our as's SSE and AVX (VEX) instructions byte for
# byte as clang's, on the Mac: scripts/avxas.py writes every instruction of
# as's vector table in its forms (about 15,000 lines), assembles them with
# an as built here and with clang and compares the bytes. Proven by an as without
# LLVM's operand swaps for the short VEX prefix, and one with vpaddd's
# opcode wrong (both listed the instructions they got wrong).
avxas_host_test() {
    local out
    NAME=${P}avxas                          # (no boot names it)
    mkdir -p "$WORK/avxas"
    # (its own build of as: make test does not rebuild build/host/as)
    if ! /usr/bin/clang -std=c11 -O2 -I "$ROOT/user/bin" -o "$WORK/avxas/as" "$ROOT/user/bin/as.c" \
            "$ROOT"/user/bin/as/*.c 2>"$WORK/avxas/as.err"; then
        check "as builds on the Mac" "$(head -3 "$WORK/avxas/as.err")" false
        return
    fi
    out=$(python3 "$ROOT/scripts/avxas.py" "$ROOT" "$WORK/avxas" "$WORK/avxas/as" 2>&1 | tail -12)
    check "as: SSE and AVX instructions byte for byte as clang's ($(tail -1 <<<"$out"))" "$out" \
          eval 'grep -qE "^avxas: the same bytes: [0-9]+ instructions" <<<"$out"'
}

# neonas_host_test (32f): our as's AArch64 vector (NEON) instructions byte
# for byte as clang's, on the Mac: scripts/neonas.py writes them in their
# forms (about 4,700 lines), assembles them with an as built here and with
# clang and compares the bytes. Proven by an as with addp's opcode wrong
# and one with the left shifts' immediate counted as the right shifts'.
neonas_host_test() {
    local out
    NAME=${P}neonas                         # (no boot names it)
    mkdir -p "$WORK/neonas"
    if ! /usr/bin/clang -std=c11 -O2 -I "$ROOT/user/bin" -o "$WORK/neonas/as" "$ROOT/user/bin/as.c" \
            "$ROOT"/user/bin/as/*.c 2>"$WORK/neonas/as.err"; then
        check "as builds on the Mac" "$(head -3 "$WORK/neonas/as.err")" false
        return
    fi
    out=$(python3 "$ROOT/scripts/neonas.py" "$ROOT" "$WORK/neonas" "$WORK/neonas/as" 2>&1 | tail -12)
    check "as: NEON instructions byte for byte as clang's ($(tail -1 <<<"$out"))" "$out" \
          eval 'grep -qE "^neonas: the same bytes: [0-9]+ instructions" <<<"$out"'
}

edid_host_test() {
    local out
    NAME=${P}edid                           # (no boot names it)
    if ! /usr/bin/clang -std=c11 -Wall -Wextra -Werror -fsanitize=address,undefined \
            -fno-sanitize-recover=all -g -I "$ROOT/kernel" -o "$WORK/edidtest" \
            "$ROOT/scripts/edidtest.c" "$ROOT/kernel/edid.c" 2>"$WORK/edidtest.err"; then
        check "edidtest builds on the Mac" "$(head -3 "$WORK/edidtest.err")" false
        return
    fi
    out=$("$WORK/edidtest" 2>&1)
    check "the EDID parser: every check of edidtest passed ($out)" "$out" \
          eval 'grep -qE "^edidtest: [0-9]+ checks passed$" <<<"$out"'
}

# windowd launches a session program by default (step 15h; owl since step 18a).
# The compositor tests below drive windowd with their own explicit clients, so
# they turn that off with an empty `startup =` in /system/config/windows.
windows_bare() {
    printf 'startup =\n' > "$WORK/${P}windows.cfg"
    $RFS put "$1" $RFS_PART /system/config/windows "$WORK/${P}windows.cfg" >/dev/null || exit 1
}

# Set windowd's startup program (for tests that need a specific one, e.g. term).
windows_startup() {
    printf 'startup = %s\n' "$2" > "$WORK/${P}windows.cfg"
    $RFS put "$1" $RFS_PART /system/config/windows "$WORK/${P}windows.cfg" >/dev/null || exit 1
}

# windowd_session / windowd_shell_test: the window server (step 15e). windowd
# (a background job) takes the screen; a client makes a green window, windowd
# composites it with a title bar and border, and a screenshot confirms it.
# Moving the mouse sends a pointer event through the kernel (DISPLAY_EVENT) to
# windowd, which forwards it to the window's client.
windowd_session() {
    local n=1 t="/system/$ARCH_NAME/test/wclient" mon="$WORK/monitor.sock"
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type 'kill -USR1 $!\r'                   # (66c-1) its frame report
    serial_wait "windowd: frames: " 1 10
    serial_type "$t\r"
    serial_wait "wclient: window created" 1 15
    sleep 0.3
    echo "screendump $WORK/${NAME}-win.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    mouse_inject                                    # a pointer event windowd forwards to the window
    serial_wait "wclient: pointer" 1 10
}

windowd_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}windowd "")
    windows_bare "$image"
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=windowd_session
    boot ${P}windowd "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "windowd: listening on /run/windowd"
    # (65e-34b) Its frame rate: QEMU's firmware gives no EDID, so 60.
    expect "windowd: 60.000 frames a second at most (the default)"
    expect "wclient: window created"
    expect "wclient: pointer"                        # input reached windowd and the client
    # (66c-1) The frame report on USR1 (its first frames: the empty
    # desktop); windowd goes on (the client's window came after it).
    # Proven by a compositor that leaves USR1 blocked.
    local frames
    frames=$(grep -a -o 'windowd: frames: [0-9][0-9]*, composing [0-9][0-9]* ms, flush calls [0-9][0-9]* ms ([0-9][0-9]* Mpx; per frame [0-9.]* ms and [0-9.]* ms; [0-9][0-9]* MB/s flushed; [0-9][0-9]* again)' \
             "$WORK/${P}windowd.log" | head -1)
    check "windowd's frame report: ${frames:-none}" "${frames:-none}" test -n "$frames"
    check_screen windowd $w $h "$WORK/${P}windowd-win.ppm"
    reject "panic"
    show_log_on_failure $before
}

# windowd2_session / windowd2_test: window interaction (step 15e2). Two
# overlapping windows (green id 0, red id 1 on top); clicking the lower one's
# exposed title bar focuses and raises it, and dragging its title bar moves
# it. The pointer is driven over QMP as deltas from the screen centre (where
# windowd's cursor starts). Three screenshots check the stacking, the focus
# colour and the move.
windowd2_session() {
    local n=1 t="/system/$ARCH_NAME/test/wclient" mon="$WORK/monitor.sock" q="$WORK/qmp.sock"
    local curx cury
    if [ "$ARCH_NAME" = x86_64 ]; then curx=640 cury=400; else curx=400 cury=300; fi
    qmp() { local c; { echo '{"execute":"qmp_capabilities"}'; sleep 0.3
                       for c in "$@"; do echo "$c"; sleep 0.15; done; } |
            nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1; }
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    moveto() { qmp "$(rel x $(( $1 - curx )))" "$(rel y $(( $2 - cury )))"; curx=$1; cury=$2; }
    shot() { sleep 0.3; echo "screendump $WORK/${NAME}-$1.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
             sleep 0.4; }

    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t 0 200 80 &\r"                    # green window, id 0, at 100,100
    serial_wait "wclient: window created, id 0" 1 15
    serial_type "$t 200 60 60 &\r"                   # red window, id 1, at 140,140, on top
    serial_wait "wclient: window created, id 1" 1 15
    shot before
    moveto 120 112                                   # id 0's exposed title bar (clear of the resize edge)
    qmp "$(btn true)" "$(btn false)"                 # click: focus and raise id 0
    shot raised
    moveto 120 112
    qmp "$(btn true)"                                # press on id 0's title bar
    moveto 120 312                                   # drag it down (button held)
    qmp "$(btn false)"                               # release
    shot moved
}

windowd2_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}windowd2 "")
    windows_bare "$image"
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=windowd2_session
    boot ${P}windowd2 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    # Before: red (id 1) is in front over the overlap; id 0's title bar is dim.
    check_screen px-200-200-200-60-60 $w $h "$WORK/${P}windowd2-before.ppm"
    check_screen px-110-108-67-76-94 $w $h "$WORK/${P}windowd2-before.ppm"
    # After the click: id 0 raised (green over the overlap) and focused (bright bar,
    # sampled clear of the cursor arrow that sits where it was clicked).
    check_screen px-200-200-0-200-80 $w $h "$WORK/${P}windowd2-raised.ppm"
    check_screen px-200-108-94-129-172 $w $h "$WORK/${P}windowd2-raised.ppm"
    # After the drag: id 0 moved down (green at its new place; red shows where it was).
    check_screen px-200-380-0-200-80 $w $h "$WORK/${P}windowd2-moved.ppm"
    check_screen px-200-200-200-60-60 $w $h "$WORK/${P}windowd2-moved.ppm"
    reject "panic"
    show_log_on_failure $before
}

# wtext_session / wtext_shell_test: libwindow (step 15f). A toolkit app opens
# a titled window and draws a background, a box and a line of text; windowd
# draws the window title with the same font. A screenshot checks the box, the
# background, and that text pixels appear in the window and in the title bar.
wtext_session() {
    local n=1 t="/system/$ARCH_NAME/test/wtext" mon="$WORK/monitor.sock"
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t\r"
    serial_wait "wtext: drawn" 1 15
    sleep 0.4
    echo "screendump $WORK/${NAME}-text.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

wtext_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}wtext "")
    windows_bare "$image"
    before=$failures
    SERIAL_SCRIPT=wtext_session
    boot ${P}wtext "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "wtext: drawn"
    check_screen px-350-226-0-0-200 $w $h "$WORK/${P}wtext-text.ppm"                 # background (+6: taller title bar)
    check_screen px-150-184-0-200-0 $w $h "$WORK/${P}wtext-text.ppm"                 # the box
    check_screen region-112-134-45-15-255-255-255 $w $h "$WORK/${P}wtext-text.ppm"   # "Hello"
    check_screen region-106-102-72-15-255-255-255 $w $h "$WORK/${P}wtext-text.ppm"   # the title
    reject "panic"
    show_log_on_failure $before
}

# termwin_session / termwin_shell_test: a terminal in a window (step 15g).
# windowd runs; `term` opens a window titled "Terminal" and starts the shell
# on a pseudo-terminal. The shell's prompt is rendered in the window; typing
# `echo zzzz` on the keyboard (routed by windowd to the window and on to the
# shell) produces output rendered on the next line. Screenshots check the
# title, the prompt, and the echo output.
termwin_session() {
    local n=1 t="/system/$ARCH_NAME/apps/term.program/term" mon="$WORK/monitor.sock" key
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t\r"
    serial_wait "term: started" 1 15
    sleep 1.5                                       # the shell prints its prompt; term renders it
    echo "screendump $WORK/${NAME}-prompt.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    for key in e c h o spc z z z z ret; do          # type `echo zzzz` into the window's shell
        echo "sendkey $key" | nc -w 3 -U "$mon" >/dev/null 2>&1
        sleep 0.15
    done
    sleep 1                                         # the shell runs it; term renders the output
    echo "screendump $WORK/${NAME}-echo.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

termwin_shell_test() {
    local image before w h x
    # (ARM's 800-pixel screen: term's window, 12 pixels wider with its scroll
    # bar since 15o, is moved to x 60 to fit, 25e)
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800 x=100; else w=800 h=600 x=60; fi
    image=$(make_image ${P}termwin "")
    windows_bare "$image"
    before=$failures
    SERIAL_SCRIPT=termwin_session
    boot ${P}termwin "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "term: started"
    # windowd drew the title (white); term rendered the shell's prompt and the
    # echo output (term's lighter white 220,220,220) in the window.
    check_screen region-$((x + 6))-102-72-15-255-255-255 $w $h "$WORK/${P}termwin-prompt.ppm"
    check_screen region-$((x + 2))-124-120-15-220-220-220 $w $h "$WORK/${P}termwin-prompt.ppm"
    check_screen region-$((x + 2))-139-720-15-220-220-220 $w $h "$WORK/${P}termwin-echo.ppm"
    reject "panic"
    show_log_on_failure $before
}

# termcmd_session / termcmd_shell_test: `term CMD` runs a command, not the shell
# (step 17a, for the file manager to open a program). windowd runs; `term echo
# RitterOS` opens a window, runs echo, and -- because it was given a command --
# keeps the window open after echo exits, showing an "[... exited ...]" line.
# The command's output and the exit line are rendered (white 220,220,220).
termcmd_session() {
    local n=1 t="/system/$ARCH_NAME/apps/term.program/term" mon="$WORK/monitor.sock"
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t echo RitterOS &\r"              # run echo in a terminal window
    serial_wait "term: started" 1 15
    sleep 1.5                                       # echo runs, exits; term shows the exit line
    echo "screendump $WORK/${NAME}-cmd.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    n=$((n + 1))
    prompt_wait $n                                  # term kept its window, so the shell is free
}

termcmd_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}termcmd "")
    windows_bare "$image"
    before=$failures
    SERIAL_SCRIPT=termcmd_session
    boot ${P}termcmd "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "term: started"
    check_screen region-102-124-72-15-220-220-220 $w $h "$WORK/${P}termcmd-cmd.ppm"    # echo's output "RitterOS" (+6)
    check_screen region-102-154-300-15-220-220-220 $w $h "$WORK/${P}termcmd-cmd.ppm"   # the "[... exited ...]" line
    reject "panic"
    show_log_on_failure $before
}

# owl_session / owl_shell_test: the graphical file browser (step 17b). windowd
# runs; `owl /system` opens a window listing /system -- the path at the top
# (yellow) and the directories (green), x86_64/ among them. Pressing Down three
# times selects x86_64 and Enter opens it, so the listing becomes /system/x86_64
# and kernel.elf (a file, white) appears. Keys are routed by windowd to owl
# (arrows arrive as the terminal's ESC [ A/B, which owl decodes).
owl_session() {
    local n=1 t="/system/$ARCH_NAME/apps/owl.program/owl" mon="$WORK/monitor.sock" key
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t /system &\r"                     # start the browser at /system
    serial_wait "owl: started" 1 15
    sleep 1
    echo "screendump $WORK/${NAME}-root.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    # select <arch> and open it: owl sorts, so aarch64/ is the first row after
    # .., x86_64/ the eighth (after certs, config, doc, firmware, fonts,
    # include, sdk: 63f's sdk/ made six downs open sdk/ on x86, include/ on
    # ARM; 50j's doc/ made seven open sdk/ again)
    local downs="down down down down down down down down"
    [ "$ARCH_NAME" = x86_64 ] || downs="down"
