    moveto $((768 + dx)) 112                             # the + (maximize) box, left of - and X (24-wide boxes)
    qmp "$(btn true)" "$(btn false)"                     # maximize: owl fills the screen
    sleep 1.5
    echo "screendump $WORK/${NAME}-max.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
