# wmin_session / wmin_test: minimizing a window (step 18b). A window's title bar
# has a `-` box left of the `X`; clicking it hides the window to a button at the
# bottom of the screen, and clicking that button restores it. The pointer is
# driven over QMP. Proven by not clicking the `-` (the window stays).
wmin_session() {
    local n=1 t="/system/$ARCH_NAME/test/wclient" mon="$WORK/monitor.sock" q="$WORK/qmp.sock"
    local curx cury tby
    if [ "$ARCH_NAME" = x86_64 ]; then curx=640 cury=400 tby=790; else curx=400 cury=300 tby=590; fi
    qmp() { local c; { echo '{"execute":"qmp_capabilities"}'; sleep 0.3
                       for c in "$@"; do echo "$c"; sleep 0.15; done; } |
            nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1; }
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    # A long move in steps of at most 300 pixels: QEMU's PS/2 mouse queues 16
    # bytes (four packets of four with the wheel, 15o) and keeps the rest of a
    # longer move until the next input event, so a quick click came first.
    moveto() {
        local dx=$(( $1 - curx )) dy=$(( $2 - cury )) s steps=()
        while [ $dx -gt 300 ] || [ $dx -lt -300 ]; do
            s=$([ $dx -gt 0 ] && echo 300 || echo -300); steps+=("$(rel x $s)"); dx=$((dx - s))
        done
        while [ $dy -gt 300 ] || [ $dy -lt -300 ]; do
            s=$([ $dy -gt 0 ] && echo 300 || echo -300); steps+=("$(rel y $s)"); dy=$((dy - s))
        done
        qmp ${steps[@]+"${steps[@]}"} "$(rel x $dx)" "$(rel y $dy)"; curx=$1; cury=$2
    }

    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t &\r"                                 # a 200x150 window at 100,100 (id 0)
    serial_wait "wclient: window created, id 0" 1 15
    sleep 0.3
    echo "screendump $WORK/${NAME}-open.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    moveto 277 108                                       # onto the minimize box (- left of X)
    qmp "$(btn true)" "$(btn false)"                     # minimize it
    sleep 0.5
    echo "screendump $WORK/${NAME}-min.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    moveto 50 $tby                                       # onto the taskbar button (slot 0)
    qmp "$(btn true)" "$(btn false)"                     # restore it
    sleep 0.5
    echo "screendump $WORK/${NAME}-restored.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

wmin_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}wmin "")
