# wmenu_session / wmenu_test: the menu system (step 19a). A client declares a
# menu bar ("File" with Open=1, Quit=2); windowd draws it. Clicking "File" opens
# a dropdown; clicking "Open" sends the client WMSG_MENU, which it prints as
# `wmenu: menu 1`. The pointer is driven over QMP. Proven by not clicking an item.
wmenu_session() {
    local n=1 t="/system/$ARCH_NAME/test/wmenu" mon="$WORK/monitor.sock" q="$WORK/qmp.sock"
    local curx cury
    if [ "$ARCH_NAME" = x86_64 ]; then curx=640 cury=400; else curx=400 cury=300; fi
    qmp() { local c; { echo '{"execute":"qmp_capabilities"}'; sleep 0.3
                       for c in "$@"; do echo "$c"; sleep 0.15; done; } |
            nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1; }
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    rbtn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"right","down":%s}}]}}' "$1"; }
    moveto() { qmp "$(rel x $(( $1 - curx )))" "$(rel y $(( $2 - cury )))"; curx=$1; cury=$2; }

    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t &\r"
    serial_wait "wmenu: window created" 1 15
    sleep 0.3
    moveto 120 131                                       # the "File" title in the menu bar (+6)
    qmp "$(btn true)" "$(btn false)"                     # open its dropdown
    sleep 0.4
    echo "screendump $WORK/${NAME}-open.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    moveto 120 148                                       # the "Open" item in the dropdown (+6)
    qmp "$(btn true)" "$(btn false)"                     # choose it
    serial_wait "wmenu: menu 1" 1 10
    moveto 152 184                                       # a point in the content
    qmp "$(rbtn true)" "$(rbtn false)"                   # right-click: a context menu
    sleep 0.4
    echo "screendump $WORK/${NAME}-ctx.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    moveto 160 192                                       # the "Copy" item in the popup
    qmp "$(btn true)" "$(btn false)"                     # choose it
    serial_wait "wmenu: menu 3" 1 10
}

