# wdesktop_session / wdesktop_shell_test: the desktop's right-click menu (this
# step). With a bare compositor (no startup app), right-clicking the background
# opens a menu: (41g) the apps by the names in their /system/<arch>/apps/
# bundles' info files (42b: NAME.program/info), sorted -- the test's own aaa ("A test app") first,
# then iBrowser, Image viewer, owl, Terminal, Video player (41g-2: windowed
# apps only, not tune's or edit's) -- and "Close window server". "Terminal" launches a terminal (term: started; at its
# place only when the files are read: proven by the old fixed menu); a
# right-click again and "Image viewer" start imageview; then Ctrl + click (a
# right-click for touchpads) and "Close window server" give the screen back to
# the text console (proven by ignoring the modifiers: no menu, no quit). The left
# strip (x < 100) is always clear of the launched terminal's window (720x375 at
# origin 100,100), so the clicks land on the desktop on both screen sizes.
# Proven by removing the right-click branch (no menu, so no term and no quit).
wdesktop_session() {
    local n=1 mon="$WORK/monitor.sock" q="$WORK/qmp.sock"
    local curx cury
    if [ "$ARCH_NAME" = x86_64 ]; then curx=640 cury=400; else curx=400 cury=300; fi
    qmp() { local c; { echo '{"execute":"qmp_capabilities"}'; sleep 0.3
                       for c in "$@"; do echo "$c"; sleep 0.15; done; } |
            nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1; }
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    rbtn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"right","down":%s}}]}}' "$1"; }
    ctrl() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"key","data":{"down":%s,"key":{"type":"qcode","data":"ctrl"}}}]}}' "$1"; }
    moveto() { qmp "$(rel x $(( $1 - curx )))" "$(rel y $(( $2 - cury )))"; curx=$1; cury=$2; }

    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    sleep 0.3
    moveto 40 200                                        # the empty left strip of the desktop
    qmp "$(rbtn true)" "$(rbtn false)"                   # right-click: the desktop menu opens
    sleep 0.4
    echo "screendump $WORK/${NAME}-menu.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    moveto 60 272                                        # "Terminal" (item 4)
    qmp "$(btn true)" "$(btn false)"                     # choose it
    serial_wait "term: started" 1 15                     # windowd launched the terminal
    sleep 1
    local minx=798                                       # (41g-3) its - box: to the taskbar
    [ "$ARCH_NAME" = aarch64 ] && minx=764               # (kept on ARM's screen: 60 or 72)
    moveto $minx 112
    qmp "$(btn true)" "$(btn false)"
    sleep 1
    echo "screendump $WORK/${NAME}-taskbar.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    moveto 40 300                                        # the left strip again (clear of the term window)
    qmp "$(rbtn true)" "$(rbtn false)"                   # the menu again
    sleep 0.4
    moveto 60 340                                        # "Image viewer" (item 2)
    qmp "$(btn true)" "$(btn false)"
    serial_wait "imageview: started" 1 15
    sleep 0.5
    moveto 40 300
    qmp "$(ctrl true)" "$(btn true)" "$(btn false)" "$(ctrl false)"   # Ctrl + click: the menu again
    sleep 0.4
    moveto 60 404                                        # "Close window server" (item 6)
    qmp "$(btn true)" "$(btn false)"                     # choose it
    serial_wait "windowd: window server closed" 1 10     # back to the text console
    n=$((n + 1))
    prompt_wait $n
    sleep 0.3
    echo "screendump $WORK/${NAME}-restored.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    serial_type 'help\r'                                # (41g) the apps, not their files
    prompt_wait $((n + 1))
}

wdesktop_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}wdesktop "")
    windows_bare "$image"                                # no startup app: an empty desktop
    printf 'name = A test app\n' >"$WORK/${P}aaa.info"   # (41g: an app of the test's, 42b a bundle:
    $RFS put "$image" $RFS_PART /system/$ARCH_NAME/apps/aaa.program/info "$WORK/${P}aaa.info" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /system/$ARCH_NAME/apps/aaa.program/aaa \
        "$ROOT/build/system/$ARCH_NAME/test/wclient" >/dev/null || exit 1   # its program: listed)
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=wdesktop_session
    boot ${P}wdesktop "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    # The desktop menu's seven items (white text); item 0 sampled clear of the
    # cursor arrow that sits at the click point (also white).
    check_screen region-70-201-80-14-255-255-255 $w $h "$WORK/${P}wdesktop-menu.ppm"   # "A test app"
    check_screen region-46-297-160-14-255-255-255 $w $h "$WORK/${P}wdesktop-menu.ppm"  # "Close window server"
    # (41g-3) the apps' icons at half size, left of their names: owl's folder
    # (yellow) on item 3, the video player's disc (red) on item 5; and
    # Terminal's (its grey frame; its dark screen is the desktop's colour) on
    # the minimized terminal's taskbar button
    check_screen region-43-248-16-16-235-203-139 $w $h "$WORK/${P}wdesktop-menu.ppm"
    check_screen region-43-280-16-16-191-97-106 $w $h "$WORK/${P}wdesktop-menu.ppm"
    check_screen region-3-$((h - 18))-16-16-76-86-106 $w $h "$WORK/${P}wdesktop-taskbar.ppm"
    expect "term: started"                               # "Terminal" launched it
    expect "imageview: started, no image"                # and "Image viewer" imageview
    compare "help lists the apps, not their .info files (41g)" "imageview 1, info files 0" \
            "imageview $(command_output help | grep -ac '^  imageview '), info files $(command_output help | grep -acE '^  [^ ]+\.(info|png)( |$)')"
    expect "windowd: window server closed"               # "Close window server" quit windowd
    check_screen restored $w $h "$WORK/${P}wdesktop-restored.ppm"   # the text console came back
    reject "panic"
    show_log_on_failure $before
}

# wopen_session / wopen_shell_test: opening files from the GUI (after the
# window fixes, the user's). imageview starts without a file (an empty window
# with a File menu); File > Open... brings up the shared dialog
# (window_choose_file in libwindow: a window of its own listing a folder),
# where a path typed and Enter choose the file: imageview shows it and its
# window takes the image's size. owl opens a .ppm by its type (in imageview,
# not the editor), and reel, also started without a file, plays a video
# chosen in the same dialog. Proven by a dialog that never returns a choice
# (no "showing", no "playing").
wopen_session() {
    local n=1 mon="$WORK/monitor.sock" q="$WORK/qmp.sock" curx cury
    if [ "$ARCH_NAME" = x86_64 ]; then curx=640 cury=400; else curx=400 cury=300; fi
    qmp() { local c; { echo '{"execute":"qmp_capabilities"}'; sleep 0.3
                       for c in "$@"; do echo "$c"; sleep 0.15; done; } |
            nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1; }
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    moveto() { qmp "$(rel x $(( $1 - curx )))" "$(rel y $(( $2 - cury )))"; curx=$1; cury=$2; }
    click() { moveto $1 $2; qmp "$(btn true)" "$(btn false)"; }
    keys() { local k; for k in "$@"; do echo "sendkey $k"; sleep 0.15; done | nc -w 3 -U "$mon" >/dev/null 2>&1; }
    # Window k opens at (100 + 40k, 100 + 40k): its File title at x+6..x+56, y+24..y+40,
    # the dropdown's first item (Open...) at y+40..y+56.
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_wait "imageview: started, no image" 1 15
    sleep 0.5
    click 130 132                                        # File (window 0)
    sleep 0.3
    click 130 148                                        # Open...: the dialog, window 1
    sleep 1
    echo "screendump $WORK/${NAME}-dialog.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    keys slash t e s t slash s o l i d dot p p m ret     # a path typed, then Enter
    serial_wait "imageview: showing /test/solid.ppm" 1 15
    sleep 1
    echo "screendump $WORK/${NAME}-view.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    serial_type 'owl /test/open &\r'                     # window 1 again (the dialog closed)
    serial_wait "owl: started" 1 15
    sleep 0.5
    keys down ret                                        # past "..", the picture: open it
    serial_wait "imageview: showing /test/open/solid.ppm" 1 15
    serial_type 'reel &\r'                               # window 3
    serial_wait "reel: started, no video" 1 15
    sleep 0.5
    click 250 252                                        # File (window 3)
    sleep 0.3
    click 250 268                                        # Open...
    sleep 1
    keys slash t e s t slash c l i p dot r v i d ret
    serial_wait "reel: playing /test/clip.rvid" 1 15
    serial_wait "reel: done" 1 20
    serial_type '\r'
    n=$((n + 1)); prompt_wait $n
}

wopen_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}wopen "")
    windows_startup "$image" imageview               # without a file: an empty window
    python3 "$ROOT/scripts/mkimage.py" "$WORK/${P}wopen-pic.ppm" "$WORK/${P}wopen-pic.bmp" \
        "$WORK/${P}wopen-solid.ppm" >/dev/null || exit 1
    python3 "$ROOT/scripts/mkvideo.py" "$WORK/${P}wopen-clip.rvid" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /test/solid.ppm "$WORK/${P}wopen-solid.ppm" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /test/open/solid.ppm "$WORK/${P}wopen-solid.ppm" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /test/clip.rvid "$WORK/${P}wopen-clip.rvid" >/dev/null || exit 1
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
