    check_screen region-144-164-150-15-235-203-139 $w $h "$WORK/${P}wopen-dialog.ppm"  # the dialog's folder line
    expect "imageview: showing /test/solid.ppm (200x150)"
    check_screen region-120-150-80-40-200-80-40 $w $h "$WORK/${P}wopen-view.ppm"      # the picture in window 0
    expect "imageview: showing /test/open/solid.ppm"     # owl opened it by its type
    reject "edit: "                                      # (not in the editor)
