# open_session / open_shell_test: `open FILE...` (41g-2, the user's; names
# agreed): each file to the program its ending has in (42a) the user's
# ~/.config/filetypes (window_app_for, owl's lookup too): a picture named in
# capital letters in imageview, a video in reel, a folder in owl, text and a
# sound in edit and tune in a terminal (programs in bin), a file no program
# takes in the editor, a program run in a terminal, a missing file refused
# (exit 1, the others opened all the same); a line the user added (pic =
# imageview) is followed. Proven by a window_app_for that minds the ending's
# case, one that reads only /system/config/filetypes (the user's line
# ignored) and one that runs every program in its window.
open_session() {
    local n=1
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type 'echo hi > /home/root/note.txt; echo hi > /home/root/x.dat; cp /test/Solid.PPM /home/root/copy.pic\r'
    n=$((n + 1)); prompt_wait $n
    serial_type 'echo "pic = imageview" >> /home/root/.config/filetypes\r'
    n=$((n + 1)); prompt_wait $n
    serial_type 'open /test/Solid.PPM /test/clip.rvid /test /home/root/note.txt /test/tone.wav /home/root/x.dat /test/run.sh /nosuch /home/root/copy.pic; echo rc=$?\r'
    n=$((n + 1)); prompt_wait $n
    serial_wait "reel: done" 1 20
    sleep 2
}

open_shell_test() {
    local image before
    image=$(make_image ${P}open "")
    windows_bare "$image"
    python3 "$ROOT/scripts/mkimage.py" "$WORK/${P}open-pic.ppm" "$WORK/${P}open-pic.bmp" \
        "$WORK/${P}open-solid.ppm" >/dev/null || exit 1
    python3 "$ROOT/scripts/mkvideo.py" "$WORK/${P}open-clip.rvid" >/dev/null || exit 1
    python3 "$ROOT/scripts/mkwav.py" "$WORK/${P}open-tone.wav" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /test/Solid.PPM "$WORK/${P}open-solid.ppm" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /test/clip.rvid "$WORK/${P}open-clip.rvid" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /test/tone.wav "$WORK/${P}open-tone.wav" >/dev/null || exit 1
    printf '#!/bin/sh\necho ran\n' >"$WORK/${P}open-run.sh"       # (put files are 0755)
    $RFS put "$image" $RFS_PART /test/run.sh "$WORK/${P}open-run.sh" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=open_session
    boot ${P}open "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    want_text want <<'LINES'
open: /test/Solid.PPM in imageview
open: /test/clip.rvid in reel
open: /test in owl
open: /home/root/note.txt in edit, in a terminal
open: /test/tone.wav in tune, in a terminal
open: /home/root/x.dat in edit, in a terminal
open: /test/run.sh run in a terminal
open: /nosuch: No such file or directory
open: /home/root/copy.pic in imageview
rc=1
LINES
    compare "open: each file to its program, by the user's file types (41g-2, 42a)" "$want" \
            "$(tr -d '\r' <<<"$TEXT" | grep -aE '^(open: |rc=)')"
    expect "imageview: showing /test/Solid.PPM"
    expect "imageview: showing /home/root/copy.pic"   # (42a) by the line the user added
    expect "reel: playing /test/clip.rvid"
    expect "owl: started"
    compare "four terminals started (edit twice, tune, the program)" "4" \
            "$(tr -d '\r' <<<"$TEXT" | grep -ac '^term: started')"
    reject "panic"
    show_log_on_failure $before
}

# notify_session / notify_shell_test: notifications (41g-4, the user's
# names). Without windowd `notify` says so (exit 1; 2 for no words); then a
# window's (widgettest notify: window_notify with a title and a text that
# wraps) and the shell's `notify` (no title) show as boxes at the top right,
# the newest on top, pixel-exact; 6 s later both are gone. Proven by windowd
# ignoring WMSG_NOTIFY (no boxes) and by boxes that never go.
notify_session() {
    local n=1 mon="$WORK/monitor.sock"
    prompt_wait $n
    serial_type 'notify hi; echo notify-rc=$?; notify; echo notify-usage=$?\r'
    n=$((n + 1)); prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type "/system/$ARCH_NAME/test/widgettest notify &\r"
    serial_wait "widgettest: notified" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type 'notify Hello from the shell\r'
    n=$((n + 1)); prompt_wait $n
    sleep 0.5
    echo "screendump $WORK/${NAME}-shown.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 6.5                                       # (5 s each)
    echo "screendump $WORK/${NAME}-gone.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

notify_shell_test() {
    local image before w h x bg=59.66.82 fg=216.222.233
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    x=$((w - 320 - 8 + 8))                          # the boxes' text: NOTE_GAP and NOTE_PAD in
    image=$(make_image ${P}notify "")
    windows_bare "$image"
    before=$failures
    SERIAL_SCRIPT=notify_session
    boot ${P}notify "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "notify: no window server: "
    expect "notify-rc=1"
    expect "usage: notify TEXT..."
    expect "notify-usage=2"
    expect "widgettest: notified 0"
    local shown="$WORK/${P}notify-shown.ppm"
    # the shell's (the newest, on top): one line, no title; the window's below
    # it (8 + 31 + 8): its bold title, then its text in two lines
    check_screen "textat-$x-16-regular-$fg-$bg-Hello from the shell" $w $h "$shown"
    check_screen "textat-$x-55-bold-255.255.255-$bg-From a window" $w $h "$shown"
    check_screen "textat-$x-72-regular-$fg-$bg-widgettest says hello with a text" $w $h "$shown"
    check_screen "textat-$x-87-regular-$fg-$bg-that wraps onto a second line" $w $h "$shown"
    check_screen px-$((w - 20))-20-46-52-64 $w $h "$WORK/${P}notify-gone.ppm"    # the desktop again
    check_screen px-$((w - 20))-60-46-52-64 $w $h "$WORK/${P}notify-gone.ppm"
    reject "panic"
    show_log_on_failure $before
}

# theme_session / theme_shell_test: the user's colours (41g-5, the user's
# names): /system/config/windows with theme = light and accent = BF616A.
# term alone (its light background and dark text), then owl and
# widgettest (libwidget) over it: the desktop, owl's title bar (behind) and
# widgettest's (in front, the accent), owl's light panel, libwidget's
# background, button face, text and its checked box in the accent. The dark
# theme without an accent is every other window test's. Proven by windowd,
# libwindow's window_color, owl and term each ignoring the theme.
theme_session() {
    local n=1 mon="$WORK/monitor.sock"
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type "/system/$ARCH_NAME/apps/term.program/term &\r"
    serial_wait "term: started" 1 15
    n=$((n + 1)); prompt_wait $n
    sleep 1.5
    echo "screendump $WORK/${NAME}-term.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    serial_type 'kill $!\r'
    n=$((n + 1)); prompt_wait $n
    sleep 1
    serial_type "/system/$ARCH_NAME/apps/owl.program/owl /system &\r"
    serial_wait "owl: started" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type "/system/$ARCH_NAME/test/widgettest &\r"
    n=$((n + 1)); prompt_wait $n
    sleep 2
    echo "screendump $WORK/${NAME}-apps.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

theme_shell_test() {
    local image before w h t a dx=0
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    [ "$ARCH_NAME" = aarch64 ] && dx=-28            # (owl's window at x 72 there, 25e)
    image=$(make_image ${P}theme "")
    printf 'startup =\ntheme = light\naccent = BF616A\n' > "$WORK/${P}windows.cfg"
    $RFS put "$image" $RFS_PART /system/config/windows "$WORK/${P}windows.cfg" >/dev/null || exit 1
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=theme_session
    boot ${P}theme "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "term: started"
    expect "owl: started"
    reject "windowd: accent ="
    t="$WORK/${P}theme-term.ppm"
    check_screen px-$((w - 10))-20-216-222-233 $w $h "$t"                # the light desktop
    check_screen region-0-0-$w-$h-236-239-244 $w $h "$t"                 # term's light background
    check_screen region-0-0-$w-$h-46-52-64 $w $h "$t"                    # and its dark text
    a="$WORK/${P}theme-apps.ppm"
    check_screen px-$((w - 10))-20-216-222-233 $w $h "$a"
    check_screen px-330-110-229-233-240 $w $h "$a"                       # owl's title bar, behind
    check_screen region-$((106 + dx))-102-90-15-59-66-82 $w $h "$a"      # its dark title
    check_screen region-110-150-25-150-229-233-240 $w $h "$a"            # owl's light panel
    check_screen px-300-150-191-97-106 $w $h "$a"                        # widgettest's in front: the accent
    # libwidget (exact points: the dark theme's text, edges and background
    # are the light one's background, face and text): its background, the
    # Big button's face, the checked box in the accent
    check_screen px-400-200-236-239-244 $w $h "$a"
    check_screen px-170-300-216-222-233 $w $h "$a"
    check_screen region-144-164-300-240-191-97-106 $w $h "$a"
    reject "panic"
    show_log_on_failure $before
}

# headless_session / headless_shell_test: `windowd headless WxH` (41h-1,
# the user's names): no screen, no input devices, listening where
# WINDOW_SOCKET says. Root runs the screen's windowd and a headless one at
# /tmp/w1 beside it; widgettest with WINDOW_SOCKET=/tmp/w1 opens its window
# there (libwindow follows the variable), not on the screen; a bad size is
# refused (exit 2). bob, over SSH (no screen of his), runs a headless one of
# his own with a window in it. Proven by a headless windowd that ignores
# WINDOW_SOCKET (/run/windowd is taken), one that takes the screen (bob is
# refused), and a libwindow that ignores the variable (the window shows).
headless_session() {
    local n=1 mon="$WORK/monitor.sock" a="/system/$ARCH_NAME"
    local -a bob=(-o PubkeyAuthentication=no -o PreferredAuthentications=password
                  -o NumberOfPasswordPrompts=1)
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15                        # (and the elf sshd listening)
    serial_type "useradd bob\r"
    n=$((n + 1)); prompt_wait $n
    serial_type "passwd bob\r"
    serial_wait "New password: " 1
    serial_type "bob-pw-1\r"
    serial_wait "Again: " 1
    serial_type "bob-pw-1\r"
    n=$((n + 1)); prompt_wait $n 30
    serial_type 'windowd headless; echo usage-rc=$?; windowd headless 10x10; echo small-rc=$?\r'
    n=$((n + 1)); prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type 'WINDOW_SOCKET=/tmp/w1 windowd headless 640x480 &\r'
    serial_wait "windowd: listening on /tmp/w1" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type "WINDOW_SOCKET=/tmp/w1 $a/test/widgettest screen &\r"
    serial_wait "widgettest: screen ready" 1 15
    n=$((n + 1)); prompt_wait $n
    sleep 1
    echo "screendump $WORK/${NAME}-screen.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    SSH_ASKPASS="$WORK/${P}askpass-bob" SSH_ASKPASS_REQUIRE=force DISPLAY=:0 \
        mac_ssh headless-bob "${bob[@]}" bob@127.0.0.1 \
        "WINDOW_SOCKET=/tmp/bw $a/bin/windowd headless 320x200 & w=\$!; sleep 2; WINDOW_SOCKET=/tmp/bw $a/test/widgettest screen & c=\$!; sleep 3; kill \$c \$w; echo bob done"
}

headless_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}headless "")
    windows_bare "$image"
    rm -f "$WORK/${P}known_hosts"
    printf '#!/bin/sh\necho bob-pw-1\n' >"$WORK/${P}askpass-bob"
    chmod 700 "$WORK/${P}askpass-bob"
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_SSH_PORT-:22"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=headless_session
    boot ${P}headless "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "usage: windowd [headless WxH] (W and H 64-8192)"
    expect "usage-rc=2"
    expect "small-rc=2"
    expect "windowd: listening on /run/windowd, screen ${w}x${h}"
    expect "windowd: listening on /tmp/w1, screen 640x480 (headless)"
    expect "widgettest: screen ready"
    check_screen px-200-200-46-52-64 $w $h "$WORK/${P}headless-screen.ppm"   # its window not on the screen
    local bob_out
    bob_out=$(cat "$WORK/${P}headless-bob")
    compare "bob's headless windowd over SSH, with a window in it" \
            "$(printf 'windowd: listening on /tmp/bw, screen 320x200 (headless)\nwidgettest: screen ready\nbob done\nexit 0')" \
            "$(grep -E '^(windowd: listening|widgettest: screen ready|bob done|exit )' <<<"$bob_out")"
    reject "panic"
    show_log_on_failure $before
}

# wshot_session / wshot_shell_test: `wshot FILE.png` (41h-2, the user's
# names): WMSG_SHOT to a headless windowd (640x400) holding widgettest's
# window and a notification; the PNG (libimage's own DEFLATE) is read on
# the Mac by scripts/pngcheck.py's decoder (Python's zlib) into a picture
# whose desktop, window, title bar and notification text are where windowd
# draws them, and on RitterOS by imagetest (libimage's decoder) to the same
# pixels' SHA-256. wshot without a file (exit 2) and without a windowd
# (exit 1). Proven by wshot taking blue for red (the desktop and the title
# bar wrong) and by image_save writing PPM for .png (the Mac cannot decode
# it). (windowd draws what is pending before the copy, for a shot within a
# frame of a change: the session waits a second, so that is not tested.)
wshot_session() {
    local n=1 a="/system/$ARCH_NAME"
    prompt_wait $n
    serial_type 'wshot; echo usage-rc=$?; wshot /tmp/none.png; echo none-rc=$?\r'
    n=$((n + 1)); prompt_wait $n
    serial_type 'WINDOW_SOCKET=/tmp/w1 windowd headless 640x400 &\r'
    serial_wait "windowd: listening on /tmp/w1" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type "WINDOW_SOCKET=/tmp/w1 $a/test/widgettest screen &\r"
    serial_wait "widgettest: screen ready" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type 'WINDOW_SOCKET=/tmp/w1 notify Hello from wshot; sleep 1; WINDOW_SOCKET=/tmp/w1 wshot /tmp/shot.png; echo shot-rc=$?\r'
    n=$((n + 1)); prompt_wait $n 20
    serial_type "$a/test/imagetest /tmp/shot.png\r"
    n=$((n + 1)); prompt_wait $n 20
}

wshot_shell_test() {
    local image before png="$WORK/${P}wshot.png" ppm="$WORK/${P}wshot-png.ppm" hash
    image=$(make_image ${P}wshot "")
    windows_bare "$image"
    rm -f "$png" "$ppm"
    before=$failures
    SERIAL_SCRIPT=wshot_session
    boot ${P}wshot "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "usage: wshot FILE.png"
    expect "usage-rc=2"
    expect "wshot: no window server at /run/windowd: "
    expect "none-rc=1"
    expect "wshot: /tmp/shot.png (640x400)"
    expect "shot-rc=0"
    $RFS cat "$image" $RFS_PART /tmp/shot.png >"$png"
    hash=$(python3 - "$ROOT/scripts" "$png" "$ppm" <<'PY'
import hashlib, sys
sys.path.insert(0, sys.argv[1])
import pngcheck
w, h, ch, pix = pngcheck.decode_png(open(sys.argv[2], "rb").read())
rgb = pix if ch == 3 else b"".join(pix[i:i + 3] for i in range(0, len(pix), 4))
open(sys.argv[3], "wb").write(b"P6\n%d %d\n255\n" % (w, h) + rgb)
rgba = b"".join(rgb[i:i + 3] + b"\xff" for i in range(0, len(rgb), 3))
print(hashlib.sha256(rgba).hexdigest())
PY
)
    check "the PNG decodes on the Mac" "the PNG does not decode on the Mac" eval '[ ${#hash} = 64 ]'
    [ ${#hash} = 64 ] && expect "imagetest: /tmp/shot.png 640x400 sha256 $hash"   # the same pixels on RitterOS
    check_screen px-630-390-46-52-64 640 400 "$ppm"                     # the desktop
    check_screen px-200-200-48-96-48 640 400 "$ppm"                     # widgettest's window
    check_screen px-250-110-94-129-172 640 400 "$ppm"                   # its title bar, in front
    check_screen "textat-320-16-regular-216.222.233-59.66.82-Hello from wshot" 640 400 "$ppm"
    reject "panic"
    show_log_on_failure $before
}

# wsend_session / wsend_shell_test: `wsend` (41h-3, the user's names):
# WMSG_INPUT into a headless windowd (640x400), handled as the devices'
# events. A click focuses widgettest's editor; typed text (54 bytes, ~108
# events at once: more than windowd queues for a program), Enter,
# Backspace and Left edit it; a click on the close box closes it (the
# editor's text printed). A drag of a window's title bar moves it (seen by
# wshot); a right-click on the desktop opens its menu and a click on "Close
# window server" ends that windowd. The screen's windowd refuses wsend
# (exit 1); bad arguments exit 2. Proven by a windowd taking input on the
# screen too, one answering before the programs' queues went out (text
# lost: "the quick browXn"), and wsend's drag moving with the button let
# go (the window stays).
wsend_session() {
    local n=1 a="/system/$ARCH_NAME"
    prompt_wait $n
    serial_type 'wsend; echo usage-rc=$?; wsend key nosuch; echo key-rc=$?\r'
    n=$((n + 1)); prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type 'wsend click 10 10; echo refused-rc=$?\r'
    n=$((n + 1)); prompt_wait $n
    # (41h-6) wsend wait: nothing there (10 s), then the server, a window
    serial_type 'export WINDOW_SOCKET=/tmp/w1; wsend wait; echo early-rc=$?\r'
    n=$((n + 1)); prompt_wait $n 20
    serial_type 'windowd headless 640x400 & wsend wait; echo up-rc=$?\r'
    serial_wait "up-rc=" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type "$a/test/widgettest editor & wsend wait editor; echo editor-rc=\$?\r"
    serial_wait "editor-rc=" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type 'wsend wait nosuch; echo nosuch-rc=$?\r'
    n=$((n + 1)); prompt_wait $n 20
    serial_type 'wsend click 200 150; wsend type "the quick brown fox jumps over the lazy dog, 0123456789"; wsend key enter; wsend type world; wsend key backspace; wsend key left; wsend type X; wsend click 456 112\r'
    serial_wait "widgettest: done" 1 20
    n=$((n + 1)); prompt_wait $n
    serial_type "$a/test/widgettest screen &\r"
    serial_wait "widgettest: screen ready" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type 'wsend drag 200 110 300 160; wshot /tmp/drag.png\r'
    n=$((n + 1)); prompt_wait $n 20
    # (41h-5) physical keys, held and let go, into wkeys (in front)
    serial_type "$a/test/wkeys 7 &\r"
    serial_wait "wkeys: ready" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type 'wsend down ctrl; wsend key a; wsend up ctrl; wsend key f2; wsend down space\r'
    serial_wait "wkeys: done" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type 'wsend right 40 200; wsend click 60 288\r'
    serial_wait "windowd: window server closed" 1 15
    n=$((n + 1)); prompt_wait $n
}

wsend_shell_test() {
    local image before png="$WORK/${P}wsend.png" ppm="$WORK/${P}wsend-png.ppm" ok
    image=$(make_image ${P}wsend "")
    windows_bare "$image"
    rm -f "$png" "$ppm"
    before=$failures
    SERIAL_SCRIPT=wsend_session
    boot ${P}wsend "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "usage: wsend click|right|move X Y | drag X1 Y1 X2 Y2 | type TEXT | key|down|up NAME | wait [TITLE]"
    expect "wsend: no window server at /tmp/w1 (waited 10 s)"      # (41h-6)
    expect "early-rc=1"
    expect "up-rc=0"
    expect "editor-rc=0"
    expect 'wsend: no window "nosuch" at /tmp/w1 (waited 10 s)'
    expect "nosuch-rc=1"
    expect "usage-rc=2"
    expect "wsend: no key nosuch (a-z, 0-9, space, enter, tab, escape, backspace, up, down, left, right, home, end, pageup, pagedown, insert, delete, ctrl, shift, alt, f1-f12)"
    expect "key-rc=2"
    expect "wsend: refused: only a headless windowd takes input"
    expect "refused-rc=1"
    expect "editor the quick brown fox jumps over the lazy dog, 0123456789|worXl, entry "   # typed, Enter, Backspace, Left; closed
    expect "wshot: /tmp/drag.png (640x400)"
    compare "physical keys, Ctrl held over a, F2, Space held (41h-5)" \
            "$(printf 'wkeys: down 0xe0\nwkeys: down 0x04\nwkeys: byte 0x61\nwkeys: up 0x04\nwkeys: up 0xe0\nwkeys: down 0x3b\nwkeys: up 0x3b\nwkeys: down 0x2c')" \
            "$(tr -d '\r' <<<"$TEXT" | grep -a '^wkeys: \(down\|up\|byte\)')"
    expect "windowd: window server closed"               # the desktop menu's last item
    $RFS cat "$image" $RFS_PART /tmp/drag.png >"$png"
    ok=$(python3 - "$ROOT/scripts" "$png" "$ppm" <<'PY'
import sys
sys.path.insert(0, sys.argv[1])
import pngcheck
w, h, ch, pix = pngcheck.decode_png(open(sys.argv[2], "rb").read())
rgb = pix if ch == 3 else b"".join(pix[i:i + 3] for i in range(0, len(pix), 4))
open(sys.argv[3], "wb").write(b"P6\n%d %d\n255\n" % (w, h) + rgb)
print("ok")
PY
)
    check "the drag's PNG decodes" "the drag's PNG does not decode" eval '[ "$ok" = ok ]'
    check_screen px-450-300-48-96-48 640 400 "$ppm"            # the window, dragged by (100, 50)
    check_screen px-150-150-46-52-64 640 400 "$ppm"            # where it was: the desktop
    reject "panic"
    show_log_on_failure $before
}

# owl_with_session / owl_with_test: owl's Open with... (42c, the user's
# names) in a headless windowd (1024x768) driven by wsend. owl in /test/ow
# (.., pic.png); a right-click on pic.png, the menu's Open with... opens
# libwindow's window_choose at /system/<arch>/apps: the bundles are items
# (no slash), those whose info lists png (imageview) in the text's colour,
# the rest greyed (window_app_opens). owl typed in its name line is
# refused (the dialog stays; owl is not started again); imageview typed as
# it is shown (no .program) is chosen: owl starts it with the file.
# Proven by a dialog that lets anything be chosen (a second owl) and a
# window_app_opens that ignores `types` (nothing greyed).
owl_with_session() {
    local n=1 a="/system/$ARCH_NAME"
    prompt_wait $n
    serial_type 'export WINDOW_SOCKET=/tmp/w1; windowd headless 1024x768 & wsend wait; echo up-rc=$?\r'
    serial_wait "up-rc=" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type "$a/apps/owl.program/owl /test/ow & wsend wait owl; echo owl-rc=\$?\r"
    serial_wait "owl-rc=" 1 15
    n=$((n + 1)); prompt_wait $n
    # pic.png's row (the path, .., then pic.png), a right-click there, the
    # menu's second item
    serial_type 'wsend right 200 177; wsend click 220 201; wsend wait "Open with"; echo dialog-rc=$?; wshot /tmp/with.png\r'
    serial_wait "wshot: /tmp/with.png" 1 20
    n=$((n + 1)); prompt_wait $n
    serial_type 'wsend type owl; wsend key enter; wsend type imageview; wsend key enter\r'
    serial_wait "imageview: showing" 1 20
    n=$((n + 1)); prompt_wait $n
}

owl_with_test() {
    local image before png="$WORK/${P}owlwith.png" ppm="$WORK/${P}owlwith.ppm" ok
    image=$(make_image ${P}owlwith "")
    windows_bare "$image"
    $RFS put "$image" $RFS_PART /test/ow/pic.png "$ROOT/build/system/$ARCH_NAME/apps/owl.program/icon.png" \
        >/dev/null || exit 1
    rm -f "$png" "$ppm"
    before=$failures
    SERIAL_SCRIPT=owl_with_session
    boot ${P}owlwith "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "dialog-rc=0"
    expect "owl: open /test/ow/pic.png with /system/$ARCH_NAME/apps/imageview.program"
    expect "imageview: showing /test/ow/pic.png (32x32)"
    check "owl started once (the dialog refused owl for a .png)" "$(grep -ac 'owl: started' <<<"$TEXT")" \
          eval '[ "$(grep -ac "owl: started" <<<"$TEXT")" = 1 ]'
    $RFS cat "$image" $RFS_PART /tmp/with.png >"$png"
    ok=$(python3 - "$ROOT/scripts" "$png" "$ppm" <<'PY'
import sys
sys.path.insert(0, sys.argv[1])
import pngcheck
w, h, ch, pix = pngcheck.decode_png(open(sys.argv[2], "rb").read())
rgb = pix if ch == 3 else b"".join(pix[i:i + 3] for i in range(0, len(pix), 4))
open(sys.argv[3], "wb").write(b"P6\n%d %d\n255\n" % (w, h) + rgb)
print("ok")
PY
)
    check "the dialog's picture decodes" "it does not decode" eval '[ "$ok" = ok ]'
    # its rows of 15 from y 194: ibrowser, imageview, owl, reel, term
    check_screen region-150-209-90-15-216-222-233 1024 768 "$ppm"   # imageview: can be chosen
    check_screen region-150-224-90-15-108-118-134 1024 768 "$ppm"   # owl: greyed
    check_screen region-150-239-90-15-108-118-134 1024 768 "$ppm"   # reel: greyed
    reject "panic"
    show_log_on_failure $before
}

# wmany_session / wmany_shell_test: windowd reaps the per-connection threads
# (overnight review fix). Opening and closing 21 windows in turn works only if
# windowd joins the finished client threads; without reaping the 15th fails.
wmany_session() {
    local n=1 t="/system/$ARCH_NAME/test/wmany"
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t\r"
    serial_wait "wmany: ok" 1 30
    n=$((n + 1))
    prompt_wait $n
}

wmany_shell_test() {
    local image before
    image=$(make_image ${P}wmany "")
    windows_bare "$image"
    before=$failures
    SERIAL_SCRIPT=wmany_session
    boot ${P}wmany "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "wmany: ok, 21 windows opened and closed in turn"
    reject "failed to open"
    reject "panic"
    show_log_on_failure $before
}

# wstart_session / wstart_shell_test: windowd launches a session program on its
# own (step 15h) and keeps the desktop up when it ends (this step). With
# startup = term it starts a terminal; typing `exit` into the window (keys
# routed by windowd to the shell) ends the shell, so term closes -- but windowd
# stays, the empty desktop showing where the window was (not the text console).
# Ctrl-Alt-Delete then ends windowd and the console returns. Proven by windowd
# no longer printing "session ended" (it used to exit with the session).
wstart_session() {
    local n=1 mon="$WORK/monitor.sock" key
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_wait "term: started" 1 15                 # windowd started the terminal by itself
    sleep 1.5                                        # the shell prints its prompt; term renders it
    echo "screendump $WORK/${NAME}-term.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    for key in e x i t ret; do                       # type `exit` into the window's shell
        echo "sendkey $key" | nc -w 3 -U "$mon" >/dev/null 2>&1
        sleep 0.15
    done
    sleep 1.5                                        # the shell and term end; windowd stays up
    echo "screendump $WORK/${NAME}-desktop.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    echo "sendkey ctrl-alt-delete" | nc -w 3 -U "$mon" >/dev/null 2>&1   # now end windowd
    sleep 1.5
    n=$((n + 1))
    prompt_wait $n
    sleep 0.3
    echo "screendump $WORK/${NAME}-restored.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

wstart_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}wstart "")
    windows_startup "$image" term                    # this test drives the terminal and `exit`
    before=$failures
    SERIAL_SCRIPT=wstart_session
    boot ${P}wstart "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "term: started"                           # windowd launched it, not the test
    reject "windowd: session ended"                  # windowd no longer exits with the session
    check_screen region-106-102-72-15-255-255-255 $w $h "$WORK/${P}wstart-term.ppm"   # the "Terminal" title
    check_screen px-150-150-46-52-64 $w $h "$WORK/${P}wstart-desktop.ppm"   # the desktop stayed up where the window was
    check_screen restored $w $h "$WORK/${P}wstart-restored.ppm"            # Ctrl-Alt-Delete brought the console back
    reject "panic"
    show_log_on_failure $before
}

# wescape_session / wescape_shell_test: the Ctrl-Alt-Delete escape (step 15h).
# windowd owns the screen (with its terminal); Ctrl-Alt-Delete makes the kernel
# end the owner, so the text console comes back without the session ending on
# its own -- the escape for a hung window server. Proven by removing the
# kernel's key check (the console then stays the desktop).
wescape_session() {
    local n=1 mon="$WORK/monitor.sock"
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_wait "owl: started" 1 15                  # windowd's default app (step 18a)
    sleep 1
    echo "sendkey ctrl-alt-delete" | nc -w 3 -U "$mon" >/dev/null 2>&1    # end the window server
    sleep 1.5
    n=$((n + 1))
    prompt_wait $n
    sleep 0.3
    echo "screendump $WORK/${NAME}-restored.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

wescape_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}wescape "")
    before=$failures
    SERIAL_SCRIPT=wescape_session
    boot ${P}wescape "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "owl: started"                                          # windowd launched its default app
    check_screen restored $w $h "$WORK/${P}wescape-restored.ppm"   # Ctrl-Alt-Delete brought the console back
    reject "panic"
    show_log_on_failure $before
}

# wclose_session / wclose_shell_test: the close box (step 15i). A client's
# window carries an X at the right of its title bar; clicking it makes windowd
# send WMSG_CLOSE, and the client closes. The pointer is driven over QMP as
# deltas from the screen centre (where windowd's cursor starts). Proven by not
# clicking the box (the window stays) -- the test clicks it and the window goes.
wclose_session() {
    local n=1 t="/system/$ARCH_NAME/test/wclient" mon="$WORK/monitor.sock" q="$WORK/qmp.sock"
    local curx cury
    if [ "$ARCH_NAME" = x86_64 ]; then curx=640 cury=400; else curx=400 cury=300; fi
    qmp() { local c; { echo '{"execute":"qmp_capabilities"}'; sleep 0.3
                       for c in "$@"; do echo "$c"; sleep 0.15; done; } |
            nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1; }
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    # A long move in steps of at most 300 pixels: QEMU's PS/2 mouse queues 16
    # bytes (four packets of four with the wheel, 15o) and keeps the rest of a
    # longer move until the next input event, so a quick click came first.
    moveto() {
        local dx=$(( $1 - curx )) dy=$(( $2 - cury )) s steps=()
        while [ $dx -gt 300 ] || [ $dx -lt -300 ]; do
            s=$([ $dx -gt 0 ] && echo 300 || echo -300); steps+=("$(rel x $s)"); dx=$((dx - s))
        done
        while [ $dy -gt 300 ] || [ $dy -lt -300 ]; do
            s=$([ $dy -gt 0 ] && echo 300 || echo -300); steps+=("$(rel y $s)"); dy=$((dy - s))
        done
        qmp ${steps[@]+"${steps[@]}"} "$(rel x $dx)" "$(rel y $dy)"; curx=$1; cury=$2
    }

    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t &\r"                                 # a 200x150 window at 100,100 (id 0)
    serial_wait "wclient: window created, id 0" 1 15
    sleep 0.3
    moveto 295 108                                       # onto its close box (X), at the title bar's right
    qmp "$(btn true)" "$(btn false)"                     # click it
    serial_wait "wclient: closed" 1 10
    sleep 0.3
    echo "screendump $WORK/${NAME}-gone.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

wclose_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}wclose "")
    windows_bare "$image"                                # no auto-term: drive windowd with wclient
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=wclose_session
    boot ${P}wclose "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "wclient: window created, id 0"
    expect "wclient: closed"                             # the X asked it to close, and it did
    check_screen px-150-150-46-52-64 $w $h "$WORK/${P}wclose-gone.ppm"   # the desktop where the window was
    reject "panic"
    show_log_on_failure $before
}

# wresize_session / wresize_shell_test: resizing (step 15j). windowd launches
# the terminal (80x25, outer bottom near y=495 at origin 100,100); dragging its
# bottom edge down makes windowd send WMSG_RESIZE, term reflows to more rows and
# hands windowd a taller buffer, so the window grows to cover what was desktop.
# The pointer is driven over QMP. Proven by term ignoring the resize (see below).
# (41e-2) Its first screenshot also needs windowd's first full frame on the
# screen: that copy failed partway now and then (EFAULT), leaving console
# rows; windowd copies a failed area again (failing 3 of 3 runs on x86
# without that, after 41e-1's focus messages changed the timing).
wresize_session() {
    local n=1 mon="$WORK/monitor.sock" q="$WORK/qmp.sock" curx cury
    if [ "$ARCH_NAME" = x86_64 ]; then curx=640 cury=400; else curx=400 cury=300; fi
    qmp() { local c; { echo '{"execute":"qmp_capabilities"}'; sleep 0.3
                       for c in "$@"; do echo "$c"; sleep 0.15; done; } |
            nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1; }
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    moveto() { qmp "$(rel x $(( $1 - curx )))" "$(rel y $(( $2 - cury )))"; curx=$1; cury=$2; }

    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_wait "term: started" 1 15
    sleep 1.5                                            # the terminal is up at its default size
    echo "screendump $WORK/${NAME}-before.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    moveto 400 500                                       # onto the window's bottom edge (its resize margin)
    qmp "$(btn true)"                                    # grab it
    moveto 400 580                                       # drag down: more rows
    qmp "$(btn false)"                                   # release: windowd asks term to resize
    sleep 2                                              # term adopts the taller buffer and reflows
    echo "screendump $WORK/${NAME}-after.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

wresize_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}wresize "")
    windows_startup "$image" term                    # this test resizes the terminal
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=wresize_session
    boot ${P}wresize "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "term: started"
    check_screen px-150-520-46-52-64 $w $h "$WORK/${P}wresize-before.ppm"   # desktop below the small window
    check_screen px-150-520-0-0-0 $w $h "$WORK/${P}wresize-after.ppm"       # term grew to cover it (black)
    reject "panic"
    show_log_on_failure $before
}

# sockets_session: DHCP and sockets (sockets_shell_test).
sockets_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test/sock"
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    answer_lines 'net' "$t udp 10.0.2.2 $NET_UDP_PORT hello-udp" "$t udploop" \
                 "$t tcp 10.0.2.2 $NET_ECHO_PORT hello-tcp" "$t get 10.0.2.2 $NET_SEND_PORT 1000000" \
                 "$t put 10.0.2.2 $NET_RECV_PORT 1000000" "$t loop 300000" \
                 "$t tcp 10.0.2.2 $NET_CLOSED_PORT nobody" \
                 "$t slowget 10.0.2.2 $NET_SEND_PORT 1000000" "$t put 10.0.2.2 $NET_SLOW_PORT 1000000"
    host_service_wait "$WORK/${P}testnet.log" "^tcp-slowrecv:"   # still reading what QEMU holds
    serial_type "$t serve 7000\r"
    serial_wait "sock: listening on port 7000" 1 20
    python3 "$ROOT/scripts/testnet.py" client $NET_FORWARD_PORT hello-guest >"$WORK/${P}client.log" 2>&1
    n=$((n + 1))
    prompt_wait $n 30
    answer_lines 'net'
}

# sockets_shell_test: no settings on the disk, so net up (login) makes
# /system/config/network/eth0 and asks for an address by DHCP (QEMU's
# server: 10.0.2.15, its gateway and DNS server);
# programs' sockets (user/test/sock) against services on the Mac
# (scripts/testnet.py, reached as 10.0.2.2): a UDP echo, a UDP loopback
# with a port in use and a receive that times out, TCP: a short exchange,
# 1,000,000 bytes each way (many windows' worth), 300,000 bytes over the
# loopback between two threads, a port nobody listens on (refused), a
# connection from the Mac to a program listening (QEMU's hostfwd); flow
# control: 1,000,000 bytes read slowly by the program, and sent to a slow
# reader on the Mac (the windows close and open again).
sockets_shell_test() {
    local image before services
    image=$(make_image ${P}sockets "")
    guard_rules "$image" 'allow in tcp 7000'          # (the Mac's connections to sock serve)
    python3 "$ROOT/scripts/testnet.py" udp-echo:$NET_UDP_PORT tcp-echo:$NET_ECHO_PORT \
            tcp-send:$NET_SEND_PORT:1000000 tcp-recv:$NET_RECV_PORT tcp-slowrecv:$NET_SLOW_PORT \
            >"$WORK/${P}testnet.log" 2>&1 &
    services=$!
    host_service_wait "$WORK/${P}testnet.log" listening
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_FORWARD_PORT-:7000"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=sockets_session
    boot ${P}sockets "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $services 2>/dev/null
    wait $services 2>/dev/null
    local t="/system/$ARCH_NAME/test/sock"
    expect_line "net: eth0: DHCP: the elf dhclient asks for its address"
    expect_line "net: /system/config/elves/dhclient made: the elf dhclient asks for the addresses"
    expect "elvesd: dhclient started (process "
    expect "dhclient: eth0: 10.0.2.15/24 from 10.0.2.2, gateway 10.0.2.2, DNS 10.0.2.3, lease "
    reject "dhcpd"                                  # the old name (44d: dhclient)
    expect "       address 10.0.2.15/24 (DHCP, lease "
    expect_line "sock: answer from 10.0.2.2:$NET_UDP_PORT: 'echo: hello-udp'"
    want_text want <<'LINES'
sock: port 4000 again: Address already in use
sock: 'datagram 1' from 127.0.0.1, the sender's port
sock: 'datagram 2' from 127.0.0.1, the sender's port
sock: 'datagram 3' from 127.0.0.1, the sender's port
sock: nothing more: Timed out
LINES
    compare "UDP over the loopback" "$want" "$(command_output "$t udploop")"
    expect_line "sock: answer: 'echo: hello-tcp'"
    compare "TCP: 1,000,000 bytes from the Mac" "sock: received 1000000 bytes, pattern ok" \
            "$(command_output "$t get 10.0.2.2 $NET_SEND_PORT 1000000")"
    compare "TCP: 1,000,000 bytes to the Mac" "sock: sent 1000000 bytes" \
            "$(command_output "$t put 10.0.2.2 $NET_RECV_PORT 1000000")"
    compare "the Mac received them" "tcp-recv: received 1000000 bytes, pattern ok" \
            "$(grep '^tcp-recv:' "$WORK/${P}testnet.log")"
    compare "TCP over the loopback" "sock: received 300000 bytes, pattern ok" \
            "$(command_output "$t loop 300000")"
    compare "nobody listening" "sock: connect: Connection refused" \
            "$(command_output "$t tcp 10.0.2.2 $NET_CLOSED_PORT nobody" | head -1)"
    want_text want <<'LINES'
sock: listening on port 7000
sock: connection from 10.0.2.2
sock: connection ended
LINES
    compare "a connection from the Mac" "$want" "$(command_output "$t serve 7000")"
    compare "the Mac's answer" "client: answer: HELLO-GUEST" "$(cat "$WORK/${P}client.log")"
    compare "TCP: read slowly" "sock: received 1000000 bytes, pattern ok" \
            "$(command_output "$t slowget 10.0.2.2 $NET_SEND_PORT 1000000")"
    compare "TCP: to a slow reader" "sock: sent 1000000 bytes" \
            "$(command_output "$t put 10.0.2.2 $NET_SLOW_PORT 1000000")"
    compare "the slow reader received them" "tcp-slowrecv: received 1000000 bytes, pattern ok" \
            "$(grep '^tcp-slowrecv:' "$WORK/${P}testnet.log")"
    expect "; sent again: "
    reject "panic"
    show_log_on_failure $before
}

# netrate_session / netrate_test (65e): user/test/netrate measures how fast
# a TCP stream comes in. The Mac sends 20,000,000 bytes of the tests'
# pattern (testnet.py's tcp-send, byte i = i % 251) and closes; netrate
# counts them and checks every byte (-p). The rate itself depends on the
# Mac and QEMU (the e1000 is polled by the tick): it is shown, not judged.
# Proven by a sender one byte short (the count) and one with a byte
# changed (1 wrong). `netrate read` reads a file to its end: netrate's own
# program file, its size from the build. (65e) `netrate send` uploads
# 4,000,000 bytes of the pattern to testnet.py's tcp-recv, which counts and
# checks them (proven by an upload one byte short). `netrate listen` is the
# receiving end between two machines: here both ends in the guest, over lo
# (proven by a send one byte short: the count, and the answer). (36e)
# `netrate serve` is the other end that stays (the J1900's for measuring
# Wi-Fi): over lo a download of 2 s (the request "send", every byte
# checked), then an upload on a second connection, answered (proven by a
# server whose pattern is one byte off and which ends after one
# connection). (36e-8) A second download right after the first: the
# first closes with data unread, so its TCP sends a RST and the server
# takes the next at once (with a FIN its write waited ~6 s on the closed
# side's zero window: the second got nothing in its 2 s; proven by a TCP
# that closes with a FIN), and net counts the reset.
netrate_session() {
    local n=1
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    answer_lines "/system/$ARCH_NAME/test/netrate 10.0.2.2 $NET_RATE_PORT 60 -p" \
                 "/system/$ARCH_NAME/test/netrate read /system/$ARCH_NAME/test/netrate 10" \
                 "/system/$ARCH_NAME/test/netrate send 10.0.2.2 $NET_RATE_UP_PORT 4000000" \
                 "/system/$ARCH_NAME/test/netrate listen 5001 -p &" "sleep 1" \
                 "/system/$ARCH_NAME/test/netrate send 127.0.0.1 5001 3000000" "sleep 1" \
                 "/system/$ARCH_NAME/test/netrate serve 5002 &" "sleep 1" \
                 "/system/$ARCH_NAME/test/netrate 127.0.0.1 5002 2 -p send" \
                 "/system/$ARCH_NAME/test/netrate 127.0.0.1 5002 2 -p send" \
                 "/system/$ARCH_NAME/test/netrate send 127.0.0.1 5002 2000000" "net"
}

netrate_test() {
    local image before services line
    image=$(make_image ${P}netrate "")
    python3 "$ROOT/scripts/testnet.py" tcp-send:$NET_RATE_PORT:20000000 tcp-recv:$NET_RATE_UP_PORT \
            >"$WORK/${P}netrate-mac.log" 2>&1 &
    services=$!
    host_service_wait "$WORK/${P}netrate-mac.log" listening
    QEMU_EXTRA="-netdev user,id=net0 -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=netrate_session
    boot ${P}netrate "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $services 2>/dev/null
    wait $services 2>/dev/null
    expect_line "netrate: connected to 10.0.2.2 port $NET_RATE_PORT"
    line=$(grep -E '^netrate: [0-9]+ bytes in ' <<<"$TEXT" | head -1)
    check "netrate: all 20,000,000 bytes, every one as sent ($line)" "got: '$line'" \
          eval 'grep -qE "^netrate: 20000000 bytes in [0-9]+\.[0-9]{2} s: [0-9]+\.[0-9]{2} MB/s \(the other side closed\), 0 wrong$" <<<"$line"'
    local size
    size=$(stat -f %z "$ROOT/build/system/$ARCH_NAME/test/netrate")
    line=$(grep -E '\(the end\)$' <<<"$TEXT" | head -1)
    check "netrate read: the program file to its end, $size bytes ($line)" "got: '$line'" \
          eval 'grep -qE "^netrate: $size bytes in [0-9]+\.[0-9]{2} s: [0-9]+\.[0-9]{2} MB/s \(the end\)$" <<<"$line"'
    line=$(grep -E '^netrate: sent [0-9]+ bytes' <<<"$TEXT" | head -1)
    check "netrate send: 4,000,000 bytes to the Mac's end ($line)" "got: '$line'" \
          eval 'grep -qE "^netrate: sent 4000000 bytes in [0-9]+\.[0-9]{2} s to the answer: [0-9]+\.[0-9]{2} MB/s \(answer: .none.\)$" <<<"$line"'
    check "the Mac received all 4,000,000 bytes, the pattern right" "$(grep tcp-recv "$WORK/${P}netrate-mac.log")" \
          grep -q "^tcp-recv: received 4000000 bytes, pattern ok$" "$WORK/${P}netrate-mac.log"
    check "netrate listen: all 3,000,000 bytes over lo, every one right" \
          "$(grep -E '^netrate: [0-9]+ bytes in .*other side ended' <<<"$TEXT")" \
          eval 'grep -qE "^netrate: 3000000 bytes in [0-9]+\.[0-9]{2} s: [0-9]+\.[0-9]{2} MB/s \(the other side ended\), 0 wrong$" <<<"$TEXT"'
    check "netrate send got the listener's answer" "$(grep -E '^netrate: sent 3000000' <<<"$TEXT")" \
          eval 'grep -qE "^netrate: sent 3000000 bytes in .* \(answer: .netrate: 3000000 bytes came.\)$" <<<"$TEXT"'
    expect_line "netrate: serving on port 5002"
    check "netrate serve: a download of 2 s, every byte right" \
          "$(grep -E '\(time up\)' <<<"$TEXT")" \
          eval 'grep -qE "^netrate: [1-9][0-9]* bytes in 2\.[0-9]{2} s: [0-9]+\.[0-9]{2} MB/s \(time up\), 0 wrong$" <<<"$TEXT"'
    check "netrate serve: its side of the download" "$(grep -E '^netrate: sent [0-9]+ bytes in [0-9.]+ s: ' <<<"$TEXT")" \
          eval 'grep -qE "^netrate: sent [1-9][0-9]* bytes in [0-9]+\.[0-9]{2} s: [0-9]+\.[0-9]{2} MB/s$" <<<"$TEXT"'
    check "netrate serve: a second download right after, also with data (36e-8: the RST)" \
          "$(grep -E '\(time up\)' <<<"$TEXT" | tr '\n' '|')" \
          eval '[ "$(grep -cE "^netrate: [1-9][0-9]* bytes in 2\.[0-9]{2} s: .*\(time up\), 0 wrong$" <<<"$TEXT")" = 2 ]'
    check "net: the closes with data unread counted" "$(grep -E '^tcp:' <<<"$TEXT" | tail -1)" \
          eval 'grep -E "^tcp:" <<<"$TEXT" | tail -1 | grep -qE ", [1-9][0-9]* reset with data unread$"'
    check "netrate serve: then an upload on a third connection, answered" \
          "$(grep -E '^netrate: sent 2000000' <<<"$TEXT")" \
          eval 'grep -qE "^netrate: sent 2000000 bytes in .* \(answer: .netrate: 2000000 bytes came.\)$" <<<"$TEXT"'
    reject "netrate: read:"
    reject "panic"
    show_log_on_failure $before
}

# wscale_session / wscale_test (65e-15): TCP window scaling (RFC 7323).
# QEMU's user network (slirp) offers none, so host A of testroute.py is the
# peer here, on a dgram network of its own: its port 8889 sends 16,000,000
# bytes of the pattern in the window the guest announces, scaled if both
# offered (its shift 7). The guest's SYN offers shift 6 (up to 4 MiB of
# receive buffer); with both, the buffer starts at 128 KiB and doubles while
# the sender reaches the window's edge (65e-18): the window reaches 1 MiB
# (three doublings at least, net counts them; 38d-3: "past 1 MiB" had asked
# for a fourth, which a guest that drains its buffer quickly enough does not
# need, since the buffer grows only while the window holds the sender back;
# and 16,000,000 bytes for room) and the bytes in flight past
# 64 KiB, in
# flight; netrate checks every byte, net counts the scaled connection.
# Proven by a kernel that offers no scaling (no shift, at most 65535 in
# flight, 0 scaled). (65e-16) The same SYN offers SACK: host A leaves out
# every 50th segment of the first 4 MB once and resends only what the
# guest's SACK blocks show missing; each block must lie above what is
# acknowledged, inside what was sent and outside the holes. Proven by a
# kernel that offers no SACK (A goes back instead; no blocks).
# (65e-25) Then the other way round: A opens the connection (bulkto) to
# the guest's `netrate listen 5001`, offering both, and sends the same
# 16,000,000 bytes with the same holes. The listener's cookie keeps the
# offers: its SYN-ACK offers shift 6 and SACK, the window goes past 1 MiB,
# the blocks are right, and net counts two of each. Proven by a kernel
# whose listener offers neither (no shift, at most 65535 in flight).
# (65e-29) Delayed ACKs: A's port 8891 sends 201 full segments one every
# 15 ms, each in a burst of its own; after the first 16 (acknowledged at
# once) the guest acknowledges every second one, so about 108 ACKs come,
# and the odd last one's ACK waits for the timer (40 ms). Proven by a
# kernel that holds none (an ACK per segment, the last at once).
wscale_session() {
    local n=1
    prompt_wait $n
    dhcp_wait eth0 192.168.71.50
    answer_lines "/system/$ARCH_NAME/test/netrate 192.168.71.2 8889 60 -p" 'net' \
                 "/system/$ARCH_NAME/test/netrate listen 5001 -p &" "sleep 1"
    route_ask bulkto A 192.168.71.50 5001
    serial_wait "netrate: 16000000 bytes in " 2 90
    serial_type "\r"
    n=$((n + 1))
    prompt_wait $n
    answer_lines 'net' "/system/$ARCH_NAME/test/netrate 192.168.71.2 8891 30 -p" 'net'
}

wscale_test() {
    local image before testroute line w f
    image=$(make_image ${P}wscale "")
    guard_rules "$image" "allow in tcp 5001"
    rm -f "$WORK/${P}route-answers"
    python3 "$ROOT/scripts/testroute.py" serve $NET_ROUTE_CONTROL $NET_ROUTE_A_HOST $NET_ROUTE_A_GUEST $NET_ROUTE_B_HOST $NET_ROUTE_B_GUEST \
            >"$WORK/${P}testroute.log" 2>&1 &
    testroute=$!
    host_service_wait "$WORK/${P}testroute.log" "testroute: listening"
    route_ask dhcp A on
    QEMU_EXTRA="-netdev dgram,id=neta,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_A_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_A_HOST"
    QEMU_EXTRA+=" -device e1000,netdev=neta,mac=52:54:00:00:71:01"
    before=$failures
    SERIAL_SCRIPT=wscale_session
    boot ${P}wscale "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $testroute 2>/dev/null
    wait $testroute 2>/dev/null
    line=$(grep -E '^netrate: [0-9]+ bytes in ' <<<"$TEXT" | head -1)
    check "netrate: all 16,000,000 bytes from host A, every one as sent ($line)" "got: '$line'" \
          eval 'grep -qE "^netrate: 16000000 bytes in [0-9]+\.[0-9]{2} s: [0-9]+\.[0-9]{2} MB/s \(the other side closed\), 0 wrong$" <<<"$line"'
    line=$(grep -h "tcp 8889: sent" "$WORK/${P}testroute.log" | head -1)
    check "the guest's SYN offered window scaling, shift 6" "A: '$line'" \
          eval 'grep -q "; the guest offered shift 6; " <<<"$line"'
    w=$(sed -n 's/.*its largest window \([0-9]*\);.*/\1/p' <<<"$line")
    f=$(sed -n 's/.*at most \([0-9]*\) bytes in flight.*/\1/p' <<<"$line")
    check "its window at least 1 MiB, three doublings (${w:-?} bytes), past 64 KiB in flight (${f:-?})" "A: '$line'" \
          test "${w:-0}" -ge 1048576 -a "${f:-0}" -gt 65535
    check "net: the connection had scaled windows" "$(command_output net | grep '^tcp:')" \
          eval 'command_output net | grep -q "; 1 with scaled windows"'
    line=$(grep -h "tcp 8889: SACK\|tcp 8889: no SACK" "$WORK/${P}testroute.log" | head -1)
    check "the guest's SYN offered SACK; its ACKs reported the holes, every block right" "A: '$line'" \
          eval 'grep -qE "^A: tcp 8889: SACK offered; [1-9][0-9]* segments .* left out once; [1-9][0-9]* ACKs with SACK blocks \(at most [2-4] in one\), every block right; " <<<"$line"'
    check "net: the connection used SACK" "$(command_output net | grep '^tcp:')" \
          eval 'command_output net | grep -q ", 1 with SACK"'
    w=$(command_output net | sed -n 's/^tcp:.*receive buffers doubled \([0-9]*\) times.*/\1/p')
    check "net: the receive buffer doubled while the window held the sender back (${w:-?} times)" \
          "$(command_output net | grep '^tcp:')" test "${w:-0}" -ge 3
    # (65e-25) A's connection to the guest's listener.
    line=$(grep -E '^netrate: [0-9]+ bytes in ' <<<"$TEXT" | sed -n 2p)
    check "netrate listen: all 16,000,000 bytes from host A's connection, every one as sent ($line)" \
          "got: '$line'" \
          eval 'grep -qE "^netrate: 16000000 bytes in [0-9]+\.[0-9]{2} s: [0-9]+\.[0-9]{2} MB/s \(the other side ended\), 0 wrong$" <<<"$line"'
    line=$(grep -h "tcp 8889: sent" "$WORK/${P}testroute.log" | sed -n 2p)
    check "the listener's SYN-ACK offered window scaling, shift 6" "A: '$line'" \
          eval 'grep -q "; the guest offered shift 6; " <<<"$line"'
    w=$(sed -n 's/.*its largest window \([0-9]*\);.*/\1/p' <<<"$line")
    f=$(sed -n 's/.*at most \([0-9]*\) bytes in flight.*/\1/p' <<<"$line")
    check "its window at least 1 MiB, three doublings (${w:-?} bytes), past 64 KiB in flight (${f:-?})" "A: '$line'" \
          test "${w:-0}" -ge 1048576 -a "${f:-0}" -gt 65535
    line=$(grep -h "tcp 8889: SACK\|tcp 8889: no SACK" "$WORK/${P}testroute.log" | sed -n 2p)
    check "the SYN-ACK offered SACK; the listener's ACKs reported the holes, every block right" "A: '$line'" \
          eval 'grep -qE "^A: tcp 8889: SACK offered; [1-9][0-9]* segments .* left out once; [1-9][0-9]* ACKs with SACK blocks \(at most [2-4] in one\), every block right; " <<<"$line"'
    check "net: both connections had scaled windows and SACK" "$(command_output net 2 | grep '^tcp:')" \
          eval 'command_output net 2 | grep -q "; 2 with scaled windows, 2 with SACK,"'
    # (65e-29) Delayed ACKs.
    line=$(grep -E '^netrate: [0-9]+ bytes in ' <<<"$TEXT" | sed -n 3p)
    check "netrate: all 293,460 bytes from port 8891, every one as sent ($line)" "got: '$line'" \
          eval 'grep -qE "^netrate: 293460 bytes in .*\(the other side closed\), 0 wrong$" <<<"$line"'
    line=$(grep -h "tcp 8891:" "$WORK/${P}testroute.log")
    w=$(sed -n 's/.*every 15 ms: \([0-9]*\) ACKs;.*/\1/p' <<<"$line")
    f=$(sed -n 's/.*the last acknowledged after \([0-9-]*\) ms.*/\1/p' <<<"$line")
    check "201 segments one at a time got about one ACK per two (${w:-?} ACKs, at most 130)" "A: '$line'" \
          test "${w:-999}" -ge 90 -a "${w:-999}" -le 130
    check "the odd last one's ACK came with the timer (${f:-?} ms, 30-200)" "A: '$line'" \
          test "${f:--1}" -ge 30 -a "${f:--1}" -le 200
    w=$(command_output net 3 | sed -n 's/^tcp:.*, \([0-9]*\) ACKs delayed.*/\1/p')
    check "net: ACKs delayed (${w:-?}, at least 90)" "$(command_output net 3 | grep '^tcp:')" \
          test "${w:-0}" -ge 90
    reject "panic"
    show_log_on_failure $before
}

# sacksend_session / sacksend_test (65e-19): SACK on the sending side.
# The guest uploads 1,000,000 bytes of the pattern (sock put) to host A's
# port 8890, which leaves out the first copy of four of its segments close
# together (one flight) and acknowledges every segment 100 ms after it came (a round
# trip), with SACK blocks: the guest resends the holes the blocks show, the
# next at each further ACK, so the four are filled within about two round
# trips (NewReno, without them, finds one hole per round trip: five or more).
# Proven by a kernel that resends from the scoreboard nothing (NewReno).
# (65e-20) A second upload, 4,000,000 bytes without holes: the send
# buffer doubles once the peer's window and the congestion window would
# carry more than its 64 KiB, so more than 96 KiB are in flight at once
# and net counts the doublings. Proven by a kernel whose send buffer stays.
sacksend_session() {
    local n=1
    prompt_wait $n
    dhcp_wait eth0 192.168.71.50
    answer_lines "/system/$ARCH_NAME/test/sock put 192.168.71.2 8890 1000000" \
                 "/system/$ARCH_NAME/test/sock put 192.168.71.2 8890 4000000" 'net'
}

sacksend_test() {
    local image before testroute line ms
    image=$(make_image ${P}sacksend "")
    guard_rules "$image"
    python3 "$ROOT/scripts/testroute.py" serve $NET_ROUTE_CONTROL $NET_ROUTE_A_HOST $NET_ROUTE_A_GUEST $NET_ROUTE_B_HOST $NET_ROUTE_B_GUEST \
            >"$WORK/${P}testroute.log" 2>&1 &
    testroute=$!
    host_service_wait "$WORK/${P}testroute.log" "testroute: listening"
    route_ask dhcp A on
    QEMU_EXTRA="-netdev dgram,id=neta,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_A_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_A_HOST"
    QEMU_EXTRA+=" -device e1000,netdev=neta,mac=52:54:00:00:71:01"
    before=$failures
    SERIAL_SCRIPT=sacksend_session
    boot ${P}sacksend "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    sleep 1
    kill $testroute 2>/dev/null
    wait $testroute 2>/dev/null
    line=$(grep -h "tcp 8890: .*(connection 1)" "$WORK/${P}testroute.log")
    check "A got all 1,000,000 bytes of the upload, right, with SACK" "A: '$line'" \
          eval 'grep -q "^A: tcp 8890: received 1000000 bytes, the pattern right; SACK offered; 4 segments left out once" <<<"$line"'
    ms=$(sed -n 's/.*filled \(-*[0-9]*\) ms after the first.*/\1/p' <<<"$line")
    check "the four holes filled within 3 round trips (${ms:-?} ms)" "A: '$line'" \
          test "${ms:--1}" -ge 0 -a "${ms:-999}" -lt 300
    check "net: holes resent from the peer's SACK blocks" "$(command_output net | grep '^tcp:')" \
          eval 'command_output net | grep -qE "; [3-9][0-9]* holes resent from SACK|; [1-9][0-9]+ holes resent from SACK"'
    line=$(grep -h "tcp 8890: .*(connection 2)" "$WORK/${P}testroute.log")
    check "A got all 4,000,000 bytes of the second upload, right" "A: '$line'" \
          eval 'grep -q "^A: tcp 8890: received 4000000 bytes, the pattern right" <<<"$line"'
    ms=$(sed -n 's/.*at most \([0-9]*\) bytes in flight.*/\1/p' <<<"$line")
    check "the second upload had more than 96 KiB in flight (${ms:-?} bytes)" "A: '$line'" \
          test "${ms:-0}" -gt 98304
    ms=$(command_output net | sed -n 's/^tcp:.*send buffers doubled \([0-9]*\) times.*/\1/p')
    check "net: the send buffer doubled (${ms:-?} times)" "$(command_output net | grep '^tcp:')" \
          test "${ms:-0}" -ge 1
    reject "panic"
    show_log_on_failure $before
}

# fetch_session: HTTP (fetch_shell_test).
fetch_session() {
    local n=1 asked=0 w="http://mac.test:$NET_HTTP_PORT"
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    dnsd_wait
    mac_asks_dnsd mac.test >"$WORK/${P}dnsd-from-mac"
    answer_lines "fetch $w/hello.txt" "fetch -i http://10.0.2.2:$NET_HTTP_PORT/hello.txt" \
                 "fetch -o /big.bin $w/big.bin" "/system/$ARCH_NAME/test/filesha /big.bin" \
                 "fetch $w/chunked.txt" "fetch $w/old" "fetch $w/away" "fetch $w/loop" \
                 "fetch $w/missing" "fetch $w/short" \
                 'fetch http://nowhere.test/' 'fetch ftp://example.com/' 'net' \
                 "/system/$ARCH_NAME/test/gaitest mac.test $NET_HTTP_PORT mac6.test" \
                 'threads' "/system/$ARCH_NAME/test/smpstress 3 pipe" 'threads'
}

# mac_asks_dnsd NAME: the Mac asks the guest's dnsd for NAME (type A),
# through QEMU's hostfwd: "answer: ADDRESS", or why there is none.
mac_asks_dnsd() {
    python3 -c '
import socket, struct, sys
name, port = sys.argv[1], int(sys.argv[2])
q = struct.pack(">HHHHHH", 0x4242, 0x0100, 1, 0, 0, 0)
q += b"".join(bytes([len(l)]) + l.encode() for l in name.split(".")) + b"\0" + struct.pack(">HH", 1, 1)
s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
s.settimeout(5)
s.sendto(q, ("127.0.0.1", port))
try:
    a = s.recv(512)
except socket.timeout:
    sys.exit(print("no answer"))
rcode = a[3] & 15
if rcode or struct.unpack(">H", a[6:8])[0] == 0:
    sys.exit(print("rcode", rcode))
print("answer: " + ".".join(str(b) for b in a[-4:]))
' "$1" $NET_DNSD_PORT
}

# dnsburst_session / dnsburst_test (64j): many name lookups at once. net6test
# burst starts 40 threads that look burst.test up through dnsd at the same
# moment (80 questions, AAAA and A each; the name has both, as www.apple.com
# on the J1900) while the tests' DNS server answers only after half a
# second, so dnsd's queue fills while it waits: every lookup must be
# answered, and net's udp: line counts no datagram dropped.
# Proven by the old kernel (16 datagrams a UDP socket and 16 ports bound in
# all) and the library asking only once (found on the J1900: iBrowser's
# fetches of a page's files failed with "did not answer"). (64k) A second
# burst for a name with no AAAA record (v4only.test): dnsd keeps the empty
# answer, so the tests' DNS server is asked for its AAAA record once; proven
# by the dnsd of 64j, which asked again for every question (all 40 failed:
# 40 questions half a second each, one after another). (64q) A third burst
# of 30 different names (60 questions, AAAA and A each, every answer half a
# second late): dnsd asks them all at once, each once; proven by the dnsd
# of 64k, which asked one at a time (lookups failed: 30 s of questions in
# turn, the library waits 6 s).
dnsburst_session() {
    local n=1 asked=0
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    dnsd_wait
    answer_lines "/system/$ARCH_NAME/test/net6test burst 40 burst.test" \
                 "/system/$ARCH_NAME/test/net6test burst 40 v4only.test" \
                 "/system/$ARCH_NAME/test/net6test burst 30 n%%d.many.test" 'net'
}

dnsburst_test() {
    local image before dns
    image=$(make_image ${P}dnsburst "")
    printf 'address = dhcp\ndns = 10.0.2.2:%s\n' $NET_DNS_PORT >"$WORK/${P}network"
    $RFS put "$image" $RFS_PART /system/config/network/eth0 "$WORK/${P}network" >/dev/null || exit 1
    python3 "$ROOT/scripts/testdns.py" $NET_DNS_PORT --delay=0.5 burst.test=10.0.2.99 burst.test=fec0::99 v4only.test=10.0.2.98 '*.many.test=10.0.2.97' \
        >"$WORK/${P}testdns.log" 2>&1 &
    dns=$!
    host_service_wait "$WORK/${P}testdns.log" listening
    QEMU_EXTRA="-netdev user,id=net0 -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=dnsburst_session
    boot ${P}dnsburst "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $dns 2>/dev/null
    wait $dns 2>/dev/null
    expect_line "net6test: burst: an IPv6 address beyond the link: yes"
    expect_line "net6test: burst: 40 lookups of burst.test at once: 40 answered, 0 failed"
    expect_line "net6test: burst: 40 lookups of v4only.test at once: 40 answered, 0 failed"
    expect_line "net6test: burst: 30 lookups of n%d.many.test at once: 30 answered, 0 failed"
    check "dnsd asked the server each question once" \
          "$(grep -c '^question n[0-9]*.many.test type' "$WORK/${P}testdns.log") question(s)" \
          test "$(grep -c '^question n[0-9]*.many.test type' "$WORK/${P}testdns.log")" = 60
    reject "net6test: burst: lookup "
    check "dnsd kept the empty answer: the AAAA question asked once" \
          "$(grep -c '^question v4only.test type 28' "$WORK/${P}testdns.log")" \
          test "$(grep -c '^question v4only.test type 28' "$WORK/${P}testdns.log")" = 1
    check "net: no datagram dropped" "$(command_output 'net' | grep '^udp:' || echo MISSING)" \
          eval 'command_output net | grep -Eq "^udp: [0-9]+ of 128 port\(s\) bound; 0 datagram\(s\) dropped by a full queue$"'
    reject "panic"
    show_log_on_failure $before
}

# fetch_shell_test: fetch against a web server on the Mac
# (scripts/testhttp.py), by name (the tests' DNS server, set by hand next
# to DHCP's address): a page, the headers with -i, 1,000,000 bytes saved
# to a file (its SHA-256 checked), chunks, redirections (a path, another
# host name, a loop), 404, a body cut short, other schemes
# refused, a name nobody knows. The Mac asks the guest's dnsd for a name
# (through a UDP hostfwd): it answers other machines too.
fetch_shell_test() {
    local image before dns web w="http://mac.test:$NET_HTTP_PORT"
    image=$(make_image ${P}fetch "")
    printf 'address = dhcp\ndns = 10.0.2.2:%s\n' $NET_DNS_PORT >"$WORK/${P}network"
    $RFS put "$image" $RFS_PART /system/config/network/eth0 "$WORK/${P}network" >/dev/null || exit 1
    python3 "$ROOT/scripts/testdns.py" $NET_DNS_PORT mac.test=10.0.2.2 mac6.test=fec0::2 >"$WORK/${P}testdns.log" 2>&1 &
    dns=$!
    python3 "$ROOT/scripts/testhttp.py" $NET_HTTP_PORT >"$WORK/${P}testhttp.log" 2>&1 &
    web=$!
    host_service_wait "$WORK/${P}testdns.log" listening
    host_service_wait "$WORK/${P}testhttp.log" listening
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=udp:127.0.0.1:$NET_DNSD_PORT-:53"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=fetch_session
    boot ${P}fetch "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $dns $web 2>/dev/null
    wait $dns $web 2>/dev/null
    expect "dhclient: eth0: 10.0.2.15/24 from 10.0.2.2, gateway 10.0.2.2, DNS 10.0.2.2:$NET_DNS_PORT, lease "
    compare "dnsd answers other machines too (the Mac, 44i)" "answer: 10.0.2.2" \
            "$(cat "$WORK/${P}dnsd-from-mac")"
    # (53d) getaddrinfo and the other netdb.h calls, by name through dnsd;
    # proven by a getaddrinfo that skips the services file.
    local gai
    want_text gai <<'LINES'
gaitest: a name and a service: 10.0.2.2:80 tcp, named mac.test
gaitest: for bind: [::]:8080 tcp
gaitest: for bind: 0.0.0.0:8080 tcp
gaitest: no node, both types: [::1]:53 tcp
gaitest: no node, both types: [::1]:53 udp
gaitest: no node, both types: 127.0.0.1:53 tcp
gaitest: no node, both types: 127.0.0.1:53 udp
gaitest: numbers only: 127.0.0.1:22 udp
gaitest: a name with AI_NUMERICHOST: Name or service not known
gaitest: an unknown service: Servname not supported for ai_socktype
gaitest: a service name with AI_NUMERICSERV: Name or service not known
gaitest: IPv6: Name or service not known
gaitest: IPv6, mapped: [::ffff:10.0.2.2]:80 tcp
gaitest: an IPv6 name: [fec0::2]:80 tcp
gaitest: an IPv6 number: [::1]:22 udp
gaitest: an IPv6 number for IPv4: Name or service not known
gaitest: a name nobody knows: Name or service not known
gaitest: neither: Name or service not known
gaitest: getnameinfo: 0 10.0.2.2 https
gaitest: getnameinfo NI_NUMERICSERV: 0 10.0.2.2 443
gaitest: getnameinfo NI_NAMEREQD: Name or service not known
gaitest: gethostbyname: mac.test 10.0.2.2
gaitest: gethostbyname of nobody's name: none, h_errno HOST_NOT_FOUND
gaitest: getservbyname ssh: 22 tcp
gaitest: getservbyport 53: domain
gaitest: connect 0, the page's first line: HTTP/1.1 200 OK
gaitest: done
LINES
    compare "getaddrinfo, getnameinfo, gethostbyname, services (53d)" "$gai" \
            "$(command_output "/system/$ARCH_NAME/test/gaitest mac.test $NET_HTTP_PORT mac6.test")"
    compare "a page" "Hello from the Mac!" "$(command_output "fetch $w/hello.txt")"
    compare "-i: the status line first" "HTTP/1.1 200 OK" \
            "$(command_output "fetch -i http://10.0.2.2:$NET_HTTP_PORT/hello.txt" | head -1)"
    expect_line "Content-Type: text/plain"
    expect_line "Content-Length: 20"
    compare "-i: an empty line, then the page" "$(printf '\nHello from the Mac!')" \
            "$(command_output "fetch -i http://10.0.2.2:$NET_HTTP_PORT/hello.txt" | tail -2)"
    compare "1,000,000 bytes saved" "fetch: 200 OK, 1000000 bytes saved to /big.bin" \
            "$(command_output "fetch -o /big.bin $w/big.bin")"
    expect_line "filesha: /big.bin: 1000000 bytes, sha256 $(python3 -c "import hashlib; print(hashlib.sha256(bytes(i % 251 for i in range(1000000))).hexdigest())")"
    compare "chunks" "$(python3 -c "import sys; sys.stdout.write('first chunk\nsecond, a bit longer chunk\n' + 'x' * 3000 + '\nlast')")" \
            "$(command_output "fetch $w/chunked.txt")"
    want_text want <<'LINES'
fetch: 301 Moved Permanently: redirected to /hello.txt
Hello from the Mac!
LINES
    compare "a redirection to a path" "$want" "$(command_output "fetch $w/old")"
    compare "a redirection to a host name" \
            "$(printf 'fetch: 302 Found: redirected to %s/hello.txt\nHello from the Mac!' "$w")" \
            "$(command_output "fetch $w/away")"
    compare "a loop of redirections" \
            "$(printf 'fetch: 302 Found: redirected to /loop\n%.0s' 1 2 3 4 5; echo "fetch: $w/loop: too many redirections")" \
            "$(command_output "fetch $w/loop" | grep -v 'exit code')"
    expect_line "fetch: $w/missing: 404 Not Found"
    expect "0123456789fetch: $w/short: the connection ended early (10 of 100 bytes)"
    expect_line "fetch: nowhere.test: Name not found"
    expect_line "fetch: ftp://example.com/: not an http:// or https:// address"
    check "the Host headers" "not so: $(grep -c "Host: mac.test:$NET_HTTP_PORT$" "$WORK/${P}testhttp.log")" \
          test "$(grep -c "^GET /hello.txt Host: mac.test:$NET_HTTP_PORT$" "$WORK/${P}testhttp.log")" = 3
    reject "panic"
    # (65e) dnsd waits in poll() on its sockets alone: 3 s of pipe traffic
    # between other threads leaves it asleep. Proven by the old poll(),
    # where every pollable queue's wake-up woke every poller: thousands.
    local dn1 dn2
    dn1=$(command_output threads | awk '$2 == "dnsd" {print $NF}')
    dn2=$(command_output threads 2 | awk '$2 == "dnsd" {print $NF}')
    expect_line "smpstress: all parts ok"
    check "dnsd in poll() during 3 s of pipe traffic: woken at most 30 times (${dn1:-?} then ${dn2:-?} switches)" \
          "dnsd switches: ${dn1:-?} then ${dn2:-?}" \
          eval '[ -n "$dn1" ] && [ -n "$dn2" ] && [ $((dn2 - dn1)) -le 30 ]'
    show_log_on_failure $before
}

# pty_session: pseudo-terminals (pty_shell_test).
pty_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test"
    prompt_wait $n
    answer_lines "$t/ptytest 'echo hello' 'echo abx^Hc' '$t/ptytest size' 'cd /test' 'ls docs' '$t/loop' '^C' 'exit 3'" \
                 "$t/ptytest -hangup 'echo before' '$t/loop'" 'ps' 'echo the console still works'
}

# pty_shell_test: a shell on a pseudo-terminal (user/test/ptytest types
# into its master side and shows what came back): echo of typed text,
# Backspace (erased with "\b \b"), the size set by the master, its own
# current directory, Ctrl-C stopping a job there (the shell says "^C"),
# exit codes, every line break as CR LF; closing the master while a job
# runs ends the shell and the job (SIGHUP), and the console's own shell
# works on.
pty_shell_test() {
    local image before t="/system/$ARCH_NAME/test"
    image=$(make_image ${P}pty "")
    before=$failures
    SERIAL_SCRIPT=pty_session
    boot ${P}pty "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    want_text want <<LINES
| ritteros:/# echo hello
| hello
| ritteros:/# echo abx<BS> <BS>c
| abc
| ritteros:/# $t/ptytest size
| ptytest: size 30x100
| ritteros:/# cd /test
| ritteros:/test# ls docs
|      <dir>  notes/
| ritteros:/test# $t/loop
| loop: running until Ctrl-C
| ^C
| ritteros:/test# exit 3
| 
ptytest: 13 line breaks, 0 without CR
ptytest: the shell ended with exit code 3
LINES
    compare "the transcript of the pseudo-terminal" "$want" \
            "$(command_output "$t/ptytest 'echo hello' 'echo abx^Hc' '$t/ptytest size' 'cd /test' 'ls docs' '$t/loop' '^C' 'exit 3'")"
    expect_line "ptytest: the shell ended by signal 1"
    expect_line "| loop: running until Ctrl-C"
    check "no loop left after the hang-up" "a loop is still there" \
          eval '! command_output ps | grep -q " loop"'
    expect_line "the console still works"
    reject "panic"
    show_log_on_failure $before
}

# mac_ssh FILE ARGS...: the Mac's ssh into the guest (through the hostfwd);
# its output (CR removed) and exit code into $WORK/${P}FILE.
mac_ssh() {
    local out="$WORK/${P}$1"
    shift
    /usr/bin/ssh -p $NET_SSH_PORT -o UserKnownHostsFile="$WORK/${P}known_hosts" \
        -o StrictHostKeyChecking=accept-new -o ConnectTimeout=30 -o LogLevel=ERROR \
        -o ServerAliveInterval=0 "$@" 2>"$out.err" </dev/null | tr -d '\r' >"$out"
    echo "exit ${PIPESTATUS[0]}" >>"$out"
}

# ssh_session: sshd and ssh (ssh_shell_test).
ssh_session() {
    local n=1 asked=0 key="$WORK/${P}id_ed25519" i
    local -a with_key=(-i "$key" -o IdentitiesOnly=yes -o BatchMode=yes)
    local -a by_password=(-o PubkeyAuthentication=no -o PreferredAuthentications=password
                          -o NumberOfPasswordPrompts=1)
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15                        # (and the elf sshd listening)
    # The server, from the Mac.
    mac_ssh ssh-key "${with_key[@]}" root@127.0.0.1 'echo hello from RitterOS'
    mac_ssh ssh-exit "${with_key[@]}" root@127.0.0.1 'exit 7'
    mac_ssh ssh-semi "${with_key[@]}" root@127.0.0.1 'echo one; echo two'
    mac_ssh ssh-lorem "${with_key[@]}" root@127.0.0.1 'cat /test/text/lorem.txt'
    { printf 'echo one\nid\nexit\n'; sleep 15; } |
        /usr/bin/ssh -tt -p $NET_SSH_PORT -o UserKnownHostsFile="$WORK/${P}known_hosts" \
            -o LogLevel=ERROR "${with_key[@]}" root@127.0.0.1 2>"$WORK/${P}ssh-tt.err" |
        tr -d '\r' >"$WORK/${P}ssh-tt"
    SSH_ASKPASS="$WORK/${P}askpass" SSH_ASKPASS_REQUIRE=force DISPLAY=:0 \
        mac_ssh ssh-password "${by_password[@]}" root@127.0.0.1 'echo by password'
    SSH_ASKPASS="$WORK/${P}askpass-wrong" SSH_ASKPASS_REQUIRE=force DISPLAY=:0 \
        mac_ssh ssh-wrong "${by_password[@]}" root@127.0.0.1 'echo should not run'
    serial_type '\r'                                # sshd's messages came after the prompt
    n=$((n + 1))
    prompt_wait $n
    # The client, here (to this machine's own sshd): with the key, then
    # by password, then a session typed into.
    serial_type "ssh root@127.0.0.1 'echo from the client'\r"
    serial_wait "(yes/no) " 1 30
    serial_type 'yes\r'
    n=$((n + 1))
    prompt_wait $n 60
    serial_type "ssh -p 22 root@localhost 'exit 5'\r"
    serial_wait "(yes/no) " 2 30
    serial_type 'yes\r'
    n=$((n + 1))
    prompt_wait $n 60
    answer_lines 'mv /home/root/.ssh/id_ed25519 /home/root/.ssh/key-off' 'cat /home/root/.ssh/known_hosts'
    serial_type "ssh root@127.0.0.1 'echo by password'\r"
    serial_wait "root@127.0.0.1's password: " 1 30
    serial_type "$ROOT_PASSWORD\r"
    n=$((n + 1))
    prompt_wait $n 60
    serial_type 'ssh root@127.0.0.1\r'
    serial_wait "root@127.0.0.1's password: " 2 30
    serial_type "$ROOT_PASSWORD\r"
    n=$((n + 1))                                    # the remote shell's prompt
    prompt_wait $n 60
    serial_type 'echo inside\r'
    n=$((n + 1))
    prompt_wait $n 30
    serial_type 'exit\r'
    n=$((n + 1))
    prompt_wait $n 30
    # A host whose key changed is refused.
    serial_type "echo '127.0.0.1 ssh-ed25519 $(cut -d' ' -f2 "$WORK/${P}other.pub")' > /home/root/.ssh/known_hosts\r"
    n=$((n + 1))
    prompt_wait $n
    answer_lines "ssh root@127.0.0.1 'echo should not run'"
}

# ssh_shell_test: sshd (the elf net up makes, on from the start) with a
# host key made at its first start, logged into from the Mac's own ssh: with an
# Ed25519 key in /home/root/.ssh/authorized_keys (a command's output and
# exit code, 6,200 bytes of a file, a session with a terminal), with the
# password (right and wrong); the fingerprint as the Mac's ssh-keygen shows
# it. Then the client ssh here, to the same sshd: the host's key asked
# about and kept, the key in /home/root/.ssh/id_ed25519 (OpenSSH's format,
# made by the Mac), the remote exit code, the password, a session typed
# into, and a host whose key changed refused.
ssh_shell_test() {
    local image before key="$WORK/${P}id_ed25519" print
    image=$(make_image ${P}ssh "")
    rm -f "$key" "$key.pub" "$WORK/${P}other" "$WORK/${P}other.pub" "$WORK/${P}known_hosts"
    ssh-keygen -q -t ed25519 -N '' -C test@mac -f "$key" || exit 1
    ssh-keygen -q -t ed25519 -N '' -C other -f "$WORK/${P}other" || exit 1
    $RFS put "$image" $RFS_PART /home/root/.ssh/authorized_keys "$key.pub" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /home/root/.ssh/id_ed25519 "$key" >/dev/null || exit 1
    printf '#!/bin/sh\necho %s\n' "$ROOT_PASSWORD" >"$WORK/${P}askpass"
    printf '#!/bin/sh\necho wrong-password\n' >"$WORK/${P}askpass-wrong"
    chmod 700 "$WORK/${P}askpass" "$WORK/${P}askpass-wrong"
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_SSH_PORT-:22"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=ssh_session
    boot ${P}ssh "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    # The server.
    expect_line "net: /system/config/elves/sshd made: the elf sshd lets others log in (port 22)"
    expect "elvesd: sshd started (process "
    print=$(grep -o 'sshd: made a new host key SHA256:[A-Za-z0-9+/]*' <<<"$TEXT" | sed 's/.* //')
    check "a host key made, fingerprint $print" "no host key line" test -n "$print"
    compare "the Mac's ssh-keygen shows the same fingerprint" "$print" \
            "$(ssh-keygen -lf "$WORK/${P}known_hosts" | awk '{print $2}')"
    compare "a command by key" "$(printf 'hello from RitterOS\nexit 0')" "$(cat "$WORK/${P}ssh-key")"
    compare "its exit code" "exit 7" "$(cat "$WORK/${P}ssh-exit")"
    compare "two commands with ';' (sh -c)" "$(printf 'one\ntwo\nexit 0')" "$(cat "$WORK/${P}ssh-semi")"
    compare "6,200 bytes of a file" "$($RFS cat "$image" $RFS_PART /test/text/lorem.txt; echo "exit 0")" \
            "$(cat "$WORK/${P}ssh-lorem")"
    check "a session with a terminal: id ran there" "$(cat "$WORK/${P}ssh-tt")" \
          grep -q "uid=0(root)" "$WORK/${P}ssh-tt"
    compare "by password" "$(printf 'by password\nexit 0')" "$(cat "$WORK/${P}ssh-password")"
    check "a wrong password refused" "$(cat "$WORK/${P}ssh-wrong" "$WORK/${P}ssh-wrong.err")" \
          eval 'grep -q "Permission denied" "$WORK/${P}ssh-wrong.err" && grep -qx "exit 255" "$WORK/${P}ssh-wrong"'
    expect_line "sshd: root logged in from 10.0.2.2 (publickey)"
    expect_line "sshd: root logged in from 10.0.2.2 (password)"
    expect_line "sshd: root from 10.0.2.2: password refused"
    # The client.
    expect "ssh: 127.0.0.1 is not known yet. Its host key: $print"
    expect "from the client"
    expect_line "ssh: the connection to 127.0.0.1 is closed"
    expect "ssh: localhost is not known yet. Its host key: $print"
    expect_line "ssh: exit code 5"
    local host_key
    host_key=$(awk '{print $3; exit}' "$WORK/${P}known_hosts")
    want="$(printf '127.0.0.1 ssh-ed25519 %s\nlocalhost ssh-ed25519 %s' "$host_key" "$host_key")"
    compare "known_hosts: both names with the host key" "$want" \
            "$(command_output 'cat /home/root/.ssh/known_hosts')"
    expect_line "by password"
    expect_line "sshd: root logged in from 127.0.0.1 (password)"
    expect_line "inside"
    expect "ssh: WARNING: the host key of 127.0.0.1 is not the one in /home/root/.ssh/known_hosts"
    check "nothing ran for a wrong password or a changed host key" "it ran" \
          eval '! grep -qx "should not run" <<<"$TEXT"'
    reject "panic"
    show_log_on_failure $before
}

# sshexec_session / sshexec_shell_test: non-interactive ssh exec and file
# transfer. A remote OpenSSH client (the Mac's) runs commands with no pty, so
# sshd runs them on raw pipes: binary-clean stdin/stdout, separate stderr, a
# real exit status. Pushes a binary file (`cat > FILE < localbin`), checks the
# guest's sha256 of it, pulls it back binary-safe and compares, checks stdout
# and stderr stay apart, the exit code, and (22t) the session's variables
# (HOME, USER, LOGNAME, SHELL; TERM only with a terminal). The binary legs bypass mac_ssh
# (whose `tr -d '\r'` would corrupt binary). Proven by forcing the pty path (a
# pty mangles binary and merges stderr), which fails these checks.
sshexec_session() {
    local n=1 asked=0 key="$WORK/${P}id_ed25519"
    local -a with_key=(-i "$key" -o IdentitiesOnly=yes -o BatchMode=yes)
    local -a opts=(-p $NET_SSH_PORT -o UserKnownHostsFile="$WORK/${P}known_hosts"
                   -o StrictHostKeyChecking=accept-new -o LogLevel=ERROR "${with_key[@]}")
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15                        # (and the elf sshd listening)
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 'cat > /home/root/x' <"$WORK/${P}src.bin" \
        >"$WORK/${P}push.out" 2>"$WORK/${P}push.err"
    echo "push exit $?" >"$WORK/${P}push.rc"
    mac_ssh sx-sha "${with_key[@]}" root@127.0.0.1 "/system/$ARCH_NAME/test/filesha /home/root/x"
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 'cat /home/root/x' \
        >"$WORK/${P}pull.bin" 2>"$WORK/${P}pull.err"
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 'echo OUT; cat /no/such/file' \
        >"$WORK/${P}se.out" 2>"$WORK/${P}se.err"
    mac_ssh sx-exit "${with_key[@]}" root@127.0.0.1 'exit 7'
    # Long commands and scripts (sh -c kept only 255 bytes of a command; a
    # piped script was read 255 bytes at a time, lines cut or run together)
    local long; long=$(printf 'x%.0s' $(seq 1 380))
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 "echo BEGIN $long END" \
        >"$WORK/${P}long.out" 2>"$WORK/${P}long.err"
    for i in $(seq 1 60); do echo "echo line $i"; done >"$WORK/${P}script.sh"
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 sh <"$WORK/${P}script.sh" \
        >"$WORK/${P}script.out" 2>"$WORK/${P}script.err"
    { echo "echo before"; echo "echo $(printf 'y%.0s' $(seq 1 5000))"; echo "echo after"; } \
        >"$WORK/${P}huge.sh"
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 sh <"$WORK/${P}huge.sh" \
        >"$WORK/${P}huge.out" 2>"$WORK/${P}huge.err"
    # The session's environment (22t): without a terminal, and with one
    # (TERM as the client asked)
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 'echo $HOME $USER $LOGNAME $SHELL [$TERM]' \
        >"$WORK/${P}env.out" 2>&1
    TERM=vt100 /usr/bin/ssh -tt "${opts[@]}" root@127.0.0.1 'echo [$TERM]' \
        >"$WORK/${P}envtty.out" 2>&1 </dev/null
}

# tar_session / tar_shell_test (63h): tar between the Mac and RitterOS. A
# folder (sub-folders, a binary file, an empty one, a symbolic link, a
# long name for ustar's prefix, a longer one for a pax header, a deep
# path, modes 600 and 700) is made by the Mac's tar (bsdtar) and taken
# apart on RitterOS in one ssh call (tar xf - -C /tmp); RitterOS copies it
# through its own pipe (tar cf - | tar xf -), lists it (tar tvf) and sends
# the copy back (tar cf -), which the Mac's tar takes apart: the same files,
# links and modes as the original. A hostile archive (.. paths, a link to
# a folder and a file through it) leaves nothing outside. Proven by a tar
# that writes plain names only (the long ones lost) and one that follows
# links.
tar_session() {
    local n=1 key="$WORK/${P}id_ed25519"
    local -a opts=(-p $NET_SSH_PORT -o UserKnownHostsFile="$WORK/${P}known_hosts"
                   -o StrictHostKeyChecking=accept-new -o LogLevel=ERROR
                   -i "$key" -o IdentitiesOnly=yes -o BatchMode=yes)
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15                        # (and the elf sshd listening)
    COPYFILE_DISABLE=1 /usr/bin/tar cf - -C "$WORK/${P}tar" src |
        /usr/bin/ssh "${opts[@]}" root@127.0.0.1 'tar xf - -C /tmp' >"$WORK/${P}tar-in.out" 2>&1
    echo "exit $?" >>"$WORK/${P}tar-in.out"
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 \
        'mkdir -p /tmp/copy && cd /tmp && tar cf - src | tar xf - -C /tmp/copy && tar tvf /tmp/none.tar; tar cvf /tmp/src.tar src > /tmp/c.out; tar tvf /tmp/src.tar' \
        </dev/null >"$WORK/${P}tar-list.out" 2>&1
    rm -rf "$WORK/${P}tar-back"
    mkdir -p "$WORK/${P}tar-back"
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 'tar cf - -C /tmp/copy src' </dev/null 2>"$WORK/${P}tar-out.err" |
        /usr/bin/tar xf - -C "$WORK/${P}tar-back" 2>>"$WORK/${P}tar-out.err"
    echo "exit $?" >>"$WORK/${P}tar-out.err"
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 \
        'cd /tmp && echo a > t1 && touch -t 202001021530.44 t1 && touch -r t1 t2 && chmod 600 t1 && cp -p t1 t3 && cp t1 t4 && touch -c t5 && mkdir -p d/e && touch -t 201505050505 d/e d && cp -rp d d2 && tar cf - t1 t2 t3 t4 d2 | tar tvf -' \
        </dev/null >"$WORK/${P}tar-times.out" 2>&1
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 'mkdir -p /tmp/evil /tmp/outside && tar xvf - -C /tmp/evil' \
        <"$WORK/${P}evil.tar" >"$WORK/${P}tar-evil.out" 2>&1
    echo "exit $?" >>"$WORK/${P}tar-evil.out"
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 'ls /tmp/outside; ls /tmp; ls -l /tmp/evil' </dev/null \
        >"$WORK/${P}tar-after.out" 2>&1
}

tar_shell_test() {
    local image before key="$WORK/${P}id_ed25519" s="$WORK/${P}tar/src" d i
    image=$(make_image ${P}tar "")
    rm -f "$key" "$key.pub" "$WORK/${P}known_hosts"
    ssh-keygen -q -t ed25519 -N '' -C test@mac -f "$key" || exit 1
    $RFS put "$image" $RFS_PART /home/root/.ssh/authorized_keys "$key.pub" >/dev/null || exit 1
    rm -rf "$WORK/${P}tar"
    mkdir -p "$s/a/b"
    echo hello >"$s/a/one.txt"
    : >"$s/empty"
    head -c 100000 /dev/urandom >"$s/a/b/bin.dat"
    ln -s a/one.txt "$s/link"
    d="$s/a_folder_whose_name_is_long_enough_to_need_ustars_prefix_field_beyond_the_hundred_bytes"
    mkdir -p "$d" && echo prefix >"$d/inside.txt"
    d="$s/$(printf 'n%.0s' $(seq 1 120))"
    mkdir -p "$d" && echo pax >"$d/a_file_name_that_does_not_fit_in_ustar_at_all.txt"
    d="$s"
    for i in $(seq 1 12); do d="$d/deep_folder_$i"; done
    mkdir -p "$d" && echo deep >"$d/x"
    chmod 600 "$s/a/one.txt"
    chmod 700 "$s/a/b"
    python3 -I - "$WORK/${P}evil.tar" <<'PY'
import io, sys, tarfile
def add(t, name, data=b"x", kind=tarfile.REGTYPE, link=""):
    i = tarfile.TarInfo(name); i.type = kind; i.linkname = link
    i.size = len(data) if kind == tarfile.REGTYPE else 0
    t.addfile(i, io.BytesIO(data) if kind == tarfile.REGTYPE else None)
with tarfile.open(sys.argv[1], "w", format=tarfile.PAX_FORMAT) as t:
    add(t, "../escaped.txt"); add(t, "ok/../../up.txt")
    add(t, "s", kind=tarfile.SYMTYPE, link="/tmp/outside")
    add(t, "s/through.txt"); add(t, "/rooted.txt", b"rooted"); add(t, "fine.txt", b"fine")
PY
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_SSH_PORT-:22"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=tar_session
    boot ${P}tar "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    check "the Mac's tar into RitterOS's, one ssh call" "$(cat "$WORK/${P}tar-in.out")" \
          grep -qx "exit 0" "$WORK/${P}tar-in.out"
    check "RitterOS's tar back into the Mac's" "$(cat "$WORK/${P}tar-out.err")" \
          grep -qx "exit 0" "$WORK/${P}tar-out.err"
    check "the folder came back the same (diff -r)" "$(diff -r "$s" "$WORK/${P}tar-back/src" 2>&1 | head -5)" \
          diff -r "$s" "$WORK/${P}tar-back/src"
    compare "the modes, times (63m) and the link came back the same" \
            "$(cd "$WORK/${P}tar" && find src -exec stat -f '%Sp %m %N' {} \; | sort -k3)" \
            "$(cd "$WORK/${P}tar-back" && find src -exec stat -f '%Sp %m %N' {} \; | sort -k3)"
    # (63m) touch -t, -r, -c; cp -p and cp; cp -rp of a folder; as tar tvf lists them
    local times
    times=$(cat "$WORK/${P}tar-times.out")
    check "touch -t, touch -r and cp -p: the time and mode kept; cp alone: now" "$times" \
          eval 'grep -q "^-rw------- .* 2020-01-02 15:30 t1$" <<<"$times" &&
                grep -q "^-rw-r--r-- .* 0 2020-01-02 15:30 t2$" <<<"$times" &&
                grep -q "^-rw------- .* 2020-01-02 15:30 t3$" <<<"$times" &&
                grep -q " t4$" <<<"$times" && ! grep -q "2020-01-02 15:30 t4$" <<<"$times" &&
                ! grep -q " t5$" <<<"$times"'
    check "cp -rp: the folders keep their times" "$times" \
          eval 'grep -q "^drwxr-xr-x .* 2015-05-05 05:05 d2/$" <<<"$times" &&
                grep -q "^drwxr-xr-x .* 2015-05-05 05:05 d2/e/$" <<<"$times"'
    check "tar tvf on RitterOS lists the link and a mode" "$(head -30 "$WORK/${P}tar-list.out")" \
          eval 'grep -q "^lrwxrwxrwx .* src/link -> a/one.txt$" "$WORK/${P}tar-list.out" &&
                grep -q "^-rw------- .* src/a/one.txt$" "$WORK/${P}tar-list.out"'
    check "a missing archive: tar says so" "$(head -3 "$WORK/${P}tar-list.out")" \
          grep -q "^tar: /tmp/none.tar: " "$WORK/${P}tar-list.out"
    check "the hostile archive: refused, and said so" "$(cat "$WORK/${P}tar-evil.out")" \
          eval 'grep -q "^tar: ../escaped.txt: a path that would leave this folder" "$WORK/${P}tar-evil.out" &&
                grep -q "^tar: ok/../../up.txt: a path that would leave this folder" "$WORK/${P}tar-evil.out" &&
                grep -q "^tar: s/through.txt: it would go through a symbolic link" "$WORK/${P}tar-evil.out" &&
                grep -qx "exit 1" "$WORK/${P}tar-evil.out"'
    check "nothing outside: /tmp/outside empty, no escaped files, /rooted.txt inside" \
          "$(cat "$WORK/${P}tar-after.out")" \
          eval '! grep -q "through.txt\|escaped.txt\|up.txt" "$WORK/${P}tar-after.out" &&
                grep -q " rooted.txt$" "$WORK/${P}tar-after.out" && grep -q " fine.txt$" "$WORK/${P}tar-after.out"'
    reject "panic"
    show_log_on_failure $before
}

sshexec_shell_test() {
    local image before key="$WORK/${P}id_ed25519" srcsha size
    image=$(make_image ${P}sshexec "")
    rm -f "$key" "$key.pub" "$WORK/${P}known_hosts"
    ssh-keygen -q -t ed25519 -N '' -C test@mac -f "$key" || exit 1
    $RFS put "$image" $RFS_PART /home/root/.ssh/authorized_keys "$key.pub" >/dev/null || exit 1
    $RFS cat "$image" $RFS_PART /test/block.bin >"$WORK/${P}src.bin" || exit 1
    srcsha=$(shasum -a 256 "$WORK/${P}src.bin" | awk '{print $1}')
    size=$(wc -c <"$WORK/${P}src.bin" | tr -d ' ')
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_SSH_PORT-:22"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=sshexec_session
    boot ${P}sshexec "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    check "the binary push succeeded" "$(cat "$WORK/${P}push.rc" "$WORK/${P}push.err")" \
          grep -qx "push exit 0" "$WORK/${P}push.rc"
    check "the guest's sha256 of the pushed file matches" "$(cat "$WORK/${P}sx-sha")" \
          grep -qxF "filesha: /home/root/x: $size bytes, sha256 $srcsha" "$WORK/${P}sx-sha"
    compare "the file round-trips (pulled back binary-safe)" "$srcsha" \
            "$(shasum -a 256 "$WORK/${P}pull.bin" | awk '{print $1}')"
    check "stdout has the echo and not the error" "$(cat "$WORK/${P}se.out")" \
          eval 'grep -qx OUT "$WORK/${P}se.out" && ! grep -q "no/such" "$WORK/${P}se.out"'
    check "stderr has the error, kept apart" "$(cat "$WORK/${P}se.err")" \
          grep -q "/no/such/file" "$WORK/${P}se.err"
    compare "a command's exit code" "exit 7" "$(cat "$WORK/${P}sx-exit")"
    check "a 400-byte command runs whole (sh -c)" "$(head -c 120 "$WORK/${P}long.out")" \
          eval 'grep -q "^BEGIN x*x END$" "$WORK/${P}long.out"'
    compare "a 60-line script through a pipe runs every line once, in order" \
            "$(seq 1 60 | sed 's/^/line /')" \
            "$(grep -o 'line [0-9][0-9]*' "$WORK/${P}script.out")"
    compare "a piped script prints only its own output (63c: no prompts, no exit)" \
            "$(seq 1 60 | sed 's/^/line /')" "$(tr -d '\r' <"$WORK/${P}script.out")"
    compare "a line too long is refused, the others run" \
            "before after; sh: a line longer than 4095 bytes: not run" \
            "$(grep -o 'before\|after' "$WORK/${P}huge.out" | tr '\n' ' ' | sed 's/ $//'); $(cat "$WORK/${P}huge.err")"
    compare "the session's variables (22t), no terminal: no TERM" \
            "/home/root root root /system/$ARCH_NAME/bin/sh []" "$(tr -d '\r' <"$WORK/${P}env.out")"
    compare "with a terminal: the client's TERM" "[vt100]" \
            "$(tr -d '\r' <"$WORK/${P}envtty.out" | grep -o '\[[a-z0-9]*\]' | head -1)"
    reject "panic"
    show_log_on_failure $before
}

# selfbuild_session / selfbuild_shell_test (63, level 2: RitterOS builds
# RitterOS). The sources the build needs (boot, common, kernel, arch, user,
# (67h) the drivers and their interface (drivers/*.c, drivers/include/; 37g-5a
# a driver's own parts, drivers/*.h and drivers/NAME_*.c, too), the
# generators in scripts/*.c, the two fonts it compiles and the Makefile)
# are copied into /src over SSH, one file at a time with `cat > FILE` (the
# user's choice: no tar), the folders first through a piped script. RitterOS
# then runs `make TOOLCHAIN=ritteros HOSTCC=cc arch-build` for its own
# architecture: its cc builds the host toolchain (cc, as, ld, ar) and the
# generators from their sources, and those build the bootloader, the kernel,
# the libraries and every program. The Mac builds the same files the same
# way (our own make, built for the Mac, in a copy of the same sources), and
# every file of build/system/<arch> and the bootloader must be byte for byte
# the same: the modules too (/system/<arch>/drivers/*.mod, our cc's). Proven
# by a source changed on the guest only (the hashes of what it touches
# differ; 67h: a line added to drivers/hda.c, only hda.mod differed).
selfbuild_session() {
    local n=1 key="$WORK/${P}id_ed25519" f
    local -a with_key=(-i "$key" -o IdentitiesOnly=yes -o BatchMode=yes)
    local -a opts=(-p $NET_SSH_PORT -o UserKnownHostsFile="$WORK/${P}known_hosts"
                   -o StrictHostKeyChecking=accept-new -o LogLevel=ERROR "${with_key[@]}")
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15                        # (and the elf sshd listening)
    local start=$(date +%s)
    grep / "$WORK/${P}srcfiles" | sed 's|/[^/]*$||' | sort -u | sed 's|^|mkdir -p /src/|' >"$WORK/${P}mkdirs.sh"
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 sh <"$WORK/${P}mkdirs.sh" >"$WORK/${P}mkdirs.out" 2>&1
    local failed=0 hung=0
    # (41h) A copy still running after 60 s is the open SSH hang (CLAUDE.md):
    # before it is ended, the guest's processes, threads and network and its
    # cores (GDB) go into copy-hang.txt; the copies go on.
    local evidence="/usr/bin/ssh ${opts[*]} root@127.0.0.1 'ps; threads; net' </dev/null"
    evidence+=" >>$WORK/${P}copy-hang.txt 2>&1; python3 $ROOT/scripts/gdbprobe.py $WORK/gdb.sock"
    evidence+=" $ARCH_NAME $ROOT/build/system/$ARCH_NAME/kernel.elf >>$WORK/${P}copy-hang.txt 2>&1"
    rm -f "$WORK/${P}copy-hang.txt"
    while read -r f; do
        perl -MPOSIX=:sys_wait_h -e '
            my $pid = fork; exec @ARGV[2 .. $#ARGV] if !$pid;
            my $end = time + 60;                # (by the clock: counted steps run long)
            while (time < $end) {
                exit($? & 127 ? 128 + ($? & 127) : $? >> 8) if waitpid($pid, WNOHANG) > 0;
                select(undef, undef, undef, 0.01);
            }
            open(my $o, ">>", $ARGV[1]); print $o "copy of $ARGV[$#ARGV] hung 60 s\n"; close($o);
            system($ARGV[0]); kill "KILL", $pid; waitpid($pid, 0); exit 142' \
            "$evidence" "$WORK/${P}copy-hang.txt" /usr/bin/ssh "${opts[@]}" root@127.0.0.1 "cat > /src/$f" \
            <"$WORK/${P}src/$f" 2>>"$WORK/${P}copy.err"
        case $? in
        0) ;;
        142) failed=$((failed + 1)) hung=$((hung + 1)) ;;
        *) failed=$((failed + 1)) ;;
        esac
    done <"$WORK/${P}srcfiles"
    echo "copy failures $failed, $(($(date +%s) - start)) s, hung $hung" >"$WORK/${P}copy.rc"
    start=$(date +%s)
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 \
        "cd /src && make TOOLCHAIN=ritteros HOSTCC=cc ARCH=$ARCH_NAME arch-build > /src/make.log 2>&1; echo make exit \$?" \
        >"$WORK/${P}make.rc" 2>&1 </dev/null
    echo "$(($(date +%s) - start)) s" >>"$WORK/${P}make.rc"
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 'tail -n 20 /src/make.log' >"$WORK/${P}make.tail" 2>&1 </dev/null
    sed "s|^|/system/$ARCH_NAME/test/filesha /src/build/|" "$WORK/${P}products" >"$WORK/${P}sha.sh"
    /usr/bin/ssh "${opts[@]}" root@127.0.0.1 sh <"$WORK/${P}sha.sh" >"$WORK/${P}guest.sha" 2>&1
}

selfbuild_shell_test() {
    local image before key="$WORK/${P}id_ed25519" src="$WORK/${P}src" f
    NAME=${P}selfbuild                              # (the checks before the boot)
    image=$(make_image ${P}selfbuild "")
    rm -f "$key" "$key.pub" "$WORK/${P}known_hosts"
    ssh-keygen -q -t ed25519 -N '' -C test@mac -f "$key" || exit 1
    $RFS put "$image" $RFS_PART /home/root/.ssh/authorized_keys "$key.pub" >/dev/null || exit 1
    # the sources, as git has them plus the tree's changes (a copy: the Mac's
    # reference build runs in it, as RitterOS's in /src)
    (cd "$ROOT" && { git ls-files --cached --others --exclude-standard boot common kernel arch user Makefile;
                     git ls-files --cached --others --exclude-standard drivers |
                         grep -E '^drivers/([^/]*\.[ch]|include/[^/]*\.h)$';
                     ls scripts/*.c;
                     echo fonts/9x15.bdf; echo fonts/9x15B.bdf; echo VERSION; } | sort -u) >"$WORK/${P}srcfiles"
    rm -rf "$src"
    while read -r f; do
        mkdir -p "$src/$(dirname "$f")"
        cp "$ROOT/$f" "$src/$f"
    done <"$WORK/${P}srcfiles"
    # the Mac's build of the same: our make (built for the Mac), our tools
    mkdir -p "$WORK/${P}mk"
    printf '#define PROGRAM_HELP(a, b)\nextern char **environ;\n' >"$WORK/${P}mk/ritteros.h"
    cc -std=c11 -O1 -I"$WORK/${P}mk" -o "$WORK/${P}mk/make" "$ROOT/user/bin/make.c" || exit 1
    (cd "$src" && "$WORK/${P}mk/make" TOOLCHAIN=ritteros ARCH=$ARCH_NAME arch-build) >"$WORK/${P}mac-make.log" 2>&1
    check "the Mac builds the copy with our make and tools" "$(tail -5 "$WORK/${P}mac-make.log")" \
          test -f "$src/build/system/$ARCH_NAME/kernel.elf"
    (cd "$src/build" && find "system/$ARCH_NAME" esp -type f | sort) >"$WORK/${P}products"
    (cd "$src/build" && while read -r f; do
        echo "filesha: /src/build/$f: $(wc -c <"$f" | tr -d ' ') bytes, sha256 $(shasum -a 256 "$f" | awk '{print $1}')"
     done <"$WORK/${P}products") >"$WORK/${P}mac.sha"
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_SSH_PORT-:22"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=selfbuild_session
    boot ${P}selfbuild "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    compare "every source copied over SSH with cat" "copy failures 0" \
            "$(sed 's/,.*//' "$WORK/${P}copy.rc")"
    if [ -s "$WORK/${P}copy-hang.txt" ]; then       # (41h) the open SSH hang, seen again
        echo "--- a copy hung: $WORK/${P}copy-hang.txt ---"
        head -60 "$WORK/${P}copy-hang.txt"
    fi
    check "RitterOS's make finished" "$(cat "$WORK/${P}make.rc" "$WORK/${P}make.tail")" \
          grep -qx "make exit 0" "$WORK/${P}make.rc"
    compare "RitterOS built every file of build/system/$ARCH_NAME and the bootloader as the Mac did" \
            "$(cat "$WORK/${P}mac.sha")" \
            "$(tr -d '\r' <"$WORK/${P}guest.sha" | sed 's/^\(ritteros:[^$]*\$ \)*//' | grep '^filesha')"
    reject "panic"
    show_log_on_failure $before
}

# kill_session / kill_shell_test: the program kill (for the SDK's remote
# stop). A program that never ends by itself (loop) runs in the background;
# `kill PID` ends it with SIGTERM (the shell reports "[PID] stopped by signal
# 15" and ps no longer lists it running), `kill -KILL PID` a second one with
# SIGKILL; a missing process, a wrong signal and no arguments are refused.
# Proven by kill sending nothing (the loops stay).
kill_session() {
    local n=1 t="/system/$ARCH_NAME/test/loop" pids
    prompt_wait $n
    serial_type "$t &\r"                            # never ends by itself
    n=$((n + 1))
    prompt_wait $n
    serial_wait "loop: running until Ctrl-C" 1 10
    serial_type '\r'                                # its line came after the prompt
    n=$((n + 1))
    prompt_wait $n
    serial_type "$t &\r"                            # a second one
    n=$((n + 1))
    prompt_wait $n
    serial_wait "loop: running until Ctrl-C" 2 10
    serial_type '\r'
    n=$((n + 1))
    prompt_wait $n
    pids=$(tr -d '\r' <"$SERIAL_LOG" | grep -xE '\[[0-9]+\]' | tr -d '[]' | tr '\n' ' ')
    echo "$pids" >"$WORK/${P}kill.pids"
    set -- $pids
    answer_lines 'ps' "kill $1" "kill -KILL $2" 'ps' 'kill 999' 'kill -FOO 1' 'kill'
}

kill_shell_test() {
    local image before p1 p2
    image=$(make_image ${P}kill "")
    before=$failures
    SERIAL_SCRIPT=kill_session
    boot ${P}kill "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    read -r p1 p2 <"$WORK/${P}kill.pids"
    check "two background loops started" "pids: '$p1' '$p2'" test -n "$p2"
    check "ps lists both loops running" "$(command_output ps)" \
          eval '[ "$(command_output ps | grep -cE " running +loop$")" -eq 2 ]'
    expect_line "[$p1] stopped by signal 15"        # kill: SIGTERM by default
    expect_line "[$p2] stopped by signal 9"         # kill -KILL
    check "after kill no loop runs" "$(command_output ps 2)" \
          eval '! command_output ps 2 | grep -qE " running +loop$"'
    expect_line "kill: 999: No such process"
    expect_line "kill: FOO: not a signal (TERM, KILL, INT, HUP, USR1, USR2 or 1-31)"
    expect_line "usage: kill [-SIGNAL] PID..."
    reject "panic"
    show_log_on_failure $before
}

# grow_session / grow_shell_test (68j): a stick image (mkdisk --size 256)
# written to a bigger disk (the file made 20 GiB: its bitmap of 160 blocks
# needs a taller tree than one level's 128). At the first start, after
# root's password, login runs disks grow: partition 2 reaches the disk's
# end (the GPT fitted, its copy at the end, the old copy's header in the
# middle cleared), the kernel keeps it mounted with its new size and the
# RitterFS takes the room in one commit. disks grow again finds nothing to
# do. The Mac's ritterfs.py checks the grown file system and a second boot
# mounts and checks it with the new size. Proven by the bitmap's tree kept
# at its old height.
grow_session() {
    local n=1
    prompt_wait $n
    answer_lines 'disks grow' 'disks nvme0n1'
}

grow_shell_test() {
    local image before part="133120 41807872" gpt
    image=$(MKDISK_SIZE=256 make_image ${P}grow "")
    truncate -s 20g "$image" || exit 1
    before=$failures
    SERIAL_SCRIPT=grow_session
    boot ${P}grow "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "RitterFS:      nvme0n1p2 'RitterOS'"
    expect "48640 blocks of 4 KiB (190 MiB)"
    expect "disks: nvme0n1p2 grows from 190.0 MiB to 19.9 GiB, to the end of nvme0n1"
    expect "nvme0n1p2: grown to 41807872 blocks (20414 MiB), still mounted at /"
    expect "RitterFS:      nvme0n1p2 grown from 48640 to 5225984 blocks of 4 KiB (20414 MiB)"
    expect "disks: the RitterFS on nvme0n1p2 now has "
    expect "(5225984 blocks of 4 KiB)"
    expect "disks: nvme0n1p2 reaches the end of nvme0n1 already"
    reject "no longer in the partition table"
    reject "panic"
    show_log_on_failure $before
    check "the grown RitterFS is whole on the Mac" "$($RFS check "$image" $part 2>&1 | tail -3)" \
          eval '$RFS check "$image" $part | grep -q "5225984 blocks, .*all checksums ok, bitmap consistent"'
    gpt=$(python3 - "$image" <<'PY'
import struct, sys, zlib
f = open(sys.argv[1], "rb")
def header(lba):
    f.seek(lba * 512)
    s = f.read(512)
    return s[:8], struct.unpack_from("<QQQQ", s, 24)
sig, (me, other, first, last) = header(1)
print("primary", sig.decode(errors="replace"), me, other, last)
f.seek(2 * 512 + 128 + 32)
print("partition 2", *struct.unpack("<QQ", f.read(16)))
sig, (me, other, first, last) = header(41943039)
print("copy", sig.decode(errors="replace"), me, other, last)
f.seek(524287 * 512)
print("old copy cleared", not any(f.read(512)))
PY
)
    compare "the GPT fills the disk" "primary EFI PART 1 41943039 41943006
partition 2 133120 41940991
copy EFI PART 41943039 1 41943006
old copy cleared True" "$gpt"
    before=$failures
    boot ${P}grow2 "$image" "RitterOS kernel: boot complete"
    expect "5225984 blocks of 4 KiB (20414 MiB)"
    expect "RitterFS check: done in"
    reject "disks: "
    reject "PROBLEMS FOUND"
    reject "panic"
    show_log_on_failure $before
}

# uname_session / uname_shell_test (68i): the release in the kernel. The
# boot's first line names VERSION's release, the commit build/version.h
# was written with and the architecture; uname answers the same (-s alone
# without options, POSIX's order with several, -a all), and refuses an
# unknown option or an operand. Proven by the kernel answering another
# release than it booted with.
uname_session() {
    local n=1
    prompt_wait $n
    answer_lines 'uname' 'uname -a' 'uname -r' 'uname -mrs' 'uname -n -v' 'uname -x' 'uname now'
}

uname_shell_test() {
    local image before release commit text
    release=$(cat "$ROOT/VERSION")
    commit=$(sed -n 's/^#define RITTEROS_COMMIT "\(.*\)"$/\1/p' "$ROOT/build/version.h")
    text="$release${commit:+ ($commit)}, $ARCH_NAME"
    image=$(make_image ${P}uname "")
    before=$failures
    SERIAL_SCRIPT=uname_session
    boot ${P}uname "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "RitterOS kernel started: $text"
    compare "uname without options" "RitterOS" "$(command_output uname)"
    compare "uname -a" "RitterOS ritteros $release ${commit:-unknown} $ARCH_NAME" "$(command_output 'uname -a')"
    compare "uname -r: VERSION's release" "$release" "$(command_output 'uname -r')"
    compare "uname -mrs in POSIX's order" "RitterOS $release $ARCH_NAME" "$(command_output 'uname -mrs')"
    compare "uname -n -v" "ritteros ${commit:-unknown}" "$(command_output 'uname -n -v')"
    expect_line "uname: unknown option -x"
    expect_line "uname: unexpected 'now'"
    expect_line "usage: uname [-amnrsv]"
    reject "panic"
    show_log_on_failure $before
}

# sdk_make DIR ARGS...: make in an SDK project, as an outside developer runs
# it (none of this run's make settings leak in).
sdk_make() {
    local dir=$1
    shift
    env -u MAKEFLAGS -u MFLAGS -u MAKELEVEL make --no-print-directory -C "$dir" \
        RITTEROS="$ROOT" ARCH=$ARCH_NAME "$@"
}

# sdk_session / sdk_shell_test: the SDK (sdk/), used exactly as its guide
# says. Copies of sdk/template (a command-line program) and
# sdk/examples/hellowin (a windowed app) are built outside the tree through
# sdk/ritteros.mk; the guide's key setup runs by password; `make deploy run`
# copies the program over ssh and runs it (output and exit code back); an
# overwritten program keeps its mode, the other architecture's build does not
# start (126), a missing program is 127; sdk/API.md matches the headers
# (scripts/sdkapi.py --check); hellowin, run over ssh while windowd shows the
# desktop, opens its window and streams its output until `make
# stop` ends it. Proven by a wrong ps filter in `make stop` (it finds nothing,
# the app keeps running).
sdk_session() {
    local n=1 key="$WORK/${P}sdk_key" mon="$WORK/monitor.sock" i other=aarch64
    [ "$ARCH_NAME" = aarch64 ] && other=x86_64
    local opts="-p $NET_SSH_PORT -i $key -o IdentitiesOnly=yes"
    opts+=" -o UserKnownHostsFile=$WORK/${P}known_hosts -o LogLevel=ERROR"
    local -a with_key=(-i "$key" -o IdentitiesOnly=yes -o BatchMode=yes)
    local -a by_password=(-p $NET_SSH_PORT -o UserKnownHostsFile="$WORK/${P}known_hosts"
                          -o StrictHostKeyChecking=accept-new -o LogLevel=ERROR
                          -o PubkeyAuthentication=no -o PreferredAuthentications=password
                          -o NumberOfPasswordPrompts=1)
    local -a remote=(HOST=root@127.0.0.1 "SSH_OPTS=$opts")
    local prog="$WORK/${P}sdk-hello/build/$ARCH_NAME/hello"
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15                        # (and the elf sshd listening)
    serial_type 'windowd &\r'                       # the desktop, for the windowed app
    serial_wait "windowd: listening on /run/windowd" 1 15
    # The guide's key setup: two commands, root's password typed (askpass).
    SSH_ASKPASS="$WORK/${P}askpass" SSH_ASKPASS_REQUIRE=force DISPLAY=:0 \
        /usr/bin/ssh "${by_password[@]}" root@127.0.0.1 'mkdir -p /home/root/.ssh' \
        </dev/null >"$WORK/${P}sdk-mkdir" 2>&1
    echo "exit $?" >>"$WORK/${P}sdk-mkdir"
    SSH_ASKPASS="$WORK/${P}askpass" SSH_ASKPASS_REQUIRE=force DISPLAY=:0 \
        /usr/bin/ssh "${by_password[@]}" root@127.0.0.1 'cat >> /home/root/.ssh/authorized_keys' \
        <"$key.pub" >"$WORK/${P}sdk-addkey" 2>&1
    echo "exit $?" >>"$WORK/${P}sdk-addkey"
    # A command-line program: make deploy run.
    sdk_make "$WORK/${P}sdk-hello" "${remote[@]}" deploy run ARGS=agent \
        >"$WORK/${P}sdk-run" 2>&1
    echo "exit $?" >>"$WORK/${P}sdk-run"
    # LINK = static (22d): the same program, carrying its library code.
    sdk_make "$WORK/${P}sdk-hello" "${remote[@]}" APP=hellostatic LINK=static deploy run ARGS=static \
        >"$WORK/${P}sdk-static" 2>&1
    echo "exit $?" >>"$WORK/${P}sdk-static"
    # Copied over again without chmod: it keeps its mode, and still runs.
    /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 "cat > /system/$ARCH_NAME/bin/hello" \
        <"$prog" >/dev/null 2>&1
    mac_ssh sdk-again "${with_key[@]}" root@127.0.0.1 'hello again'
    # The other architecture's build does not start (126); no program is 127.
    /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 \
        "cat > /system/$ARCH_NAME/bin/sdkother; chmod 755 /system/$ARCH_NAME/bin/sdkother" \
        <"$WORK/${P}sdk-hello/build/$other/hello" >/dev/null 2>&1
    mac_ssh sdk-other "${with_key[@]}" root@127.0.0.1 sdkother
    mac_ssh sdk-nosuch "${with_key[@]}" root@127.0.0.1 sdknosuch
    # A windowed app: deploy, run in the background, see it, stop it.
    sdk_make "$WORK/${P}sdk-win" "${remote[@]}" deploy >"$WORK/${P}sdk-windeploy" 2>&1
    echo "exit $?" >>"$WORK/${P}sdk-windeploy"
    { sdk_make "$WORK/${P}sdk-win" "${remote[@]}" run >"$WORK/${P}sdk-winrun" 2>&1
      echo "exit $?" >>"$WORK/${P}sdk-winrun"; } &
    for ((i = 0; i < 120; i++)); do
        grep -q "hellowin: started" "$WORK/${P}sdk-winrun" 2>/dev/null && break
        sleep 0.25
    done
    sleep 0.5
    echo "screendump $WORK/${NAME}-win.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    sdk_make "$WORK/${P}sdk-win" "${remote[@]}" stop >"$WORK/${P}sdk-stop" 2>&1
    for ((i = 0; i < 120; i++)); do
        grep -q "^exit " "$WORK/${P}sdk-winrun" 2>/dev/null && break
        sleep 0.25
    done
    mac_ssh sdk-ps "${with_key[@]}" root@127.0.0.1 ps
    # (63f) The same projects built on the machine itself: their files sent
    # with cat (the guide's way), then make there with /system/sdk/ritteros.mk.
    local f d
    for d in hello win; do
        /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 "mkdir -p /home/root/$d" </dev/null >/dev/null 2>&1
    done
    for f in Makefile hello.c; do
        /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 "cat > /home/root/hello/$f" \
            <"$ROOT/sdk/template/$f" >/dev/null 2>&1
    done
    for f in Makefile hellowin.c; do
        /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 "cat > /home/root/win/$f" \
            <"$ROOT/sdk/examples/hellowin/$f" >/dev/null 2>&1
    done
    # (41h-9) root deploys without sudo: sudo is away meanwhile (the shell
    # finds programs in bin, not by PATH), then put back
    local sudo_at=/system/$ARCH_NAME/bin/sudo
    mac_ssh sdk-here "${with_key[@]}" root@127.0.0.1 \
        "mv $sudo_at $sudo_at.away && cd /home/root/hello && make APP=hellohere deploy run ARGS=machine;
         r=\$?; mv $sudo_at.away $sudo_at; exit \$r"
    mac_ssh sdk-herestatic "${with_key[@]}" root@127.0.0.1 \
        'cd /home/root/hello && make APP=herestatic LINK=static deploy run ARGS=still'
    mac_ssh sdk-hereldd "${with_key[@]}" root@127.0.0.1 \
        "ldd /system/$ARCH_NAME/bin/hellohere /system/$ARCH_NAME/bin/herestatic"
    mac_ssh sdk-herewin "${with_key[@]}" root@127.0.0.1 \
        "cd /home/root/win && make && ldd build/$ARCH_NAME/hellowin"
    mac_ssh sdk-herearch "${with_key[@]}" root@127.0.0.1 "cd /home/root/hello && make ARCH=$other"
    # (63g) a header changed on the machine rebuilds what includes it (cc -MMD -MP)
    printf '#define GREETING "first"\n' |
        /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 'cat > /home/root/hello/greet.h' >/dev/null 2>&1
    printf '#include <stdio.h>\n#include "greet.h"\nint main(void) { puts(GREETING); return 0; }\n' |
        /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 'cat > /home/root/hello/greet.c' >/dev/null 2>&1
    mac_ssh sdk-dep1 "${with_key[@]}" root@127.0.0.1 \
        "cd /home/root/hello && make APP=greet SRCS=greet.c && build/$ARCH_NAME/greet && cat build/$ARCH_NAME/obj/greet.d"
    sleep 1
    printf '#define GREETING "second"\n' |
        /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 'cat > /home/root/hello/greet.h' >/dev/null 2>&1
    mac_ssh sdk-dep2 "${with_key[@]}" root@127.0.0.1 \
        "cd /home/root/hello && make APP=greet SRCS=greet.c && build/$ARCH_NAME/greet"
    # (63m) the project sent again with tar keeps its files' times: nothing rebuilt
    COPYFILE_DISABLE=1 /usr/bin/tar cf - -C "$ROOT/sdk/template" Makefile hello.c |
        /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 'tar xf - -C /home/root/hello' >/dev/null 2>&1
    mac_ssh sdk-resend "${with_key[@]}" root@127.0.0.1 "cd /home/root/hello && make APP=hellohere"
    # (41h-4) the notes example as its Makefile says: deployed (42b: its
    # bundle, notes.info as its info), its own test.sh run on the machine (a
    # headless windowd, wsend, wshot) while the screen's windowd runs; the
    # picture fetched
    sdk_make "$WORK/${P}sdk-notes" "${remote[@]}" deploy >"$WORK/${P}sdk-notesdeploy" 2>&1
    /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 'cat > /tmp/notes-test.sh' \
        <"$ROOT/sdk/examples/notes/test.sh" >/dev/null 2>&1
    mac_ssh sdk-notestest "${with_key[@]}" root@127.0.0.1 'sh /tmp/notes-test.sh'
    /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 'cat /tmp/notes.png' </dev/null \
        >"$WORK/${P}sdk-notes.png" 2>/dev/null
    # (41h-7) deploying as a user of one's own, dev, through sudo: first in
    # sudo's nopassword list (nothing typed), then with a password typed to
    # make (passwd's two lines piped, 41h-7's line-at-a-time reading)
    local -a dev=(HOST=dev@127.0.0.1 "SSH_OPTS=$opts")
    /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 \
        "useradd dev; mkdir -p /home/dev/.ssh; cp /home/root/.ssh/authorized_keys /home/dev/.ssh/authorized_keys; chown 1000:1000 /home/dev/.ssh /home/dev/.ssh/authorized_keys; echo 'users = dev' > /system/config/sudo; echo 'nopassword = dev' >> /system/config/sudo" \
        </dev/null >"$WORK/${P}sdk-devsetup" 2>&1
    sdk_make "$WORK/${P}sdk-notes" "${dev[@]}" deploy </dev/null >"$WORK/${P}sdk-devnopw" 2>&1
    echo "exit $?" >>"$WORK/${P}sdk-devnopw"
    printf 'dev-pw-1\ndev-pw-1\n' | /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 \
        "passwd dev; echo 'users = dev' > /system/config/sudo" >>"$WORK/${P}sdk-devsetup" 2>&1
    printf 'dev-pw-1\n' | sdk_make "$WORK/${P}sdk-hello" "${dev[@]}" APP=devhello deploy \
        >"$WORK/${P}sdk-devpw" 2>&1
    echo "exit $?" >>"$WORK/${P}sdk-devpw"
    mac_ssh sdk-devrun -i "$key" -o IdentitiesOnly=yes -o BatchMode=yes dev@127.0.0.1 'devhello dev'
    # nothing typed (no terminal: an agent): stopped, sudo never handed the
    # archive; then dev out of sudo's users: refused at once, nothing asked
    sdk_make "$WORK/${P}sdk-hello" "${dev[@]}" APP=devnone deploy </dev/null >"$WORK/${P}sdk-devnone" 2>&1
    echo "exit $?" >>"$WORK/${P}sdk-devnone"
    /usr/bin/ssh $opts -o BatchMode=yes root@127.0.0.1 "echo 'users =' > /system/config/sudo" \
        </dev/null >>"$WORK/${P}sdk-devsetup" 2>&1
    sdk_make "$WORK/${P}sdk-hello" "${dev[@]}" APP=devnone deploy </dev/null >"$WORK/${P}sdk-devrefused" 2>&1
    echo "exit $?" >>"$WORK/${P}sdk-devrefused"
    mac_ssh sdk-devnoneran -i "$key" -o IdentitiesOnly=yes -o BatchMode=yes dev@127.0.0.1 'devnone'
}

sdk_shell_test() {
    local image before w h key="$WORK/${P}sdk_key" d other
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}sdk "")
    windows_bare "$image"                           # no startup app: hellowin is window 0
    rm -f "$key" "$key.pub" "$WORK/${P}known_hosts"
    ssh-keygen -q -t ed25519 -N '' -C sdk@mac -f "$key" || exit 1
    printf '#!/bin/sh\necho %s\n' "$ROOT_PASSWORD" >"$WORK/${P}askpass"
    chmod 700 "$WORK/${P}askpass"
    # The projects, started as the guide says: copies of the template and the example.
    rm -rf "$WORK/${P}sdk-hello" "$WORK/${P}sdk-win" "$WORK/${P}sdk-widgets" "$WORK/${P}sdk-notes"
    rm -f "$WORK/${P}sdk-notes.png" "$WORK/${P}sdk-notes.ppm"
    cp -R "$ROOT/sdk/template" "$WORK/${P}sdk-hello"
    cp -R "$ROOT/sdk/examples/hellowin" "$WORK/${P}sdk-win"
    cp -R "$ROOT/sdk/examples/widgets" "$WORK/${P}sdk-widgets"      # (41e)
    cp -R "$ROOT/sdk/examples/notes" "$WORK/${P}sdk-notes"          # (41h-4)
    for d in sdk-hello sdk-win sdk-widgets sdk-notes; do
        sdk_make "$WORK/${P}$d" >"$WORK/${P}$d.build" 2>&1
        echo "exit $?" >>"$WORK/${P}$d.build"
    done
    other=aarch64                                   # the template for the other one too
    [ "$ARCH_NAME" = aarch64 ] && other=x86_64
    env -u MAKEFLAGS -u MFLAGS -u MAKELEVEL make --no-print-directory -C "$WORK/${P}sdk-hello" \
        RITTEROS="$ROOT" ARCH=$other >"$WORK/${P}sdk-other.build" 2>&1
    echo "exit $?" >>"$WORK/${P}sdk-other.build"
    python3 "$ROOT/scripts/sdkapi.py" --check >"$WORK/${P}sdk-api" 2>&1   # sdk/API.md = the headers
    echo "exit $?" >>"$WORK/${P}sdk-api"
    { python3 "$ROOT/scripts/abicheck.py" && python3 "$ROOT/scripts/abicheck.py" --selftest; } \
        >"$WORK/${P}sdk-abi" 2>&1                   # the libraries' interfaces (22d)
    echo "exit $?" >>"$WORK/${P}sdk-abi"
    sdk_make "$WORK/${P}sdk-hello" APP=hellostatic LINK=static >"$WORK/${P}sdk-static.build" 2>&1
    echo "exit $?" >>"$WORK/${P}sdk-static.build"
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_SSH_PORT-:22"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=sdk_session
    boot ${P}sdk "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    check "the template builds outside the tree" "$(tail -5 "$WORK/${P}sdk-hello.build")" \
          grep -qx "exit 0" "$WORK/${P}sdk-hello.build"
    check "the windowed example builds" "$(tail -5 "$WORK/${P}sdk-win.build")" \
          grep -qx "exit 0" "$WORK/${P}sdk-win.build"
    check "the widgets example builds (41e)" "$(tail -5 "$WORK/${P}sdk-widgets.build")" \
          grep -qx "exit 0" "$WORK/${P}sdk-widgets.build"
    check "the notes example builds (41h-4)" "$(tail -5 "$WORK/${P}sdk-notes.build")" \
          grep -qx "exit 0" "$WORK/${P}sdk-notes.build"
    check "the template builds for the other architecture" "$(tail -5 "$WORK/${P}sdk-other.build")" \
          grep -qx "exit 0" "$WORK/${P}sdk-other.build"
    check "sdk/API.md matches the headers (scripts/sdkapi.py)" "$(cat "$WORK/${P}sdk-api")" \
          grep -qx "exit 0" "$WORK/${P}sdk-api"
    check "the libraries' interfaces are compatible, the checker's self-test ok" \
          "$(cat "$WORK/${P}sdk-abi")" \
          eval 'grep -qx "exit 0" "$WORK/${P}sdk-abi" && grep -qx "abicheck: self-test ok" "$WORK/${P}sdk-abi"'
    compare "the template links to the shared libraries (LINK = shared)" \
            "hello: soname -; needs libritteros.so.1" \
            "$(cd "$WORK/${P}sdk-hello/build/$ARCH_NAME" && python3 "$ROOT/scripts/elfneeded.py" hello)"
    compare "LINK = static links it statically" "hellostatic: static" \
            "$(cd "$WORK/${P}sdk-hello/build/$ARCH_NAME" && python3 "$ROOT/scripts/elfneeded.py" hellostatic)"
    check "the static build runs there too" "$(cat "$WORK/${P}sdk-static")" \
          eval 'grep -qx "Hello, static, from RitterOS!" "$WORK/${P}sdk-static" && grep -qx "exit 0" "$WORK/${P}sdk-static"'
    check "the key setup's mkdir -p (by password)" "$(cat "$WORK/${P}sdk-mkdir")" \
          grep -qx "exit 0" "$WORK/${P}sdk-mkdir"
    check "the key setup's cat >> authorized_keys" "$(cat "$WORK/${P}sdk-addkey")" \
          grep -qx "exit 0" "$WORK/${P}sdk-addkey"
    check "make deploy run: deployed, ran, exit 0" "$(cat "$WORK/${P}sdk-run")" \
          eval 'grep -q "^deployed build/$ARCH_NAME/hello to root@127.0.0.1:/system/$ARCH_NAME/bin/hello$" "$WORK/${P}sdk-run" &&
                grep -qx "Hello, agent, from RitterOS!" "$WORK/${P}sdk-run" &&
                grep -qx "exit 0" "$WORK/${P}sdk-run"'
    compare "an overwritten program keeps its mode and runs" \
            "$(printf 'Hello, again, from RitterOS!\nexit 0')" "$(cat "$WORK/${P}sdk-again")"
    check "the other architecture's build does not start (126)" \
          "$(cat "$WORK/${P}sdk-other" "$WORK/${P}sdk-other.err")" \
          eval 'grep -qx "exit 126" "$WORK/${P}sdk-other" &&
                grep -qx "sh: sdkother: Exec format error" "$WORK/${P}sdk-other.err"'
    check "no such program is 127" "$(cat "$WORK/${P}sdk-nosuch" "$WORK/${P}sdk-nosuch.err")" \
          eval 'grep -qx "exit 127" "$WORK/${P}sdk-nosuch" &&
                grep -qx "sh: sdknosuch: command not found" "$WORK/${P}sdk-nosuch.err"'
    check "the windowed app deployed to apps" "$(cat "$WORK/${P}sdk-windeploy")" \
          eval 'grep -q "^deployed build/$ARCH_NAME/hellowin to root@127.0.0.1:/system/$ARCH_NAME/apps/hellowin.program/hellowin$" "$WORK/${P}sdk-windeploy" &&
                grep -qx "exit 0" "$WORK/${P}sdk-windeploy"'
    check "its output came back over ssh while it ran" "$(cat "$WORK/${P}sdk-winrun")" \
          grep -qx "hellowin: started" "$WORK/${P}sdk-winrun"
    check_screen region-106-102-72-15-255-255-255 $w $h "$WORK/${P}sdk-win.ppm"  # its title
    check_screen px-440-210-43-58-85 $w $h "$WORK/${P}sdk-win.ppm"              # its background
    check_screen px-200-165-136-192-208 $w $h "$WORK/${P}sdk-win.ppm"           # its accent line
    check "make stop found it and killed it" "$(cat "$WORK/${P}sdk-stop")" \
          grep -qE "^kill [0-9]+$" "$WORK/${P}sdk-stop"
    check "the run ended with the kill (143)" "$(cat "$WORK/${P}sdk-winrun")" \
          grep -q "Error 143" "$WORK/${P}sdk-winrun"         # (51a: sh -c reports nothing itself)
    # (63f) built on the machine
    check "on the machine: make deploy run with its own cc" "$(cat "$WORK/${P}sdk-here" "$WORK/${P}sdk-here.err")" \
          eval 'grep -qx "deployed build/$ARCH_NAME/hellohere to /system/$ARCH_NAME/bin/hellohere" "$WORK/${P}sdk-here" &&
                grep -qx "Hello, machine, from RitterOS!" "$WORK/${P}sdk-here" && grep -qx "exit 0" "$WORK/${P}sdk-here"'
    check "on the machine: root deploys without sudo" "$(cat "$WORK/${P}sdk-here" "$WORK/${P}sdk-here.err")" \
          eval '! grep -q "sudo: command not found" "$WORK/${P}sdk-here" "$WORK/${P}sdk-here.err" &&
                grep -qx "exit 0" "$WORK/${P}sdk-here"'
    check "on the machine: LINK=static" "$(cat "$WORK/${P}sdk-herestatic" "$WORK/${P}sdk-herestatic.err")" \
          eval 'grep -qx "Hello, still, from RitterOS!" "$WORK/${P}sdk-herestatic" && grep -qx "exit 0" "$WORK/${P}sdk-herestatic"'
    check "on the machine: shared and static, as ldd sees them" "$(cat "$WORK/${P}sdk-hereldd")" \
          eval 'grep -q "libritteros.so.1" "$WORK/${P}sdk-hereldd" && grep -q "static" "$WORK/${P}sdk-hereldd"'
    check "on the machine: the windowed example links libwindow by itself" \
          "$(cat "$WORK/${P}sdk-herewin" "$WORK/${P}sdk-herewin.err")" \
          eval 'grep -q "libwindow.so.1" "$WORK/${P}sdk-herewin" && grep -qx "exit 0" "$WORK/${P}sdk-herewin"'
    check "on the machine: another ARCH is refused" "$(cat "$WORK/${P}sdk-herearch" "$WORK/${P}sdk-herearch.err")" \
          eval 'grep -q "this machine builds for $ARCH_NAME only, not ARCH=$other" "$WORK/${P}sdk-herearch" "$WORK/${P}sdk-herearch.err" &&
                ! grep -qx "exit 0" "$WORK/${P}sdk-herearch"'
    check "on the machine: cc -MMD -MP's rule (the project's header, not the system's)" \
          "$(cat "$WORK/${P}sdk-dep1" "$WORK/${P}sdk-dep1.err")" \
          eval 'grep -qx "build/$ARCH_NAME/obj/greet.o: greet.c greet.h" "$WORK/${P}sdk-dep1" &&
                grep -qx "greet.h:" "$WORK/${P}sdk-dep1" && grep -qx "first" "$WORK/${P}sdk-dep1"'
    check "on the machine: a changed header rebuilds" "$(cat "$WORK/${P}sdk-dep2" "$WORK/${P}sdk-dep2.err")" \
          eval 'grep -q "^cc .*greet.c" "$WORK/${P}sdk-dep2" && grep -qx "second" "$WORK/${P}sdk-dep2" &&
                grep -qx "exit 0" "$WORK/${P}sdk-dep2"'
    check "on the machine: the project sent again with tar builds nothing (its times kept)" \
          "$(cat "$WORK/${P}sdk-resend" "$WORK/${P}sdk-resend.err")" \
          eval '! grep -q "^cc " "$WORK/${P}sdk-resend" && grep -qx "exit 0" "$WORK/${P}sdk-resend"'
    check "ps no longer lists it running" "$(cat "$WORK/${P}sdk-ps")" \
          eval '! grep -qE " running +hellowin$" "$WORK/${P}sdk-ps"'
    # (41h-4) notes' own test, headless on the machine: its note saved, its
    # notification in the picture wshot took
    check "notes' test.sh passes on the machine, without a screen (41h-4)" \
          "$(cat "$WORK/${P}sdk-notestest" "$WORK/${P}sdk-notestest.err" "$WORK/${P}sdk-notesdeploy" | head -8)" \
          eval 'grep -qx "notes test: ok" "$WORK/${P}sdk-notestest" && grep -qx "exit 0" "$WORK/${P}sdk-notestest"'
    python3 - "$ROOT/scripts" "$WORK/${P}sdk-notes.png" "$WORK/${P}sdk-notes.ppm" <<'PY' >/dev/null 2>&1
import sys
sys.path.insert(0, sys.argv[1])
import pngcheck
w, h, ch, pix = pngcheck.decode_png(open(sys.argv[2], "rb").read())
rgb = pix if ch == 3 else b"".join(pix[i:i + 3] for i in range(0, len(pix), 4))
open(sys.argv[3], "wb").write(b"P6\n%d %d\n255\n" % (w, h) + rgb)
PY
    check "a user in sudo's nopassword deploys with nothing typed (41h-7)" \
          "$(cat "$WORK/${P}sdk-devsetup" "$WORK/${P}sdk-devnopw" | tail -8)" \
          eval 'grep -q "^deployed build/$ARCH_NAME/notes to dev@127.0.0.1:/system/$ARCH_NAME/apps/notes.program/notes$" "$WORK/${P}sdk-devnopw" && grep -qx "exit 0" "$WORK/${P}sdk-devnopw"'
    check "a user with a password deploys it typed once to make (41h-7)" \
          "$(cat "$WORK/${P}sdk-devsetup" "$WORK/${P}sdk-devpw" | tail -8)" \
          eval 'grep -q "^sudo password on dev@127.0.0.1: " "$WORK/${P}sdk-devpw" && grep -q "^deployed build/$ARCH_NAME/devhello to dev@127.0.0.1:/system/$ARCH_NAME/bin/devhello$" "$WORK/${P}sdk-devpw" && grep -qx "exit 0" "$WORK/${P}sdk-devpw"'
    compare "the program dev deployed runs" "$(printf 'Hello, dev, from RitterOS!\nexit 0')" \
            "$(cat "$WORK/${P}sdk-devrun")"
    check "nothing typed: make deploy stops, saying why (not sudo's wrong password)" \
          "$(tail -5 "$WORK/${P}sdk-devnone")" \
          eval 'grep -q "^make deploy: dev@127.0.0.1 needs a password for sudo: type it here, or root lists the user in /system/config/sudo.s nopassword$" "$WORK/${P}sdk-devnone" && ! grep -qx "exit 0" "$WORK/${P}sdk-devnone" && ! grep -q "wrong password" "$WORK/${P}sdk-devnone"'
    check "a user sudo refuses is told at once, no password asked" \
          "$(tail -5 "$WORK/${P}sdk-devrefused")" \
          eval 'grep -qx "sudo: dev may not run commands as root (not in /system/config/sudo)" "$WORK/${P}sdk-devrefused" && ! grep -q "sudo password on" "$WORK/${P}sdk-devrefused" && ! grep -qx "exit 0" "$WORK/${P}sdk-devrefused"'
    check "neither installed anything" "$(cat "$WORK/${P}sdk-devnoneran")" \
          grep -qx "exit 127" "$WORK/${P}sdk-devnoneran"
    check_screen "textat-320-16-bold-255.255.255-59.66.82-Saved" 640 480 "$WORK/${P}sdk-notes.ppm"
    check_screen "textat-320-33-regular-216.222.233-59.66.82-17 bytes in ~/notes.txt" 640 480 \
                 "$WORK/${P}sdk-notes.ppm"
    reject "panic"
    show_log_on_failure $before
}

# lo_session: the loopback without a network card (lo_shell_test).
lo_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test/sock"
    prompt_wait $n
    answer_lines 'net' 'ping -c 2 127.0.0.1' 'ping -c 1 localhost' 'ping -c 1 127.9.8.7' \
                 "$t udploop" "$t loop 300000"
    serial_type 'sshd &\r'
    n=$((n + 1))
    prompt_wait $n
    serial_wait "sshd: listening on port 22" 1 30
    serial_type '\r'                                # sshd's messages came after the prompt
    n=$((n + 1))
    prompt_wait $n
    serial_type "ssh root@localhost 'echo over the loopback'\r"
    serial_wait "(yes/no) " 1 30
    serial_type 'yes\r'
    n=$((n + 1))
    prompt_wait $n 60
    serial_type '\r'                                # sshd's login message
    n=$((n + 1))
    prompt_wait $n
    answer_lines 'net'
}

# lo_shell_test: the loopback interface lo on a machine without a network
# card: in the boot log and in net (with "no network cards"), login does
# not try to set up a card; ping to 127.0.0.1, localhost and another
# 127.x address, UDP and 300,000 bytes of TCP between two threads, sshd
# and ssh to localhost (with a key made by the Mac's ssh-keygen); lo's
# counters afterwards (as many packets received as sent).
lo_shell_test() {
    local image before key="$WORK/${P}lo_id_ed25519" t="/system/$ARCH_NAME/test/sock" line
    image=$(make_image ${P}lo "")
    rm -f "$key" "$key.pub"
    ssh-keygen -q -t ed25519 -N '' -C test@mac -f "$key" || exit 1
    $RFS put "$image" $RFS_PART /home/root/.ssh/authorized_keys "$key.pub" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /home/root/.ssh/id_ed25519 "$key" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=lo_session
    boot ${P}lo "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect_line "  lo:            the loopback, 127.0.0.1/8"
    want_text want <<'LINES'
lo     the loopback, 127.0.0.1/8
       received 0 packets (0 bytes), sent 0 packets (0 bytes), 0 not sent
       IPv6 ::1/128
no network cards
route: 127.0.0.0/8 on lo
forwarding: off; 0 packets forwarded, not: 0 without a route, 0 out of time (TTL), 0 without an ARP answer
masquerade: off
tcp: 0 connection(s); segments 0 sent, 0 received; sent again: 0 after a timeout, 0 fast; 0 kept after a gap, 0 window probes; 0 with scaled windows, 0 with SACK, receive buffers doubled 0 times; 0 holes resent from SACK, send buffers doubled 0 times, 0 ACKs delayed, 0 reset with data unread
udp: 0 of 128 port(s) bound; 0 datagram(s) dropped by a full queue
LINES
    compare "net without a card: lo, its route, nothing sent yet" "$want" "$(command_output 'net')"
    reject "net: eth0"                              # login set up no card
    expect "--- 127.0.0.1: 2 sent, 2 received, 0% lost"
    expect_line "PING localhost (127.0.0.1): 56 data bytes"
    expect "--- localhost: 1 sent, 1 received, 0% lost"
    expect "64 bytes from 127.9.8.7: seq=1 time="
    want_text want <<'LINES'
sock: port 4000 again: Address already in use
sock: 'datagram 1' from 127.0.0.1, the sender's port
sock: 'datagram 2' from 127.0.0.1, the sender's port
sock: 'datagram 3' from 127.0.0.1, the sender's port
sock: nothing more: Timed out
LINES
    compare "UDP over lo" "$want" "$(command_output "$t udploop")"
    compare "TCP over lo" "sock: received 300000 bytes, pattern ok" \
            "$(command_output "$t loop 300000")"
    expect "ssh: localhost is not known yet. Its host key: SHA256:"
    expect_line "over the loopback"
    expect_line "sshd: root logged in from 127.0.0.1 (publickey)"
    line=$(command_output 'net' 2 | sed -n 2p)
    check "lo counted: $line" "lo: '$line'" \
          eval '[[ "$line" =~ ^\ +received\ ([0-9]+)\ packets\ \([0-9]+\ bytes\),\ sent\ ([0-9]+)\ packets ]] &&
                [ "${BASH_REMATCH[1]}" = "${BASH_REMATCH[2]}" ] && [ "${BASH_REMATCH[1]}" -gt 100 ]'
    reject "panic"
    show_log_on_failure $before
}

# ping_average_below HOST MS: the average round trip of the last "ping
# HOST" in the session is below MS milliseconds (for cards that take
# frames by interrupt: polled by the 10 ms tick, it is about 5 ms).
ping_average_below() {
    local host="$1" limit="$2" avg
    avg=$(grep -a "^--- $host: " <<<"$TEXT" | tail -1 | sed -n 's|.*min/avg/max [0-9.]*/\([0-9.]*\)/.*|\1|p')
    check "ping $host: $avg ms on average (below $limit: by interrupt)" \
          "ping $host: ${avg:-?} ms on average, not below $limit (polled?)" \
          awk -v a="${avg:-99}" -v l="$limit" 'BEGIN { exit !(a < l) }'
}

# dhcp_wait CARD ADDRESS: wait (up to 20 s) until the elf dhclient has given
# CARD its address, then a fresh prompt (its line may have come after one).
dhcp_wait() {
    serial_wait "dhclient: $1: $2/" 1 20
    serial_wait "sshd: listening on port 22" 1 30  # (its lines would land in an output)
    serial_wait " rule(s) loaded (in = " 1 30     # guardd's: until then nothing comes in
    answer_lines ''
}

# dnsd_wait: wait (up to 20 s) until elvesd has started the elf dnsd
# (names), then a fresh prompt.
dnsd_wait() {
    serial_wait "elvesd: dnsd started" 1 20
    answer_lines ''
}

# igb_session: the Intel 82576 (igb_shell_test).
igb_session() {
    local n=1 asked=0 w="http://mac.test:$NET_HTTP_PORT"
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    answer_lines 'ping -c 10 10.0.2.2' "fetch -o /big.bin $w/big.bin" \
                 "/system/$ARCH_NAME/test/filesha /big.bin" "fetch $w/hello.txt" 'net'
}

# igb_shell_test: an Intel 82576 (igb, the test PC's card) on QEMU's user
# network: found with its MAC address and link (after the PHY's
# negotiation), DHCP, ping, 1,000,000 bytes from the web server on the Mac
# (about 700 frames: the receive ring of 64 goes round ten times; its
# SHA-256 checked) and a page, net's lines for the card (driver, model,
# counters, its interrupts: MSI); 10 pings to the gateway average below
# 3 ms (frames taken by interrupt, not at the 10 ms tick).
igb_shell_test() {
    local image before dns web w="http://mac.test:$NET_HTTP_PORT"
    image=$(make_image ${P}igb "")
    printf 'address = dhcp\ndns = 10.0.2.2:%s\n' $NET_DNS_PORT >"$WORK/${P}network"
    $RFS put "$image" $RFS_PART /system/config/network/eth0 "$WORK/${P}network" >/dev/null || exit 1
    python3 "$ROOT/scripts/testdns.py" $NET_DNS_PORT mac.test=10.0.2.2 >"$WORK/${P}testdns.log" 2>&1 &
    dns=$!
    python3 "$ROOT/scripts/testhttp.py" $NET_HTTP_PORT >"$WORK/${P}testhttp.log" 2>&1 &
    web=$!
    host_service_wait "$WORK/${P}testdns.log" listening
    host_service_wait "$WORK/${P}testhttp.log" listening
    QEMU_EXTRA="-netdev user,id=net0 -device igb,netdev=net0,mac=52:54:00:12:34:57"
    before=$failures
    SERIAL_SCRIPT=igb_session
    boot ${P}igb "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $dns $web 2>/dev/null
    wait $dns $web 2>/dev/null
    expect "eth0:          Intel 82576 at "
    expect "(igb), MAC 52:54:00:12:34:57, "
    expect_link 52:54:00:12:34:57 1000
    expect "dhclient: eth0: 10.0.2.15/24 from 10.0.2.2, gateway 10.0.2.2"
    expect "--- 10.0.2.2: 10 sent, 10 received, 0% lost"
    ping_average_below 10.0.2.2 3
    # (65e-14) Ten or more interrupts and frames sent: since TCP acknowledges a
    # card's burst of frames once, a 1 MB download sends tens of frames, not
    # hundreds (the download itself checks that nothing was lost).
    check "net: the card's interrupts (MSI)" "$(command_output 'net' | grep 'igb: interrupts')" \
          eval 'command_output net | grep -Eq "^       igb: interrupts: MSI-X, [0-9]{2,}, frames found by the tick instead [0-9]+$"'
    expect "       igb: IMS 0x00000000, IVAR0 0x00000080, EITR0 0x00000000, GPIE 0x80000011, EIMS 0x00000001; "  # MSI-X (44j)
    compare "1,000,000 bytes saved" "fetch: 200 OK, 1000000 bytes saved to /big.bin" \
            "$(command_output "fetch -o /big.bin $w/big.bin")"
    expect_line "filesha: /big.bin: 1000000 bytes, sha256 $(python3 -c "import hashlib; print(hashlib.sha256(bytes(i % 251 for i in range(1000000))).hexdigest())")"
    compare "a page" "Hello from the Mac!" "$(command_output "fetch $w/hello.txt")"
    check "net: the card" "$(command_output 'net' | grep '^eth0')" \
          eval 'command_output net | grep -q "^eth0   52:54:00:12:34:57  link up, 1000 Mbit/s, Intel 82576 (igb at "'
    check "net: over 1,000,000 bytes received, none left unsent" "$(command_output 'net' | grep -A3 '^eth0' | grep received)" \
          eval 'command_output net | grep -A3 "^eth0" | grep -Eq "^       received [0-9]+ frames \([0-9]{7,} bytes\), sent [0-9]{2,} frames .*, 0 not sent$"'
    check "net: the chip's own counters" "$(command_output 'net' | grep 'igb: chip')" \
          eval 'command_output net | grep -Eq "^       igb: chip received [0-9]{3,} \(good [0-9]{3,}, missed 0, no buffer 0, CRC errors 0, queue dropped 0\), sent [0-9]{2,}$"'
    expect "igb: receive ring head "
    reject "the PHY does not answer"
    reject "  igb:           "
    reject "panic"
    show_log_on_failure $before
}

# realtek_session: three Realtek chips (realtek_shell_test).
realtek_session() {
    local n=1 asked=0 net
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    dhcp_wait eth1 10.0.3.15
    dhcp_wait eth2 10.0.4.15
    answer_lines 'ping -c 10 10.0.2.2'
    for net in 2 3 4; do
        answer_lines "ping -c 2 10.0.$net.2" "fetch -o /r$net.bin http://10.0.$net.2:$NET_HTTP_PORT/big.bin" \
                     "/system/$ARCH_NAME/test/filesha /r$net.bin"
    done
    answer_lines 'net' 'drivers'
    # (64p) the first chip stops sending: the driver resets it after 5 s
    echo "qom-set /machine/peripheral/rtl0 stuck true" | nc -w 3 -U "$WORK/monitor.sock" >/dev/null 2>&1
    answer_lines 'ping -c 8 10.0.2.2' 'ping -c 2 10.0.2.2' 'net' 'cpus'
}

# realtek_shell_test: Realtek chips on our own model in QEMU
# (scripts/qemu/rtl8168.c; the tests' QEMU has it from setup-toolchain.sh),
# each on a QEMU user network of its own (10.0.2.0/24, 10.0.3.0/24,
# 10.0.4.0/24): an RTL8168H with the laptop's ID, Killer's E2600 (a newer
# chip: PHY through OCP, the RXDV gate, its FIFOs set through ERI; taken
# for an RTL8125 by its ID until 47b),
# an RTL8168E (an older one: PHYAR) and an RTL8125 with the Killer E3000's
# ID (2.5 Gbit/s), every PHY starting powered down. Found with version, MAC
# and link; no settings on the disk: net up makes a file for each card
# (DHCP), and all three get an address; ping to
# each gateway, 1,000,000 bytes by fetch through each (SHA-256 checked);
# net's routes and the cards' counters.
realtek_shell_test() {
    local image before web net sha
    image=$(make_image ${P}realtek "")
    python3 "$ROOT/scripts/testhttp.py" $NET_HTTP_PORT >"$WORK/${P}testhttp.log" 2>&1 &
    web=$!
    host_service_wait "$WORK/${P}testhttp.log" listening
    QEMU_EXTRA="-netdev user,id=net0 -device rtl8168,id=rtl0,netdev=net0,mac=52:54:00:12:34:58,device-id=0x2600"
    QEMU_EXTRA+=" -netdev user,id=net1,net=10.0.3.0/24"
    QEMU_EXTRA+=" -device rtl8168,netdev=net1,mac=52:54:00:12:34:59,xid=0x2c1"
    QEMU_EXTRA+=" -netdev user,id=net2,net=10.0.4.0/24"
    QEMU_EXTRA+=" -device rtl8125,netdev=net2,mac=52:54:00:12:34:5a,device-id=0x3000"
    before=$failures
    SERIAL_SCRIPT=realtek_session
    boot ${P}realtek "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $web 2>/dev/null
    wait $web 2>/dev/null
    expect "Realtek RTL8168H, version 0x541 at "
    # (67a) The driver is a module, loaded after the root mount for its
    # three chips (their bus addresses differ between the architectures);
    # drivers says where it lies and what it took. Proven by a loader that
    # never matches a table (none loaded, no card) and one with an x86
    # PC32 relocation a byte off (the boot crashed).
    local mods ids kb usbmods
    mods=$(ls build/system/$ARCH_NAME/drivers/*.mod | wc -l | tr -d ' ')
    ids=$(grep -o '{ 0x10EC, 0x' drivers/rtl8168.c | wc -l | tr -d ' ')
    kb=$(( ($(wc -c < build/system/$ARCH_NAME/drivers/rtl8168.mod) + 1023) / 1024 ))
    usbmods=$(grep -l '^USB_MODULE(' drivers/*.c | wc -l | tr -d ' ')     # (67e: always loaded)
    compare "modules: rtl8168 loaded for the three chips" 1 \
            "$(grep -cE "^modules: rtl8168 \(00:0[0-9a-f]\.0, 00:0[0-9a-f]\.0, 00:0[0-9a-f]\.0\), usbnet \(no device yet\) loaded; $((mods - 1 - usbmods)) not needed$" <<<"$TEXT")"
    check "drivers: rtl8168 at the module region's start, the chips it took" \
          "$(command_output drivers | grep rtl8168)" \
          eval 'command_output drivers | grep -qE "^  rtl8168\.mod      rtl8168 at 0xffffffff82000000: code [0-9]+ KB, read-only [0-9]+ KB, data [0-9]+ KB \(file $kb KB\); $ids PCI IDs; took 00:0[0-9a-f]\.0 \(10ec:2600\) 00:0[0-9a-f]\.0 \(10ec:8168\) 00:0[0-9a-f]\.0 \(10ec:3000\)$"'
    expect_link 52:54:00:12:34:58 1000
    expect "Realtek RTL8168E, version 0x2c1 at "
    expect_link 52:54:00:12:34:59 1000
    expect "Realtek RTL8125A, version 0x609 at "
    expect_link 52:54:00:12:34:5a 2500
    # (65d) Two cores: each card's message interrupt goes to core 1 (the
    # boot core keeps the tick and the rest), which then takes the cards'
    # interrupts while they move 3 MB. Proven by a boot without the
    # spreading: no such lines, and core 1 took no device interrupts.
    compare "the three cards' interrupts moved to core 1" 3 \
            "$(grep -cE '^  interrupts:    [0-9a-f:.]+ \(10ec:(2600|8168|3000), MSI\) to core 1$' <<<"$TEXT")"
    local core1
    core1=$(command_output cpus | sed -n 's/^     1  0x[0-9a-f]* *online, .* ticks, \([0-9][0-9]*\) device interrupts, .*$/\1/p')
    check "core 1 took the cards' interrupts (${core1:-?})" "core 1: '${core1:-?}' device interrupts" \
          test "${core1:-0}" -ge 100
    sha=$(python3 -c "import hashlib; print(hashlib.sha256(bytes(i % 251 for i in range(1000000))).hexdigest())")
    want_text want <<'LINES'
# This card's settings (net up applies them; see the manual):
#   address = dhcp, or ADDRESS/PREFIX with gateway = ... and dns = ...
address = dhcp
LINES
    for net in 2 3 4; do
        expect_line "net: eth$((net - 2)): /system/config/network/eth$((net - 2)) made (address = dhcp)"
        compare "/system/config/network/eth$((net - 2)): DHCP" "$want" \
                "$($RFS cat "$image" $RFS_PART /system/config/network/eth$((net - 2)))"
        expect "dhclient: eth$((net - 2)): 10.0.$net.15/24 from 10.0.$net.2, gateway 10.0.$net.2"
        expect "--- 10.0.$net.2: 2 sent, 2 received, 0% lost"
        compare "1,000,000 bytes through 10.0.$net.2" "fetch: 200 OK, 1000000 bytes saved to /r$net.bin" \
                "$(command_output "fetch -o /r$net.bin http://10.0.$net.2:$NET_HTTP_PORT/big.bin")"
        expect_line "filesha: /r$net.bin: 1000000 bytes, sha256 $sha"
    done
    want_text want <<'LINES'
route: 127.0.0.0/8 on lo
route: 10.0.2.0/24 on eth0
route: 10.0.3.0/24 on eth1
route: 10.0.4.0/24 on eth2
route: default via 10.0.2.2 on eth0
LINES
    compare "net: a route for each card" "$want" "$(command_output 'net' | grep '^route:')"
    check "net: each card received over 1,000,000 bytes, none left unsent" \
          "$(command_output 'net' | grep -A3 '^eth' | grep received)" \
          test "$(command_output 'net' | grep -A3 '^eth' |
                  grep -Ec 'received [0-9]+ frames \([0-9]{7,} bytes\), sent [0-9]{2,} frames .*, 0 not sent$')" = 3
    # (64b) Each card's address from QEMU's router advertisement, which goes
    # to ff02::1: the chips' hash filters let it through.
    want_text want <<'LINES'
       IPv6 fec0::5054:ff:fe12:3458/64
       IPv6 fec0::5054:ff:fe12:3459/64
       IPv6 fec0::5054:ff:fe12:345a/64
LINES
    compare "net: each card's IPv6 address from QEMU's router" "$want" \
            "$(command_output 'net' | grep -o '^       IPv6 fec0::[^ ]*')"
    # (65e-14) Ten or more frames sent and interrupts: one ACK per burst of
    # frames (as in igb_shell_test).
    check "net: each chip's tally counters" "$(command_output 'net' | grep 'rtl8168: chip')" \
          test "$(command_output 'net' |
                  grep -Ec '^       rtl8168: chip sent [0-9]{2,} \(errors 0, aborted 0, underruns 0\), received [0-9]{3,} \(errors 0, missed 0, to us [0-9]{3,}, broadcasts [0-9]+\)$')" = 3
    ping_average_below 10.0.2.2 3
    check "net: each chip's interrupts (MSI)" "$(command_output 'net' | grep 'rtl8168: interrupts')" \
          test "$(command_output 'net' |
                  grep -Ec '^       rtl8168: interrupts: MSI, [0-9]{2,}, frames found by the tick instead [0-9]+$')" = 3
    check "net: nothing left to send on any chip" "$(command_output 'net' | grep 'rtl8168: ChipCmd')" \
          test "$(command_output 'net' | grep -Ec '^       rtl8168: ChipCmd 0x0c, .*; 0 to send$')" = 3
    # (64p) the chip made to stop sending (the model's `stuck`) was reset
    # after 5 s of frames waiting, and answers pings again; the others were
    # never reset (proven by a driver without the watchdog: no reset line,
    # and the pings after it were lost)
    check "a chip that stopped sending was reset after 5 s" \
          "$(grep -a 'the chip sent nothing' <<<"$TEXT" || echo MISSING)" \
          eval 'grep -Eq "^eth0: the chip sent nothing for 5 s with [0-9]+ frame\(s\) waiting: reset" <<<"$TEXT"'
    check "pings after the reset: both answered" \
          "$(command_output 'ping -c 2 10.0.2.2' 2 | grep -- '---' || echo MISSING)" \
          eval 'command_output "ping -c 2 10.0.2.2" 2 | grep -q -- "--- 10.0.2.2: 2 sent, 2 received, 0% lost"'
    check "net: one chip reset after a send timeout, the others never" \
          "$(command_output 'net' 2 | grep 'reset after a send timeout' || echo MISSING)" \
          test "$(command_output 'net' 2 | grep -c 'rtl8168: reset after a send timeout: 1 time(s)')$(command_output 'net' 2 | grep -c 'rtl8168: reset after a send timeout: 0 time(s)')" = 12
    check "net: nothing left to send after the reset" "$(command_output 'net' 2 | grep 'rtl8168: ChipCmd')" \
          test "$(command_output 'net' 2 | grep -Ec '^       rtl8168: ChipCmd 0x0c, .*; 0 to send$')" = 3
    check "net: the RTL8168H's FIFOs set (ERI), nothing waiting" "$(command_output 'net' | grep 'rtl8168: ERI')" \
          test "$(command_output 'net' |
                  grep -Ec '^       rtl8168: ERI send FIFO 0x00020006, receive FIFO 0x00080010; .*, none waiting 0x00000000$')" = 1
    reject "the PHY does not answer"
    reject "  rtl8168:       "
    reject "panic"
    show_log_on_failure $before

    # (67a) nomodules: no module loaded, so the chip stays unused (proven by
    # a kernel that ignores the option: the card was set up).
    before=$failures
    image=$(make_image ${P}nomodules "nomodules")
    QEMU_EXTRA="-netdev user,id=net0 -device rtl8168,netdev=net0,mac=52:54:00:12:34:58,device-id=0x2600"
    boot ${P}nomodules "$image" "RitterOS kernel: boot complete"
    QEMU_EXTRA=
    expect_line "modules: not loaded: the command line says nomodules"
    reject "Realtek RTL8168H"
    reject "modules: rtl8168"
    show_log_on_failure $before
}

# drivertemplate_test: (67b) the template driver (drivers/template/),
# built outside the tree with drivers/driver.mk as another driver's author
# would, put on the disk and loaded for QEMU's PCI test device; a copy that
# says it was built for the driver interface 1.9 (its .module patched) is
# refused. Proven by a template whose table names another device (no line,
# not loaded), one calling a kernel function outside the interface (the
# build stopped) and a loader without the version check (the copy loaded).
drivertemplate_test() {
    local tpl sys image before major minor mods usbmods
    NAME=${P}template                               # (the build's check comes before the boot)
    before=$failures
    tpl="$WORK/${P}template"
    rm -rf "$tpl"
    cp -R "$ROOT/drivers/template" "$tpl"
    check "the template builds outside the tree" "its build failed: see $tpl/make.log" \
          eval 'make -C "$tpl" RITTEROS="$ROOT" ARCH=$ARCH_NAME BUILD="$tpl/build" >"$tpl/make.log" 2>&1'
    sys="$WORK/${P}system-template"
    rm -rf "$sys"
    cp -cR "$ROOT/build/system" "$sys"              # (a clone: quick)
    cp "$tpl/build/$ARCH_NAME/example.mod" "$sys/$ARCH_NAME/drivers/example.mod"
    python3 - "$tpl/build/$ARCH_NAME/example.mod" "$sys/$ARCH_NAME/drivers/newer.mod" <<'PY'
import sys
d = bytearray(open(sys.argv[1], 'rb').read())
i = d.index(b'MOD2')                    # module_info: magic, api_major, api_minor
d[i + 6:i + 8] = (9).to_bytes(2, 'little')
open(sys.argv[2], 'wb').write(d)
PY
    major=$(sed -n 's/^#define DRIVER_API_MAJOR \([0-9]*\)$/\1/p' drivers/include/driver.h)
    minor=$(sed -n 's/^#define DRIVER_API_MINOR \([0-9]*\)$/\1/p' drivers/include/driver.h)
    mods=$(ls build/system/$ARCH_NAME/drivers/*.mod | wc -l | tr -d ' ')
    image=$(make_image ${P}template "" "$sys")
    QEMU_EXTRA="-device pci-testdev"
    boot ${P}template "$image" "RitterOS kernel: boot complete"
    QEMU_EXTRA=
    compare "the template driver took the PCI test device" 1 \
            "$(grep -cE "^example: QEMU PCI test device at 00:0[0-9a-f]\.0, BAR 0 at 0x[0-9a-f]+ \([0-9]+ KB\), first register 0x[0-9a-f]{8}; driver interface $major\.$minor$" <<<"$TEXT")"
    usbmods=$(grep -l '^USB_MODULE(' drivers/*.c | wc -l | tr -d ' ')     # (67e: always loaded)
    compare "modules: example loaded, the in-tree ones not needed" 1 \
            "$(grep -cE "^modules: example \(00:0[0-9a-f]\.0\), usbnet \(no device yet\) loaded; $((mods - usbmods)) not needed$" <<<"$TEXT")"
    expect_line "modules:       newer.mod: made for the driver interface $major.9, this kernel has $major.$minor"
    reject "panic"
    show_log_on_failure $before
}

# dhcp_session: a DHCP server that comes later, a cable pulled and plugged
# in again (dhcp_shell_test).
dhcp_session() {
    local n=1 asked=0
    prompt_wait $n
    serial_wait "dhclient: eth0: no answer from a DHCP server yet" 1 30
    route_ask dhcp A on
    sleep 13                                        # dhclient asks every 10 seconds
    answer_lines '' 'net'                           # (a fresh prompt: one shown again counts as none)
    echo "set_link neta off" | nc -w 3 -U "$WORK/monitor.sock" >/dev/null 2>&1
    sleep 1
    answer_lines 'net up' 'net'
    echo "set_link neta on" | nc -w 3 -U "$WORK/monitor.sock" >/dev/null 2>&1
    sleep 4                                         # the card asks when the link comes
    answer_lines '' 'net'
    # A message between a prompt and its read (44j): a job's line while
    # askslow waits before reading; its prompt must come back.
    serial_type "/system/$ARCH_NAME/test/counter late 2 1500 &\r"
    n=$((n + 1))
    prompt_wait $n
    serial_type "/system/$ARCH_NAME/test/askslow answer? 3000\r"
    serial_wait "counter late: 2" 1 10
    sleep 2.5
    answer_lines 'yes'
    # The same while the shell's own line editor holds a typed line (44l).
    serial_type "/system/$ARCH_NAME/test/counter later 2 1500 &\r"
    n=$((n + 1))
    prompt_wait $n
    serial_type 'echo partial'
    serial_wait "counter later: 2" 1 10
    sleep 0.5                                       # (shown again by itself, before Enter)
    grep -a -A1 "counter later: 2" "$SERIAL_LOG" | tr -d '\r' >"$WORK/${P}dhcp-partial"
    answer_lines ''
}

# dhcp_shell_test: DHCP that waits for its server and its link. The card
# is on a QEMU network of its own (-netdev dgram) where host A of
# scripts/testroute.py can be a DHCP server, off at the start: net up
# (login) makes /system/config/network/eth0 (DHCP), finds no server and
# says the card asks again in the background; the server switched on, the
# card has its address within 13 seconds without anyone asking. The link
# taken away (QEMU's set_link): net up says "no link", the card has no
# address; the link back: the address comes back within seconds.
dhcp_shell_test() {
    local image before testroute address
    image=$(make_image ${P}dhcp "")
    rm -f "$WORK/${P}route-answers"
    python3 "$ROOT/scripts/testroute.py" serve $NET_ROUTE_CONTROL $NET_ROUTE_A_HOST $NET_ROUTE_A_GUEST $NET_ROUTE_B_HOST $NET_ROUTE_B_GUEST \
            >"$WORK/${P}testroute.log" 2>&1 &
    testroute=$!
    host_service_wait "$WORK/${P}testroute.log" "testroute: listening"
    QEMU_EXTRA="-netdev dgram,id=neta,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_A_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_A_HOST"
    QEMU_EXTRA+=" -device e1000,netdev=neta,mac=52:54:00:00:71:01"
    before=$failures
    SERIAL_SCRIPT=dhcp_session
    boot ${P}dhcp "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $testroute 2>/dev/null
    wait $testroute 2>/dev/null
    address="       address 192.168.71.50/24 (DHCP, lease 3600 s), gateway 192.168.71.2, DNS 192.168.71.2"
    expect_line "net: eth0: /system/config/network/eth0 made (address = dhcp)"
    # (37e-1b) net up wrote the missing routing file with its default text
    compare "/system/config/routing: written by net up, its default text" "$(settings_hash ROUTING)" \
            "$($RFS cat "$image" $RFS_PART /system/config/routing | shasum -a 256)"
    expect "dhclient: eth0: no answer from a DHCP server yet; asking again every 10 s"
    compare "the server came: an address without asking" "$address" \
            "$(command_output 'net' | grep '^       address')"
    prompt_shown_again "$WORK/${P}dhcp.log" "dhclient: eth0: 192.168.71.50/24 from"
    check "a prompt shown again after a message that came before its read" \
          "askslow's prompt not shown again: $(grep -a -A1 'counter late: 2' "$WORK/${P}dhcp.log" | cat -v | tr '\n' '|')" \
          eval 'grep -a -A1 "counter late: 2" "$WORK/${P}dhcp.log" | tr -d "\r" | grep -qx $'"'"'\e\\[0Kanswer? yes'"'"''
    expect_line "askslow: got 'yes'"
    check "the shell's own line shown again after a message" \
          "not shown again before Enter: $(cat -v "$WORK/${P}dhcp-partial" | tr '\n' '|')" \
          grep -qx $'\e\\[0Kritteros:/\\$ echo partial' "$WORK/${P}dhcp-partial"
    expect_line "partial"
    expect_line "eth0: link down"
    expect_line "eth0: link up, 1000 Mbit/s"
    expect "dhclient: eth0: no link: no address"
    compare "no link: no address" \
            "$(printf 'eth0   52:54:00:00:71:01  no link, Intel 82540EM (e1000 at 00:05.0)\n       no address (net up applies /system/config/network/eth0)')" \
            "$(command_output 'net' 2 | grep -A1 '^eth0' | sed -E 's/at [0-9a-f:.]+\)/at 00:05.0)/')"
    compare "the link back: the address back" "$address" \
            "$(command_output 'net' 3 | grep '^       address')"
    check "the address came twice (DHCP lines)" \
          "$(grep -c 'dhclient: eth0: 192.168.71.50/24 from 192.168.71.2, gateway 192.168.71.2' <<<"$TEXT") time(s)" \
          test "$(grep -c 'dhclient: eth0: 192.168.71.50/24 from 192.168.71.2, gateway 192.168.71.2' <<<"$TEXT")" = 2
    reject "panic"
    show_log_on_failure $before
}

# security_session: after the address, a command; after the attack,
# another (the shell must still answer, so the kernel did not hang).
security_session() {
    local n=1 asked=0
    prompt_wait $n
    serial_wait "dhclient: eth0: 192.168.71.50/24 from" 1 40
    serial_type 'echo before-attack\r'
    n=$((n + 1)); prompt_wait $n 20
    route_ask attack A 192.168.71.50
    serial_type 'net\r'                                 # net occurrence 1: right after the
    n=$((n + 1)); prompt_wait $n 20                      # attack, before the ping re-resolves ARP
    serial_type 'echo after-attack\r'
    n=$((n + 1)); prompt_wait $n 20
    serial_type 'ping -c 2 192.168.71.2\r'
    n=$((n + 1)); prompt_wait $n 20
    # A UDP request-reply where host A floods the flow table between the
    # request and the reply (49d): the reply arrives only if our outbound
    # flow was kept.
    serial_type "/system/$ARCH_NAME/test/sock udp 192.168.71.2 9999 floodtest\r"
    n=$((n + 1)); prompt_wait $n 30
    # FIN_WAIT_2 timeout (49e): connect to host A's responder, send, close.
    # A acks our FIN but sends none, leaving us in FIN_WAIT_2; the slot must
    # free after the timeout (net occurrence 2 shows it, occurrence 3 not).
    serial_type "/system/$ARCH_NAME/test/sock put 192.168.71.2 8888 50\r"
    n=$((n + 1)); prompt_wait $n 30
    sleep 1
    serial_type 'net\r'                                 # net occurrence 2
    n=$((n + 1)); prompt_wait $n 20
    sleep 7                                              # > FIN_WAIT2_MS (5 s)
    serial_type 'net\r'                                 # net occurrence 3
    n=$((n + 1)); prompt_wait $n 20
}

# security_shell_test: malformed packets from the LAN must not hang or
# crash the machine (49a). Host A gives the guest an address, then sends a
# SYN to port 22 with an MSS option of 0 (a zero segment size looped the
# sender forever and could divide by zero), a UDP datagram to port 53
# whose source is the guest's own address (a martian source made dnsd
# answer itself forever), and a DNS response to port 53 (dnsd answered it
# too). The guest keeps answering shell commands and pings, and net still
# prints its tcp line. Without the fixes the shell stops answering.
security_shell_test() {
    local image before testroute
    image=$(make_image ${P}security "")
    guard_rules "$image"
    rm -f "$WORK/${P}route-answers"
    python3 "$ROOT/scripts/testroute.py" serve $NET_ROUTE_CONTROL $NET_ROUTE_A_HOST $NET_ROUTE_A_GUEST $NET_ROUTE_B_HOST $NET_ROUTE_B_GUEST \
            >"$WORK/${P}testroute.log" 2>&1 &
    testroute=$!
    host_service_wait "$WORK/${P}testroute.log" "testroute: listening"
    route_ask dhcp A on
    QEMU_EXTRA="-netdev dgram,id=neta,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_A_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_A_HOST"
    QEMU_EXTRA+=" -device e1000,netdev=neta,mac=52:54:00:00:71:01"
    before=$failures
    SERIAL_SCRIPT=security_session
    boot ${P}security "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $testroute 2>/dev/null
    wait $testroute 2>/dev/null
    expect_line "before-attack"
    check "the attack packets were sent" "$(grep -h attack "$WORK/${P}route-answers" 2>/dev/null)" \
          eval 'grep -q "mss=0" "$WORK/${P}route-answers"'
    # A reply must not wait for ARP in the receive thread (49c): a ping from
    # an on-link source we never answer ARP for is answered at once, because
    # the guest learned the sender's MAC from the frame (without the fix it
    # blocks ~1.5 s and drops the reply, so "answered" never appears).
    check "a reply to an on-link source goes out without waiting for ARP (49c)" \
          "$(grep -h "spoofed-source ping" "$WORK/${P}route-answers" 2>/dev/null || echo MISSING)" \
          eval 'grep -q "spoofed-source ping to the guest: answered" "$WORK/${P}route-answers"'
    # The machine survived: the shell answered after the attack.
    expect_line "after-attack"
    # Anti-smurf (49g): a ping to a broadcast address is not answered.
    check "a broadcast ping is not answered (anti-smurf, 49g)" \
          "$(grep -h "broadcast ping" "$WORK/${P}route-answers" 2>/dev/null || echo MISSING)" \
          eval 'grep -q "broadcast ping to 192.168.71.255: not answered" "$WORK/${P}route-answers"'
    # ICMP still works after the attack: the guest pings its gateway (host A).
    expect "--- 192.168.71.2: 2 sent, 2 received, 0% lost"
    # Sticky ARP (49g): a spoofed gratuitous ARP did not replace host A's
    # learned MAC; net still shows the real one, not de:ad:be:ef:00:01.
    check "a spoofed ARP does not overwrite a learned MAC (sticky ARP, 49g)" \
          "$(command_output 'net' | grep '^arp: 192.168.71.2' || echo MISSING)" \
          eval 'command_output "net" | grep -qE "^arp: 192.168.71.2 +is 02:00:00:00:71:02" &&
                ! command_output "net" | grep -qi "de:ad:be:ef"'
    # The firewall keeps the machine's own outbound flow through a flood of
    # inbound flows (49d): the reply to the guest's UDP request gets back
    # (without the fix the flood evicts the outbound flow and it times out).
    expect_line "sock: answer from 192.168.71.2:9999: 'flood-survived'"
    check "net still works after the attack (its tcp line)" \
          "$(command_output 'net' | grep '^tcp:' || echo MISSING)" \
          eval 'command_output "net" | grep -q "^tcp:"'
    # SYN cookies (49f): 40 SYNs with no final ACK leave no half-open
    # connections (without cookies the table fills with "SYN received").
    check "a SYN flood leaves no half-open connections (SYN cookies, 49f)" \
          "$(command_output 'net' | grep '^tcp:' || echo MISSING)" \
          eval 'command_output "net" | grep -q "^tcp:" && ! command_output "net" | grep -q "SYN received"'
    # RFC 5961 (49e): a segment on the four-tuple with an in-window sequence
    # but a bogus ACK must not slip its data in (challenge ACK instead).
    check "a bad-ACK data injection is rejected (RFC 5961, 49e)" \
          "$(grep -h "bad-ACK data injection" "$WORK/${P}route-answers" 2>/dev/null || echo MISSING)" \
          eval 'grep -q "bad-ACK data injection on tcp 22: rejected" "$WORK/${P}route-answers"'
    # FIN_WAIT_2 timeout (49e): a connection whose peer never sends its FIN
    # is in FIN_WAIT_2 (net 2) and then freed by the timeout (net 3).
    check "a FIN_WAIT_2 connection is present before the timeout (49e)" \
          "$(command_output 'net' 2 | grep '^tcp:' || echo MISSING)" \
          eval 'command_output "net" 2 | grep -q "FIN wait"'
    check "a FIN_WAIT_2 connection is freed after the timeout (49e)" \
          "$(command_output 'net' 3 | grep '^tcp:' || echo MISSING)" \
          eval 'command_output "net" 3 | grep -q "^tcp:" && ! command_output "net" 3 | grep -q "FIN wait"'
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# guard_rules IMAGE RULE...: the firewall's file on IMAGE, as guardd's
# first start makes it (ping, sshd, dnsd let in), and RULE... after it.
guard_rules() {
    local image="$1"
    shift
    { printf 'in = drop\nout = allow\nallow in icmp\nallow in tcp 22\nallow in udp 53\n'
      printf '%s\n' "$@"; } >"$WORK/${P}guard-rules"
    $RFS put "$image" $RFS_PART /system/config/guard "$WORK/${P}guard-rules" >/dev/null || exit 1
}

# guard_client N: the Mac connects to the guest's port 7000 (sock serve,
# through QEMU's hostfwd); what it got into ${P}guardclient-N.log.
guard_client() {
    python3 "$ROOT/scripts/testnet.py" client $NET_FORWARD_PORT "hello-guard-$1" \
            >"$WORK/${P}guardclient-$1.log" 2>&1
}

# guard_session: the firewall's kernel half (guard_shell_test).
guard_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test" f=/home/root/g
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    answer_lines "echo 'in = drop' > ${f}a" "echo 'allow in icmp' >> ${f}a" \
                 "echo 'allow in tcp 7000 from 10.0.2.0/24 on eth0   # the Mac' >> ${f}a" \
                 "$t/guardload ${f}a" 'ping -c 2 10.0.2.2' "$t/sock serve 7000 &"
    sleep 1
    guard_client 1
    # Nobody listens now: a closed port would answer "refused" at once (an
    # empty answer), a dropped one never answers.
    answer_lines '' "echo 'in = drop' > ${f}b" "echo 'allow in icmp' >> ${f}b" "$t/guardload ${f}b"
    guard_client 2                                  # (dropped: it waits 20 s for nothing)
    answer_lines '' "$t/guardload status" "echo 'drop out icmp to 10.0.2.2' > ${f}c" \
                 "$t/guardload ${f}c" 'ping -c 1 10.0.2.2' "$t/guardload off" "$t/sock serve 7000 &"
    sleep 1
    guard_client 3
    answer_lines '' "echo 'allow sideways' > ${f}x" "$t/guardload ${f}x" \
                 "echo 'allow in 22' > ${f}x" "$t/guardload ${f}x" \
                 "echo 'limit in tcp 22 10/hour' > ${f}x" "$t/guardload ${f}x" \
                 "echo 'allow in udp 6000-6010 to 10.0.2.15 on eth1' > ${f}x" "$t/guardload ${f}x" \
                 "echo 'limit in tcp 22 from 10.0.2.0/24 5/minute' > ${f}x" "$t/guardload ${f}x" \
                 "$t/guardload off" \
                 "echo 'allow in tcp 9999 on wlan0' > ${f}w" "echo 'allow forward in wlan1 out eth0' >> ${f}w" \
                 "$t/guardload ${f}w" "$t/guardload status" "$t/guardload off"
}

# guard_shell_test: the firewall in the kernel (45a), with the test
# program guardload: in = drop with rules letting ping and the Mac (port
# 7000, from 10.0.2.0/24 on eth0) in; the replies to the machine's own
# ping pass; without the rule the Mac's connection is dropped (the drop
# recorded, counted by the default); drop out stops a ping leaving
# (Operation not permitted); off lets the waiting connection in; rules
# read back in words, wrong ones explained.
guard_shell_test() {
    local image before t="/system/$ARCH_NAME/test" f=/home/root/g
    image=$(make_image ${P}guard "")
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_FORWARD_PORT-:7000"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=guard_session
    boot ${P}guard "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    want_text want <<'LINES'
guardload: 2 rule(s), in = drop, out = allow
  1: allow in icmp
  2: allow in tcp 7000 from 10.0.2.0/24 on eth0
LINES
    compare "rules loaded and read back in words" "$want" "$(command_output "$t/guardload ${f}a")"
    expect "--- 10.0.2.2: 2 sent, 2 received, 0% lost"   # replies to our own pings came in
    compare "the rule let the Mac in" "client: answer: HELLO-GUARD-1" \
            "$(grep '^client:' "$WORK/${P}guardclient-1.log")"
    check "without the rule the Mac's connection is dropped (no answer, not even refused)" \
          "$(tr '\n' '|' <"$WORK/${P}guardclient-2.log")" \
          eval '! grep -q "^client: answer" "$WORK/${P}guardclient-2.log" &&
                grep -q "timed out" "$WORK/${P}guardclient-2.log"'
    check "status: the drop by the default, recorded" "$(command_output "$t/guardload status" | tr '\n' '|')" \
          eval 'command_output "$t/guardload status" | grep -q "^state on, in = drop, out = allow, 1 rule(s)$" &&
                command_output "$t/guardload status" | grep -Eq "^1: allow in icmp: [0-9]+ packet\(s\)$" &&
                command_output "$t/guardload status" | grep -Eq "^defaults: in 0 allowed, [1-9][0-9]* dropped; out [0-9]+ allowed, 0 dropped; connections [0-9]+$" &&
                command_output "$t/guardload status" | grep -q "^dropped: in tcp 7000 from 10.0.2.2 to 10.0.2.15 on eth0 (default)$"'
    expect_line "seq=1: Operation not permitted"    # drop out icmp to 10.0.2.2
    compare "off: the Mac gets in again" "client: answer: HELLO-GUARD-3" \
            "$(grep '^client:' "$WORK/${P}guardclient-3.log")"
    # (50k) Wi-Fi cards in rules: read, loaded and written back as wlanN
    check "rules name wlanN cards" "$(command_output "$t/guardload status" 2 | tr '\n' '|')" \
          eval 'command_output "$t/guardload status" 2 | grep -Eq "^1: allow in tcp 9999 on wlan0: 0 packet\(s\)$" &&
                command_output "$t/guardload status" 2 | grep -Eq "^2: allow forward in wlan1 out eth0: 0 packet\(s\)$"'
    expect_line "guardload: ${f}x: line 1: 'sideways': in, out or forward is missing"
    expect_line "guardload: ${f}x: line 1: '22': a port needs tcp or udp"
    expect_line "guardload: ${f}x: line 1: '10/hour': limit needs N/minute at the end (like limit in tcp 22 10/minute)"
    expect_line "  1: allow in udp 6000-6010 to 10.0.2.15 on eth1"
    expect_line "  1: limit in tcp 22 from 10.0.2.0/24 5/minute"
    reject "panic"
    show_log_on_failure $before
}

# guardd_session: the firewall's elf (guardd_shell_test).
guardd_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test" f=/system/config/guard
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    answer_lines "cat $f" "echo 'allow in tcp 7000   # sock serve' >> $f"
    serial_wait "guardd: 4 rule(s) loaded" 1 15
    answer_lines '' "$t/sock serve 7000 &"
    sleep 1
    guard_client 1
    answer_lines '' "echo 'allow sideways' >> $f"
    serial_wait "the rules loaded before stay" 1 15
    answer_lines '' "$t/sock serve 7000 &"
    sleep 1
    guard_client 2                                  # the rules loaded before let it in
    # The file as guardd made it (no 7000), nobody listening: dropped.
    answer_lines '' "echo 'in = drop' > $f" "echo 'allow in icmp' >> $f" \
                 "echo 'allow in tcp 22' >> $f" "echo 'allow in udp 53' >> $f"
    serial_wait "guardd: 3 rule(s) loaded" 2 15
    guard_client 3
    answer_lines '' 'elf stop guardd'
    serial_wait "guardd: switched off: nothing is checked now" 1 15
    guard_client 4                                  # (nobody listens: refused, at once)
    answer_lines '' "$t/guardload status" 'guard' 'net up' 'elf start guardd'
    serial_wait "guardd: 3 rule(s) loaded" 3 15
    answer_lines '' "$t/guardload status"
    # The command guard (45e).
    answer_lines 'guard' 'guard add allow in tcp 7000'
    serial_wait "guardd: 4 rule(s) loaded" 2 15
    answer_lines '' "$t/sock serve 7000 &"
    sleep 1
    guard_client 5
    answer_lines '' 'guard insert 1 drop in tcp 7000 from 10.0.2.0/24'
    serial_wait "guardd: 5 rule(s) loaded" 1 15
    guard_client 6                                  # (dropped by rule 1: nobody listens now)
    answer_lines '' 'guard' 'guard remove 1' 'guard in allow' 'guard add allow sideways' \
                 'guard remove 9' 'guard insert 0 allow in icmp'
    serial_wait "guardd: 4 rule(s) loaded (in = allow" 1 15
    answer_lines '' "cat $f"
}

# guardd_shell_test: the firewall's elf (45d): net up makes its elf file,
# its first start the rules (ping, sshd and dnsd let in) and loads them; a
# rule added to the file is loaded within seconds and lets the Mac in; a
# wrong line is named and the rules before stay; without the rule the
# Mac's connection is dropped (a timeout); elf stop guardd switches the
# checks off (a closed port refuses again; net up says so); started again
# it loads the rules.
guardd_shell_test() {
    local image before t="/system/$ARCH_NAME/test"
    image=$(make_image ${P}guardd "")
    rm -f "$WORK/${P}"guardclient-*.log
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_FORWARD_PORT-:7000"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=guardd_session
    boot ${P}guardd "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect_line "net: /system/config/elves/guardd made: the elf guardd loads the rules of /system/config/guard"
    expect_line "guardd: /system/config/guard made: in = drop, out = allow; let in: icmp, tcp 22 (sshd), udp 53 (dnsd)"
    expect_line "guardd: 3 rule(s) loaded (in = drop, out = allow)"
    want_text want <<'LINES'
# The firewall's rules (guardd made this file; see the manual, "guard").
# Read top to bottom: the first rule that matches a packet decides; the
# replies to the machine's own connections always pass.
in = drop
out = allow
allow in icmp                # ping
allow in tcp 22              # sshd
allow in udp 53              # dnsd
LINES
    compare "the rules guardd made" "$want" "$(command_output 'cat /system/config/guard')"
    compare "a rule added: the Mac gets in" "client: answer: HELLO-GUARD-1" \
            "$(grep '^client:' "$WORK/${P}guardclient-1.log")"
    expect_line "guardd: /system/config/guard: line 10: 'sideways': in, out or forward is missing; the rules loaded before stay"
    compare "a wrong line: the rules before stay" "client: answer: HELLO-GUARD-2" \
            "$(grep '^client:' "$WORK/${P}guardclient-2.log")"
    check "the rule gone: the Mac's connection dropped (a timeout)" \
          "$(tail -1 "$WORK/${P}guardclient-3.log")" \
          eval '! grep -q "^client: answer" "$WORK/${P}guardclient-3.log" &&
                grep -q "timed out" "$WORK/${P}guardclient-3.log"'
    expect_line "guardd: switched off: nothing is checked now"
    check "switched off: a closed port refuses again" "$(tail -1 "$WORK/${P}guardclient-4.log")" \
          grep -q "reset\|refused" "$WORK/${P}guardclient-4.log"
    check "the kernel: off, then on again" \
          "$(command_output "$t/guardload status" | head -1) / $(command_output "$t/guardload status" 2 | head -1)" \
          eval '[ "$(command_output "$t/guardload status" | head -1)" = "state off, in = drop, out = allow, 3 rule(s)" ] &&
                [ "$(command_output "$t/guardload status" 2 | head -1)" = "state on, in = drop, out = allow, 3 rule(s)" ]'
    expect_line "net: the firewall checks nothing (the elf guardd is off)"
    # guard
    compare "guard while off" "firewall: off: nothing is checked (the elf guardd is off)" \
            "$(command_output guard | head -1)"
    check "guard: the state, the rules with their counters, the defaults" \
          "$(command_output guard 2 | head -6 | tr '\n' '|')" \
          eval '[ "$(command_output guard 2 | head -1)" = "firewall: on; in = drop, out = allow, forward = drop" ] &&
                command_output guard 2 | grep -Eq "^  1  allow in icmp +[0-9]+ packet\(s\)$" &&
                command_output guard 2 | grep -Eq "^  3  allow in udp 53 +[0-9]+ packet\(s\)$" &&
                command_output guard 2 | grep -Eq "^     in = drop \(no rule matched\) +[0-9]+ packet\(s\)$"'
    expect_line "guard: rule 4: allow in tcp 7000; guardd loads it within 2 s"
    compare "guard add: the Mac gets in" "client: answer: HELLO-GUARD-5" \
            "$(grep '^client:' "$WORK/${P}guardclient-5.log")"
    expect_line "guard: rule 1: drop in tcp 7000 from 10.0.2.0/24; guardd loads it within 2 s"
    check "guard insert 1: a drop rule first: dropped" "$(tail -1 "$WORK/${P}guardclient-6.log")" \
          grep -q "timed out" "$WORK/${P}guardclient-6.log"
    check "guard: rule 1 counted it, the drop listed with its rule" "$(command_output guard 3 | tr '\n' '|')" \
          eval 'command_output guard 3 | grep -Eq "^  1  drop in tcp 7000 from 10.0.2.0/24 +[1-9][0-9]* packet\(s\)$" &&
                command_output guard 3 | grep -Eq "^  [0-9-]{10} [0-9:]{8}  in tcp 7000 from 10.0.2.2 to 10.0.2.15 on eth0 \(rule 1\)$"'
    expect_line "guard: rule 1 removed; guardd loads the rules within 2 s"
    expect_line "guard: in = allow; guardd loads it within 2 s"
    expect_line "guard: 'sideways': in, out or forward is missing"
    expect_line "guard: 9: no such rule (there are 4)"
    expect_line "guard: 0: no such rule (there are 4)"
    check "the file: in = allow in place, rule 1 gone, the new rule at the end" \
          "$(command_output "cat /system/config/guard" 2 | tr '\n' '|')" \
          eval 'command_output "cat /system/config/guard" 2 | grep -qx "in = allow" &&
                ! command_output "cat /system/config/guard" 2 | grep -q "drop in tcp 7000" &&
                [ "$(command_output "cat /system/config/guard" 2 | tail -1)" = "allow in tcp 7000" ]'
    reject "panic"
    show_log_on_failure $before
}

# guardlimit_session: limit (guardlimit_shell_test).
guardlimit_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test"
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    for i in 1 2; do
        answer_lines "$t/sock serve 7000 &"
        sleep 1
        guard_client $i
        answer_lines ''
    done
    guard_client 3                                  # the third in a minute: dropped
    answer_lines 'guard'
    sleep 50                                        # (a minute after the first)
    answer_lines "$t/sock serve 7000 &"
    sleep 1
    guard_client 4
    answer_lines ''
}

# guardlimit_shell_test: "limit in tcp 7000 2/minute" (45f): the Mac's
# first two connections in a minute get in, the third is dropped (a
# timeout; nobody listens, a closed port would refuse), guard shows the
# rule and the drop; a minute after the first, one gets in again.
guardlimit_shell_test() {
    local image before
    image=$(make_image ${P}guardlimit "")
    guard_rules "$image" 'limit in tcp 7000 2/minute'
    rm -f "$WORK/${P}"guardclient-*.log
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_FORWARD_PORT-:7000"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=guardlimit_session
    boot ${P}guardlimit "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    compare "limit: the first connection" "client: answer: HELLO-GUARD-1" \
            "$(grep '^client:' "$WORK/${P}guardclient-1.log")"
    compare "limit: the second" "client: answer: HELLO-GUARD-2" \
            "$(grep '^client:' "$WORK/${P}guardclient-2.log")"
    check "limit: the third in a minute dropped (a timeout)" "$(tail -1 "$WORK/${P}guardclient-3.log")" \
          eval '! grep -q "^client: answer" "$WORK/${P}guardclient-3.log" &&
                grep -q "timed out" "$WORK/${P}guardclient-3.log"'
    check "guard: the limit rule, the drop by it" "$(command_output guard | tr '\n' '|')" \
          eval 'command_output guard | grep -Eq "^  4  limit in tcp 7000 2/minute +[0-9]+ packet\(s\)$" &&
                command_output guard | grep -Eq "  in tcp 7000 from 10.0.2.2 to 10.0.2.15 on eth0 \(rule 4\)$"'
    compare "limit: a minute later, in again" "client: answer: HELLO-GUARD-4" \
            "$(grep '^client:' "$WORK/${P}guardclient-4.log")"
    reject "panic"
    show_log_on_failure $before
}

# elves_client N: the Mac connects to the guest's port 7000 (the elf
# hello, through QEMU's hostfwd); the answer into ${P}elfclient-N.log.
elves_client() {
    python3 "$ROOT/scripts/testnet.py" client $NET_FORWARD_PORT "hello-elf-$1" \
            >"$WORK/${P}elfclient-$1.log" 2>&1
}

# elves_session: the elves (elves_shell_test).
elves_session() {
    local n=1 asked=0
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    serial_wait "elvesd: hello started" 1 20
    answer_lines '' 'elf'                           # (a fresh prompt after elvesd's lines)
    elves_client 1
    serial_wait "elvesd: hello ended (exit code 0)" 1 20
    serial_wait "elvesd: hello started" 2 20
    elves_client 2
    serial_wait "elvesd: hello started" 3 30
    answer_lines '' 'elf restart hello'
    serial_wait "elvesd: hello ended (signal 15)" 1 20
    serial_wait "elvesd: hello started" 4 20
    answer_lines '' 'elf add crash false'
    serial_wait "elvesd: crash ended (exit code 1); starting it again in 4 s" 1 30
    answer_lines '' 'elf remove crash' 'elf stop hello'
    serial_wait "elvesd: hello stopped" 1 20
    sleep 3
    answer_lines '' 'elf' 'ps' 'cat /system/config/elves/hello' 'elf start nobody'
    elves_client 3
    # Someone else than root may look, not change.
    serial_type 'useradd anna\r'
    n=$((n + 1)); prompt_wait $n
    serial_type 'passwd anna\r'
    serial_wait "New password: " 1
    serial_type 'anna-pw-1\r'
    serial_wait "Again: " 1
    serial_type 'anna-pw-1\r'
    n=$((n + 1)); prompt_wait $n 30
    serial_type 'exit\r'
    login_wait 2
    serial_type 'anna\r'
    serial_wait "Password: " 2
    serial_type 'anna-pw-1\r'
    serial_wait "[anna logged in]" 1 30
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'elf start hello' 'elf'
}

# elves_shell_test: elves, the programs elvesd keeps running. The image
# has /system/config/elves/hello (sock serve 7000: it answers one
# connection, then ends); its machine an e1000 with QEMU's hostfwd to port
# 7000. login starts elvesd, which starts hello; elf lists it; the Mac
# reaches it; it ends after each answer and elvesd starts it again; elf
# restart (its process ended by SIGTERM, started again); an elf that ends
# at once (false) is started again after growing waits, elf remove takes
# it away; elf stop: start = off in its file, the process gone (ps), the
# Mac refused; a name nobody has; anna (not root) may list, not change.
elves_shell_test() {
    local image before t="/system/$ARCH_NAME/test/sock"
    image=$(make_image ${P}elves "")
    guard_rules "$image" 'allow in tcp 7000'          # (the Mac reaches the elf hello)
    printf 'command = %s serve 7000\nstart = on\n' "$t" >"$WORK/${P}hello"
    $RFS put "$image" $RFS_PART /system/config/elves/hello "$WORK/${P}hello" >/dev/null || exit 1
    rm -f "$WORK/${P}"elfclient-*.log
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_FORWARD_PORT-:7000"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=elves_session
    boot ${P}elves "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "elvesd: hello started (process "
    check "elf: elvesd and hello running" "$(command_output 'elf')" \
          eval 'command_output elf | grep -q "^elvesd: running (process [0-9]*)$" &&
                command_output elf | grep -Eq "^hello +on +running \(process [0-9]+\) +$t serve 7000$"'
    compare "the Mac reaches the elf" "client: answer: HELLO-ELF-1" "$(cat "$WORK/${P}elfclient-1.log")"
    expect "elvesd: hello ended (exit code 0); starting it again in 2 s"
    compare "and again after it was started again" "client: answer: HELLO-ELF-2" \
            "$(cat "$WORK/${P}elfclient-2.log")"
    expect "elf: hello: process "
    expect " ended (elvesd starts it again)"
    expect "elvesd: hello ended (signal 15); starting it again in "
    expect "elvesd: crash ended (exit code 1); starting it again in 2 s"
    expect "elvesd: crash ended (exit code 1); starting it again in 4 s"
    expect_line "elf: crash removed (elvesd stops it within 2 s)"
    expect_line "elf: hello off (elvesd stops it within 2 s)"
    expect "elvesd: hello stopped"
    check "elf: hello off and not running, crash gone" "$(command_output 'elf' 2)" \
          eval 'command_output elf 2 | grep -Eq "^hello +off +not running +$t serve 7000$" &&
                ! command_output elf 2 | grep -q "^crash"'
    check "ps: no sock any more" "$(command_output 'ps')" \
          eval '! command_output ps | grep -q " sock$"'
    want_text want <<'LINES'
command = SOCK serve 7000
start = off
LINES
    compare "the file says off" "${want/SOCK/$t}" "$(command_output 'cat /system/config/elves/hello')"
    expect_line "elf: nobody: no such elf"
    check "the Mac gets no answer (nobody listens)" "$(cat "$WORK/${P}elfclient-3.log")" \
          eval '! grep -q "HELLO-ELF-3" "$WORK/${P}elfclient-3.log"'
    expect_line "elf: start: only root may change the elves"
    check "anna may list" "$(command_output 'elf' 3)" \
          eval 'command_output elf 3 | grep -Eq "^hello +off +not running"'
    reject "panic"
    show_log_on_failure $before
}

# route_ask WORDS...: a command for scripts/testroute.py (its hosts A and
# B); the answer goes to $WORK/${P}route-answers.
route_ask() {
    python3 "$ROOT/scripts/testroute.py" ask $NET_ROUTE_CONTROL "$@" >>"$WORK/${P}route-answers"
}

# route_session: routing between two cards (route_shell_test).
route_session() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines 'net'
    route_ask ping A 192.168.72.2                   # forwarding off: dropped
    route_ask ping A 192.168.72.1                   # the router's address on the other card
    answer_lines 'net forward on'
    route_ask ping A 192.168.72.2                   # forwarded (the router asks ARP for B first)
    route_ask ping B 192.168.71.2                   # the other way
    route_ask ping A 8.8.4.4                        # by the default route, to B
    route_ask ping A 192.168.72.2 1                 # TTL 1: time exceeded
    answer_lines 'guard'                            # the forward chain decided the forwards (49h)
    answer_lines 'net masquerade eth0'              # mark A's side private: source NAT (49i)
    route_ask ping A 192.168.72.2                   # masqueraded: B sees the router's eth1 source
    answer_lines 'net masquerade off'
    answer_lines 'ping -c 1 192.168.71.2' 'ping -c 1 8.8.8.8' 'net' \
                 "echo 'address = 192.168.72.1/24' > /system/config/network/eth1" \
                 "echo 'forward = on' > /system/config/routing" 'net up'
    route_ask ping A 10.9.9.9                       # no default route now: unreachable
    answer_lines 'net forward off' 'net forward'
    route_ask ping A 192.168.72.2                   # off again
    answer_lines 'net'
}

# ipv6_session: IPv6 on the link (ipv6_test).
ipv6_session() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines 'sleep 3'                          # the duplicate checks (at most 2 s after the link)
    route_ask ping6 A fe80::5054:ff:fe00:7101       # A asks the guest's group: multicast reaches it
    route_ask ping6 A ff02::1                       # a group's echo: not answered (no amplifier)
    # (typed through printf: %% is one %)
    answer_lines 'net' 'ping -c 2 fe80::ff:fe00:7102%%eth0' 'ping -c 1 ::1' \
                 'ping -c 1 fe80::5054:ff:fe00:7101%%eth0' 'ping -c 1 ff02::1%%eth0' \
                 'ping -c 1 fe80::ff:fe00:7102' 'ping -c 1 fe80::ff:fe00:7102%%eth9' \
                 'ping -c 1 fe80::5054:ff:fe00:7201%%eth1' 'ping -c 1 fe80::1:2:3%%eth0'
    route_ask mldquery A
    answer_lines 'net'
}

# ipv6_test [CARD] (64a): IPv6 on the link. eth0 (CARD: an e1000, or
# rtl8168, our model of the laptop's RTL8168H) and eth1 (an 82576, igb)
# are on two QEMU networks of their own with testroute.py's
# hosts A and B, which speak IPv6 too. When the links come up each card
# checks its link-local address (fe80:: + its MAC as an EUI-64) for
# duplicates: an MLD report of its solicited-node group from ::, then a
# solicitation from ::; B claims eth1's, so eth1 reports the duplicate
# (B's answer to ff02::1 passed the igb's filter) and never uses it. A
# finds the guest by a solicitation to its group (the stack asked eth0 for
# its groups, net_set_multicast, and its driver set the chip's filter:
# proven by drivers whose filter was left empty) and gets
# its echo answered; a group's echo is not answered. The guest pings A
# (twice), ::1, its own address (the loopback), ff02::1 (answered by A);
# a link-local address without its card, an unknown card, eth1's own
# duplicate and a neighbour nobody has are refused or unanswered. An MLD
# query gets the report again; net shows the addresses and neighbours.
ipv6_test() {
    local card=${1:-e1000} image before testroute name=${P}ipv6
    [ "$card" = e1000 ] || name=${P}ipv6-$card
    image=$(make_image $name "")
    printf 'address = 192.168.71.1/24\n' >"$WORK/${P}eth0"
    printf 'address = 192.168.72.1/24\n' >"$WORK/${P}eth1"
    $RFS put "$image" $RFS_PART /system/config/network/eth0 "$WORK/${P}eth0" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /system/config/network/eth1 "$WORK/${P}eth1" >/dev/null || exit 1
    rm -f "$WORK/${P}route-answers"
    python3 "$ROOT/scripts/testroute.py" serve $NET_ROUTE_CONTROL $NET_ROUTE_A_HOST $NET_ROUTE_A_GUEST $NET_ROUTE_B_HOST $NET_ROUTE_B_GUEST \
            >"$WORK/${P}testroute.log" 2>&1 &
    testroute=$!
    host_service_wait "$WORK/${P}testroute.log" "testroute: listening"
    route_ask claim6 B fe80::5054:ff:fe00:7201      # eth1's address: B has it
    QEMU_EXTRA="-netdev dgram,id=neta,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_A_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_A_HOST"
    QEMU_EXTRA+=" -device $card,netdev=neta,mac=52:54:00:00:71:01"
    QEMU_EXTRA+=" -netdev dgram,id=netb,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_B_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_B_HOST"
    QEMU_EXTRA+=" -device pcie-root-port,id=portb,chassis=2,slot=2"
    QEMU_EXTRA+=" -device igb,netdev=netb,mac=52:54:00:00:72:01,bus=portb"
    before=$failures
    SERIAL_SCRIPT=ipv6_session
    boot $name "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $testroute 2>/dev/null
    wait $testroute 2>/dev/null
    local log="$WORK/${P}testroute.log"
    check "A sees eth0's duplicate check" "$(grep 'duplicate check' "$log")" \
          grep -q "^A: NDP: duplicate check for fe80::5054:ff:fe00:7101, hop limit 255$" "$log"
    check "the group was reported first, from ::" "$(grep 'MLD' "$log")" \
          grep -q "^A: MLD report from ::, hop limit 1: ff02::1:ff00:7101$" "$log"
    check "B defends eth1's address" "$(grep '^B: NDP' "$log")" \
          grep -q "^B: NDP: fe80::5054:ff:fe00:7201 is ours: told everyone$" "$log"
    expect_line "eth1: IPv6 address fe80::5054:ff:fe00:7201 is used by another machine (02:00:00:00:72:02); not used"
    want_text want <<'LINES'
B: defends fe80::5054:ff:fe00:7201
A to fe80::5054:ff:fe00:7101: answered by fe80::5054:ff:fe00:7101, hop limit 64
A to ff02::1: no answer
A: MLD report from fe80::5054:ff:fe00:7101: ff02::1:ff00:7101
LINES
    compare "A and the guest" "$want" "$(cat "$WORK/${P}route-answers")"
    want_text want <<'LINES'
       IPv6 ::1/128
       IPv6 fe80::5054:ff:fe00:7101/64 (link-local)
       IPv6 fe80::5054:ff:fe00:7201/64 (link-local, used by another machine: not used)
LINES
    compare "net: the IPv6 addresses" "$want" "$(command_output 'net' | grep 'IPv6')"
    check "net: A among the neighbours" "$(command_output 'net' 2 | grep '^ndp:')" \
          eval 'command_output net 2 | grep -qx "ndp: fe80::ff:fe00:7102%eth0 is 02:00:00:00:71:02"'
    expect "64 bytes from fe80::ff:fe00:7102%eth0: seq=2 time="
    expect "--- fe80::ff:fe00:7102%eth0: 2 sent, 2 received, 0% lost"
    expect "--- ::1: 1 sent, 1 received, 0% lost"
    expect "--- fe80::5054:ff:fe00:7101%eth0: 1 sent, 1 received, 0% lost"
    expect "--- ff02::1%eth0: 1 sent, 1 received, 0% lost"
    expect_line "ping: fe80::ff:fe00:7102: a link-local address needs its card (ADDRESS%eth0)"
    expect_line "ping: fe80::ff:fe00:7102%eth9: no such card"
    expect "--- fe80::5054:ff:fe00:7201%eth1: 1 sent, 0 received, 100% lost"
    expect "--- fe80::1:2:3%eth0: 1 sent, 0 received, 100% lost"
    check "A answered the guest's echo to ff02::1" "$(grep 'echo request' "$log")" \
          grep -q "^A: ICMPv6 echo request from fe80::5054:ff:fe00:7101 to ff02::1: answered$" "$log"
    reject "panic"
    show_log_on_failure $before
}

# slaac_session: addresses from the network's router (slaac_test).
slaac_session() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines 'sleep 4'                          # routers asked, the router's prefix checked
    route_ask router6 B 2001:db8:79::/64 1800       # an advertisement eth1 (fixed) must not take
    answer_lines 'sleep 2' 'net' 'ping -c 1 2001:db8:71::ff:fe00:7102' 'ping -c 1 2001:db8:99::1' \
                 'ping -c 1 2001:db8:72::2'
    route_ask ping6 A 2001:db8:71::5054:ff:fe00:7101
    route_ask ra6 A 2001:db8:73::/64 6 5            # a prefix for 6 seconds
    answer_lines 'sleep 2' 'net' 'sleep 6' 'net'
    route_ask router6 A off                         # router lifetime 0: eth1's gateway now
    answer_lines 'sleep 1' 'net' 'ping -c 1 2001:db8:99::1' \
                 "echo 'address = 192.168.72.1/24' > /system/config/network/eth1" \
                 "echo 'address6 = off' >> /system/config/network/eth1" 'net up' 'net' \
                 'ping -c 1 2001:db8:99::1'
}

# slaac_test (64b): addresses from the network's router. eth0 (an e1000)
# on host A's network: A is its router (testroute.py router6: the prefix
# 2001:db8:71::/64, a DNS server and an MTU of 1400); eth1 (an 82576) has
# fixed IPv6 settings (address6, gateway6 = B, dns6) and takes no
# advertisement, though B advertises 2001:db8:79::/64 too. With its
# link-local address in use the card asks the routers, makes its address
# from A's prefix (checked for duplicates) and takes the router, DNS
# server and MTU; net shows them and the routes (route6:). The guest
# pings A on the link, an address beyond it (by A, the default router)
# and B on eth1's fixed network; A pings the guest's new address. A
# second prefix for 6 seconds comes and goes; A stops being a router
# (lifetime 0) and the default route goes to eth1's gateway (B answers);
# address6 = off on eth1 (net up): no IPv6 there, and no route beyond.
slaac_test() {
    local image before testroute log
    image=$(make_image ${P}slaac "")
    printf 'address = 192.168.71.1/24\n' >"$WORK/${P}eth0"
    printf 'address = 192.168.72.1/24\naddress6 = 2001:db8:72::1/64\ngateway6 = 2001:db8:72::2\ndns6 = 2001:db8:72::53\n' \
           >"$WORK/${P}eth1"
    $RFS put "$image" $RFS_PART /system/config/network/eth0 "$WORK/${P}eth0" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /system/config/network/eth1 "$WORK/${P}eth1" >/dev/null || exit 1
    rm -f "$WORK/${P}route-answers"
    python3 "$ROOT/scripts/testroute.py" serve $NET_ROUTE_CONTROL $NET_ROUTE_A_HOST $NET_ROUTE_A_GUEST $NET_ROUTE_B_HOST $NET_ROUTE_B_GUEST \
            >"$WORK/${P}testroute.log" 2>&1 &
    testroute=$!
    host_service_wait "$WORK/${P}testroute.log" "testroute: listening"
    route_ask router6 A 2001:db8:71::/64 1800 dns 2001:db8:71::53 mtu 1400
    route_ask addr6 B 2001:db8:72::2
    QEMU_EXTRA="-netdev dgram,id=neta,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_A_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_A_HOST"
    QEMU_EXTRA+=" -device e1000,netdev=neta,mac=52:54:00:00:71:01"
    QEMU_EXTRA+=" -netdev dgram,id=netb,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_B_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_B_HOST"
    QEMU_EXTRA+=" -device pcie-root-port,id=portb,chassis=2,slot=2"
    QEMU_EXTRA+=" -device igb,netdev=netb,mac=52:54:00:00:72:01,bus=portb"
    before=$failures
    SERIAL_SCRIPT=slaac_session
    boot ${P}slaac "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $testroute 2>/dev/null
    wait $testroute 2>/dev/null
    log="$WORK/${P}testroute.log"
    check "A was asked for router advertisements" "$(grep 'router solicitation' "$log")" \
          grep -q "^A: NDP: router solicitation from fe80::5054:ff:fe00:7101, hop limit 255$" "$log"
    expect_line "net: eth1: IPv6 2001:db8:72::1/64, gateway 2001:db8:72::2, DNS 2001:db8:72::53"
    check "eth0's address from the router's prefix" "$(command_output 'net' | grep 'IPv6 2001')" \
          eval 'command_output net | grep -Eqx "       IPv6 2001:db8:71:0:5054:ff:fe00:7101/64 \(from the router, valid 8[0-9]{4} s, preferred 14[0-9]{3} s\)"'
    check "eth0's router, DNS server and MTU" "$(command_output 'net' | grep 'IPv6 router')" \
          eval 'command_output net | grep -Eqx "       IPv6 router fe80::ff:fe00:7102 \(1[0-9]{3} s\), DNS 2001:db8:71::53 \(1[0-9]{3} s\), MTU 1400"'
    want_text want <<'LINES'
       IPv6 2001:db8:72::1/64 (fixed)
       IPv6 gateway 2001:db8:72::2, DNS 2001:db8:72::53
LINES
    compare "eth1: fixed, B's advertisement not taken" "$want" \
            "$(command_output 'net' | grep -A20 '^eth1' | grep -E '^       IPv6 (2001|gateway|router)')"
    want_text want <<'LINES'
route6: 2001:db8:71::/64 on eth0
route6: 2001:db8:72::/64 on eth1
route6: default via fe80::ff:fe00:7102 on eth0
LINES
    compare "net: the IPv6 routes" "$want" "$(command_output 'net' | grep '^route6:')"
    expect "--- 2001:db8:71::ff:fe00:7102: 1 sent, 1 received, 0% lost"
    expect "--- 2001:db8:72::2: 1 sent, 1 received, 0% lost"
    check "beyond the link by A, the default router" "$(grep 'to 2001:db8:99::1' "$log")" \
          grep -q "^A: ICMPv6 echo request from 2001:db8:71:0:5054:ff:fe00:7101 to 2001:db8:99::1: answered$" "$log"
    want_text want <<'LINES'
A: the router of 2001:db8:71::/64
B: has 2001:db8:72::2
B: the router of 2001:db8:79::/64
A to 2001:db8:71::5054:ff:fe00:7101: answered by 2001:db8:71:0:5054:ff:fe00:7101, hop limit 64
A: advertised 2001:db8:73::/64 for 6 s
A: no longer a router
LINES
    compare "A and the guest" "$want" "$(cat "$WORK/${P}route-answers")"
    check "the 4-second prefix came" "$(command_output 'net' 2 | grep 'IPv6 2001:db8:73')" \
          eval 'command_output net 2 | grep -Eqx "       IPv6 2001:db8:73:0:5054:ff:fe00:7101/64 \(from the router, valid [0-6] s, preferred [0-5] s\)"'
    check "and went" "$(command_output 'net' 3 | grep '2001:db8:73')" \
          eval '! command_output net 3 | grep -q "2001:db8:73"'
    compare "A no longer a router: the default by eth1's gateway" "route6: default via 2001:db8:72::2 on eth1" \
            "$(command_output 'net' 4 | grep '^route6: default')"
    check "beyond the link by B then" "$(grep 'to 2001:db8:99::1' "$log")" \
          grep -q "^B: ICMPv6 echo request from 2001:db8:72::1 to 2001:db8:99::1: answered$" "$log"
    expect_line "net: eth1: IPv6 off"
    compare "address6 = off: no IPv6 on eth1" "       IPv6 off" \
            "$(command_output 'net' 5 | grep -A20 '^eth1' | grep '^       IPv6')"
    compare "and no route beyond the link" "route6: 2001:db8:71::/64 on eth0" \
            "$(command_output 'net' 5 | grep '^route6:')"
    expect "seq=1: Network is unreachable"
    reject "2001:db8:79"
    reject "panic"
    show_log_on_failure $before
}

# tcp6_session: UDP and TCP over IPv6 (tcp6_test).
tcp6_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test/net6test"
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    answer_lines 'sleep 3'                          # QEMU's router: eth0's fec0:: address
    answer_lines "$t loop" "$t get fec0::2 $NET_V6_PORT" "$t udp fec0::2 $NET_V6_PORT hello-six" \
                 "$t udpserve 7007 &" "$t udpserve 7008 &" 'sleep 1'
    route_ask frag6 A fe80::5054:ff:fe00:7101 7007 3000
    route_ask frag6 A fe80::5054:ff:fe00:7101 7007 3000 overlap
    route_ask frag6 A fe80::5054:ff:fe00:7101 7008 3000
    route_ask tcp6 A on
    answer_lines "$t send fe80::ff:fe00:7102%%eth1 8888 20000" 'net'
    # (64d) Names and programs over IPv6.
    local w=":$NET_V6_HTTP_PORT/six.txt"
    answer_lines "fetch http://[fec0::2]$w" "fetch http://mac6.test$w" "fetch http://both.test$w" \
                 'ping -6 -c 1 mac6.test' 'ping -6 -c 1 mac6.test' 'ping -c 1 -6 fec0::2' \
                 "$t banner ::1 22" "$t dns ::1 mac.test" "$t dns ::ffff:127.0.0.1 mac.test" \
                 "$t nb 10.0.2.2 $NET_CLOSED_PORT" "$t nb fec0::2 $NET_CLOSED_PORT" "$t nb ::1 6999"
}

# tcp6_test (64c): UDP and TCP over IPv6. eth0 (an e1000) is on QEMU's
# network, whose router gives it a fec0:: address and whose fec0::2 is
# the Mac's ::1, where a server sends 1,000,000 bytes (i % 251) on TCP
# and echoes UDP; eth1 (an 82576) is on testroute.py's network of host A.
# net6test loop: TCP over ::1 there and back (300,000 bytes), the names of
# both ends, an IPv4 client of an IPv6 listener (::ffff:127.0.0.1), UDP
# over ::1, the IPv4 calls on an IPv6 socket, an IPv4 socket refusing
# IPv6, a closed port. The guest fetches the Mac's bytes and gets its
# UDP echo. A sends a 3000-byte datagram in three pieces (put back
# together: answered), with overlapping pieces (dropped: RFC 5722), and to
# port 7008, which the firewall does not let in (the interim rule: rules
# without addresses count for IPv6). The guest sends 20,000 bytes to A's
# port 8888: A answers the first full-size segment with "packet too big"
# (1280), and the rest come in smaller segments. (64d) Names: fetch by
# [fec0::2], by an IPv6-only name and by a name of both families (IPv6
# first: the IPv4 address has no web server); ping -6 by name twice
# (dnsd's cache: one AAAA question), sshd on ::1, dnsd answering a
# question that came over IPv6 (and one from ::ffff:127.0.0.1).
tcp6_test() {
    local image before testroute server log dns web
    image=$(make_image ${P}tcp6 "")
    guard_rules "$image" 'allow in udp 7007' "drop out tcp $NET_CLOSED_PORT"
    printf 'address = dhcp\ndns = 10.0.2.2:%s\n' $NET_DNS_PORT >"$WORK/${P}eth0"
    printf 'address = 192.168.71.1/24\n' >"$WORK/${P}eth1"
    $RFS put "$image" $RFS_PART /system/config/network/eth0 "$WORK/${P}eth0" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /system/config/network/eth1 "$WORK/${P}eth1" >/dev/null || exit 1
    rm -f "$WORK/${P}route-answers"
    python3 "$ROOT/scripts/testroute.py" serve $NET_ROUTE_CONTROL $NET_ROUTE_A_HOST $NET_ROUTE_A_GUEST $NET_ROUTE_B_HOST $NET_ROUTE_B_GUEST \
            >"$WORK/${P}testroute.log" 2>&1 &
    testroute=$!
    host_service_wait "$WORK/${P}testroute.log" "testroute: listening"
    # The Mac's IPv6 server: TCP sends 1,000,000 bytes and closes, UDP echoes.
    python3 -c '
import socket, sys, threading
port = int(sys.argv[1])
def tcp():
    s = socket.socket(socket.AF_INET6, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(("::1", port)); s.listen(4)
    data = bytes(i % 251 for i in range(1000000))
    while True:
        c, a = s.accept(); print("tcp6 from", a[0], flush=True); c.sendall(data); c.close()
threading.Thread(target=tcp, daemon=True).start()
u = socket.socket(socket.AF_INET6, socket.SOCK_DGRAM); u.bind(("::1", port))
print("v6server: listening", flush=True)
while True:
    m, a = u.recvfrom(2048); print("udp6 from", a[0], m, flush=True); u.sendto(b"echo: " + m, a)
' $NET_V6_PORT >"$WORK/${P}v6server.log" 2>&1 &
    server=$!
    host_service_wait "$WORK/${P}v6server.log" "v6server: listening"
    # (64d) Names: mac6.test has only an IPv6 address, both.test both (its
    # IPv4 one, the Mac's 127.0.0.1, has no web server: IPv6 must come
    # first); a web server on the Mac's ::1 only.
    python3 "$ROOT/scripts/testdns.py" $NET_DNS_PORT mac.test=10.0.2.2 mac6.test=fec0::2 \
            both.test=10.0.2.2 both.test=fec0::2 >"$WORK/${P}testdns.log" 2>&1 &
    dns=$!
    host_service_wait "$WORK/${P}testdns.log" listening
    rm -rf "$WORK/${P}www6"
    mkdir -p "$WORK/${P}www6"
    printf 'hello over IPv6\n' >"$WORK/${P}www6/six.txt"
    python3 -m http.server --bind ::1 --directory "$WORK/${P}www6" $NET_V6_HTTP_PORT \
            >"$WORK/${P}www6.log" 2>&1 &
    web=$!
    host_service_wait "$WORK/${P}www6.log" "Serving HTTP"
    QEMU_EXTRA="-netdev user,id=net0 -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    QEMU_EXTRA+=" -netdev dgram,id=neta,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_A_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_A_HOST"
    QEMU_EXTRA+=" -device pcie-root-port,id=porta,chassis=1,slot=1"
    QEMU_EXTRA+=" -device igb,netdev=neta,mac=52:54:00:00:71:01,bus=porta"
    before=$failures
    SERIAL_SCRIPT=tcp6_session
    boot ${P}tcp6 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $testroute $server $dns $web 2>/dev/null
    wait $testroute $server $dns $web 2>/dev/null
    log="$WORK/${P}testroute.log"
    want_text want <<'LINES'
net6test: listening on :: (family 10) port 6000 (bind 6000)
net6test: connect [::1]:6000: 0
net6test: peer ::1 (family 10) port 6000, own ::1 (family 10)
net6test: tcp ::1: 300000 sent, 300000 back, the same
net6test: accepted from ::1 (family 10)
net6test: an IPv4 client of the IPv6 listener: 0
net6test: its echo: 4
net6test: accepted from ::ffff:127.0.0.1 (family 10)
net6test: udp ::1: sent 9, got 9 'hello six' from ::1 (family 10), the sender's port yes
net6test: the IPv4 recvfrom: 5 bytes, address 0
net6test: an IPv4 socket to ::1: EAFNOSUPPORT
net6test: an IPv4 TCP socket to ::1: EAFNOSUPPORT
net6test: [::1]:6999: ECONNREFUSED
LINES
    compare "on this machine: TCP and UDP over ::1" "$want" \
            "$(command_output "/system/$ARCH_NAME/test/net6test loop" | grep '^net6test:')"
    expect_line "net6test: got 1000000 bytes, as sent"
    expect_line "net6test: udp answer 'echo: hello-six' from fec0::2 (family 10) port $NET_V6_PORT"
    check "the Mac's server saw the guest's address" "$(cat "$WORK/${P}v6server.log")" \
          grep -q "^tcp6 from ::1" "$WORK/${P}v6server.log"
    want_text want <<'LINES'
A: 3 pieces to fe80::5054:ff:fe00:7101 port 7007: answer 'got 3000 bytes, PATTERN'
A: 3 pieces to fe80::5054:ff:fe00:7101 port 7007: no answer
A: 3 pieces to fe80::5054:ff:fe00:7101 port 7008: no answer
A: tcp6 on
LINES
    local sum
    sum=$(python3 -c 'h=0
for i in range(3000): h=(h*31+i%251)&0xFFFFFFFF
print("%08x" % h)')
    compare "fragments: together, overlapping ones dropped, the firewall's port" "${want/PATTERN/$sum}" \
            "$(cat "$WORK/${P}route-answers")"
    expect_line "net6test: sent 20000 bytes"
    check "packet too big: smaller segments after it" "$(grep 'tcp6 8888' "$log")" \
          grep -q "^A: tcp6 8888: 20000 bytes, segments of at most 0 before packet too big, 1220 after$" "$log"
    check "net: the segments made smaller" "$(command_output 'net' | grep '^tcp:')" \
          eval 'command_output net | grep -q "1 smaller (too big)"'
    # (64d)
    compare "fetch [fec0::2]" "hello over IPv6" "$(command_output "fetch http://[fec0::2]:$NET_V6_HTTP_PORT/six.txt")"
    compare "fetch an IPv6 name" "hello over IPv6" "$(command_output "fetch http://mac6.test:$NET_V6_HTTP_PORT/six.txt")"
    compare "fetch a name of both families: IPv6 first" "hello over IPv6" \
            "$(command_output "fetch http://both.test:$NET_V6_HTTP_PORT/six.txt")"
    expect_line "PING mac6.test (fec0::2): 56 data bytes"
    expect "--- mac6.test: 1 sent, 1 received, 0% lost"
    expect "--- fec0::2: 1 sent, 1 received, 0% lost"
    check "dnsd kept the AAAA answer (asked once: a fetch and two pings)" \
          "$(grep 'mac6.test type 28' "$WORK/${P}testdns.log")" \
          test "$(grep -c '^question mac6.test type 28: answered' "$WORK/${P}testdns.log")" = 1
    check "sshd listens on IPv6" "$(command_output "/system/$ARCH_NAME/test/net6test banner ::1 22")" \
          eval 'command_output "/system/$ARCH_NAME/test/net6test banner ::1 22" | grep -q "^net6test: ::1 says .SSH-2.0-"'
    expect_line "net6test: dns mac.test: 10.0.2.2, from ::1 (family 10) port 53"
    expect_line "net6test: dns mac.test: 10.0.2.2, from ::ffff:127.0.0.1 (family 10) port 53"
    # A connect that does not wait (O_NONBLOCK) through the IPv6 calls: to a
    # port the firewall drops going out (IPv4, and IPv6 by the rule without
    # an address), poll gives up after its 5 s; refused at once on ::1.
    expect_line "net6test: nb 10.0.2.2: connect -1 (EINPROGRESS), poll 0 after about 5 s, revents 0"
    expect_line "net6test: nb fec0::2: connect -1 (EINPROGRESS), poll 0 after about 5 s, revents 0"
    check "a refused connect does not wait" "$(command_output "/system/$ARCH_NAME/test/net6test nb ::1 6999")" \
          eval 'command_output "/system/$ARCH_NAME/test/net6test nb ::1 6999" | grep -Eq "^net6test: nb ::1: connect -1 \((EINPROGRESS|another)\), poll 1 after under 1 s"'
    reject "panic"
    show_log_on_failure $before
}

# guard6_session: the firewall's IPv6 rules (guard6_test).
guard6_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test/net6test" port
    prompt_wait $n
    serial_wait " rule(s) loaded (in = " 1 30
    answer_lines 'sleep 3'                          # the link-local address checked
    for port in 7007 7008 7009 7010 7011; do
        answer_lines "$t udpserve $port &"
    done
    answer_lines 'sleep 1'
    route_ask udp A fe80::5054:ff:fe00:7101 7007 one
    route_ask udp A fe80::5054:ff:fe00:7101 7008 two
    route_ask udp A fe80::5054:ff:fe00:7101 7009 three
    route_ask udp A 192.168.71.1 7009 four
    route_ask udp A fe80::5054:ff:fe00:7101 7010 five 5561     # (three connections: a limit
    route_ask udp A fe80::5054:ff:fe00:7101 7010 six 5562      # counts new ones)
    route_ask udp A fe80::5054:ff:fe00:7101 7010 seven 5563
    route_ask udp A fe80::5054:ff:fe00:7101 7011 eight
    route_ask ping6 A fe80::5054:ff:fe00:7101
    answer_lines 'guard'
}

# guard6_test (64e): the firewall's IPv6 rules. One rules file for both
# families: rules without an address count for both, one with an IPv4
# address only for IPv4, one with an IPv6 address only for IPv6 (each
# family's own table, GUARD_SET6). The guest (an e1000 on testroute.py's
# network of host A, 192.168.71.1 and fe80::5054:ff:fe00:7101) answers UDP
# on ports 7007-7011; A sends datagrams: 7007 allowed from A's own address,
# 7008 dropped from fe80::/10 before an allow, 7009 dropped from
# 192.168.71.0/24 (IPv4's: A's IPv6 datagram passes, its IPv4 one is
# dropped), 7010 limited to 2 a minute from fe80::/64, 7011 allowed only
# from 2001:db8::/32 (in = drop decides); A's ping passes (allow in icmp,
# no address). guard lists the rules in the file's order, each with its
# family's address and its packets, and the drops of both families.
guard6_test() {
    local image before testroute
    image=$(make_image ${P}guard6 "")
    printf 'address = 192.168.71.1/24\n' >"$WORK/${P}eth0"
    $RFS put "$image" $RFS_PART /system/config/network/eth0 "$WORK/${P}eth0" >/dev/null || exit 1
    guard_rules "$image" 'allow in udp 7007 from fe80::ff:fe00:7102' 'drop in udp 7008 from fe80::/10' \
                'allow in udp 7008' 'drop in udp 7009 from 192.168.71.0/24' 'allow in udp 7009' \
                'limit in udp 7010 from fe80::/64 2/minute' 'allow in udp 7011 from 2001:db8::/32'
    rm -f "$WORK/${P}route-answers"
    python3 "$ROOT/scripts/testroute.py" serve $NET_ROUTE_CONTROL $NET_ROUTE_A_HOST $NET_ROUTE_A_GUEST $NET_ROUTE_B_HOST $NET_ROUTE_B_GUEST \
            >"$WORK/${P}testroute.log" 2>&1 &
    testroute=$!
    host_service_wait "$WORK/${P}testroute.log" "testroute: listening"
    QEMU_EXTRA="-netdev dgram,id=neta,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_A_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_A_HOST"
    QEMU_EXTRA+=" -device e1000,netdev=neta,mac=52:54:00:00:71:01"
    before=$failures
    SERIAL_SCRIPT=guard6_session
    boot ${P}guard6 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $testroute 2>/dev/null
    wait $testroute 2>/dev/null
    expect_line "guardd: 10 rule(s) loaded (in = drop, out = allow)"
    want_text want <<'LINES'
A: udp to fe80::5054:ff:fe00:7101 port 7007: answer 'got 3 bytes, 0001ae66'
A: udp to fe80::5054:ff:fe00:7101 port 7008: no answer
A: udp to fe80::5054:ff:fe00:7101 port 7009: answer 'got 5 bytes, 0693a59e'
A: udp to 192.168.71.1 port 7009: no answer
A: udp to fe80::5054:ff:fe00:7101 port 7010: answer 'got 4 bytes, 002ff6b2'
A: udp to fe80::5054:ff:fe00:7101 port 7010: answer 'got 3 bytes, 0001bce2'
A: udp to fe80::5054:ff:fe00:7101 port 7010: no answer
A: udp to fe80::5054:ff:fe00:7101 port 7011: no answer
A to fe80::5054:ff:fe00:7101: answered by fe80::5054:ff:fe00:7101, hop limit 64
LINES
    compare "both families through one rules file" "$want" "$(cat "$WORK/${P}route-answers")"
    local listing
    listing=$(command_output 'guard')
    check "guard: the rules in the file's order, each family's address" "$listing" eval '
        grep -Eq "^  4  allow in udp 7007 from fe80::ff:fe00:7102 +1 packet\(s\)$" <<<"$listing" &&
        grep -Eq "^  5  drop in udp 7008 from fe80::/10 +1 packet\(s\)$" <<<"$listing" &&
        grep -Eq "^  7  drop in udp 7009 from 192.168.71.0/24 +1 packet\(s\)$" <<<"$listing" &&
        grep -Eq "^  8  allow in udp 7009 +1 packet\(s\)$" <<<"$listing" &&
        grep -Eq "^  9  limit in udp 7010 from fe80::/64 2/minute +3 packet\(s\)$" <<<"$listing" &&
        grep -Eq "^ 10  allow in udp 7011 from 2001:db8::/32 +0 packet\(s\)$" <<<"$listing"'
    check "guard: the drops of both families" "$listing" eval '
        grep -Eq " in udp 7008 from fe80::ff:fe00:7102 to fe80::5054:ff:fe00:7101 on eth0 \(rule 5\)$" <<<"$listing" &&
        grep -Eq " in udp 7009 from 192.168.71.2 to 192.168.71.1 on eth0 \(rule 7\)$" <<<"$listing" &&
        grep -Eq " in udp 7010 from fe80::ff:fe00:7102 to fe80::5054:ff:fe00:7101 on eth0 \(rule 9\)$" <<<"$listing" &&
        grep -Eq " in udp 7011 from fe80::ff:fe00:7102 to fe80::5054:ff:fe00:7101 on eth0 \(in = drop\)$" <<<"$listing"'
    reject "panic"
    show_log_on_failure $before
}

# dhcp6_session: DHCPv6 (dhcp6_test).
dhcp6_session() {
    local n=1 asked=0
    prompt_wait $n
    serial_wait "dhclient: eth0: IPv6 2001:db8:71::1:1 from DHCPv6" 1 30
    serial_wait "dhclient: eth1: IPv6 2001:db8:72::1:1 from DHCPv6" 1 30
    serial_wait "dhclient: eth0: IPv6 2001:db8:71::1:1 renewed" 1 20
    answer_lines '' 'net'
    route_ask dhcp6 A off                           # no renewals now: the lease ends (valid 12 s)
    serial_wait "dhclient: eth0: the IPv6 lease ended: no IPv6 address from DHCPv6" 1 30
    route_ask router6 B 2001:db8:72::/64 1800 flags O     # "other" only: the DNS server
    answer_lines '' "echo 'address = 192.168.72.1/24' > /system/config/network/eth1" 'net up'
    serial_wait "dhclient: eth1: DNS 2001:db8:72::53 from DHCPv6" 1 30
    answer_lines '' 'net'
}

# dhcp6_test (64g): DHCPv6 in the elf dhclient. eth0 (an e1000, address6
# auto as by default) on host A's network: A's router advertisement says
# "managed" (testroute.py router6 ... flags M) and A is a DHCPv6 server
# (dhcp6: 2001:db8:71::1:N, a DNS server, T1 4 s, valid 12 s); eth1 (an
# 82576) is set to address6 = dhcp on host B's network, whose router does
# not say "managed" and whose prefix is for addresses: eth1 takes
# DHCPv6's address only. Both get their address and DNS server (dhclient's
# lines, net's "from DHCPv6" and "(DHCPv6, ...)"); eth0 renews at T1 and,
# A's server gone, its lease ends at the valid lifetime. Then eth1 goes
# back to address6 = auto (net up) with B saying only "other": a SLAAC
# address and the DNS server from an Information-request.
dhcp6_test() {
    local image before testroute
    image=$(make_image ${P}dhcp6 "")
    printf 'address = dhcp\n' >"$WORK/${P}eth0"
    printf 'address = 192.168.72.1/24\naddress6 = dhcp\n' >"$WORK/${P}eth1"
    $RFS put "$image" $RFS_PART /system/config/network/eth0 "$WORK/${P}eth0" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /system/config/network/eth1 "$WORK/${P}eth1" >/dev/null || exit 1
    rm -f "$WORK/${P}route-answers"
    python3 "$ROOT/scripts/testroute.py" serve $NET_ROUTE_CONTROL $NET_ROUTE_A_HOST $NET_ROUTE_A_GUEST $NET_ROUTE_B_HOST $NET_ROUTE_B_GUEST \
            >"$WORK/${P}testroute.log" 2>&1 &
    testroute=$!
    host_service_wait "$WORK/${P}testroute.log" "testroute: listening"
    route_ask dhcp A on
    route_ask router6 A 2001:db8:71::/64 1800 flags M
    route_ask dhcp6 A on 2001:db8:71::/64 dns 2001:db8:71::53 t1 4 valid 12
    route_ask router6 B 2001:db8:72::/64 1800
    route_ask dhcp6 B on 2001:db8:72::/64 dns 2001:db8:72::53
    QEMU_EXTRA="-netdev dgram,id=neta,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_A_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_A_HOST"
    QEMU_EXTRA+=" -device e1000,netdev=neta,mac=52:54:00:00:71:01"
    QEMU_EXTRA+=" -netdev dgram,id=netb,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_B_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_B_HOST"
    QEMU_EXTRA+=" -device pcie-root-port,id=portb,chassis=2,slot=2"
    QEMU_EXTRA+=" -device igb,netdev=netb,mac=52:54:00:00:72:01,bus=portb"
    before=$failures
    SERIAL_SCRIPT=dhcp6_session
    boot ${P}dhcp6 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $testroute 2>/dev/null
    wait $testroute 2>/dev/null
    expect_line "net: eth1: IPv6 by DHCPv6: the elf dhclient asks for its address"
    expect_line "dhclient: eth0: IPv6 2001:db8:71::1:1 from DHCPv6 (fe80::ff:fe00:7102), DNS 2001:db8:71::53, valid 12 s"
    expect_line "dhclient: eth1: IPv6 2001:db8:72::1:1 from DHCPv6 (fe80::ff:fe00:7202), DNS 2001:db8:72::53, valid 3600 s"
    expect_line "dhclient: eth0: IPv6 2001:db8:71::1:1 renewed, valid 12 s"
    local first second
    first=$(command_output 'net')
    check "eth0: DHCPv6's address beside the router's prefix's" "$first" eval '
        grep -Eq "^       IPv6 2001:db8:71::1:1/128 \(from DHCPv6, valid [0-9]+ s, preferred [0-9]+ s\)$" <<<"$first" &&
        grep -Eq "^       IPv6 2001:db8:71:0:5054:ff:fe00:7101/64 \(from the router" <<<"$first" &&
        grep -Eq "DNS 2001:db8:71::53 \(DHCPv6, [0-9]+ s\)" <<<"$first"'
    check "eth1 (address6 = dhcp): DHCPv6's address, none from the prefix" "$first" eval '
        grep -Eq "^       IPv6 2001:db8:72::1:1/128 \(from DHCPv6" <<<"$first" &&
        ! grep -q "2001:db8:72:0:5054" <<<"$first"'
    expect_line "dhclient: eth0: the IPv6 lease ended: no IPv6 address from DHCPv6"
    second=$(command_output 'net' 2)
    check "eth0: the lease's address gone" "$second" eval '! grep -q "2001:db8:71::1:1/128" <<<"$second"'
    check "eth1 (auto, the router says other): the prefix's address and DHCPv6's DNS server" "$second" eval '
        grep -Eq "^       IPv6 2001:db8:72:0:5054:ff:fe00:7201/64 \(from the router" <<<"$second" &&
        grep -Eq "DNS 2001:db8:72::53 \(DHCPv6, for ever\)" <<<"$second" &&
        ! grep -q "2001:db8:72::1:1/128" <<<"$second"'
    check "B was asked for the DNS server alone" "$(grep 'Information-request' "$WORK/${P}testroute.log")" \
          grep -q "^B: DHCPv6 Information-request from fe80::5054:ff:fe00:7201$" "$WORK/${P}testroute.log"
    reject "panic"
    show_log_on_failure $before
}

# route_shell_test: a router between two networks. The machine's cards
# eth0 and eth1 (Intel 82576s, igb, like the two ports of the test PC's
# card) are on two QEMU networks of their own (-netdev dgram), each
# with one host played by scripts/testroute.py on the Mac: A 192.168.71.2
# and B 192.168.72.2 (B also the gateway: it answers echo requests for any
# address). /system/config/network/eth0 and eth1 set the cards and the
# default route through B; net lists the routes. Forwarding off: A's
# echo request to B is dropped, the router's own other address answers.
# On (net forward on): A and B reach each other both ways, the TTL one
# less and the header checksum right where it arrives, the first packet
# kept while the router asks ARP for B; the default route takes A's
# packet for 8.8.4.4 to B; TTL 1 gets "time exceeded"; the machine's own
# pings take the routes too. Then eth1 without a gateway and
# /system/config/routing with forward = on (net up): "network unreachable"
# for 10.9.9.9; net forward
# off: dropped again; the counters.
route_shell_test() {
    local image before testroute
    image=$(make_image ${P}route "")
    printf 'address = 192.168.71.1/24\n' >"$WORK/${P}eth0"
    printf 'address = 192.168.72.1/24\ngateway = 192.168.72.2\n' >"$WORK/${P}eth1"
    $RFS put "$image" $RFS_PART /system/config/network/eth0 "$WORK/${P}eth0" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /system/config/network/eth1 "$WORK/${P}eth1" >/dev/null || exit 1
    # Forwarding is gated by the firewall's forward chain (49h): allow
    # forwarded ICMP so the routing below works; the forward default stays
    # drop (without this rule nothing is forwarded).
    guard_rules "$image" 'allow forward icmp'
    rm -f "$WORK/${P}route-answers"
    python3 "$ROOT/scripts/testroute.py" serve $NET_ROUTE_CONTROL $NET_ROUTE_A_HOST $NET_ROUTE_A_GUEST $NET_ROUTE_B_HOST $NET_ROUTE_B_GUEST \
            >"$WORK/${P}testroute.log" 2>&1 &
    testroute=$!
    host_service_wait "$WORK/${P}testroute.log" "testroute: listening"
    # Each 82576 behind a PCIe port of its own (QEMU puts the card's
    # virtual functions in the slots after it, where a second card would be).
    QEMU_EXTRA="-netdev dgram,id=neta,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_A_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_A_HOST"
    QEMU_EXTRA+=" -device pcie-root-port,id=porta,chassis=1,slot=1"
    QEMU_EXTRA+=" -device igb,netdev=neta,mac=52:54:00:00:71:01,bus=porta"
    QEMU_EXTRA+=" -netdev dgram,id=netb,local.type=inet,local.host=127.0.0.1,local.port=$NET_ROUTE_B_GUEST"
    QEMU_EXTRA+=",remote.type=inet,remote.host=127.0.0.1,remote.port=$NET_ROUTE_B_HOST"
    QEMU_EXTRA+=" -device pcie-root-port,id=portb,chassis=2,slot=2"
    QEMU_EXTRA+=" -device igb,netdev=netb,mac=52:54:00:00:72:01,bus=portb"
    before=$failures
    SERIAL_SCRIPT=route_session
    boot ${P}route "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $testroute 2>/dev/null
    wait $testroute 2>/dev/null
    expect_line "net: eth0: 192.168.71.1/24, gateway none, DNS none"
    expect_line "net: eth1: 192.168.72.1/24, gateway 192.168.72.2, DNS none"
    want_text want <<'LINES'
route: 127.0.0.0/8 on lo
route: 192.168.71.0/24 on eth0
route: 192.168.72.0/24 on eth1
route: default via 192.168.72.2 on eth1
forwarding: off; 0 packets forwarded, not: 0 without a route, 0 out of time (TTL), 0 without an ARP answer
LINES
    compare "net: the routes, forwarding off" "$want" "$(command_output 'net' | grep -E '^(route|forwarding):')"
    want_text want <<'LINES'
A to 192.168.72.2: no answer
A to 192.168.72.1: answered by 192.168.72.1, ttl 64
A to 192.168.72.2: answered by 192.168.72.2, ttl 63, seen at B with ttl 63, checksum ok
B to 192.168.71.2: answered by 192.168.71.2, ttl 63, seen at A with ttl 63, checksum ok
A to 8.8.4.4: answered by 8.8.4.4, ttl 63, seen at B with ttl 63, checksum ok
A to 192.168.72.2: time exceeded from 192.168.71.1, quoting our packet
A to 192.168.72.2: answered by 192.168.72.2, ttl 63
A to 10.9.9.9: unreachable (code 0) from 192.168.71.1, quoting our packet
A to 192.168.72.2: no answer
LINES
    compare "the hosts A and B through the router" "$want" "$(cat "$WORK/${P}route-answers")"
    expect_line "net: forwarding between cards: on"
    expect "--- 192.168.71.2: 1 sent, 1 received, 0% lost"
    expect "64 bytes from 8.8.8.8: seq=1 time="
    compare "the counters with forwarding on" \
            "forwarding: on; 8 packets forwarded, not: 0 without a route, 1 out of time (TTL), 0 without an ARP answer" \
            "$(command_output 'net' 2 | grep '^forwarding:')"
    # The forward chain (49h): forwarding is gated by the firewall; the
    # 'allow forward icmp' rule matched the forwarded packets (nonzero
    # count), and the forward default is drop (without the rule nothing is
    # forwarded).
    check "the forward default is drop (49h)" \
          "$(command_output 'guard' | grep -E '^firewall:' || echo MISSING)" \
          eval 'command_output "guard" | grep -q "forward = drop"'
    check "the forward rule decided the forwarded packets (49h)" \
          "$(command_output 'guard' | grep 'allow forward' || echo MISSING)" \
          eval 'command_output "guard" | grep -qE "allow forward icmp +[1-9]"'
    compare "net up: the file's routes (no gateway now)" \
            "$(printf 'route: 127.0.0.0/8 on lo\nroute: 192.168.71.0/24 on eth0\nroute: 192.168.72.0/24 on eth1')" \
            "$(command_output 'net' 3 | grep '^route:')"
    compare "net forward" "net: forwarding between cards: off" "$(command_output 'net forward')"
    compare "the counters at the end" \
            "forwarding: off; 8 packets forwarded, not: 1 without a route, 1 out of time (TTL), 0 without an ARP answer" \
            "$(command_output 'net' 3 | grep '^forwarding:')"
    # Masquerade (source NAT, 49i): with eth0 marked private, A's ping to B
    # reaches B with the router's eth1 address as its source, not A's; the
    # reply is translated back so A still gets it. net names the private card.
    expect_line "net: masquerade (source NAT), private: eth0"
    check "B saw the forwarded ping from the router's address, not A's (masquerade, 49i)" \
          "$(grep -h 'ICMP 8/0 from 192.168.72.1 to 192.168.72.2' "$WORK/${P}testroute.log" 2>/dev/null || echo MISSING)" \
          eval 'grep -q "ICMP 8/0 from 192.168.72.1 to 192.168.72.2" "$WORK/${P}testroute.log"'
    reject "panic"
    show_log_on_failure $before
}

# image_session / image_shell_test: libimage (decode) and imageview. The host
# makes a patterned picture as both PPM and BMP and computes the SHA-256 of its
# RGBA pixels; imagetest decodes each and must print that same size and hash
# (so both decoders agree with the host and each other). A solid-colour PPM is
# shown by imageview under windowd and a screenshot confirms its colour fills
# the window. Proven by the host hash differing from any wrong decode. Then
# the window's bottom edge is dragged 100 pixels down (QMP): the picture keeps
# its proportions, centred, with the background above and below it (proven
# by the old imageview, which stretched it over the whole window).
image_session() {
    local n=1 asked=0 mon="$WORK/monitor.sock" q="$WORK/qmp.sock" curx cury
    if [ "$ARCH_NAME" = x86_64 ]; then curx=640 cury=400; else curx=400 cury=300; fi
    qmp() { local c; { echo '{"execute":"qmp_capabilities"}'; sleep 0.3
                       for c in "$@"; do echo "$c"; sleep 0.15; done; } |
            nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1; }
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    moveto() { qmp "$(rel x $(( $1 - curx )))" "$(rel y $(( $2 - cury )))"; curx=$1; cury=$2; }
    prompt_wait $n
    answer_lines "/system/$ARCH_NAME/test/imagetest /test/pic.ppm" \
                 "/system/$ARCH_NAME/test/imagetest /test/pic.bmp" \
                 "/system/$ARCH_NAME/test/imagetest -s /test/pic.ppm /tmp/saved.bmp /test/pic.bmp /tmp/saved.ppm" \
                 "ls -l /tmp/saved.bmp /tmp/saved.ppm"
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "/system/$ARCH_NAME/apps/imageview.program/imageview /test/solid.ppm &\r"
    serial_wait "imageview: showing" 1 15
    sleep 1
    echo "screendump $WORK/${NAME}-view.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    # The window: at (100,100), content 200x150 from y 140 (title 24, menu
    # bar 16), its bottom border at 290-293: grab it, 100 pixels down.
    moveto 200 292
    qmp "$(btn true)"
    moveto 200 392
    qmp "$(btn false)"
    sleep 2
    echo "screendump $WORK/${NAME}-taller.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

image_shell_test() {
    local image before w h hash
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}image "")
    windows_bare "$image"
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    hash=$(python3 "$ROOT/scripts/mkimage.py" "$WORK/${P}pic.ppm" "$WORK/${P}pic.bmp" "$WORK/${P}solid.ppm")
    $RFS put "$image" $RFS_PART /test/pic.ppm "$WORK/${P}pic.ppm" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /test/pic.bmp "$WORK/${P}pic.bmp" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /test/solid.ppm "$WORK/${P}solid.ppm" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=image_session
    boot ${P}image "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "imagetest: /test/pic.ppm 200x150 sha256 $hash"
    expect "imagetest: /test/pic.bmp 200x150 sha256 $hash"      # the BMP decodes to the same pixels
    # (63e) image_save, a row at a time: saved and read back, the same pixels,
    # each file exactly its format's size (BMP rows padded to 4 bytes)
    expect "imagetest: /tmp/saved.bmp 200x150 sha256 $hash"
    expect "imagetest: /tmp/saved.ppm 200x150 sha256 $hash"
    expect " $((54 + 150 * 600))  /tmp/saved.bmp"
    expect " $((15 + 200 * 150 * 3))  /tmp/saved.ppm"
    # imageview filled its window with the solid colour (region holds that pixel)
    check_screen region-120-140-80-40-200-80-40 $w $h "$WORK/${P}image-view.ppm"
    # taller window (content 200x250): the 200x150 picture in the middle
    # (y 190-339), the background (0x363D4A) in the 50 rows above and below
    check_screen region-120-150-80-30-54-61-74 $w $h "$WORK/${P}image-taller.ppm"
    check_screen region-120-220-80-80-200-80-40 $w $h "$WORK/${P}image-taller.ppm"
    check_screen region-120-350-80-30-54-61-74 $w $h "$WORK/${P}image-taller.ppm"
    reject "panic"
    show_log_on_failure $before
}

# png_session / png_shell_test: libimage's PNG decoder (25a). scripts/mkpng.py
# writes one pattern in every variant (each colour type and bit depth,
# palettes and transparency, Adam7, all five row filters, stored and dynamic
# DEFLATE blocks) and the SHA-256 of the RGBA pixels each must decode to;
# imagetest decodes them all in one command (the shell expands the *) and
# must print each size and hash. Two damaged files (a wrong CRC, image data
# cut short) must be refused. Proven by a decoder with the Paeth filter
# wrong: every file using it fails its hash.
png_session() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines "/system/$ARCH_NAME/test/imagetest /test/*.png"
}

png_shell_test() {
    local image before name size hash
    image=$(make_image ${P}png "")
    rm -rf "$WORK/${P}png.d"; mkdir -p "$WORK/${P}png.d"
    python3 "$ROOT/scripts/mkpng.py" "$WORK/${P}png.d" > "$WORK/${P}png.expected" || exit 1
    for f in "$WORK/${P}png.d"/*.png; do
        $RFS put "$image" $RFS_PART "/test/$(basename "$f")" "$f" >/dev/null || exit 1
    done
    before=$failures
    SERIAL_SCRIPT=png_session
    boot ${P}png "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    while read -r name size hash; do
        expect "imagetest: /test/$name.png $size sha256 $hash"
    done < "$WORK/${P}png.expected"
    expect "imagetest: /test/zcrc.png: Invalid argument"
    expect "imagetest: /test/zshort.png: Invalid argument"
    reject "panic"
    show_log_on_failure $before
}

# jpeg_session / jpeg_shell_test: libimage's JPEG decoder (25b-25c).
# scripts/mkjpeg.py writes chosen coefficients in every baseline variant
# (grey; 4:4:4, 4:2:2, 4:2:0, 4:4:0, 4:1:1; restart markers; one scan per
# component; 16-bit tables; Adobe RGB; sizes that are not whole MCUs) and
# progressive ones (libjpeg's usual script, spectral selection alone, deep
# successive approximation with restarts) and each one's exact picture (a
# floating-point inverse DCT of the same coefficients) as a PPM; imagetest -c
# decodes each JPEG and compares: at most 3 levels apart, a mean under 0.2.
# Each progressive file must also give exactly the pixels of its baseline
# twin (the same coefficients). A file cut short still decodes (the rest
# grey), a frame of width 0 is refused. Proven by an inverse DCT with two
# odd-part constants swapped, and (25c) by a refinement that drops its
# correction bits.
jpeg_session() {
    local n=1 asked=0 name
    local -a lines=()
    prompt_wait $n
    while read -r name; do
        lines+=("/system/$ARCH_NAME/test/imagetest -c /test/$name.jpg /test/$name.ppm")
    done < "$WORK/${P}jpeg.names"
    lines+=("/system/$ARCH_NAME/test/imagetest /test/zcut.jpg /test/zsof.jpg")
    lines+=("/system/$ARCH_NAME/test/imagetest -c /test/p420.jpg /test/s420.jpg /test/pgrey.jpg /test/grey.jpg")
    lines+=("/system/$ARCH_NAME/test/imagetest -c /test/p444r.jpg /test/s444.jpg /test/pbig420.jpg /test/big420.jpg")
    answer_lines "${lines[@]}"
}

# jpeg_close NAME: imagetest's comparison of /test/NAME.jpg with its exact
# picture: at most 3 levels apart, a mean of at most 200/1000.
jpeg_close() {
    local line most mean
    line=$(grep -F "imagetest: /test/$1.jpg " <<<"$TEXT" | head -1)
    most=$(sed -n 's/.* at most \([0-9][0-9]*\) apart.*/\1/p' <<<"$line")
    mean=$(sed -n 's/.* mean \([0-9][0-9]*\)\/1000.*/\1/p' <<<"$line")
    [ -n "$most" ] && [ -n "$mean" ] && [ "$most" -le 3 ] && [ "$mean" -le 200 ]
}

jpeg_shell_test() {
    local image before name
    image=$(make_image ${P}jpeg "")
    rm -rf "$WORK/${P}jpeg.d"; mkdir -p "$WORK/${P}jpeg.d"
    python3 "$ROOT/scripts/mkjpeg.py" "$WORK/${P}jpeg.d" > "$WORK/${P}jpeg.names" || exit 1
    for f in "$WORK/${P}jpeg.d"/*.jpg "$WORK/${P}jpeg.d"/*.ppm; do
        $RFS put "$image" $RFS_PART "/test/$(basename "$f")" "$f" >/dev/null || exit 1
    done
    before=$failures
    SERIAL_SCRIPT=jpeg_session
    boot ${P}jpeg "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    while read -r name; do
        check "$name.jpg decodes to its exact picture (within 3 levels, mean under 0.2)" \
              "$name.jpg: $(grep -F "imagetest: /test/$name.jpg " <<<"$TEXT" | head -1 || echo MISSING)" \
              jpeg_close "$name"
    done < "$WORK/${P}jpeg.names"
    expect "imagetest: /test/zcut.jpg 61x45 sha256 "
    expect "imagetest: /test/zsof.jpg: Invalid argument"
    expect "imagetest: /test/p420.jpg 61x45, from /test/s420.jpg at most 0 apart, mean 0/1000"
    expect "imagetest: /test/pgrey.jpg 61x45, from /test/grey.jpg at most 0 apart, mean 0/1000"
    expect "imagetest: /test/p444r.jpg 61x45, from /test/s444.jpg at most 0 apart, mean 0/1000"
    expect "imagetest: /test/pbig420.jpg 320x240, from /test/big420.jpg at most 0 apart, mean 0/1000"
    reject "panic"
    show_log_on_failure $before
}

# soundmix_session / soundmix_shell_test: the soundd mixer. soundd owns
# /dev/pcm0 and mixes PCM from clients on /run/sound. Two toneclients send a
# constant level at once; soundd sums them, so the captured peak is about twice
# one client's (and over the threshold a single client cannot reach). Proven by
# the peak being one client's level if the mixer did not sum.
soundmix_session() {
    local n=1 asked=0
    prompt_wait $n
    serial_type "/system/$ARCH_NAME/bin/soundd &\r"
    serial_wait "soundd: mixing" 1 15
    n=$((n + 1)); prompt_wait $n
    serial_type "/system/$ARCH_NAME/test/toneclient 6000 36000 &\r"
    serial_type "/system/$ARCH_NAME/test/toneclient 6000 36000 &\r"
    serial_wait "toneclient: sent" 2 25
    sleep 1
}

soundmix_shell_test() {
    local image before peak
    image=$(make_image ${P}soundmix "")
    QEMU_EXTRA="-device intel-hda -device hda-output,audiodev=snd"
    QEMU_EXTRA+=" -audiodev wav,id=snd,path=$WORK/${P}soundmix.wav"
    before=$failures
    SERIAL_SCRIPT=soundmix_session
    boot ${P}soundmix "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "soundd: mixing on /run/sound"
    peak=$(python3 "$ROOT/scripts/wavpeak.py" "$WORK/${P}soundmix.wav" 2>/dev/null || echo 0)
    # one client alone captures ~4000 (QEMU resamples 48k->44.1k); two summed
    # capture ~8000, over 6500, which one client cannot reach.
    check "soundd summed two streams (peak $peak, want > 6500)" "not mixed" test "$peak" -gt 6500
    reject "panic"
    show_log_on_failure $before
}

# tune_session / tune_shell_test: playing a sound file through /dev/pcm0. With
# an HDA controller present, `tune` decodes a WAV (libaudio), resamples it to
# the output's 48 kHz, and writes it to /dev/pcm0; QEMU's wav audiodev captures
# it and the host confirms it is not silent -- the whole path, program to
# speaker. Proven by the capture being silent if /dev/pcm0 drops the data.
tune_session() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines "/system/$ARCH_NAME/bin/tune /test/snd.wav"
    sleep 1
}

tune_shell_test() {
    local image before peak
    image=$(make_image ${P}tune "")
    python3 "$ROOT/scripts/mkwav.py" "$WORK/${P}snd.wav" >/dev/null
    $RFS put "$image" $RFS_PART /test/snd.wav "$WORK/${P}snd.wav" >/dev/null || exit 1
    QEMU_EXTRA="-device intel-hda -device hda-output,audiodev=snd"
    QEMU_EXTRA+=" -audiodev wav,id=snd,path=$WORK/${P}tune.wav"
    before=$failures
    SERIAL_SCRIPT=tune_session
    boot ${P}tune "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "tune: playing /test/snd.wav"
    expect "tune: done"
    peak=$(python3 "$ROOT/scripts/wavpeak.py" "$WORK/${P}tune.wav" 2>/dev/null || echo 0)
    check "tune played audible sound (peak $peak, want > 3000)" "silent capture" \
          test "$peak" -gt 3000
    reject "panic"
    show_log_on_failure $before
}

# sudo_session / sudo_shell_test: su and sudo (50c; setuid root programs,
# 50b). Root adds anna and bob and allows anna in /system/config/sudo; su is
# shown rws, root's. anna: `sudo id` with her password runs as root, with a
# wrong one is refused; `su bob` with bob's password gives his shell (id:
# bob), `exit` brings her back; `su` (root) with a wrong password is
# refused. bob: `sudo id` is refused without a password asked (not in the
# file). Proven by a sudo without the list and a su without the password.
# (68d) The password is one line: from a file, the next line is the
# command's input; no password at all says so (exit 1). Proven by a sudo
# reading everything at once (cat gets nothing). (68e) A second sudo in the
# session asks nothing; after `sudo -k` it asks again. Proven by a sudo
# that never looks at the stamp and one whose -k forgets nothing.
sudo_session() {
    local n=1 u
    prompt_wait $n
    for u in anna bob; do
        answer_lines "useradd $u"
        serial_type "passwd $u\r"
        serial_wait "New password: " $([ $u = anna ] && echo 1 || echo 2)
        serial_type "$u-pw-1\r"
        serial_wait "Again: " $([ $u = anna ] && echo 1 || echo 2)
        serial_type "$u-pw-1\r"
        n=$((n + 1)); prompt_wait $n 30
    done
    answer_lines 'echo "users = anna" > /system/config/sudo' "ls -l /system/$ARCH_NAME/bin/su"
    serial_type 'exit\r'
    login_wait 2
    serial_type 'anna\r'
    serial_wait "Password: " 1
    serial_type 'anna-pw-1\r'
    serial_wait "[anna logged in]" 1 30
    n=$((n + 1)); prompt_wait $n 30
    serial_type 'sudo id\r'
    serial_wait "Password for anna: " 1
    serial_type 'anna-pw-1\r'
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'sudo id'                              # (68e) remembered: no password asked
    serial_type 'sudo -k; sudo id\r'                    # forgotten: asked again
    serial_wait "Password for anna: " 2
    serial_type 'not-hers\r'
    n=$((n + 1)); prompt_wait $n 30
    # (68d) the password one line: what follows is the command's; none: said
    answer_lines 'echo anna-pw-1 > /tmp/in; echo from the pipe >> /tmp/in' 'sudo cat < /tmp/in' \
                 'sudo -k; sudo true < /dev/null; echo none-rc=$?'
    # (41h-7) anna, through sudo, puts herself in nopassword: never asked
    answer_lines "echo anna-pw-1 > /tmp/pw; sudo sh -c 'echo nopassword = anna >> /system/config/sudo' < /tmp/pw" \
                 'sudo -k; sudo id; echo nopw-rc=$?'
    serial_type 'su bob\r'
    serial_wait "Password: " 2
    serial_type 'bob-pw-1\r'
    n=$((n + 1)); prompt_wait $n 30                     # bob's shell
    answer_lines 'id' 'exit' 'id'                       # bob; back to anna; anna
    serial_type 'su\r'
    serial_wait "Password: " 3
    serial_type 'wrong\r'
    n=$((n + 1)); prompt_wait $n 30
    serial_type 'exit\r'
    login_wait 3
    serial_type 'bob\r'
    serial_wait "Password: " 4
    serial_type 'bob-pw-1\r'
    serial_wait "[bob logged in]" 1 30
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'sudo id'
}

sudo_shell_test() {
    local image before
    image=$(make_image ${P}sudo "")
    before=$failures
    SERIAL_SCRIPT=sudo_session
    boot ${P}sudo "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    check "su is root's and setuid" "$(command_output "ls -l /system/$ARCH_NAME/bin/su")" \
          eval 'command_output "ls -l /system/$ARCH_NAME/bin/su" | grep -q "^-rwsr-xr-x   1     0     0 "'
    expect_line "uid=0(root) gid=0"
    compare "sudo again within 5 minutes: no password asked (68e)" "uid=0(root) gid=0" \
            "$(command_output 'sudo id' 2)"
    check "anna asked for her password 5 times: not at the remembered sudo (68e), nor in nopassword (41h-7)" \
          "asked $(grep -ac 'Password for anna: ' <<<"$TEXT") times" \
          test "$(grep -ac 'Password for anna: ' <<<"$TEXT")" = 5
    compare "in nopassword: sudo asks nothing (41h-7)" "$(printf 'uid=0(root) gid=0\nnopw-rc=0')" \
            "$(command_output 'sudo -k; sudo id; echo nopw-rc=$?')"
    expect_line "sudo: wrong password"
    expect_line "from the pipe"                     # (68d) after the password's line: cat's input
    expect_line "sudo: no password given"
    expect_line "none-rc=1"
    compare "su bob: his shell" "uid=1001(bob) gid=1001" "$(command_output 'id' 1)"
    compare "exit: anna again" "uid=1000(anna) gid=1000" "$(command_output 'id' 2)"
    expect_line "su: wrong password"
    expect_line "sudo: bob may not run commands as root (not in /system/config/sudo)"
    check "bob was not asked for a password" "asked" \
          test "$(grep -c 'Password for bob' <<<"$TEXT")" = 0
    reject "panic"
    show_log_on_failure $before
}

# noterminal_session / noterminal_shell_test: a session without a terminal
# (49k, from the security audit). A command run over SSH without a terminal
# shares sshd's console terminal; a new session made from it could take the
# console's foreground (the logged-in user's typing, login's password
# prompt) and with it pass the "at the console" check for the screen and
# keyboard. The test program makes such a session (its input a pipe): the
# foreground, the echo, the screen as user 1000 and the sound device as user
# 1000 are refused, and the console's shell goes on. sudo's log line keeps a
# line break in a command's name as '?' (one line, none forged). Proven by
# a kernel that keeps the console for such a session and a sudo that logs
# the name as it is. (65e) Any process of the session the terminal belongs
# to may hand its foreground on (POSIX), but a member of another session
# sharing the console may not (`noterminal shared`; proven by a kernel that
# lets any process with a terminal: "allowed").
noterminal_session() {
    local n=1 t="/system/$ARCH_NAME/test"
    prompt_wait $n
    answer_lines "$t/noterminal" "$t/noterminal sudo" "$t/noterminal shared" "$t/logtest take" \
                 'echo still here'
}

noterminal_shell_test() {
    local image before
    image=$(make_image ${P}noterminal "")
    QEMU_EXTRA="-device intel-hda -device hda-output,audiodev=snd -audiodev none,id=snd"
    before=$failures
    SERIAL_SCRIPT=noterminal_session
    boot ${P}noterminal "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect_line "noterminal: console foreground: refused (Operation not permitted)"
    expect_line "noterminal: console echo off: refused (Operation not permitted)"
    expect_line "noterminal: screen and keyboard as user 1000: refused (Operation not permitted)"
    expect_line "noterminal: sound device as user 1000: refused (Permission denied)"
    expect_line "noterminal: done"
    expect_line "noterminal: console foreground from another session sharing the console: refused (Operation not permitted)"
    expect_line "noterminal: shared done"
    expect "may not run commands as root (x?sudo: FORGED refused)"
    check "no line of the caller's in the log" \
          "$(grep -cE '^login: [0-9-]+ [0-9:]+ sudo: FORGED' <<<"$TEXT") forged line(s)" \
          test "$(grep -cE '^login: [0-9-]+ [0-9:]+ sudo: FORGED' <<<"$TEXT")" = 0
    compare "the console's shell goes on" "still here" "$(command_output 'echo still here')"
    reject "panic"
    show_log_on_failure $before
}

# setuid_session / setuid_shell_test: the setuid bit (50b, the user's choice
# for su and sudo). Root copies id to /test/rid and sets 4755 (ls -l: rws);
# a copy given to anna by chown loses the bit; a snapshot is taken. anna runs
# /test/rid: her real user and root as the effective one (uid=1000(anna)
# euid=0(root)); the same file in the snapshot runs as her alone (setuid
# counts only on the system's own file system); plain id shows her; she
# cannot change root's file's mode. Proven by a kernel ignoring the bit.
setuid_session() {
    local n=1 t="/system/$ARCH_NAME/bin"
    prompt_wait $n
    answer_lines "cp $t/id /test/rid" 'chmod 4755 /test/rid' 'ls -l /test/rid' 'useradd anna'
    serial_type 'passwd anna\r'
    serial_wait "New password: " 1
    serial_type 'anna-pw-1\r'
    serial_wait "Again: " 1
    serial_type 'anna-pw-1\r'
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'cp /test/rid /test/aid' 'chmod 4755 /test/aid' 'chown 1000:1000 /test/aid' \
                 'ls -l /test/aid' 'chmod 4755 /test/aid' 'cp /test/aid /test/acopy' \
                 'ls -l /test/acopy' 'snapshot create before'
    serial_type 'exit\r'
    login_wait 2
    serial_type 'anna\r'
    serial_wait "Password: " 1
    serial_type 'anna-pw-1\r'
    serial_wait "[anna logged in]" 1 30
    n=$((n + 1)); prompt_wait $n 30
    answer_lines '/test/rid' '/.snapshots/before/test/rid' 'id' 'chmod 755 /test/rid'
}

setuid_shell_test() {
    local image before
    image=$(make_image ${P}setuid "")
    before=$failures
    SERIAL_SCRIPT=setuid_session
    boot ${P}setuid "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    check "root's copy with 4755 shows rws" "$(command_output 'ls -l /test/rid')" \
          eval 'command_output "ls -l /test/rid" | grep -q "^-rwsr-xr-x   1     0     0 "'
    check "chown took the bit away" "$(command_output 'ls -l /test/aid' 1)" \
          eval 'command_output "ls -l /test/aid" 1 | grep -q "^-rwxr-xr-x   1  1000  1000 "'
    check "root's instant copy of anna's 4755 file: root's, without the bit (49k)" \
          "$(command_output 'ls -l /test/acopy')" \
          eval 'command_output "ls -l /test/acopy" | grep -q "^-rwxr-xr-x   1     0     0 "'
    compare "anna runs root's setuid id" "uid=1000(anna) euid=0(root) gid=1000" \
            "$(command_output '/test/rid')"
    compare "the same file in a snapshot: not setuid" "uid=1000(anna) gid=1000" \
            "$(command_output '/.snapshots/before/test/rid')"
    compare "plain id" "uid=1000(anna) gid=1000" "$(command_output 'id')"
    expect_line "chmod: /test/rid: Operation not permitted"
    reject "panic"
    show_log_on_failure $before
}

# links_session / links_shell_test: symbolic and hard links (57a, the
# user's names: SYS_SYMLINK 95, SYS_READLINK 96, SYS_LSTAT 97, SYS_LINK 98,
# ln, readlink): a relative and an absolute link, ls and ls -l showing
# them, a link to a folder (cd ends up in the folder itself), ".." after
# a link leaving its target's folder (POSIX), a loop (ELOOP), a dangling
# link and writing through it, rm of a link (the target stays) and rm -r
# through a link to a folder (the folder stays), hard links (one file, two
# names, the count, a folder refused), test -L, readlink -f; then as anna:
# a link inside a folder she may not search does not lead her out of it,
# nor does "..". 57b: the folders mkdisk makes (/bin, /usr/bin, /lib, /etc
# links, /tmp 1777 sticky): a #!/bin/sh script, /usr/bin/env, /etc's files,
# ls -l showing t; as anna in /tmp: her own file goes, root's can neither
# be removed nor renamed. 63b: rm -f (a missing file is no error, nothing
# printed; -rf together; rm -f alone). The host checker must find the disk clean
# afterwards. Proven by a resolver that skipped the folders' search right
# (57a) and a kernel without the sticky check (57b).
links_lines() {
    LINKS_ROOT=(
        'mkdir /home/root/l; echo hello > /home/root/l/f; ln -s f /home/root/l/s; cat /home/root/l/s'
        'ls /home/root/l'
        'readlink /home/root/l/s'
        'ln -s /home/root/l /home/root/dl; ls /home/root/dl; cd /home/root/dl; pwd; cd /'
        'mkdir /home/root/a /home/root/a/b; echo deep > /home/root/a/x; ln -s ../x /home/root/a/b/up; cat /home/root/a/b/up'
        'ln -s /home/root/a/b /home/root/jump; cat /home/root/jump/../x'
        'ln -s loop1 /home/root/loop2; ln -s loop2 /home/root/loop1; cat /home/root/loop1'
        'ln -s nowhere /home/root/dang; cat /home/root/dang'
        'ls -l /home/root/dang'
        'echo made > /home/root/dang; cat /home/root/nowhere'
        'rm /home/root/l/s; cat /home/root/l/f; ls /home/root/l'
        'rm -r /home/root/dl; ls /home/root/l'
        'ln /home/root/l/f /home/root/hard; echo more >> /home/root/hard; cat /home/root/l/f'
        'ls -l /home/root/hard'
        'rm /home/root/l/f; cat /home/root/hard; ls -l /home/root/hard'
        'ln /home/root/l /home/root/hd'
        '[ -L /home/root/dang ] && echo a link; [ -L /home/root/hard ] || echo not a link'
        'readlink -f /home/root/jump/../x'
        'mkdir /secret; echo s > /secret/x; chmod 700 /secret; ln -s /test/hello.txt /secret/out; ln -s /secret/x /test/peek'
        "echo '#!/bin/sh' > /tmp/s; echo 'echo via bin sh' >> /tmp/s; chmod 755 /tmp/s; /tmp/s"
        '/usr/bin/env echo through usr bin'
        'grep -c = /etc/services'
        'ls -l / | grep tmp'
        'echo mine > /tmp/root.txt; [ -k /tmp ] && echo sticky'
        'rm -f /home/root/none; echo rc $?'
        'mkdir /home/root/rf; echo x > /home/root/rf/y; rm -rf /home/root/rf /home/root/none; [ -e /home/root/rf ] || echo gone'
        'rm -f; echo rc $?'
    )
    LINKS_ANNA=(
        'cat /secret/out'
        'cat /secret/../test/hello.txt'
        'cat /test/peek'
        'cat /test/hello.txt'
        'echo hers > /tmp/anna.txt; rm /tmp/anna.txt && echo removed'
        'rm /tmp/root.txt'
        'mv /tmp/root.txt /tmp/taken.txt'
        'echo hers > /tmp/a2.txt; mv /tmp/a2.txt /tmp/root.txt'
        'echo one > /tmp/a3.txt; echo two > /tmp/a4.txt; mv /tmp/a4.txt /tmp/a3.txt; cat /tmp/a3.txt'
    )
}
links_session() {
    local n=1
    links_lines
    prompt_wait $n
    answer_lines "${LINKS_ROOT[@]}" 'useradd anna'
    serial_type 'passwd anna\r'
    serial_wait "New password: " 1
    serial_type 'anna-pw-1\r'
    serial_wait "Again: " 1
    serial_type 'anna-pw-1\r'
    n=$((n + 1)); prompt_wait $n 30
    serial_type 'exit\r'
    login_wait 2
    serial_type 'anna\r'
    serial_wait "Password: " 1
    serial_type 'anna-pw-1\r'
    serial_wait "[anna logged in]" 1 30
    n=$((n + 1)); prompt_wait $n 30
    answer_lines "${LINKS_ANNA[@]}"
}

links_shell_test() {
    local image before
    links_lines
    image=$(make_image ${P}links "")
    before=$failures
    SERIAL_SCRIPT=links_session
    boot ${P}links "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    local i=0
    for want in 'hello' $'         6  f\n    <link>  s -> f' 'f' \
                $'         6  f\n    <link>  s -> f\n/home/root/l' 'deep' 'deep' \
                $'cat: /home/root/loop1: Too many levels of symbolic links\ncat: exit code 1' \
                $'cat: /home/root/dang: No such file or directory\ncat: exit code 1' \
                'lrwxrwxrwx   1     0     0          7  /home/root/dang -> nowhere' 'made' \
                $'hello\n         6  f' '         6  f' $'hello\nmore' \
                '-rw-r--r--   2     0     0         11  /home/root/hard' \
                $'hello\nmore\n-rw-r--r--   1     0     0         11  /home/root/hard' \
                $'ln: /home/root/hd: Operation not permitted\nln: exit code 1' $'a link\nnot a link' '/home/root/a/x' '' \
                'via bin sh' 'through usr bin' \
                "$(python3 "$ROOT/scripts/settingstext.py" SERVICES | grep -c =)" \
                'drwxrwxrwt   1     0     0      <dir>  tmp/' 'sticky' 'rc 0' 'gone' 'rc 0'; do
        compare "root $i: ${LINKS_ROOT[$i]:0:40}" "$want" "$(command_output "${LINKS_ROOT[$i]}")"
        i=$((i + 1))
    done
    i=0
    for want in $'cat: /secret/out: Permission denied\ncat: exit code 1' \
                $'cat: /secret/../test/hello.txt: Permission denied\ncat: exit code 1' \
                $'cat: /test/peek: Permission denied\ncat: exit code 1' 'Hello from RitterFS!' 'removed' \
                $'rm: /tmp/root.txt: Operation not permitted\nrm: exit code 1' \
                $'mv: /tmp/root.txt -> /tmp/taken.txt: Operation not permitted\nmv: exit code 1' \
                $'mv: /tmp/a2.txt -> /tmp/root.txt: Operation not permitted\nmv: exit code 1' 'two'; do
        compare "anna $i: ${LINKS_ANNA[$i]}" "$want" "$(command_output "${LINKS_ANNA[$i]}")"
        i=$((i + 1))
    done
    check "the host checker finds the disk clean" "$($RFS check "$image" 133120 1961984 2>&1 | tail -1)" \
          eval '$RFS check "$image" 133120 1961984 > /dev/null 2>&1'
    reject "panic"
    show_log_on_failure $before
}

# regex_session / regex_shell_test: regex.h (58a, the user's: POSIX BRE
# and ERE in the C library). user/test/regextest is plain POSIX, built on
# the Mac too; its "regextest:" lines must be the Mac's: BRE (\( \) \{ \}
# back references, * as a plain one at the start, ^ and $ only at the
# ends), ERE (| + ? {m,n}, leftmost-longest: a|ab takes ab), sets and
# classes, REG_ICASE, REG_NEWLINE, REG_NOTBOL, REG_NOSUB, the errors POSIX
# names. Cases POSIX leaves open (ambiguous groups, empty branches) and
# where the Mac's own library errs (checked by brute force on the Mac in
# 58a: it broke the leftmost rule in 41 of 30,000 random cases) are left
# out; "regextest-own:" has back references in ERE. Proven by a regexec
# that kept the first match's end instead of the longest.
regex_session() {
    local n=1
    prompt_wait $n
    answer_lines "/system/$ARCH_NAME/test/regextest"
}

regex_shell_test() {
    local image before mac="$WORK/${P}regextest-mac"
    image=$(make_image ${P}regex "")
    before=$failures
    SERIAL_SCRIPT=regex_session
    boot ${P}regex "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    check "regextest builds on the Mac" "the Mac cannot build it" \
          eval 'cc -w -o "$mac" "$ROOT/user/test/regextest.c"'
    compare "every line as on the Mac" "$("$mac" | grep '^regextest: ')" \
            "$(command_output "/system/$ARCH_NAME/test/regextest" | grep '^regextest: ')"
    expect_line 'regextest-own: (.)\1 in ERE on abbc: 1-3'
    reject "panic"
    show_log_on_failure $before
}

# grep_session / grep_shell_test: the program grep (50a). The same files are
# on the test disk (/test/g) and in a folder on the Mac; every command runs
# in both places and the guest's output must be the Mac's /usr/bin/grep's
# (with the shell's "grep: exit code N" line after a non-zero end): plain
# text, -i -v -n -c -l, ^ $ . * [set] [^set], several files, a missing
# file, standard input, -r (sorted: folders list in their own order). A
# binary file says "binary file matches" in our words. Since 58a on regex.h,
# and -E: | + ? ( ) {m} and the [:class:] sets. Proven by a grep whose `*`
# takes one or more instead of none or more (50a; regex.h's own proof is the
# regex test's). (68f) -q -s -x -F -e -f (several patterns, a pattern file,
# an empty one, -x through regexec's longest match); -q ends at the first
# match as GNU's (the Mac's goes on to the next files: our own check).
# Proven by -x taking any match and -q going on.
GREP_CASES=('grep hello a.txt' 'grep -i hello a.txt' 'grep -v hello a.txt' 'grep -n o a.txt'
            'grep -c o a.txt' "grep '^a' a.txt" "grep '3\$' a.txt" "grep 'a.b' a.txt"
            "grep 'a*b' a.txt" "grep 'x[0-9][0-9]*' a.txt" "grep '[^a-z]' a.txt"
            "grep 'ab*c' a.txt" 'grep hello a.txt b.txt' 'grep -l hello a.txt b.txt'
            'grep -c hello a.txt b.txt' 'grep -in WORLD a.txt' 'grep zzz a.txt'
            'grep hello nosuch.txt' 'grep -n two < a.txt' "grep '^\$' a.txt"
            "grep -E 'ab|xy' a.txt" "grep -E 'x[0-9]+' a.txt" "grep -E '^(one|two)' a.txt"
            "grep -E 'o{2}' a.txt" "grep -cE 'l+' a.txt" "grep -iE 'HELLO|xyz' a.txt"
            "grep -E 'a?b\$' a.txt" "grep '[[:digit:]][[:digit:]]*' a.txt"
            'grep -q hello a.txt' 'grep -q zzz a.txt' 'grep -q hello nosuch.txt a.txt'
            'grep -s hello nosuch.txt' 'grep -s hello nosuch.txt a.txt' 'grep -x two a.txt'
            'grep -F a.b a.txt' "grep -F 'end\$' a.txt" 'grep -e hello -e two a.txt'
            'grep -f p.txt a.txt' 'grep -xF two a.txt' 'grep -iF HELLO a.txt'
            'grep -c -e x -e y a.txt' "grep -e '' b.txt" 'grep -vx two a.txt' 'grep -ehello a.txt'
            'grep -f empty.txt a.txt' "grep -xE 'one|two' a.txt" "grep -x '' a.txt"
            'grep -nF -f p.txt a.txt' 'grep -lq hello a.txt b.txt' 'grep -f nosuch.txt a.txt'
            'grep -cvF o a.txt' "grep -x 'a*b' a.txt" 'grep -ixF "HELLO WORLD" a.txt')
grep_session() {
    local n=1 c
    prompt_wait $n
    answer_lines 'cd /test/g' "${GREP_CASES[@]}" 'grep -r hello .' 'grep hello bin.dat' \
                 'grep -q hello a.txt nosuch.txt' 'grep -e'
}

grep_shell_test() {
    local image before c want got d="$WORK/${P}grep.d"
    image=$(make_image ${P}grep "")
    rm -rf "$d"; mkdir -p "$d/sub"
    printf 'hello world\nHello World\nfoo bar\n\nabc123\nxyz\nx42\na.b\naaab\nend$\ntwo\none two\n' >"$d/a.txt"
    printf 'second file hello\nnothing\n' >"$d/b.txt"
    printf 'deep hello\n' >"$d/sub/c.txt"
    printf 'bin\000ary hello\n' >"$d/bin.dat"
    printf 'hello\ntwo\n' >"$d/p.txt"
    : >"$d/empty.txt"
    for f in a.txt b.txt sub/c.txt bin.dat p.txt empty.txt; do
        $RFS put "$image" $RFS_PART "/test/g/$f" "$d/$f" >/dev/null || exit 1
    done
    before=$failures
    SERIAL_SCRIPT=grep_session
    boot ${P}grep "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    for c in "${GREP_CASES[@]}"; do
        want=$(cd "$d" && eval "/usr/bin/${c}" 2>&1; rc=$?; [ $rc -ne 0 ] && echo "grep: exit code $rc")
        compare "$c (as the Mac's grep)" "$want" "$(command_output "$c")"
    done
    want=$(cd "$d" && /usr/bin/grep -r hello . 2>/dev/null | grep -v '^Binary' | sort)
    got=$(command_output 'grep -r hello .' | grep -v 'binary file' | sort)
    compare "grep -r hello . (sorted, as the Mac's)" "$want" "$got"
    expect_line "grep: ./bin.dat: binary file matches"
    compare "a binary file" "grep: bin.dat: binary file matches" "$(command_output 'grep hello bin.dat')"
    compare "-q ends at the first match (the next file not looked at)" "" \
            "$(command_output 'grep -q hello a.txt nosuch.txt')"
    want_text want <<'LINES'
grep: -e needs an argument
usage: grep [-EFcilnqrsvx] [-e PATTERN]... [-f FILE]... [PATTERN] [FILE...]
grep: exit code 2
LINES
    compare "-e without its pattern" "$want" "$(command_output 'grep -e')"
    reject "panic"
    show_log_on_failure $before
}

# sed_session / sed_shell_test: sed (58b, the user's: POSIX plus -E and -i).
# The same files and scripts are in /test/s and in a folder on the Mac; each
# command runs in both places and the guest's output must be the Mac's
# /usr/bin/sed's: addresses (numbers, $, /re/, \cREc, ranges, +N, !),
# p d s (g, N, p, &, groups, -E) y = l q n N D G H h x, a i c, groups { },
# labels (b, t), -n -e -f. Scripts with backslashes are files (-f): typed
# text has its backslashes read twice. Then RitterOS's own: -i (also with a
# suffix, and a second hard link sees the edit). Proven by a sed whose s///g
# replaced only the first match.
SED_CASES=('sed p n.txt' 'sed -n p n.txt' 'sed -n 3p n.txt' "sed -n '\$p' n.txt" "sed -n '2,4p' n.txt"
           "sed -n '/three/,/six/p' n.txt" "sed -n '/six/,2p' n.txt" "sed '3,\$d' n.txt"
           "sed '2!d' n.txt" "sed -n '2,4!p' n.txt" "sed 's/o/0/' t.txt" "sed 's/o/0/g' t.txt"
           "sed 's/o/0/2' t.txt" "sed -E 's/(foo) (bar)/<&>/' t.txt" "sed 's/[a-z]*/<&>/g' t.txt"
           "sed 's/b*/-/g' t.txt" "sed 's|o|/|g' t.txt" "sed -n 's/=/ is /p' t.txt"
           "sed 's/x/X/;s/y/Y/' t.txt" "sed -e 's/a/A/' -e 's/b/B/' t.txt" 'sed -f a.sed n.txt'
           'sed -f b.sed n.txt' 'sed -f join.sed n.txt' 'sed -f tac.sed n.txt' 'sed -f pd.sed n.txt'
           'sed -f groups.sed t.txt' 'sed -f interval.sed t.txt' 'sed -f nl.sed n.txt'
           'sed -n -f comma.sed n.txt' 'sed -f newline.sed t.txt' 'sed = n.txt' "sed -n '\$=' n.txt"
           "sed 'y/abc/xyz/' t.txt" 'sed -n l t.txt' "sed '/^\$/d' t.txt" 'sed 5q n.txt'
           "sed -n '/e/{p;p;}' n.txt" "sed '/e/!s/^/#/' n.txt" "sed 'n;d' n.txt"
           "sed -n 'h;n;G;p' n.txt" "sed -E 's/[0-9]+/[&]/g' t.txt" "sed -E 's/(a|b)+/X/g' t.txt"
           "sed -n '/^[[:upper:]]/p' t.txt" "sed '2,3s/^/> /' n.txt" "sed 's/e\$/E/' n.txt"
           "sed '1d;\$d' n.txt" "sed 's/x/&&/g' t.txt" "sed -n '/one/,+2p' n.txt" 'sed p < n.txt')
SED_OWN=("cp /test/s/n.txt /tmp/m.txt; sed -i 's/one/ONE/' /tmp/m.txt; head -n 2 /tmp/m.txt"
         "sed -i.bak 3d /tmp/m.txt; wc -l < /tmp/m.txt | tr -d ' '; wc -l < /tmp/m.txt.bak | tr -d ' '"
         "ln /tmp/m.txt /tmp/h.txt; sed -i s/two/2/ /tmp/m.txt; grep 2 /tmp/h.txt")
sed_session() {
    local n=1
    prompt_wait $n
    answer_lines 'cd /test/s' "${SED_CASES[@]}" "${SED_OWN[@]}"
}

sed_shell_test() {
    local image before c want d="$WORK/${P}sed.d"
    image=$(make_image ${P}sed "")
    rm -rf "$d"; mkdir -p "$d"
    printf 'one\ntwo\nthree\nfour\nfive\nsix\nseven\neight\nnine\nten\n' > "$d/n.txt"
    printf 'hello world\nfoo bar baz\naaa bbb\n\nkey=value\nx=1 y=2\nTab\there\nlast line\n' > "$d/t.txt"
    printf 's/o/0/g\n/^t/d\n' > "$d/a.sed"
    printf '/two/a\\\nadded after two\n/four/i\\\ninserted before four\n/six/c\\\nchanged six\n' > "$d/b.sed"
    printf ':a\nN\n$!ba\ns/\\n/,/g\n' > "$d/join.sed"
    printf '1!G\nh\n$!d\n' > "$d/tac.sed"
    printf '$!N\nP\nD\n' > "$d/pd.sed"
    printf 's/\\(foo\\) \\(bar\\)/\\2 \\1/\n' > "$d/groups.sed"
    printf 's/a\\{2\\}/Z/\n' > "$d/interval.sed"
    printf '$!N;s/\\n/ /\n' > "$d/nl.sed"
    printf '\\,two,p\n' > "$d/comma.sed"
    printf 's/o/\\\n/\n' > "$d/newline.sed"
    for f in n.txt t.txt a.sed b.sed join.sed tac.sed pd.sed groups.sed interval.sed nl.sed comma.sed newline.sed; do
        $RFS put "$image" $RFS_PART "/test/s/$f" "$d/$f" >/dev/null || exit 1
    done
    before=$failures
    SERIAL_SCRIPT=sed_session
    boot ${P}sed "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    for c in "${SED_CASES[@]}"; do
        want=$(cd "$d" && eval "/usr/bin/${c}" 2>&1; rc=$?; [ $rc -ne 0 ] && echo "sed: exit code $rc")
        compare "$c (as the Mac's sed)" "$want" "$(command_output "$c")"
    done
    compare "sed -i" $'ONE\ntwo' "$(command_output "${SED_OWN[0]}")"
    compare "sed -i.bak: the file and its backup" $'9\n10' "$(command_output "${SED_OWN[1]}")"
    compare "sed -i: a second name of the file sees the edit" '2' "$(command_output "${SED_OWN[2]}")"
    reject "panic"
    show_log_on_failure $before
}

# awk_session / awk_shell_test: awk (58c, the user's: POSIX's). The same
# files are in /test/a and in a folder on the Mac; every program runs in
# both places and the guest's output must be the Mac's /usr/bin/awk's (the
# One True AWK): fields and FS (-F, one character, an ERE, tabs), records
# and RS (one character, paragraphs), patterns and ranges, the operators
# and their precedence, number and string comparisons, conversions (OFMT,
# CONVFMT), arrays (SUBSEP, in, delete, for-in), functions (recursion,
# arrays by reference, locals), every built-in function, printf's
# conversions, getline in its forms, pipes to and from commands, output
# to files, -v, -f, ARGV, FILENAME, next, nextfile, exit. Typed with % and
# \ doubled (typed_form). Left out are the cases where the Mac's awk is not
# POSIX's or refuses what gawk takes (they were checked on the Mac when
# awk was written: substr's rounding, cmd | getline's NR, %x of negative
# numbers, concatenated redirection targets). Proven by an awk whose
# field splitting on " " also split on single blanks (no runs).
awk_lines() {
    AWK_LINES=()
    local line
    while IFS= read -r line; do
        AWK_LINES+=("$line")
    done <<'LINES'
awk '{ print $(NF-1) }' p.txt
awk '{ $7 = "z"; print NF; print }' c.txt
awk '{ print ($2 < 100), ($2 < "100") }' p.txt
awk 'BEGIN { print "3x" + 1, "1e3" + 0, " 12 " + 0, ".5" + 0, "+4" + 0 }'
awk 'BEGIN { printf "%.3s|%5s|%-3s|%i\n", "abcdef", "toolongstring", "a", 12.9 }'
awk -F'\t' '{ print $2 }' tab.txt
awk -Ft '{ print $3 }' tab.txt
awk 'BEGIN { FS = "[,;]" } { print $2, NF }' sep.txt
awk 'BEGIN { RS = ";" } { print NR": "$0 }' rs.txt
awk '{ print NF, $1 }' sp.txt
awk '{ n = split($0, a); print n, a[1] }' sp.txt
awk 'BEGIN { n = split("  x  y ", a); print n, "[" a[1] "]" }'
awk 'BEGIN { n = split("a b", a, / /); print n }'
awk 'FNR == 1 { print FILENAME }' p.txt c.txt
awk 'BEGIN { ARGV[1] = "c.txt" } { print }' p.txt
awk 'BEGIN { ARGV[2] = ""; } { print FILENAME; nextfile }' p.txt c.txt
awk 'NR == 2 { nextfile } { print FILENAME, $0 }' c.txt p.txt
awk -v 'msg=hello\tthere' 'BEGIN { print msg }'
awk -f more.awk
awk 'END { $0 = "a b c"; print NF; exit 4 } END { print "not reached" }' p.txt
awk '{ a[$3] += $2 } END { for (k in a) if (k == "paris") print k, a[k] }' p.txt
awk 'BEGIN { x = y = 3; print x, y }'
awk 'BEGIN { a["k"] = 1; for (k in a) delete a[k]; print length(a) }'
awk 'BEGIN { n = 0; while ((getline l < "nosuch") > 0) n++; print n, (getline l < "nosuch") }'
awk '{ getline l < "c.txt"; print NR, l }' p.txt
awk 'NR == 1 { while ((getline line) > 0) last = line } END { print last, NR }' p.txt
awk 'BEGIN { srand(42); a = srand(7); print a }'
awk 'BEGIN { print int(12345678901234), 2147483648 * 2, 1e15 + 1 }'
awk 'BEGIN { print length(12345), length(1/4) }'
awk 'BEGIN { x = "abc"; print x ~ "b", x ~ /^a.c$/, "a.c" ~ /a\.c/, "abc" ~ "a\\.c" }'
awk 'BEGIN { print 1 - 1 " " 2, 1 " " -1 }'
awk '{ $2 = ""; print; print NF }' c.txt
awk 'BEGIN { OFS = ":" } { NF = 2; print }' p.txt
awk 'BEGIN { OFS = "-" } { print $1, $2 }' p.txt
awk 'BEGIN { ORS = "|" } { print $1 } END { printf "\n" }' p.txt
awk '{ sub(/$/, "!"); print }' c.txt
awk '{ gsub(/^/, ">"); print }' c.txt
awk 'BEGIN { s = "banana"; print gsub(/ana/, "X", s), s }'
awk 'BEGIN { s = "aaa"; sub(/a/, "\\&", s); print s }'
awk 'BEGIN { s = "hello"; gsub(/l/, "\\\\&", s); print s }'
awk 'BEGIN { s = "x"; print match(s, /y/), RSTART, RLENGTH }'
awk 'BEGIN { print toupper(123), tolower("MiXeD") }'
awk 'BEGIN { printf "%5.1e|%G|%g\n", 123456, 0.0001, 100000000 }'
awk 'BEGIN { printf "[%c]\n", "" }'
awk 'BEGIN { print -0, 0 * -1 }'
awk 'BEGIN { print 1e300 * 1e300 > "/dev/stdout" }'
awk 'BEGIN { "date +%Y" | getline y; print (y > 2000) }'
awk 'BEGIN { cmd = "cat"; print "piped" | cmd; r = close(cmd); print "closed", r }'
awk 'BEGIN { print close("never-opened") }'
awk 'BEGIN { if (!(3 in a)) print "absent"; a[3]; if (3 in a) print "present" }'
awk 'BEGIN { i = 1; a[i++] = i; for (k in a) print k, a[k] }'
awk '/a/ && /e/' p.txt
awk '/a/ || $2 > 35 { n++ } END { print n }' p.txt
awk '!/a/' p.txt
awk 'NR > 1 && NR < 4 { print NR }' p.txt
awk '{ print NR % 2 ? "odd" : "even" }' p.txt
awk '$2 ~ "^[0-9]+$" { s += $2 } END { print s }' p.txt
awk 'BEGIN { x[1]; x[2]; n = 0; for (k in x) n += k; print n }'
awk 'BEGIN { print substr("abc", 2, -1) "|" substr("", 1, 5) "|" }'
awk 'BEGIN { print index("", "") , index("a", "") }'
awk 'BEGIN{print 1;print 2}'
awk 'BEGIN { if (1) { print "a" } else { print "b" } }'
awk 'BEGIN { if (0) print "a"; else print "b" }'
awk 'BEGIN { for (;;) { if (++n > 3) break }; print n }'
awk 'BEGIN { getline line < "c.txt"; print line; getline line < "c.txt"; print line }'
awk '{ print } END { print NR }' /dev/null
awk '{ print $1 }' p.txt
awk '{ print $2, $1 }' p.txt
awk '$2 > 28' p.txt
awk '$3 == "paris" { print NR": "$1 }' p.txt
awk '{ s += $2 } END { print s, s / NR }' p.txt
awk 'NR == 2, NR == 4' p.txt
awk '/bob/,/dave/ { print $1 }' p.txt
awk -F: '{ print $2 }' c.txt
awk -F: '{ print NF }' c.txt
awk 'BEGIN { FS = ":" } { $2 = "X"; print }' c.txt
awk 'BEGIN { FS = ":"; OFS = "-" } { $1 = $1; print }' c.txt
awk '{ print length($1), length }' p.txt
awk '{ print substr($1, 2, 3) }' p.txt
awk '{ print substr($1, 2) }' p.txt
awk '{ print index($1, "a") }' p.txt
awk '{ print toupper($1), tolower("ABC") }' p.txt
awk '{ n = split($0, a, " "); print n, a[3] }' p.txt
awk 'BEGIN { n = split("a,b,,c", a, ","); print n, a[4] }'
awk 'BEGIN { n = split("a1b22c", a, /[0-9]+/); print n, a[1] a[2] a[3] }'
awk '{ sub(/a/, "A"); print }' p.txt
awk '{ gsub(/[aeiou]/, "_"); print }' p.txt
awk '{ n = gsub(/o/, "&&"); print n, $0 }' p.txt
awk 'BEGIN { s = "hello"; gsub(/l/, "[&]", s); print s }'
awk 'BEGIN { s = "aaa"; gsub(/x*/, "-", s); print s }'
awk '{ if (match($0, /[0-9]+/)) print RSTART, RLENGTH }' p.txt
awk 'BEGIN { printf "%5.2f|%-5d|%05d|%x|%o|%e|%c|%s\n", 3.14159, 42, 42, 255, 8, 1234.5, 65, "str" }'
awk 'BEGIN { printf "%c%c\n", "hello", 66 }'
awk 'BEGIN { printf "%*d|%.*f\n", 6, 7, 2, 3.14159 }'
awk 'BEGIN { x = sprintf("%03d-%s", 7, "z"); print x }'
awk 'BEGIN { print 1 / 3, 2 ^ 10, 2 ** 3, 7 % 3, -7 % 3, int(-3.7), int(3.7) }'
awk 'BEGIN { print 0.1 + 0.2, 1e6, 100000 * 100000, 3.0 }'
awk 'BEGIN { OFMT = "%.2f"; x = 3.14159; print x; y = x ""; print y }'
awk 'BEGIN { CONVFMT = "%.2f"; x = 3.14159; y = x ""; print y }'
awk 'BEGIN { print length("abc") , length() }'
awk 'BEGIN { print sqrt(16), exp(0), log(1), sin(0), cos(0), atan2(0, 1) }'
awk 'BEGIN { a["x"] = 1; a["y"] = 2; delete a["x"]; for (k in a) print k, a[k]; print ("x" in a), ("y" in a) }'
awk 'BEGIN { a[1,2] = 3; for (k in a) { split(k, p, SUBSEP); print p[1], p[2] }; print ((1,2) in a) }'
awk 'BEGIN { x = "10"; y = 9; print (x > y), ("10" > "9") }'
awk '{ print ($1 > "c") }' p.txt
awk '$2 ~ /^3/' p.txt
awk '$1 !~ /e/' p.txt
awk 'BEGIN { re = "^[a-c]"; } $0 ~ re' p.txt
awk '{ print NR, NF, FNR }' p.txt c.txt
awk 'END { print NR, $0 }' p.txt
awk 'BEGIN { while (i < 3) { i++; if (i == 2) continue; print i } }'
awk 'BEGIN { do { j++ } while (j < 5); print j }'
awk 'BEGIN { for (i = 0; i < 10; i++) { if (i == 3) break }; print i }'
awk 'NR == 3 { exit } { print }' p.txt
awk 'BEGIN { exit 3 } END { print "end ran" }'
awk '{ print; next; print "never" }' c.txt
awk -f fn.awk
awk -f wc.awk p.txt
awk -v x=5 'BEGIN { print x * 2 }'
awk '{ print x, $1 }' x=1 c.txt x=2 p.txt
awk 'BEGIN { RS = "" } { print NR": "$1" ("NF")" }' para.txt
awk 'BEGIN { RS = ""; FS = ":" } { print NF }' para.txt
awk '{ s = s $0 "," } END { print s }' nums.txt
awk '{ if ($1 > max) max = $1 } END { print max }' nums.txt
awk 'BEGIN { "echo hello there" | getline line; print line; close("echo hello there") }'
awk 'BEGIN { while (("echo a b c" | getline w) > 0) print "got", w }'
awk 'BEGIN { while ((getline l < "c.txt") > 0) n++; print n }'
awk 'NR == 1 { getline; print "after getline:", $0, NR }' p.txt
awk 'NR == 1 { getline x; print "x is", x, NR, $1 }' p.txt
awk 'BEGIN { print "b\na\nc" | "sort"; close("sort"); print "done" }'
awk 'BEGIN { system("echo from system"); print "after" }'
awk 'BEGIN { r = system("exit 3"); print r }'
awk '{ $5 = "new"; print; print NF }' p.txt
awk '{ NF = 2; print }' p.txt
awk 'BEGIN { $0 = "x y z"; print NF, $2 }'
awk 'BEGIN { x["a"]; if ("a" in x) print "yes"; print length(x) }'
awk 'BEGIN { s = "a.b.c"; n = gsub(/\./, "/", s); print n, s }'
awk 'BEGIN { print index("foobar", "bar"), index("foo", "z") }'
awk 'BEGIN { x = 5; x += 2; x -= 1; x *= 3; x /= 2; x %= 5; x ^= 2; print x }'
awk 'BEGIN { i = 5; print i++, i, ++i, i--, --i }'
awk 'BEGIN { print (1, 2) in a }'
awk 'BEGIN { a = "x"; b = a a; print b, length(b) }'
awk 'BEGIN { print -2 ^ 2, 2 ^ -1, 2 ^ 3 ^ 2 }'
awk 'BEGIN { print 1 " " 2, 1 + 2 " " 3 }'
awk '{ printf "%-10s|%5s|\n", $1, $2 }' p.txt
awk 'length($1) > 3' p.txt
awk '!seen[$3]++' p.txt
awk '{ a[NR] = $0 } END { for (i = NR; i > 0; i--) print a[i] }' p.txt
awk 'BEGIN { printf "%d %d\n", "3abc", "x" }'
awk 'BEGIN { print toupper(substr("word", 1, 1)) substr("word", 2) }'
awk '{ $0 = toupper($0); print $1 }' c.txt
awk 'BEGIN { getline; print "first:", $0 }' < p.txt
awk '{ print > "out.txt" } END { close("out.txt"); while ((getline l < "out.txt") > 0) print "read", l }' c.txt
awk 'BEGIN { printf "a\tb\\n\n" }'
awk 'BEGIN { print "x" > "/dev/stderr" }'
awk 'BEGIN { print 10 % 0.3 }'
awk 'BEGIN { n = split("", a); print n, length(a) }'
awk '$1 = $1' c.txt
awk 'BEGIN { FS = "," } { print $2 }' p.txt
awk 'NF' para.txt
awk 'END { print NF }' p.txt
LINES
}
awk_session() {
    local n=1 c
    awk_lines
    prompt_wait $n
    answer_lines 'cd /test/a'
    for c in "${AWK_LINES[@]}"; do
        answer_lines "$(typed_form "$c")"
    done
}

awk_shell_test() {
    local image before c want d="$WORK/${P}awk.d"
    awk_lines
    image=$(make_image ${P}awk "")
    rm -rf "$d"; mkdir -p "$d"
    printf 'alice 30 paris\nbob 25 london\ncarol 35 paris\ndave 40 rome\neve 22 london\n' > "$d/p.txt"
    printf 'a:b:c\n1:2:3\nx::z\n' > "$d/c.txt"
    printf 'line one\nline two\n\nsecond para line\nanother\n\n\nthird\n' > "$d/para.txt"
    printf '10\n2\n33\n4.5\n-7\n' > "$d/nums.txt"
    printf 'a,b;c\nd;e,f\n' > "$d/sep.txt"
    printf 'x\ty\tz\n1\t2\t3\n' > "$d/tab.txt"
    printf 'one;two;three' > "$d/rs.txt"
    printf '  lead  and trail  \n' > "$d/sp.txt"
    cp "$ROOT/scripts/awktest/fn.awk" "$ROOT/scripts/awktest/wc.awk" "$ROOT/scripts/awktest/more.awk" "$d/"
    for f in p.txt c.txt para.txt nums.txt sep.txt tab.txt rs.txt sp.txt fn.awk wc.awk more.awk; do
        $RFS put "$image" $RFS_PART "/test/a/$f" "$d/$f" >/dev/null || exit 1
    done
    before=$failures
    SERIAL_SCRIPT=awk_session
    boot ${P}awk "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    for c in "${AWK_LINES[@]}"; do
        want=$(cd "$d" && eval "/usr/bin/${c}" 2>&1; rc=$?; [ $rc -ne 0 ] && echo "awk: exit code $rc"; rm -f out.txt f_paris f_london f_rome)
        compare "${c:0:60} (as the Mac's awk)" "$want" "$(command_output "$(matched_form "$c")")"
    done
    reject "panic"
    show_log_on_failure $before
}

# make_session / make_shell_test: make (59, the user's: POSIX make with the
# GNU make most Makefiles use). scripts/maketest.py holds the cases --
# variables of every flavor and origin, the functions, conditionals,
# include, pattern, static pattern and suffix rules, the automatic
# variables, $? after a touch, @ - and -s -n -k -i -q, order-only and
# FORCE prerequisites, define, eval, call, export, recursion with -C --
# and the Mac's GNU make (3.81) gives each step's expected output; the
# guest runs the same steps in /test/m/NAME with RitterOS's make. Each
# typed line starts with ": NAME.INDEX" so a repeated make finds its own
# output. (sdk/ritteros.mk itself was compared with GNU make -n on the Mac
# for every target in 59: RitterOS has no compiler for it yet.) Proven by
# a make that never thought a target older than its prerequisites.
make_session() {
    local n=1 name i step
    prompt_wait $n
    while IFS=$'\t' read -r name i step; do
        answer_lines "$(typed_form ": $name.$i; cd /test/m/$name; ${step//MAKE/make}")"
    done < <(python3 "$ROOT/scripts/maketest.py" steps)
}

make_shell_test() {
    local image before d="$WORK/${P}make.d" name i step f want
    image=$(make_image ${P}make "")
    rm -rf "$d"
    python3 "$ROOT/scripts/maketest.py" files "$d/files" || exit 1
    python3 "$ROOT/scripts/maketest.py" expected "$d" || exit 1
    (cd "$d/files" && find . -type f) | while read -r f; do
        $RFS put "$image" $RFS_PART "/test/m/${f#./}" "$d/files/${f#./}" >/dev/null || exit 1
    done
    before=$failures
    SERIAL_SCRIPT=make_session
    boot ${P}make "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    while IFS=$'\t' read -r name i step; do
        want=$(cat "$d/expected/$name.$i")
        compare "$name, step $i: $step (as GNU make)" "$want" \
                "$(command_output "$(matched_form ": $name.$i; cd /test/m/$name; ${step//MAKE/make}")")"
    done < <(python3 "$ROOT/scripts/maketest.py" steps)
    reject "panic"
    show_log_on_failure $before
}

# cc_session / cc_shell_test: RitterOS's own C compiler (60), on RitterOS.
# The compiler's sources, cctest's and a few programs' are put on the image
# under /src, laid out as in the tree. cc builds cctest (C's arithmetic,
# conversions, long double, structures by value, varargs, bit-fields,
# initializers, VLAs) and the result prints what the build's clang-made
# /system/<arch>/test/cctest prints; it builds wc, whose output is the
# system's wc's; -c, -S and -E make their files; a mistake gets a message
# with its place and exit code 1; and cc builds cc, as and ld from their
# sources, and that toolchain (-B) builds cctest again with the same
# output. Proven by a cc that subtracts where it should add.
cc_session() {
    local n=1 c
    prompt_wait $n
    for c in \
        'cc -o /tmp/cctest /src/user/test/cctest.c' \
        ': cctest-ours; /tmp/cctest' \
        ": cctest-clang; /system/$ARCH_NAME/test/cctest" \
        'cc -o /tmp/wc /src/user/bin/wc.c' \
        ': wc-ours; /tmp/wc /readme.txt' \
        ': wc-system; wc /readme.txt' \
        'cd /tmp' \
        'cc -c /src/user/bin/hello.c' \
        ': object; test -f /tmp/hello.o && echo object made' \
        'cc -S -o /tmp/hello.s /src/user/bin/hello.c' \
        ': assembly; grep -c "^main:" /tmp/hello.s' \
        ': preprocessed; cc -E -DVALUE=42 /src/e.c' \
        ': avx macros; cc -mavx2 -mfma -E /src/m.c' \
        ': avx code; cc -S -o /tmp/avxcode.s /src/avxcode.c && cat /tmp/avxcode.s' \
        ': mistake; cc -o /tmp/bad /src/bad.c' \
        'cd /' \
        'mkdir /tmp/b' \
        'cc -o /tmp/b/cc /src/user/bin/cc.c /src/user/bin/cc/*.c' \
        'cc -o /tmp/b/as /src/user/bin/as.c /src/user/bin/as/*.c' \
        'cc -o /tmp/b/ld /src/user/bin/ld.c' \
        '/tmp/b/cc -B /tmp/b -o /tmp/cctest2 /src/user/test/cctest.c' \
        ': cctest-selfbuilt; /tmp/cctest2'; do
        [ -n "${CC_MODEL:-}" ] && [ "$c" = 'cc -o /tmp/wc /src/user/bin/wc.c' ] && break  # (max: cctest only)
        serial_type "$c\r"
        n=$((n + 1))
        prompt_wait $n 900
    done
    [ -n "${CC_MODEL:-}" ] || return 0
    # (32d) vectors between clang's code and cc's: vabi1.o is clang's
    for c in 'cc -o /tmp/vabi /src/vabi2.c /src/vabi1.o' ': vabi-mixed; /tmp/vabi' \
             'cc -o /tmp/vabi-ours /src/vabi2.c /src/vabi1.c' ': vabi-ours; /tmp/vabi-ours'; do
        serial_type "$c\r"
        n=$((n + 1))
        prompt_wait $n 300
    done
}

cc_shell_test() {
    local image before ours clang model=${1:-}
    [ "$model" = max ] && [ "$ARCH_NAME" != x86_64 ] && return 0
    image=$(make_image ${P}cc$model "")
    printf 'value VALUE\n' > "$WORK/${P}cc-e.c"
    printf 'int main(void)\n{\n    return missing;\n}\n' > "$WORK/${P}cc-bad.c"
    printf '#ifdef __AVX__\nint avx;\n#endif\n#ifdef __AVX2__\nint avx2;\n#endif\n#ifdef __FMA__\nint fma;\n#endif\n' \
        > "$WORK/${P}cc-m.c"
    rm -f "$WORK/${P}vabi1.o"
    if [ "$model" = max ]; then
        "$ROOT/tools/zig/zig" clang -target x86_64-unknown-none-elf -ffreestanding -nostdinc -isystem "$ROOT/tools/zig/lib/include" \
            -I "$ROOT/user/include" -fPIC -O2 -mavx2 -c -o "$WORK/${P}vabi1.o" "$ROOT/scripts/vabi/vabi1.c" || exit 1
    fi
    python3 - "$image" "$ROOT" "$WORK/${P}cc-e.c" "$WORK/${P}cc-bad.c" "$WORK/${P}cc-m.c" "$WORK/${P}vabi1.o" <<'PY' || exit 1
import glob, os, sys
image, root, e, bad, m, vabi = sys.argv[1:7]
sys.path.insert(0, os.path.join(root, 'scripts'))
import ritterfs
files = {'/src/e.c': open(e, 'rb').read(), '/src/bad.c': open(bad, 'rb').read(), '/src/m.c': open(m, 'rb').read(),
         '/src/avxcode.c': open(os.path.join(root, 'scripts/vabi/avxcode.c'), 'rb').read()}
if os.path.exists(vabi):
    files['/src/vabi1.o'] = open(vabi, 'rb').read()
    for f in ('vabi1.c', 'vabi2.c'):
        files['/src/' + f] = open(os.path.join(root, 'scripts/vabi', f), 'rb').read()
for pattern in ('user/bin/cc.c', 'user/bin/cc/*.[ch]', 'user/bin/as.c', 'user/bin/as/*.[ch]',
                'user/bin/ld.c', 'user/bin/wc.c', 'user/bin/hello.c', 'user/test/cctest.c',
                'user/test/cctest_simd.h'):
    for p in glob.glob(os.path.join(root, pattern)):
        files['/src/' + os.path.relpath(p, root)] = open(p, 'rb').read()
with open(image, 'r+b') as f:
    ritterfs.install(ritterfs.Partition(f, 133120, 1961984), files)
PY
    before=$failures
    [ "$model" = max ] && QEMU_EXTRA="-cpu max"
    CC_MODEL=$model
    SERIAL_SCRIPT=cc_session
    boot ${P}cc$model "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    CC_MODEL=
    clang=$(command_output ": cctest-clang; /system/$ARCH_NAME/test/cctest")
    ours=$(command_output ': cctest-ours; /tmp/cctest')
    check "cctest built by cc on RitterOS prints what clang's build prints ($(wc -l <<<"$clang" | tr -d ' ') lines)" \
          "cctest built by cc differs: $(diff <(echo "$clang") <(echo "$ours") | head -4 | tr '\n' '|')" \
          test -n "$clang" -a "$clang" = "$ours"
    expect_line "fails: 0"
    # (32d) the intrinsics: with QEMU's newest model every one of
    # <immintrin.h>'s, on the same vectors in clang's build and ours (the
    # check above compares them); otherwise both skip them
    if [ "$model" = max ]; then
        check "cctest: the intrinsics ran ($(grep -E '^intrinsics: [0-9]+ calls' <<<"$ours"))" "$(tail -3 <<<"$ours")" \
              eval 'grep -qE "^intrinsics: [0-9]+ calls$" <<<"$ours"'
        local how
        for how in mixed ours; do
            compare "vectors between clang's and cc's code ($how build)" \
                    "vabi: vectors to clang's function and back: 4 of 4 right|vabi: clang's function calling cc's with vectors: 4 of 4 right|" \
                    "$(command_output ": vabi-$how; /tmp/vabi$([ $how = ours ] && echo -ours)" | tr '\n' '|')"
        done
        reject "panic"
        reject "page fault"
        show_log_on_failure $before
        return
    fi
    # (32d) -mavx2 and -mfma: their macros (x86-64 only)
    if [ "$ARCH_NAME" = x86_64 ]; then
        expect_line "intrinsics: no AVX2 and FMA here"
        compare "cc -mavx2 -mfma defines __AVX__, __AVX2__ and __FMA__" "int avx;|int avx2;|int fma;|" \
                "$(command_output ': avx macros; cc -mavx2 -mfma -E /src/m.c' | grep '^int' | tr '\n' '|')"
        # (32h) AVX code as it must be (scripts/vabi/avxcode.c, compiled here):
        # vectors in ymm registers, VEX scalar code and vzeroupper in the
        # target("avx2") function, and none of it in the plain one. Proven by
        # cc without the VEX rewriting, inlining fir into plain, no vzeroupper
        # at the return, and the header of 32d (vectors through memory).
        command_output ': avx code; cc -S -o /tmp/avxcode.s /src/avxcode.c && cat /tmp/avxcode.s' >"$WORK/${P}avxcode.s"
        local avxcheck
        avxcheck=$(python3 - "$WORK/${P}avxcode.s" <<'PY'
import re, sys
text = open(sys.argv[1], errors='replace').read().replace('\r', '')
def body(name):
    m = re.search(r'^%s:\n(.*?)^\s*\.size %s' % (name, name), text, re.M | re.S)
    return m.group(1) if m else ''
fir, plain = body('fir'), body('plain')
bad = []
if not fir or not plain:
    bad.append('no fir or plain')
if not re.search(r'vfmadd213ps %ymm\d+, %ymm\d+, %ymm\d+', fir):
    bad.append('fir: no fma on ymm registers')
sse = re.findall(r'^\t((?:mov|add|sub|mul|div|sqrt|cvt|ucomi)\S*s[sd]\S*|movq %xmm|movd %xmm)', fir, re.M)
if sse:
    bad.append('fir: SSE scalar code %s' % sse[:3])
if not re.search(r'vzeroupper\n(?:\t\S.*\n)*?\tret', fir):
    bad.append('fir: no vzeroupper before ret')
if re.search(r'^\tv', plain, re.M):
    bad.append('plain: VEX code')
if not re.search(r'call fir', plain):
    bad.append('plain: fir inlined')
print('; '.join(bad) or 'ok')
PY
)
        compare "cc: AVX code with vectors in ymm registers, VEX scalar code, vzeroupper; none in plain code" "ok" "$avxcheck"
    else
        expect_line "intrinsics: x86-64's"
        expect_line "cc: '-mavx2' is x86-64's"
    fi
    compare "wc built by cc counts as the system's wc" "$(command_output ': wc-system; wc /readme.txt')" \
            "$(command_output ': wc-ours; /tmp/wc /readme.txt')"
    compare "cc -c made hello.o" "object made" "$(command_output ': object; test -f /tmp/hello.o && echo object made')"
    compare "cc -S made assembly with main" "1" "$(command_output ': assembly; grep -c "^main:" /tmp/hello.s')"
    expect_line "value 42"
    expect "/src/bad.c:3:12: error: use of undeclared identifier 'missing'"
    expect_line "cc: exit code 1"
    compare "cc, as and ld built by cc build cctest, which prints the same" "$clang" \
            "$(command_output ': cctest-selfbuilt; /tmp/cctest2')"
    reject "panic"
    reject "page fault"
    show_log_on_failure $before
}

# userconf_session / userconf_shell_test: each user's own settings (15l, the
# user's names): login makes ~/.config (with a README and the files login
# and windows, all comments) at a console login when missing -- root's at the first start, anna's at her first --
# and starts the shell as `sh -l`, which runs ~/.config/login; windowd reads
# ~/.config/windows before /system/config/windows. anna writes a login file
# (a comment, then windowd) and a windows file (startup = imageview
# /test/solid.ppm), logs out and in: the window system starts by itself and
# opens her picture. Proven by a shell that ignores -l (no windowd) and a
# windowd that reads only the system's file (no picture: its startup is empty).
userconf_session() {
    local n=1
    prompt_wait $n
    answer_lines 'ls /home/root/.config' 'useradd anna'
    serial_type 'passwd anna\r'
    serial_wait "New password: " 1
    serial_type 'anna-pw-1\r'
    serial_wait "Again: " 1
    serial_type 'anna-pw-1\r'
    n=$((n + 1)); prompt_wait $n 30
    serial_type 'exit\r'
    login_wait 2
    serial_type 'anna\r'
    serial_wait "Password: " 1
    serial_type 'anna-pw-1\r'
    serial_wait "[anna logged in]" 1 30
    n=$((n + 1)); prompt_wait $n 30
    answer_lines 'ls /home/anna/.config' 'echo "# the window system is my interface" > .config/login' \
                 'echo windowd >> .config/login' \
                 'echo "startup = imageview /test/solid.ppm" > .config/windows'
    serial_type 'exit\r'
    login_wait 3
    serial_type 'anna\r'
    serial_wait "Password: " 2
    serial_type 'anna-pw-1\r'
    serial_wait "[anna logged in]" 2 30
    serial_wait "imageview: showing" 1 30
}

userconf_shell_test() {
    local image before readme_size names
    image=$(make_image ${P}userconf "")
    windows_bare "$image"                           # (the system's startup: empty)
    python3 "$ROOT/scripts/mkimage.py" "$WORK/${P}pic.ppm" "$WORK/${P}pic.bmp" "$WORK/${P}solid.ppm" >/dev/null
    $RFS put "$image" $RFS_PART /test/solid.ppm "$WORK/${P}solid.ppm" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=userconf_session
    boot ${P}userconf "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    readme_size=$(command_output 'ls /home/root/.config' | awk '$2 == "README" {print $1}')
    names=$(command_output 'ls /home/root/.config' | awk '{print $2}' | LC_ALL=C sort | tr '\n' ' ')
    compare "root's ~/.config, made at the first start" "README filetypes login windows " "$names"
    check "its README says what goes there" "README $readme_size bytes" test "${readme_size:-0}" -gt 200
    compare "anna's ~/.config, made at her first login (the same files)" \
            "$(command_output 'ls /home/root/.config')" "$(command_output 'ls /home/anna/.config')"
    # her second login: no command typed, the window system and her picture
    expect "windowd: listening on /run/windowd"
    expect "imageview: showing /test/solid.ppm (200x150)"
    reject "panic"
    show_log_on_failure $before
}

# wuser_session / wuser_shell_test: the GUI for every user at the console
# (15k, the user's design). Root adds anna and bob. bob, over SSH from the
# Mac, cannot take the screen (he is not at the machine: its owner gets every
# key typed there). anna logs in at the console and runs windowd and
# imageview: her window shows. bob's imageview over SSH is refused by
# anna's windowd (and his libwindow refuses her windowd): another user's
# screen. Proven by a kernel that lets only root take the screen (anna's
# windowd fails) and a windowd that accepts anyone (bob's window opens).
wuser_session() {
    local n=1 mon="$WORK/monitor.sock"
    local -a bob=(-o PubkeyAuthentication=no -o PreferredAuthentications=password
                  -o NumberOfPasswordPrompts=1)
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15                        # (and the elf sshd listening)
    for u in anna bob; do
        serial_type "useradd $u\r"
        n=$((n + 1)); prompt_wait $n
        serial_type "passwd $u\r"
        serial_wait "New password: " $([ $u = anna ] && echo 1 || echo 2)
        serial_type "$u-pw-1\r"
        serial_wait "Again: " $([ $u = anna ] && echo 1 || echo 2)
        serial_type "$u-pw-1\r"
        n=$((n + 1)); prompt_wait $n 30
    done
    SSH_ASKPASS="$WORK/${P}askpass-bob" SSH_ASKPASS_REQUIRE=force DISPLAY=:0 \
        mac_ssh wuser-take "${bob[@]}" bob@127.0.0.1 "/system/$ARCH_NAME/bin/windowd"
    serial_type 'exit\r'                            # root logs out; anna at the console
    login_wait 2
    serial_type 'anna\r'
    serial_wait "Password: " 1
    serial_type 'anna-pw-1\r'
    serial_wait "[anna logged in]" 1 30
    n=$((n + 1)); prompt_wait $n 30
    serial_type "/system/$ARCH_NAME/bin/windowd &\r"
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "/system/$ARCH_NAME/apps/imageview.program/imageview /test/solid.ppm &\r"
    serial_wait "imageview: showing" 1 15
    sleep 1
    echo "screendump $WORK/${NAME}-anna.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    SSH_ASKPASS="$WORK/${P}askpass-bob" SSH_ASKPASS_REQUIRE=force DISPLAY=:0 \
        mac_ssh wuser-window "${bob[@]}" bob@127.0.0.1 "/system/$ARCH_NAME/apps/imageview.program/imageview /test/solid.ppm"
    serial_wait "windowd: refused a program" 1 15
}

wuser_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}wuser "")
    windows_bare "$image"
    rm -f "$WORK/${P}known_hosts"
    python3 "$ROOT/scripts/mkimage.py" "$WORK/${P}pic.ppm" "$WORK/${P}pic.bmp" "$WORK/${P}solid.ppm" >/dev/null
    $RFS put "$image" $RFS_PART /test/solid.ppm "$WORK/${P}solid.ppm" >/dev/null || exit 1
    printf '#!/bin/sh\necho bob-pw-1\n' >"$WORK/${P}askpass-bob"
    chmod 700 "$WORK/${P}askpass-bob"
    QEMU_EXTRA="-netdev user,id=net0,hostfwd=tcp:127.0.0.1:$NET_SSH_PORT-:22"
    QEMU_EXTRA+=" -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=wuser_session
    boot ${P}wuser "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    compare "bob, over SSH, cannot take the screen" \
            "$(printf 'windowd: cannot take the screen: Operation not permitted\nexit 1')" \
            "$(cat "$WORK/${P}wuser-take")"
    expect "[anna logged in]"
    expect "windowd: listening on /run/windowd"
    expect "imageview: showing /test/solid.ppm"
    check_screen region-120-140-80-40-200-80-40 $w $h "$WORK/${P}wuser-anna.ppm"   # anna's window
    compare "bob's window on anna's screen is refused" \
            "$(printf "imageview: showing /test/solid.ppm (200x150)\nimageview: cannot open a window: the screen is another user's\nexit 1")" \
            "$(cat "$WORK/${P}wuser-window")"
    expect "windowd: refused a program of user 1001 (this is user 1000's screen)"
    reject "panic"
    show_log_on_failure $before
}

# wkeys_session / wkeys_shell_test: physical keys in windows (15p; the user's,
# for a Doom port: no releases came, two keys could not be held, Ctrl, Shift
# and Alt sent nothing; names theirs: WINDOW_KEY_DOWN/UP, WKEY_*). The test
# program wkeys prints the events of its window; QEMU presses Shift+A and
# then Ctrl+Up: each key's press and release in order, the modifiers too,
# the bytes typed ("A", ESC [ A) beside them. Proven by a kernel that sends no releases.
wkeys_session() {
    local n=1 mon="$WORK/monitor.sock"
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "/system/$ARCH_NAME/test/wkeys 8 &\r"
    serial_wait "wkeys: ready" 1 15
    sleep 1
    { echo "sendkey shift-a"; sleep 1; echo "sendkey ctrl-up"; sleep 1; } |
        nc -w 3 -U "$mon" >/dev/null 2>&1                # (one connection for both)
    serial_wait "wkeys: done" 1 15
}

wkeys_shell_test() {
    local image before name=wkeys saved="$QEMU_CMD"
    [ "${1:-}" = ps2 ] && name=wkeysps2
    image=$(make_image ${P}$name "")
    windows_bare "$image"
    # ps2 (x86): without the USB keyboard QEMU's keys reach the PS/2 one --
    # the laptop's built-in keyboard is PS/2.
    [ "${1:-}" = ps2 ] && QEMU_CMD="${QEMU_CMD/ -device usb-kbd,bus=xhci.0,port=1.1.1/}"
    before=$failures
    SERIAL_SCRIPT=wkeys_session
    boot ${P}$name "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_CMD="$saved"
    compare "Shift+A, then Ctrl+Up: presses and releases, the modifiers too" \
            "$(printf 'wkeys: down 0xe1\nwkeys: down 0x04\nwkeys: byte 0x41\nwkeys: up 0x04\nwkeys: up 0xe1\nwkeys: down 0xe0\nwkeys: down 0x52\nwkeys: byte 0x1b\nwkeys: byte 0x5b\nwkeys: byte 0x41\nwkeys: up 0x52\nwkeys: up 0xe0')" \
            "$(grep -a '^wkeys: \(down\|up\|byte\)' <<<"$TEXT")"
    reject "panic"
    show_log_on_failure $before
}

# wfield_session / wfield_shell_test: the text field and the clipboard (15w;
# the user's: selecting text in any program, names theirs). The test program
# wfield shows a field; QEMU types "hello world", drags across "hello" and
# cuts it (Ctrl+X), double-clicks "world" and pastes over it (Ctrl+V), types
# "!" at the end, selects all with Shift+Home and copies it (Ctrl+C), then
# Enter: " hello!". A second wfield reads the clipboard: " hello!" (it is
# windowd's, not the program's). Proven by a field that ignores the drag.
wfield_session() {
    local n=1 q="$WORK/qmp.sock" mon="$WORK/monitor.sock" t="/system/$ARCH_NAME/test/wfield"
    local cx=639 cy=399 k
    [ "$ARCH_NAME" = aarch64 ] && cx=399 cy=299
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    keys() { local k; for k in "$@"; do echo "sendkey $k" | nc -w 3 -U "$mon" >/dev/null 2>&1; sleep 0.15; done; }
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t &\r"                      # window 0: content at (104,124), the text from x 118
    serial_wait "wfield: ready" 1 15
    sleep 1
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3
        rel x $((118 - cx)); echo; sleep 0.15; rel y $((143 - cy)); echo; sleep 0.3
        btn true; echo; sleep 0.1; btn false; echo; sleep 0.3      # focus the field
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    keys h e l l o spc w o r l d
    sleep 0.5
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3
        btn true; echo; sleep 0.15                   # drag from column 0...
        rel x 45; echo; sleep 0.15                   # ...to column 5: "hello"
        btn false; echo; sleep 0.3
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    keys ctrl-x                                      # " world", the clipboard "hello"
    sleep 0.5
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3
        rel x -16; echo; sleep 0.3                   # onto "world" (column 3)
        btn true; echo; sleep 0.1; btn false; echo; sleep 0.1
        btn true; echo; sleep 0.1; btn false; echo; sleep 0.5   # a double click
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    keys ctrl-v end shift-1 shift-home ctrl-c ret    # " hello", "!", all copied, Enter
    serial_wait "wfield: enter" 1 15
    serial_type "$t paste\r"
    serial_wait "wfield: clipboard" 1 15
}

wfield_shell_test() {
    local image before
    image=$(make_image ${P}wfield "")
    windows_bare "$image"
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=wfield_session
    boot ${P}wfield "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect_line "wfield: enter ' hello!'"
    expect_line "wfield: clipboard ' hello!' (7 bytes)"
    reject "panic"
    show_log_on_failure $before
}

# drawtest_host DIR: drawtest and libdraw built on the Mac (41b) into DIR,
# against draw.h and media.h alone (never user/include); 1 when it does not
# build.
drawtest_host() {
    mkdir -p "$1/inc" && cp "$ROOT/user/include/draw.h" "$ROOT/user/include/media.h" "$1/inc/" &&
        /usr/bin/clang -std=c11 -O2 -ffp-contract=off -DDRAW_HOST -I "$1/inc" -o "$1/drawtest" \
            "$ROOT/user/test/drawtest.c" "$ROOT/user/lib/draw.c" 2>"$1/drawtest.err"
}

# pngenc_host_test (41h-2): libimage's DEFLATE compressor and PNG writer
# built on the Mac under ASan and UBSan (scripts/pngenc_host.c, the
# library's own files with a stub ritteros.h), read back by Python's zlib
# (11 streams: empty, runs at 258's edge, a MiB of zeros, random bytes, a
# block repeated exactly 32768 and 32769 bytes back) and, for 10 pictures
# (noise, transparency, flat, gradient, stripes, a screen, rows repeated
# past 32 KiB, 1-pixel sides), decoded by scripts/pngcheck.py (CRCs, the
# five filters) to the pixels written, and read by the Mac's ImageIO.
# Proven by distances' extra bits one off at the window's far end (only the
# block 32768 back) and the average filter rounding up (every picture whose
# rows chose it).
pngenc_host_test() {
    local out d="$WORK/pngenc"
    NAME=${P}pngenc                         # (no boot names it)
    mkdir -p "$d/stub"
    printf '#include <stddef.h>\n#include <stdint.h>\n#include "crc32.h"\n' >"$d/stub/ritteros.h"
    if ! /usr/bin/clang -std=c11 -O1 -g -fsanitize=address,undefined -fno-sanitize-recover=all \
             -Wall -Wextra -Werror -iquote "$d/stub" -iquote "$ROOT/user/include" \
             -iquote "$ROOT/user/lib" -iquote "$ROOT/common" -o "$d/pngenc_host" \
             "$ROOT/scripts/pngenc_host.c" "$ROOT/user/lib/deflate.c" "$ROOT/user/lib/png.c" \
             "$ROOT/user/lib/inflate.c" "$ROOT/common/crc32.c" 2>"$d/build.err"; then
        check "pngenc_host builds on the Mac" "$(head -3 "$d/build.err")" false
        return
    fi
    out=$(python3 "$ROOT/scripts/pngcheck.py" "$d/pngenc_host" "$d/run" 2>&1)
    check "DEFLATE and PNG as zlib and ImageIO read them ($(tail -1 <<<"$out"))" \
          "DEFLATE and PNG as zlib and ImageIO read them: $(grep -E "FAILED|rc |Error" <<<"$out" | head -3 | tr '\n' ' ')" \
          eval '[ "$(tail -1 <<<"$out")" = "pngcheck: 0 failure(s)" ] && [ "$(grep -c "^pngcheck: \(deflate\|png\) " <<<"$out")" = 21 ]'
}

# draw_host_test (41b): libdraw's anti-aliasing on the Mac against exact
# areas: scripts/drawref.py computes every pixel's covered area (each piece
# clipped to the pixel's square; 41b-2's circles, ellipses and rounded
# rectangles by the disk's area formula; 41b-3's gradients by each centre's
# place, a turned image's rectangle, and the gray pattern copied exactly at
# right angles) for fixed and 400 random shapes and compares drawtest's
# within 1/255 (the copies: exactly). Proven by a rasteriser taking an
# edge's x at its top instead of its middle in a cell (2,306 pixels off),
# curves of pieces straying 1/16 pixel instead of 1/1024 (2,060), a
# gradient at each pixel's corner (2,282) and images read half a pixel off
# (900).
draw_host_test() {
    local out
    NAME=${P}drawref                        # (no boot names it)
    if ! drawtest_host "$WORK/drawref"; then
        check "drawtest builds on the Mac" "$(head -3 "$WORK/drawref/drawtest.err")" false
        return
    fi
    out=$(python3 "$ROOT/scripts/drawref.py" "$WORK/drawref/drawtest" 400 2>&1 | tail -6)
    check "libdraw's coverage within 1/255 of the exact area ($(tail -1 <<<"$out"))" "$out" \
          eval 'grep -qE "^drawref: [0-9]+ shapes, [0-9]+ pixels, all within" <<<"$out"'
}

# draw_session / draw_shell_test: libdraw on RitterOS (41b; names the
# user's: libdraw, draw_*, window_pixels, drawtest). drawtest's scenes give
# the checksums the Mac's build of it gives (the same pixels on every
# machine: floats in one order, no contraction), and drawn on a window's own
# pixels (window_pixels) a white rectangle, a red one at alpha 128 over it
# and a 3-pixel green line show in the screenshot as computed. Proven by a
# library built with -ffp-contract=fast (ARM's checksums differ) and by one
# whose blend leaves out the pixel behind (the window's colours: the Mac's
# checksums come from the same draw.c, so they cannot see it).
# (41c-3) The window also shows "Ritter" in FreeSans at 24 pixels
# (wfont_open): full and partly lit pixels in its corner; proven by text
# blended at full strength wherever a glyph touches (no partly lit ones).
draw_session() {
    local n=1 mon="$WORK/monitor.sock"
    prompt_wait $n
    serial_type "/system/$ARCH_NAME/test/drawtest\r"
    serial_wait "drawtest: done" 1 60
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "/system/$ARCH_NAME/test/drawtest window 30 &\r"     # window 0: content at (104,124)
    serial_wait "drawtest: window drawn" 1 30
    sleep 1
    echo "screendump $WORK/${NAME}-window.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

draw_shell_test() {
    local image before host got px text
    if ! drawtest_host "$WORK/${P}drawhost"; then
        NAME=${P}draw
        check "drawtest builds on the Mac" "$(head -3 "$WORK/${P}drawhost/drawtest.err")" false
        return
    fi
    host=$("$WORK/${P}drawhost/drawtest" | grep -E '^drawtest: [a-z]+ [0-9a-f]{16}$')
    image=$(make_image ${P}draw "")
    windows_bare "$image"
    before=$failures
    SERIAL_SCRIPT=draw_session
    boot ${P}draw "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    got=$(tr -d '\r' <<<"$TEXT" | grep -aE '^drawtest: [a-z]+ [0-9a-f]{16}$')
    compare "drawtest's scenes as the Mac draws them ($(wc -l <<<"$host" | tr -d ' ') checksums)" "$host" "$got"
    px=$(python3 - "$WORK/${NAME}-window.ppm" "$ROOT/scripts" <<'PY' 2>&1
import sys
sys.path.insert(0, sys.argv[2])
from ppm2png import read_ppm
w, h, rgb = read_ppm(sys.argv[1])
def at(x, y):
    i = ((124 + y) * w + 104 + x) * 3
    return '%d,%d,%d' % tuple(rgb[i:i + 3])
print(' '.join(at(x, y) for x, y in ((5, 5), (40, 30), (80, 65), (120, 100), (100, 130), (100, 128))))
PY
)
    compare "a window drawn on its own pixels: black, white, red at alpha 128 over white and over black, a green line and its half-covered edge" \
            "0,0,0 255,255,255 255,127,127 128,0,0 0,255,0 0,128,0" "$px"
    # (41c-3) "Ritter" in FreeSans at 24 pixels in its top right corner
    # (x 108-199, y 4-31): smooth, so full white and partly white pixels
    text=$(python3 - "$WORK/${NAME}-window.ppm" "$ROOT/scripts" <<'PY' 2>&1
import sys
sys.path.insert(0, sys.argv[2])
from ppm2png import read_ppm
w, h, rgb = read_ppm(sys.argv[1])
full = part = 0
for y in range(124 + 4, 124 + 32):
    for x in range(104 + 108, 104 + 200):
        i = (y * w + x) * 3
        r, g, b = rgb[i:i + 3]
        full += (r, g, b) == (255, 255, 255)
        part += 0 < r < 255 and r == g == b
print('full' if full > 50 else 'no full', 'partly' if part > 50 else 'no partly')
PY
)
    compare "smooth text from a scalable font (wfont_open) in the window" "full partly" "$text"
    reject "panic"
    show_log_on_failure $before
}

# ttftest_host DIR: ttftest built on the Mac (41c) into DIR (it builds
# user/lib/ttf.c in with it and needs no RitterOS header); 1 when it does
# not build.
ttftest_host() {
    mkdir -p "$1" && /usr/bin/clang -std=c11 -O2 -ffp-contract=off -o "$1/ttftest" "$ROOT/user/test/ttftest.c" \
        2>"$1/ttftest.err"
}

# ttf_host_test (41c-1): the font reader against macOS's CoreText, on the
# Mac: scripts/fontref.swift compares every glyph's outline and advance,
# every character's glyph from U+0000 to U+10FFFF and the sizes of our six
# FreeFont faces (with no contour CoreText turned round), then of the Mac's
# own plain TrueType fonts (171 here: they use what FreeFont does not, such
# as format 4's indirect glyph lists; format 4's delta there is 0 in every
# font, so that addition is never seen). Proven by composites without their
# components' offsets (1,885 FreeSans outlines off), outlines not moved by
# their left side bearing (34), format 4's indirect lists read a glyph on
# (Monaco: 927 characters) and the Unicode platform's map taken before
# Windows's (Chalkduster: 145). (41c-2) The same for CFF outlines: our six
# .otf faces and the Mac's .otf fonts (37 here); proven by subroutines'
# bias always 107 (FreeSans.otf: 3,912 outlines), hintmask's bytes not
# skipped (29 of 34 fonts), the last curve's extra argument of h/vhcurveto
# dropped and hflex's second curve's sign (both STIXTwoMath only). No font
# here is CID-keyed or uses the arithmetic operators: that code no oracle
# sees. (41c-3) The reader's glyph masks (ttftest masks) against each
# pixel's exact area of the outlines ttftest dumps (scripts/drawref.py
# --glyphs: 12 glyphs at 9, 17 and 40 pixels, the pen on a whole and a half
# pixel, every FreeFont file; within 1/255); proven by two control points'
# curve ending on the second instead of their midpoint (4,087 pixels off)
# and cubic curves as one straight piece (8,267).
ttf_host_test() {
    local out sys agreed
    NAME=${P}ttfref                        # (no boot names it)
    if ! ttftest_host "$WORK/ttfref"; then
        check "ttftest builds on the Mac" "$(head -3 "$WORK/ttfref/ttftest.err")" false
        return
    fi
    if ! swiftc -O -o "$WORK/ttfref/fontref" "$ROOT/scripts/fontref.swift" 2>"$WORK/ttfref/swift.err"; then
        check "fontref builds on the Mac" "$(head -3 "$WORK/ttfref/swift.err")" false
        return
    fi
    out=$("$WORK/ttfref/fontref" "$WORK/ttfref/ttftest" "$ROOT"/fonts/Free*.ttf "$ROOT"/fonts/Free*.otf 2>&1)
    check "FreeFont's 12 files as CoreText reads them ($(grep -c "as CoreText's$" <<<"$out") of 12)" "$out" \
          eval '[ "$(grep -c "as CoreText.s$" <<<"$out")" = 12 ]'
    # (41c-3) glyph masks against exact areas (scripts/drawref.py --glyphs)
    out=$(python3 "$ROOT/scripts/drawref.py" --glyphs "$WORK/ttfref/ttftest" "$ROOT"/fonts/Free*.ttf \
              "$ROOT"/fonts/Free*.otf 2>&1 | tail -6)
    check "glyph masks within 1/255 of the exact area ($(tail -1 <<<"$out"))" "$out" \
          eval 'grep -qE "^drawref: glyphs: 12 fonts, [0-9]+ pixels, all within" <<<"$out"'
    sys=$("$WORK/ttfref/fontref" "$WORK/ttfref/ttftest" --system 2>&1)
    agreed=$(sed -n 's/^fontref: the Mac.s fonts: \([0-9][0-9]*\) of \([0-9][0-9]*\) as CoreText reads them$/\1 \2/p' <<<"$sys")
    check "the Mac's TrueType and OpenType fonts as CoreText reads them ($(tail -1 <<<"$sys"))" "$(grep -v "^fontref: the Mac" <<<"$sys" | head -12)" \
          eval '[ -n "$agreed" ] && [ "${agreed% *}" = "${agreed#* }" ] && [ "${agreed% *}" -gt 100 ]'
}

# ttf_session / ttf_shell_test (41c-1): the font reader on RitterOS: its
# ttftest dumps every glyph and character of /system/fonts' FreeFont files
# (.ttf, 41c-2 .otf) into checksums, which must be the Mac's build's of
# fonts/ (the
# same reader there and here, on x86 and ARM). Proven by a reader giving one
# advance wrong where __APPLE__ is not defined (RitterOS only).
ttf_session() {
    local n=1
    prompt_wait $n
    serial_type "/system/$ARCH_NAME/test/ttftest\r"
    serial_wait "ttftest: done" 1 900
}

ttf_shell_test() {
    local image before host got f
    if ! ttftest_host "$WORK/${P}ttfhost"; then
        NAME=${P}ttf
        check "ttftest builds on the Mac" "$(head -3 "$WORK/${P}ttfhost/ttftest.err")" false
        return
    fi
    host=$(cd "$ROOT/fonts" && "$WORK/${P}ttfhost/ttftest" FreeSans.ttf FreeSansBold.ttf FreeSerif.ttf \
               FreeSerifBold.ttf FreeMono.ttf FreeMonoBold.ttf FreeSans.otf FreeSansBold.otf FreeSerif.otf \
               FreeSerifBold.otf FreeMono.otf FreeMonoBold.otf | grep -E '^ttftest: Free')
    image=$(make_image ${P}ttf "")
    before=$failures
    SERIAL_SCRIPT=ttf_session
    boot ${P}ttf "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    got=$(tr -d '\r' <<<"$TEXT" | grep -aE '^ttftest: Free')
    compare "every glyph and character of FreeFont's 12 files read as on the Mac" "$host" "$got"
    reject "panic"
    show_log_on_failure $before
}

# widget_session / widget_shell_test: libwidget's start (41e-1; names the
# user's: libwidget, widget_*) and focus events (41f-1: WINDOW_FOCUS,
# WMSG_FOCUS). widgettest's form (a label, check boxes Wi-Fi on and
# Bluetooth, radio buttons Small chosen and Large, a button Big stretching to
# the column's end) is driven by keys through QEMU -- Tab, Space (Wi-Fi off),
# Tab, Enter (Bluetooth on), Tab, Tab, Space (Large), Shift+Tab, Space
# (Small) -- and a click on Big, which ends the run: the callbacks' lines in
# that order, then the values. Screenshots: the window's background, and
# the first Tab's focus ring (more accent-coloured pixels). Then `widgettest
# focus`: 1 when its window opens, 0 when wclient's opens in front, 1 again
# when it is clicked. (41e-2) `widgettest more`: keys through tabs (Left/
# Right), a slider (arrows, End, Page Down), a button that fills a progress
# bar, in a 200x100 window that grows to its layout; (41f-2) `widgettest
# limits`: a window between 250x150 and 400x300 dragged 200 pixels smaller
# (250x150) and maximized (400x300). (41e-3) `widgettest rows`: the wheel
# over a list and a click on its first row (row 3 after a step), then keys
# through the list (Up, End), the tree (Down, Right, Left to the parent,
# Left closing, Space opening) and the table; (41f-3) `widgettest hover`:
# enter and leave as the pointer crosses its content, title bar and the
# desktop. (41f-4) `widgettest text`: a, B, Up, Escape and a dead key's é
# as WINDOW_TEXT; (41e-4) `widgettest editor`: typing, Shift+Left's
# selection replaced, a click at the first line's start, Ctrl+A/C into the
# entry with Ctrl+V (its newline a space), Backspace, Home; the pointer an
# I-beam over the editor and an arrow over Done. (41e-5, 41f-5) `widgettest
# dialog`: a question answered by Cancel, Delete and Escape, then a message
# while the window behind it is clicked on its Quit button: the dialog is
# brought forward, its Escape closes it, Quit is pressed only after.
widget_session() {
    local n=1 q="$WORK/qmp.sock" mon="$WORK/monitor.sock" t="/system/$ARCH_NAME/test" cx=639 cy=399 k
    [ "$ARCH_NAME" = aarch64 ] && cx=399 cy=299
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t/widgettest &\r"                    # window 0: content at (104,124), 300x240
    serial_wait "widgettest: ready" 1 15
    sleep 1.5
    echo "screendump $WORK/${NAME}-start.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    echo "sendkey tab" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 1
    echo "screendump $WORK/${NAME}-tab.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    for k in spc tab ret tab tab spc shift-tab spc; do
        echo "sendkey $k" | nc -w 3 -U "$mon" >/dev/null 2>&1
        sleep 0.4
    done
    serial_wait "widgettest: Small 1" 1 15
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # Big: from (8,120) to (88,232)
        rel x $((132 - cx)); echo; sleep 0.15; rel y $((346 - cy)); echo; sleep 0.3
        btn true; echo; sleep 0.15; btn false; echo; sleep 0.3
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    serial_wait "widgettest: done" 1 15
    serial_type "$t/widgettest focus &\r"
    serial_wait "widgettest: focus 1" 1 15
    serial_type "$t/wclient &\r"                         # window 1, at (140,140): in front
    serial_wait "widgettest: focus 0" 1 15
    sleep 0.5
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # back to (110,130): window 0
        rel x $((110 - 132)); echo; sleep 0.15; rel y $((130 - 346)); echo; sleep 0.3
        btn true; echo; sleep 0.15; btn false; echo; sleep 0.3
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    serial_wait "widgettest: done" 2 15
    # (41e-2) tabs, a slider, a progress bar, in a window that grows
    serial_type "$t/widgettest more &\r"
    serial_wait "widgettest: ready" 2 15
    sleep 1.5
    echo "screendump $WORK/${NAME}-more.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    for k in tab tab right right right end pgdn shift-tab right tab spc tab ret; do
        echo "sendkey $k" | nc -w 3 -U "$mon" >/dev/null 2>&1
        sleep 0.4
    done
    serial_wait "widgettest: done" 3 15
    # (41f-2) limits: the corner dragged 200 pixels in, then the maximize box
    serial_type "$t/widgettest limits &\r"           # window 0: outer (100,100) to (408,328)
    serial_wait "widgettest: limits ready" 1 15
    sleep 1
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # from (110,130) to the corner
        rel x $((406 - 110)); echo; sleep 0.15; rel y $((326 - 130)); echo; sleep 0.3
        btn true; echo; sleep 0.2
        rel x -200; echo; sleep 0.15; rel y -200; echo; sleep 0.3
        btn false; echo; sleep 0.5
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    serial_wait "widgettest: resize" 1 15
    sleep 1
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # 250x150: its + box at (298,112)
        rel x $((298 - 206)); echo; sleep 0.15; rel y $((112 - 126)); echo; sleep 0.3
        btn true; echo; sleep 0.15; btn false; echo; sleep 0.5
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    serial_wait "widgettest: done" 4 15
    # (41e-3) a list, a tree, a table: the wheel over the list, a click on its
    # first row, then keys
    serial_type "$t/widgettest rows &\r"            # window 0: content at (104,124)
    serial_wait "widgettest: ready" 3 15
    sleep 1.5
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # from (298,112) to the list's first row
        rel x $((134 - 298)); echo; sleep 0.15; rel y $((142 - 112)); echo; sleep 0.5
        printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"wheel-down","down":true}}]}}'; echo; sleep 0.1
        printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"wheel-down","down":false}}]}}'; echo; sleep 0.5
        btn true; echo; sleep 0.15; btn false; echo; sleep 0.5
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    echo "screendump $WORK/${NAME}-rows.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    for k in up end up tab down right down left left down spc down right down tab down down tab ret; do
        echo "sendkey $k" | nc -w 3 -U "$mon" >/dev/null 2>&1
        sleep 0.4
    done
    serial_wait "widgettest: done" 5 15
    # (41f-3) the pointer into a window's content, onto its title bar, in
    # again, out to the desktop; it waits on the desktop before the window
    # opens (QEMU moves it in steps of at most 127 pixels: a way across a
    # window would enter and leave it on the way)
    sleep 1                                          # (rows' slot free again: hover is window 0)
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # from (134,142) to (700,560)
        rel y $((560 - 142)); echo; sleep 0.3; rel x $((700 - 134)); echo; sleep 0.5
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    serial_type "$t/widgettest hover &\r"           # window 0: content (104,124) to (404,324)
    serial_wait "widgettest: hover ready" 1 15
    sleep 1
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3
        rel x $((200 - 700)); echo; sleep 0.4; rel y $((200 - 560)); echo; sleep 0.6     # in (from below)
        rel y $((112 - 200)); echo; sleep 0.6                                            # its title bar
        rel y $((200 - 112)); echo; sleep 0.6                                            # in
        rel x $((700 - 200)); echo; sleep 0.6                                            # the desktop
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    serial_wait "widgettest: done" 6 15
    # (41f-4) typed text: a, B, Up and Escape (none), ' then e (a dead key: é)
    sleep 1
    serial_type "$t/widgettest text &\r"
    serial_wait "widgettest: text ready" 1 15
    sleep 1
    for k in a shift-b up esc apostrophe e; do
        echo "sendkey $k" | nc -w 3 -U "$mon" >/dev/null 2>&1
        sleep 0.4
    done
    serial_wait "widgettest: done" 7 15
    # (41e-4) editors: typing, a selection replaced, a click, the clipboard;
    # the pointer an I-beam over the editor, an arrow over Done
    sleep 1
    serial_type "$t/widgettest editor &\r"         # window 0: content at (104,124)
    serial_wait "widgettest: ready" 4 15
    sleep 1.5
    for k in tab h e l l o ret w o r l d left left shift-left shift-left x; do
        echo "sendkey $k" | nc -w 3 -U "$mon" >/dev/null 2>&1
        sleep 0.3
    done
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # from (700,200) to the first line's start
        rel x $((114 - 700)); echo; sleep 0.3; rel y $((136 - 200)); echo; sleep 0.5
        btn true; echo; sleep 0.15; btn false; echo; sleep 0.5
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    echo "screendump $WORK/${NAME}-ibeam.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    for k in shift-z ctrl-a ctrl-c tab ctrl-v backspace home shift-a; do
        echo "sendkey $k" | nc -w 3 -U "$mon" >/dev/null 2>&1
        sleep 0.4
    done
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # onto Done
        rel x $((144 - 114)); echo; sleep 0.3; rel y $((294 - 136)); echo; sleep 0.8
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    echo "screendump $WORK/${NAME}-arrow.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    for k in tab ret; do
        echo "sendkey $k" | nc -w 3 -U "$mon" >/dev/null 2>&1
        sleep 0.4
    done
    serial_wait "widgettest: done" 8 15
    # (41e-5, 41f-5) dialogs: a question answered three ways, a message
    # while the window behind it is clicked (on its Quit: nothing but the
    # message brought forward)
    sleep 1
    serial_type "$t/widgettest dialog &\r"         # window 0: content at (104,124), 300x300
    serial_wait "widgettest: ready" 5 15
    sleep 1.5
    keys1() { local k; for k in "$@"; do echo "sendkey $k" | nc -w 3 -U "$mon" >/dev/null 2>&1; sleep 1; done; }
    keys1 tab spc
    echo "screendump $WORK/${NAME}-dialog.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    keys1 tab ret
    serial_wait "widgettest: question" 1 15
    keys1 spc ret
    serial_wait "widgettest: question" 2 15
    keys1 spc esc
    serial_wait "widgettest: question" 3 15
    keys1 tab spc
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # from (144,294) to Quit at (324,144)
        rel x $((324 - 144)); echo; sleep 0.3; rel y $((144 - 294)); echo; sleep 0.5
        btn true; echo; sleep 0.15; btn false; echo; sleep 1
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    keys1 esc
    serial_wait "widgettest: message closed" 1 15
    keys1 tab ret
    serial_wait "widgettest: done" 9 15
    # (41f-6) full screen and back by f, minimised by m, brought back by its
    # taskbar button (at the screen's bottom left)
    local sh=800 y=257                               # (owl's second entry: window 2 at 180,180,
                                                     # wclient still window 1)
    [ "$ARCH_NAME" = aarch64 ] && sh=600 y=193       # (ARM: owl kept on the screen at 72,116)
    steps() {                                        # (a long way in moves of 100 pixels at most)
        local axis=$1 left=$2 d
        while [ "$left" -ne 0 ]; do
            d=$left
            [ "$d" -gt 100 ] && d=100
            [ "$d" -lt -100 ] && d=-100
            rel "$axis" "$d"; echo; sleep 0.15
            left=$((left - d))
        done
    }
    sleep 1
    serial_type "$t/widgettest screen &\r"         # window 0: content at (104,124), 300x200
    serial_wait "widgettest: screen ready" 1 15
    sleep 1
    keys1 f
    serial_wait "widgettest: size" 1 15
    sleep 1
    echo "screendump $WORK/${NAME}-full.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    keys1 f
    serial_wait "widgettest: size" 2 15
    sleep 1
    echo "screendump $WORK/${NAME}-back.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    keys1 m
    serial_wait "widgettest: screen focus 0" 1 15
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # from (324,144) to the taskbar
        steps x $((40 - 324)); steps y $((sh - 10 - 144)); sleep 0.5
        btn true; echo; sleep 0.15; btn false; echo; sleep 1
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    serial_wait "widgettest: screen focus 1" 2 15
    keys1 q
    serial_wait "widgettest: done" 10 15
    # (41f-6) a file dragged out of owl onto a window at full screen (opened
    # first: the part owl leaves free is the drop's place)
    serial_type 'mkdir /home/root/d; echo hi > /home/root/d/note.txt\r'
    sleep 1
    serial_type "$t/widgettest drop &\r"
    serial_wait "widgettest: drop ready" 1 15
    serial_type "/system/$ARCH_NAME/apps/owl.program/owl /home/root/d &\r"
    serial_wait "owl: started" 1 15
    sleep 1.5
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # onto note.txt, pressed, moved
        steps x $((300 - 40)); steps y $((y - sh + 10)); sleep 0.5
        btn true; echo; sleep 0.3
        rel x -90; echo; sleep 0.3; rel x -90; echo; sleep 0.3; rel x -90; echo; sleep 1
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    echo "screendump $WORK/${NAME}-drag.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3                 # let go at (30,y)
        btn false; echo; sleep 0.5
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    serial_wait "widgettest: done" 11 15
}

widget_shell_test() {
    local image before px
    image=$(make_image ${P}widget "")
    windows_bare "$image"
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=widget_session
    boot ${P}widget "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    want_text want <<'LINES'
widgettest: Wi-Fi 0
widgettest: Bluetooth 1
widgettest: Large 1
widgettest: Small 1
widgettest: Big pressed
widgettest: run 1, Wi-Fi 0, Bluetooth 1, Small 1, Large 0
LINES
    compare "widgets driven by Tab, Shift+Tab, Space, Enter and a click" "$want" \
            "$(tr -d '\r' <<<"$TEXT" | grep -aE '^widgettest: (Wi-Fi|Bluetooth|Small|Large|Big|run [0-9], Wi-Fi) ')"
    compare "focus events: opened, another window in front, clicked again" \
            "$(printf 'widgettest: focus 1\nwidgettest: focus 0\nwidgettest: focus 1')" \
            "$(tr -d '\r' <<<"$TEXT" | grep -a '^widgettest: focus [01]$')"
    px=$(python3 - "$WORK/${NAME}-start.ppm" "$WORK/${NAME}-tab.ppm" "$ROOT/scripts" <<'PY' 2>&1
import sys
sys.path.insert(0, sys.argv[3])
from ppm2png import read_ppm
def look(path):
    w, h, rgb = read_ppm(path)
    at = lambda x, y: tuple(rgb[((124 + y) * w + 104 + x) * 3:((124 + y) * w + 104 + x) * 3 + 3])
    accent = sum(at(x, y) == (0x88, 0xC0, 0xD0) for y in range(240) for x in range(300))
    return at(2, 2), accent
(bg, a0), (_, a1) = look(sys.argv[1]), look(sys.argv[2])
print('background %s' % ('ok' if bg == (0x2E, 0x34, 0x40) else 'is %s' % (bg,)),
      'ring %s' % ('ok' if a0 > 20 and a1 > a0 + 40 else '%d -> %d' % (a0, a1)))
PY
)
    compare "the window's background, and a focus ring after Tab" "background ok ring ok" "$px"
    want_text want <<'LINES'
widgettest: slider 31
widgettest: slider 32
widgettest: slider 33
widgettest: slider 100
widgettest: slider 90
widgettest: tab 1
widgettest: progress 10
widgettest: run 1, slider 90, tab 1, progress 10, grew 1
LINES
    compare "tabs, a slider and a progress bar by keys, in a window grown to its layout (41e-2)" "$want" \
            "$(tr -d '\r' <<<"$TEXT" | grep -aE '^widgettest: (slider|tab|progress|run [0-9], slider) ')"
    want_text want <<'LINES'
widgettest: list 3 Item 3
widgettest: list 2 Item 2
widgettest: list 19 Item 19
widgettest: list 18 Item 18
widgettest: tree 0 Fruit
widgettest: tree 1 Apples
widgettest: tree 0 Fruit
widgettest: tree 3 Vegetables
widgettest: tree 4 Carrots
widgettest: tree 5 Orange carrots
widgettest: table 0 apple|3|fruit
widgettest: table 1 pear|5|fruit
widgettest: run 1, list 18, tree 5, table 1
LINES
    compare "a list, a tree and a table: the wheel and a click, then keys (41e-3)" "$want" \
            "$(tr -d '\r' <<<"$TEXT" | grep -aE '^widgettest: (list|tree|table|run [0-9], list) ')"
    compare "the pointer's enter and leave: in, the title bar, in, the desktop (41f-3)" \
            "$(printf 'widgettest: enter\nwidgettest: leave\nwidgettest: enter\nwidgettest: leave')" \
            "$(tr -d '\r' <<<"$TEXT" | grep -aE '^widgettest: (enter|leave)$')"
    compare "typed text as whole characters: a, B, nothing for Up and Escape, a dead key's é (41f-4)" \
            "$(printf 'widgettest: text 61\nwidgettest: text 42\nwidgettest: text e9')" \
            "$(tr -d '\r' <<<"$TEXT" | grep -aE '^widgettest: text [0-9a-f]+$')"
    expect_line "widgettest: run 1, editor Zhello|wxld, entry AZhello wxl, cursor 1"
    px=$(python3 - "$WORK/${NAME}-ibeam.ppm" "$WORK/${NAME}-arrow.ppm" "$ROOT/scripts" <<'PY' 2>&1
import sys
sys.path.insert(0, sys.argv[3])
from ppm2png import read_ppm
def at(path, x, y):
    w, h, rgb = read_ppm(path)
    return tuple(rgb[(y * w + x) * 3:(y * w + x) * 3 + 3])
white = (255, 255, 255)
print('ibeam' if at(sys.argv[1], 114 - 1, 136 - 4) == white else 'no ibeam',
      'arrow' if at(sys.argv[2], 144 - 1, 294 - 4) != white and at(sys.argv[2], 144 + 1, 294 + 4) == white
      else 'no arrow')
PY
)
    compare "the pointer an I-beam over the editor, an arrow over a button (41f-4)" "ibeam arrow" "$px"
    want_text want <<'LINES'
widgettest: question 0
widgettest: question 1
widgettest: question 0
widgettest: message closed
widgettest: run 1
LINES
    compare "dialogs: a question by Tab and Enter, Enter, Escape; a message while its window is clicked (41e-5, 41f-5)" \
            "$want" "$(tr -d '\r' <<<"$TEXT" | grep -aE '^widgettest: (question [01]|message closed|run [0-9])$' | tail -5)"
    px=$(python3 - "$WORK/${NAME}-dialog.ppm" "$ROOT/scripts" <<'PY' 2>&1
import sys
sys.path.insert(0, sys.argv[2])
from ppm2png import read_ppm
w, h, rgb = read_ppm(sys.argv[1])
ring = sum(tuple(rgb[(y * w + x) * 3:(y * w + x) * 3 + 3]) == (0x88, 0xC0, 0xD0)
           for y in range(124, 124 + 50) for x in range(104, 104 + 300))
print('no ring behind' if ring == 0 else '%d ring pixels behind' % ring)
PY
)
    compare "the window behind a dialog drawn without the keyboard's ring (41e-5)" "no ring behind" "$px"
    local sw=1280 sh=800 y=257
    [ "$ARCH_NAME" = aarch64 ] && sw=800 sh=600 y=193
    want_text want <<LINES
widgettest: screen focus 1
widgettest: size $sw x $sh
widgettest: size 300 x 200
widgettest: screen focus 0
widgettest: screen focus 1
LINES
    compare "full screen and back, minimised and brought back from the taskbar (41f-6)" "$want" \
            "$(tr -d '\r' <<<"$TEXT" | grep -aE '^widgettest: (screen focus [01]|size [0-9]+ x [0-9]+)$')"
    px=$(python3 - "$WORK/${NAME}-full.ppm" "$WORK/${NAME}-back.ppm" "$WORK/${NAME}-drag.ppm" "$y" "$ROOT/scripts" <<'PY' 2>&1
import sys
sys.path.insert(0, sys.argv[5])
from ppm2png import read_ppm
def at(path, x, y):
    w, h, rgb = read_ppm(path)
    if x < 0:
        x, y = w + x, h + y
    return tuple(rgb[(y * w + x) * 3:(y * w + x) * 3 + 3])
green, bar = (0x30, 0x60, 0x30), (0x5E, 0x81, 0xAC)
full, back, drag = sys.argv[1], sys.argv[2], sys.argv[3]
y = int(sys.argv[4])
print('full' if at(full, 0, 0) == green and at(full, -1, -1) == green else
      'not full: %s %s' % (at(full, 0, 0), at(full, -1, -1)),
      'back' if at(back, 0, 0) != green and at(back, 106, 126) == green and at(back, 300, 104) == bar else
      'not back: %s %s %s' % (at(back, 0, 0), at(back, 106, 126), at(back, 300, 104)),
      'page' if at(drag, 42, y + 10) == (255, 255, 255) and at(drag, 39, y + 10) == (0, 0, 0) else
      'no page: %s %s' % (at(drag, 42, y + 10), at(drag, 39, y + 10)))
PY
)
    compare "a window at full screen without its frame, back with it; a drag's page on the pointer (41f-6)" \
            "full back page" "$px"
    expect_line "widgettest: drop 30 $y /home/root/d/note.txt"
    compare "a window kept within its limits: dragged smaller, maximized (41f-2)" \
            "$(printf 'widgettest: resize 250 x 150\nwidgettest: resize 400 x 300')" \
            "$(tr -d '\r' <<<"$TEXT" | grep -a '^widgettest: resize ')"
    reject "panic"
    show_log_on_failure $before
}

# wtimer_session / wtimer_shell_test: the event loop beside other work (41a;
# names the user's: window_wait_timeout, window_timer, window_fd). The test
# program wtimer checks a wait of 0 ms and one of 200 ms that run out, two
# timers (50 and 120 ms) for 600 ms with none early, one removed, a ninth
# refused, a poll on window_fd beside a pipe another thread writes (the
# pipe first), then a pointer move through QEMU making window_fd readable
# and its event coming out of window_wait_timeout. Proven by timers looked
# at only when windowd sends something (no timer event at all).
wtimer_session() {
    local n=1 q="$WORK/qmp.sock" cx=639 cy=399
    [ "$ARCH_NAME" = aarch64 ] && cx=399 cy=299
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "/system/$ARCH_NAME/test/wtimer &\r"     # window 0: content at (104,124)
    serial_wait "wtimer: move the pointer" 1 30
    sleep 0.5
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3
        rel x $((150 - cx)); echo; sleep 0.15; rel y $((150 - cy)); echo; sleep 0.3
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    serial_wait "wtimer: done" 1 30
}

wtimer_shell_test() {
    local image before t1 t2
    image=$(make_image ${P}wtimer "")
    windows_bare "$image"
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=wtimer_session
    boot ${P}wtimer "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect_line "wtimer: at once 0, none 1, quick 1"
    expect_line "wtimer: 200 ms 0, none 1, waited enough 1"
    # (600 ms: at most 12 and 5; fewer when ticks are late, never early)
    t1=$(sed -n 's/^wtimer: in 600 ms timer 1 \([0-9][0-9]*\), timer 2 \([0-9][0-9]*\), early 0.*/\1/p' <<<"$TEXT" | head -1)
    t2=$(sed -n 's/^wtimer: in 600 ms timer 1 \([0-9][0-9]*\), timer 2 \([0-9][0-9]*\), early 0.*/\2/p' <<<"$TEXT" | head -1)
    check "two timers come due in time, none early (timer 1 ${t1:-?} of 12, timer 2 ${t2:-?} of 5)" \
          "the timers did not come as they should" \
          eval '[ -n "$t1" ] && [ "$t1" -ge 6 ] && [ "$t1" -le 12 ] && [ "$t2" -ge 2 ] && [ "$t2" -le 5 ]'
    expect_line "wtimer: removed, timer 1 0, timer 2 on 1"
    expect_line "wtimer: 8 timers 8, a ninth refused 1"
    expect_line "wtimer: the pipe first 1, the window quiet 1"
    expect_line "wtimer: through window_fd 1, pointer events 1"
    expect_line "wtimer: done"
    reject "panic"
    show_log_on_failure $before
}

# wtermsel_session / wtermsel_shell_test: selecting in term (15x; the user's).
# In a term window the shell runs `echo hello world`; a drag across "hello"
# in its output and Ctrl+Shift+C copy it, `echo ` + Ctrl+Shift+V + ` >
# /home/root/p` types it back (the file holds "hello"); a double click on
# "world" and Ctrl+Shift+C copy that (the clipboard: "world", read by
# wfield from the console). Proven by a term that ignores Ctrl+Shift+C.
wtermsel_session() {
    local n=1 q="$WORK/qmp.sock" mon="$WORK/monitor.sock"
    local cx=639 cy=399 bx=104                  # the text's left edge (x86: window 0 at 100)
    [ "$ARCH_NAME" = aarch64 ] && cx=399 cy=299 bx=64   # (ARM's 800 pixels: moved to 60)
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    keys() { local k; for k in "$@"; do echo "sendkey $k" | nc -w 3 -U "$mon" >/dev/null 2>&1; sleep 0.15; done; }
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "/system/$ARCH_NAME/apps/term.program/term &\r"   # the text from (bx,124), 9x15 cells
    serial_wait "term: started" 1 15
    sleep 2
    keys e c h o spc h e l l o spc w o r l d ret      # row 1: "hello world"
    sleep 1
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3
        # (in column 0 but 10 pixels from the window's edge: nearer, a press resizes it)
        rel x $((bx + 6 - cx)); echo; sleep 0.15; rel y $((146 - cy)); echo; sleep 0.3
        btn true; echo; sleep 0.15; rel x 35; echo; sleep 0.15     # columns 0-4: "hello"
        btn false; echo; sleep 0.3
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    keys ctrl-shift-c e c h o spc ctrl-shift-v spc shift-dot spc slash h o m e slash r o o t slash p ret
    sleep 1
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3
        rel x 26; echo; sleep 0.3                    # onto "world" (column 7)
        btn true; echo; sleep 0.1; btn false; echo; sleep 0.1
        btn true; echo; sleep 0.1; btn false; echo; sleep 0.5
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    keys ctrl-shift-c
    sleep 0.5
    serial_type "\r"
    answer_lines 'cat /home/root/p' "/system/$ARCH_NAME/test/wfield paste"
}

wtermsel_shell_test() {
    local image before
    image=$(make_image ${P}wtermsel "")
    windows_bare "$image"
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=wtermsel_session
    boot ${P}wtermsel "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    compare "a drag and Ctrl+Shift+C, Ctrl+Shift+V typed it back" "hello" \
            "$(command_output 'cat /home/root/p')"
    expect_line "wfield: clipboard 'world' (5 bytes)"
    reject "panic"
    show_log_on_failure $before
}

# wsteady_session / wsteady_shell_test [off]: steady clicks (15q; the user's,
# from the laptop's touchpad, measured there: the pointer crept 1 pixel at a
# time into a press, while it was held and while the finger lifted;
# `click_steady` in /system/config/windows, on by default). QMP moves the
# pointer as that touchpad did: onto a spot, then three 1-pixel steps 30 ms
# apart straight into a press, two while the button is down, two back after
# it is let go: press and release land on the spot. A 1-pixel nudge followed
# by a pause stays (the press a pixel on). A fast drag moves the whole way.
# With `click_steady = off` the creep moves the press. Proven with the
# filter off (the default case then fails like the off case).
wsteady_session() {
    local n=1 q="$WORK/qmp.sock" t="/system/$ARCH_NAME/test/wclicks"
    local cx=639 cy=399                         # (the pointer starts at the screen's middle)
    [ "$ARCH_NAME" = aarch64 ] && cx=399 cy=299
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t 3 &\r"                     # a 300x200 window at 100,100: content at 104,124
    serial_wait "wclicks: ready" 1 15
    sleep 1
    {   echo '{"execute":"qmp_capabilities"}'; sleep 0.3
        rel x $((200 - cx)); echo; sleep 0.15        # onto the spot (200,200): (96,76) in the window
        rel y $((200 - cy)); echo; sleep 0.8         # (at rest)
        rel y 1; echo; sleep 0.03; rel y 1; echo; sleep 0.03; rel x 1; echo; sleep 0.03
        btn true; echo; sleep 0.1                    # the creep ran into the press
        rel y 1; echo; sleep 0.05; rel x 1; echo; sleep 0.1
        btn false; echo; sleep 0.05                  # (two steps while held)
        rel y -1; echo; sleep 0.05; rel y -1; echo; sleep 1.2   # (two while lifting)
        rel x 1; echo; sleep 0.6                     # a nudge, then a pause
        btn true; echo; sleep 0.1; btn false; echo; sleep 0.6
        btn true; echo; sleep 0.05                   # a fast drag
        rel x 6; echo; sleep 0.05; rel x 6; echo; sleep 0.05
        btn false; echo; sleep 0.5
    } | nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1
    serial_wait "wclicks: done" 1 15
}

wsteady_shell_test() {
    local image before mode="${1:-}" name=wsteady want
    [ -n "$mode" ] && name=wsteady$mode
    image=$(make_image ${P}$name "")
    windows_bare "$image"
    if [ "$mode" = off ]; then
        printf 'startup =\nclick_steady = off\n' >"$WORK/${P}windows"
        $RFS put "$image" $RFS_PART /system/config/windows "$WORK/${P}windows" >/dev/null || exit 1
    fi
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=wsteady_session
    boot ${P}$name "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    if [ "$mode" = off ]; then
        want=$(printf 'wclicks: press 97,78\nwclicks: release 98,79\nwclicks: press 99,77\nwclicks: release 99,77\nwclicks: press 99,77\nwclicks: release 111,77')
        compare "click_steady = off: the creep moves the clicks" "$want" \
                "$(grep -a '^wclicks: \(press\|release\)' <<<"$TEXT")"
    else
        want=$(printf 'wclicks: press 96,76\nwclicks: release 96,76\nwclicks: press 97,76\nwclicks: release 97,76\nwclicks: press 97,76\nwclicks: release 109,76')
        compare "the creep held, the nudge kept, the drag whole" "$want" \
                "$(grep -a '^wclicks: \(press\|release\)' <<<"$TEXT")"
    fi
    reject "panic"
    show_log_on_failure $before
}

# wscroll_session / wscroll_shell_test: scrolling (15o; the user's: no
# window scrolled; names theirs: WINDOW_SCROLL, window_scrollbar,
# window_scrollbar_hit, term's 1000 lines). The wheel reaches windowd
# (INPUT_WHEEL; x86's PS/2 mouse in IntelliMouse mode, ARM's USB mouse) and
# the window under the pointer. owl in a folder of 60 files (61 rows with
# ..): two wheel steps down show rows 7-33 (a line per step); a press at the bottom of its
# scroll bar the last page (35-61). term running cat of 100 lines: two
# steps up scroll back 6 lines; a press at the top of its bar the whole
# scrollback. Driven over QMP. Proven by a windowd that drops the wheel and
# an owl without its bar.
wscroll_session() {
    local n=1 t="/system/$ARCH_NAME/apps" q="$WORK/qmp.sock" curx cury ox=0 tx
    if [ "$ARCH_NAME" = x86_64 ]; then curx=640 cury=400 tx=880; else curx=400 cury=300 tx=789; fi
    [ "$ARCH_NAME" = aarch64 ] && ox=-28                  # (owl's window at x 72 on ARM, 25e)
    qmp() { local c; { echo '{"execute":"qmp_capabilities"}'; sleep 0.3
                       for c in "$@"; do echo "$c"; sleep 0.15; done; } |
            nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1; }
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"%s","down":%s}}]}}' "$1" "$2"; }
    moveto() { qmp "$(rel x $(( $1 - curx )))" "$(rel y $(( $2 - cury )))"; curx=$1; cury=$2; }
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t/owl /test/scroll &\r"
    serial_wait "owl: started" 1 15
    sleep 1
    moveto 400 300                                       # over owl's list
    qmp "$(btn wheel-down true)" "$(btn wheel-down false)" "$(btn wheel-down true)" "$(btn wheel-down false)"
    serial_wait "owl: showing rows" 1 10
    sleep 0.5
    moveto $((818 + ox)) 556                             # the bottom of owl's scroll bar
    qmp "$(btn left true)" "$(btn left false)"
    serial_wait "owl: showing rows" 2 10
    serial_type "$t/term cat /test/text/lorem.txt &\r"
    serial_wait "term: started" 1 15
    sleep 2
    moveto 400 300                                       # over term's text
    qmp "$(btn wheel-up true)" "$(btn wheel-up false)" "$(btn wheel-up true)" "$(btn wheel-up false)"
    serial_wait "term: scrolled back" 1 10
    sleep 0.5
    moveto $tx 166                                       # the top of term's scroll bar
    qmp "$(btn left true)" "$(btn left false)"
    serial_wait "term: scrolled back" 2 10
    sleep 0.5
}

wscroll_shell_test() {
    local image before f
    image=$(make_image ${P}wscroll "")
    windows_bare "$image"
    printf 'file\n' >"$WORK/${P}one.txt"
    for i in $(seq -w 1 60); do
        $RFS put "$image" $RFS_PART "/test/scroll/file$i.txt" "$WORK/${P}one.txt" >/dev/null || exit 1
    done
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=wscroll_session
    boot ${P}wscroll "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    [ "$ARCH_NAME" = x86_64 ] && expect "PS/2 mouse on the i8042 (port 2) with a wheel"
    expect_line "owl: showing rows 7-33 of 61"
    expect_line "owl: showing rows 35-61 of 61"
    check "two wheel steps up: term scrolled back 6 lines" "$(grep -a 'term: scrolled back' <<<"$TEXT" | head -1)" \
          eval 'grep -aq "^term: scrolled back 6 of [0-9][0-9]* lines" <<<"$TEXT"'
    check "its bar's top: the whole scrollback" "$(grep -a 'term: scrolled back' <<<"$TEXT" | tail -1)" \
          eval 'grep -a "^term: scrolled back" <<<"$TEXT" | tail -1 | grep -qE "back ([0-9]+) of \1 lines"'
    reject "panic"
    show_log_on_failure $before
}

# wdouble_session / wdouble_shell_test [setting]: a double click (the user's:
# two clicks opened a row however far apart they were; the rule is windowd's,
# the same for every program: WINDOW_DOUBLE_CLICK, 15n). owl at /: the
# "dev/" row clicked twice 1.3 s apart stays where it is (each click only
# selects); two clicks in quick succession open it (owl: at /dev). With
# "setting", /system/config/windows says double_click = 3000: the slow pair
# opens it. The pointer is driven over QMP. Proven by the old rule (the slow
# pair opens it) and a windowd ignoring the setting.
wdouble_session() {
    local n=1 t="/system/$ARCH_NAME/apps/owl.program/owl" q="$WORK/qmp.sock" curx cury dx=0
    if [ "$ARCH_NAME" = x86_64 ]; then curx=640 cury=400; else curx=400 cury=300; fi
    [ "$ARCH_NAME" = aarch64 ] && dx=-28                  # (owl's window at x 72 on ARM, 25e)
    qmp() { local c; { echo '{"execute":"qmp_capabilities"}'; sleep 0.3
                       for c in "$@"; do echo "$c"; sleep 0.1; done; } |
            nc -w 3 -U "$q" >>"$WORK/${NAME}-qmp.txt" 2>&1; }
    rel() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"rel","data":{"axis":"%s","value":%d}}]}}' "$1" "$2"; }
    btn() { printf '{"execute":"input-send-event","arguments":{"events":[{"type":"btn","data":{"button":"left","down":%s}}]}}' "$1"; }
    moveto() { qmp "$(rel x $(( $1 - curx )))" "$(rel y $(( $2 - cury )))"; curx=$1; cury=$2; }
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "$t / &\r"
    serial_wait "owl: started" 1 15
    sleep 1
    moveto $((130 + dx)) 192                             # the "dev/" row (/, bin/, boot/, dev/, ...: bin since 57b)
    qmp "$(btn true)" "$(btn false)"                     # a click: selected
    sleep 1.2
    qmp "$(btn true)" "$(btn false)"                     # another, 1.3 s later: selected again
    sleep 1.5
    serial_type 'echo slow-pair-done\r'                  # (a mark in the log between the pairs)
    sleep 1
    [ "$WDOUBLE_MODE" = setting ] && return               # (there the slow pair opened it)
    qmp "$(btn true)" "$(btn false)" "$(btn true)" "$(btn false)"   # two within 0.3 s: open
    sleep 1.5
}

wdouble_shell_test() {
    local image before name=wdouble
    WDOUBLE_MODE="${1:-}"
    [ -n "$WDOUBLE_MODE" ] && name=wdouble$WDOUBLE_MODE
    image=$(make_image ${P}$name "")
    windows_bare "$image"
    if [ "$WDOUBLE_MODE" = setting ]; then
        printf 'startup =\ndouble_click = 3000\n' > "$WORK/${P}windows.cfg"
        $RFS put "$image" $RFS_PART /system/config/windows "$WORK/${P}windows.cfg" >/dev/null || exit 1
    fi
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA="-device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=wdouble_session
    boot ${P}$name "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "owl: started"
    local opened mark
    opened=$(grep -an '^owl: at /dev$' <<<"$TEXT" | head -1 | cut -d: -f1)
    mark=$(grep -an '^slow-pair-done' <<<"$TEXT" | head -1 | cut -d: -f1)
    if [ "$WDOUBLE_MODE" = setting ]; then
        check "with double_click = 3000 the slow pair opened /dev (before the mark)" \
              "opened at line ${opened:-none}, mark at ${mark:-none}" \
              test -n "$opened" -a -n "$mark" -a "${opened:-0}" -lt "${mark:-0}"
    else
        check "the slow pair only selected; the quick pair opened /dev (after the mark)" \
              "opened at line ${opened:-none}, mark at ${mark:-none}" \
              test -n "$opened" -a -n "$mark" -a "${opened:-0}" -gt "${mark:-0}"
    fi
    reject "panic"
    show_log_on_failure $before
}

# wfit_session / wfit_shell_test: windows that fit the screen (the user's:
# imageview and reel opened windows larger than the screen). windowd keeps a
# window on the screen above the taskbar: moved up or left, and if still too
# big its program is asked for the largest content that fits. imageview with
# a 1600x1200 picture: its window, at the usual (100,100), would run past the
# bottom, so windowd moves it up (the picture right below its menu bar at
# y 56, nothing over the taskbar). reel with a 1400x1000 video: windowd takes
# the window (it refused anything larger than the screen), asks reel for
# what fits, and reel draws the frame fitted (the frame in the middle, the
# background in the bar beside it, nothing over the taskbar). Proven by the
# old windowd and reel (the window off the bottom; no reel window at all).
wfit_session() {
    local n=1 asked=0 mon="$WORK/monitor.sock"
    prompt_wait $n
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "/system/$ARCH_NAME/apps/imageview.program/imageview /test/big.ppm &\r"
    serial_wait "imageview: showing" 1 30
    sleep 2
    echo "screendump $WORK/${NAME}-picture.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
    serial_type "/system/$ARCH_NAME/apps/reel.program/reel /test/big.rvid &\r"
    serial_wait "reel: done" 1 60
    sleep 2
    echo "screendump $WORK/${NAME}-video.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    sleep 0.5
}

wfit_shell_test() {
    local image before w h
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}wfit "")
    windows_bare "$image"
    python3 -c 'import sys; open(sys.argv[1], "wb").write(b"P6\n1600 1200\n255\n" + bytes((200, 80, 40)) * (1600 * 1200))' \
        "$WORK/${P}big.ppm"
    python3 "$ROOT/scripts/mkvideo.py" "$WORK/${P}big.rvid" 1400 1000 >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /test/big.ppm "$WORK/${P}big.ppm" >/dev/null || exit 1
    $RFS put "$image" $RFS_PART /test/big.rvid "$WORK/${P}big.rvid" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=wfit_session
    boot ${P}wfit "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "imageview: showing /test/big.ppm (1600x1200)"
    expect "reel: playing /test/big.rvid (1400x1000, 2 fps, with audio)"
    # the picture's window moved up: content from y 56 (16 + title 24 + menu 16)
    check_screen px-154-60-200-80-40 $w $h "$WORK/${P}wfit-picture.ppm"
    check_screen notpx-154-$((h - 10))-200-80-40 $w $h "$WORK/${P}wfit-picture.ppm"
    # the video's window fitted (content from (4,40)), the last frame (blue) fitted in it
    check_screen px-$((w / 2))-$((h / 2 - 100))-40-40-200 $w $h "$WORK/${P}wfit-video.ppm"   # (the pointer is at the centre)
    check_screen px-10-$((h / 2))-54-61-74 $w $h "$WORK/${P}wfit-video.ppm"
    check_screen notpx-$((w / 2))-$((h - 10))-40-40-200 $w $h "$WORK/${P}wfit-video.ppm"
    reject "panic"
    show_log_on_failure $before
}

# video_session / video_shell_test: libvideo (decode) and reel. The host makes
# an RVID video (solid-colour frames + a tone) and the SHA-256 of its frames'
# RGBA pixels; videotest decodes it and prints the same. reel then plays it
# under windowd with an HDA controller present: a screenshot during the first
# frame shows its colour, and QEMU captures the audio track (non-silent).
# Proven by the host hash differing from a wrong decode.
video_session() {
    local n=1 asked=0 mon="$WORK/monitor.sock"
    prompt_wait $n
    answer_lines "/system/$ARCH_NAME/test/videotest /test/clip.rvid"
    serial_type 'windowd &\r'
    serial_wait "windowd: listening on /run/windowd" 1 15
    serial_type "/system/$ARCH_NAME/apps/reel.program/reel /test/clip.rvid &\r"
    serial_wait "reel: playing" 1 15
    sleep 0.4                                            # within the first frame (2 fps)
    echo "screendump $WORK/${NAME}-frame.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
    serial_wait "reel: done" 1 15
}

video_shell_test() {
    local image before w h hash peak
    if [ "$ARCH_NAME" = x86_64 ]; then w=1280 h=800; else w=800 h=600; fi
    image=$(make_image ${P}video "")
    windows_bare "$image"
    hash=$(python3 "$ROOT/scripts/mkvideo.py" "$WORK/${P}clip.rvid")
    $RFS put "$image" $RFS_PART /test/clip.rvid "$WORK/${P}clip.rvid" >/dev/null || exit 1
    QEMU_EXTRA="-device intel-hda -device hda-output,audiodev=snd"
    QEMU_EXTRA+=" -audiodev wav,id=snd,path=$WORK/${P}video.wav"
    [ "$ARCH_NAME" = aarch64 ] && QEMU_EXTRA+=" -device usb-mouse,bus=xhci.0,port=2"
    before=$failures
    SERIAL_SCRIPT=video_session
    boot ${P}video "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    expect "videotest: /test/clip.rvid 160x120 2fps 3frames audio sha256 $hash"
    check_screen region-106-142-12-12-255-128-0 $w $h "$WORK/${P}video-frame.ppm"    # the frame marker (any frame; below the menu bar)
    peak=$(python3 "$ROOT/scripts/wavpeak.py" "$WORK/${P}video.wav" 2>/dev/null || echo 0)
    check "reel played the audio track (peak $peak, want > 3000)" "silent" test "$peak" -gt 3000
    reject "panic"
    show_log_on_failure $before
}

# hda_session / hda_shell_test: the HDA audio driver. Boots with `hdatone`, so
# the kernel brings up QEMU's intel-hda, finds the codec's output and plays a
# test tone through a DMA ring; QEMU's wav audiodev captures what comes out and
# the host checks the file is not silent. Proven by the capture being silent
# when the driver does not drive the stream (e.g. no RUN bit). (67g) hda is a
# module matched by the PCI class (MODULE_CLASS): loaded for the controller,
# whose vendor:device no table lists (proven by a loader that ignores class
# entries: "not needed", no pcm0).
hda_shell_test() {
    local image before peak
    image=$(make_image ${P}hda "hdatone")
    QEMU_EXTRA="-device intel-hda -device hda-output,audiodev=snd"
    QEMU_EXTRA+=" -audiodev wav,id=snd,path=$WORK/${P}hda.wav"
    before=$failures
    boot ${P}hda "$image" "RitterOS kernel: boot complete"
    QEMU_EXTRA=
    check "pcm0: the codec's line out" "$(grep -a 'pcm0:' <<<"$TEXT")" \
          eval 'grep -aq "pcm0: .* codec 0: line out pin 3 (DAC 2); 48 kHz 16-bit stereo" <<<"$TEXT"' 
    compare "modules: hda loaded for the controller" 1 \
            "$(grep -cE "^modules: hda \(00:0[0-9a-f]\.0\), usbnet \(no device yet\) loaded; [0-9]+ not needed$" <<<"$TEXT")"
    expect "sound: test tone played on pcm0"
    peak=$(python3 "$ROOT/scripts/wavpeak.py" "$WORK/${P}hda.wav" 2>/dev/null || echo 0)
    check "the tone reached the output (peak sample $peak, want > 3000)" "silent capture" \
          test "$peak" -gt 3000
    reject "panic"
    show_log_on_failure $before
}

# hdamulti_session / hdamulti_shell_test: several sound cards (26a, the
# user's names: /dev/pcm0, pcm1, ..., speakers and headphones first). Two
# intel-hda controllers: the first with a line-out codec (hda-duplex), the
# second with a speaker codec (hda-micro); each codec's output goes to a wav
# file of its own. The driver reads the pins' configuration defaults, so the
# speaker's controller becomes pcm0 and the line out's pcm1. A quiet tone
# (8000) written to /dev/pcm0 and a loud one (20000) to /dev/pcm1 must come
# out of the speaker's and the line out's capture respectively. Proven by a
# driver that takes the controllers in bus order (both peaks swap).
hdamulti_session() {
    local n=1
    prompt_wait $n
    answer_lines 'cat /test/quiet.raw > /dev/pcm0' 'cat /test/loud.raw > /dev/pcm1' 'cat /test/quiet.raw > /dev/pcm2' \
                 'ls -l /dev'
}

hdamulti_shell_test() {
    local image before line speaker
    image=$(make_image ${P}hdamulti "")
    for t in quiet:8000 loud:20000; do
        python3 -c 'import sys, struct, math
amp = int(sys.argv[2])
sys.stdout.buffer.write(b"".join(struct.pack("<hh", v, v) for v in
    (int(amp * math.sin(2 * math.pi * 440 * i / 48000)) for i in range(24000))))' \
            "$WORK/${P}${t%%:*}.raw" "${t##*:}" >"$WORK/${P}${t%%:*}.raw"
        $RFS put "$image" $RFS_PART "/test/${t%%:*}.raw" "$WORK/${P}${t%%:*}.raw" >/dev/null || exit 1
    done
    rm -f "$WORK/${P}line.wav" "$WORK/${P}speaker.wav"
    QEMU_EXTRA="-device intel-hda,id=hda0 -device hda-duplex,bus=hda0.0,audiodev=line"
    QEMU_EXTRA+=" -audiodev wav,id=line,path=$WORK/${P}line.wav"
    QEMU_EXTRA+=" -device intel-hda,id=hda1 -device hda-micro,bus=hda1.0,audiodev=speaker"
    QEMU_EXTRA+=" -audiodev wav,id=speaker,path=$WORK/${P}speaker.wav"
    before=$failures
    SERIAL_SCRIPT=hdamulti_session
    boot ${P}hdamulti "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    check "pcm0 is the speaker's controller" "$(grep -a 'pcm0:' <<<"$TEXT")" \
          eval 'grep -aq "pcm0: .*speaker pin" <<<"$TEXT"'
    compare "ls -l /dev: the sound devices after null, zero, tty (52l)" \
            "$(printf 'crw-rw-rw-   1     0     0          0  %s\n' null zero tty; printf 'crw-------   1     0     0          0  %s\n' pcm0 pcm1)" \
            "$(command_output 'ls -l /dev' | grep '^c')"
    check "pcm1 is the line out's controller" "$(grep -a 'pcm1:' <<<"$TEXT")" \
          eval 'grep -aq "pcm1: .*line out pin" <<<"$TEXT"'
    expect_line "sh: /dev/pcm2: No such file or directory"
    speaker=$(python3 "$ROOT/scripts/wavpeak.py" "$WORK/${P}speaker.wav" 2>/dev/null || echo 0)
    line=$(python3 "$ROOT/scripts/wavpeak.py" "$WORK/${P}line.wav" 2>/dev/null || echo 0)
    check "pcm0's quiet tone from the speaker (peak $speaker, want 6000-10000)" "peak $speaker" \
          test "$speaker" -gt 6000 -a "$speaker" -lt 10000
    check "pcm1's loud tone from the line out (peak $line, want > 15000)" "peak $line" \
          test "$line" -gt 15000
    reject "panic"
    show_log_on_failure $before
}

# audio_session / audio_shell_test: libaudio (WAV decode + round-trip). The
# host makes a WAV and the SHA-256 of its 16-bit samples; audiotest decodes it
# and prints the same, then saves and reloads it and confirms the samples are
# unchanged. Proven by the host hash differing from any wrong decode.
audio_session() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines "/system/$ARCH_NAME/test/audiotest /test/snd.wav"
}

audio_shell_test() {
