    $RFS put "$image" $RFS_PART /test/snd.wav "$WORK/${P}snd.wav" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=audio_session
    boot ${P}audio "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
