    # (27c) forms
    local q_get="q=hello+world&exact=yes&lang=German&go=Search" q_post="user=anna&pw=secret1&note=two%0D%0Alines&size=l"
    expect_line "ibrowser: sending GET $web_url/echo?$q_get"
