# devnull_session / devnull_shell_test: /dev/null, /dev/zero and /dev/tty
# (52c): the shell's redirections to /dev/null (> and >>), reading it (the
# end at once), /dev/zero's zeros, /dev/tty reaching the terminal while
# the output goes elsewhere, test -e (fstattest checks their kind: the
# fstat test). Proven by a kernel without the names (open
# fails: "No such file or directory").
DEVNULL_LINES=(
    'echo hidden > /dev/null; echo $?'
    'echo hidden >> /dev/null; echo $?'
    'cat /dev/null | wc -c'
    'head -c 5000 /dev/zero | wc -c'
    'head -c 4 /dev/zero | tr "\\000" z; echo'
    "sh -c 'echo to the terminal > /dev/tty' > /dev/null"
    'test -e /dev/null; echo $?; test -f /dev/null; echo $?'
)
devnull_session() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines "${DEVNULL_LINES[@]}"
}

devnull_shell_test() {
    local image before
    image=$(make_image ${P}devnull "")
    before=$failures
    SERIAL_SCRIPT=devnull_session
    boot ${P}devnull "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    compare "> /dev/null" "0" "$(command_output "${DEVNULL_LINES[0]}")"
    compare ">> /dev/null" "0" "$(command_output "${DEVNULL_LINES[1]}")"
    compare "/dev/null reads nothing" "       0" "$(command_output "${DEVNULL_LINES[2]}")"
    compare "/dev/zero's bytes" "    5000" "$(command_output "${DEVNULL_LINES[3]}")"
    compare "/dev/zero reads zeros" "zzzz" "$(command_output "${DEVNULL_LINES[4]}")"
    compare "/dev/tty reaches the terminal" "to the terminal" "$(command_output "${DEVNULL_LINES[5]}")"
    compare "it exists, not a file" $'0\n1' "$(command_output "${DEVNULL_LINES[6]}")"
    reject "panic"
    show_log_on_failure $before
}

