                pending suspend spawn; do
        expect_line "sigmasktest: $name ok"
    done
    expect_line "sigmasktest: sigsuspend waited past the ignored signal"
    expect_line "sigmasktest: the child blocks SIGTERM"
    expect_line "sigmasktest: a blocked signal during a 400 ms sleep: slept on"
