# umask_session / umask_shell_test: umask (52h, SYS_UMASK): the shell's
# built-in -- octal, symbolic (= + - for u g o a), -S, a wrong mode, a
# child shell taking the mask -- line by line as the Mac's /bin/sh; then
# what a mask of 077 gives a file made by > and by touch (a program: the
# mask is passed on) and a folder made by mkdir, and 022 again giving
# 0644. Proven by a kernel that ignores the mask (fixed 022).
UMASK_LINES=(
    'umask'
    'umask 027; umask; umask -S'
    'umask u=rwx,g=rx,o=; umask'
    'umask 022; umask g-r,o+w; umask; umask -S'
    'umask a=r; umask'
    'umask 0; umask; umask 777; umask -S; umask 022'
    'umask 077; sh -c umask'
    'umask 8 2> e.txt; echo $?'
    'umask ug=rwx,o=; umask -S'
)
UMASK_FILES='umask 077; echo x > um1; touch um2; mkdir umd; umask 022; echo y > um3; ls -l | grep " um"'
umask_session() {
    local n=1 asked=0
    prompt_wait $n
    answer_lines 'cd /home/root' "${UMASK_LINES[@]}" "$UMASK_FILES"
}

umask_shell_test() {
    local image before line dir="$WORK/${P}umask"
    image=$(make_image ${P}umask "")
    before=$failures
    SERIAL_SCRIPT=umask_session
    boot ${P}umask "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    rm -rf "$dir"; mkdir -p "$dir"
    for line in "${UMASK_LINES[@]}"; do
        compare "as the Mac's sh: $line" "$(cd "$dir" && /bin/sh -c "$line" 2>/dev/null)" \
                "$(command_output "$line" | grep -v '^umask: ')"
    done
    compare "files and folders made under 077, then 022 (ls: in the folder's order)" \
            "$(printf -- '-rw-------   1     0     0          2  um1\n-rw-------   1     0     0          0  um2\ndrwx------   1     0     0      <dir>  umd/\n-rw-r--r--   1     0     0          2  um3')" \
            "$(command_output "$UMASK_FILES")"
    expect_line "umask: 8: not a mode"
    reject "panic"
    show_log_on_failure $before
}

