            "$(command_output "/system/$ARCH_NAME/test/canceltest own" | grep '^canceltest: ')"
    expect_line "canceltest-own: an asynchronous cancel of a busy loop: 0, PTHREAD_CANCELED, cleanup 100000, it ran: yes"
    expect_line "canceltest-own: a thread that has ended: ESRCH"
