    check "the Python reference agrees with the RFCs' vectors" \
          "$(python3 "$ROOT/scripts/crypto_ref.py" vectors | grep -v ': ok$')" \
          eval 'python3 "$ROOT/scripts/crypto_ref.py" vectors >/dev/null'
    compare "every result as the reference's" "$(python3 "$ROOT/scripts/crypto_ref.py" expected)" \
            "$(command_output "/system/$ARCH_NAME/test/sshcrypto" | grep -v '^time: ')"
    echo "      $(command_output "/system/$ARCH_NAME/test/sshcrypto" | grep '^time: ')"
