# netloss_session: TCP over a lossy network (netloss_shell_test).
netloss_session() {
    local n=1 asked=0 t="/system/$ARCH_NAME/test/sock"
    prompt_wait $n
    dhcp_wait eth0 10.0.2.15
    answer_lines "$t tcp 10.0.2.2 $NET_ECHO_PORT hello-lossy" \
                 "$t get 10.0.2.2 $NET_SEND_PORT 300000" "$t put 10.0.2.2 $NET_RECV_PORT 300000" \
                 "$t slowget 10.0.2.2 $NET_SEND_PORT 300000" "$t loop 300000" 'net'
}

# netloss_shell_test: TCP loses one segment in 50, coming and going
# ("netloss=50"; at 1 in 10 QEMU's own TCP, which resends only after
# its timeout, backs off until it gives up): the handshake, a short
# exchange and its FINs, 300,000
# bytes each way, read slowly, and over the loopback all arrive intact;
# segments were sent again fast (three duplicate acknowledgements), and
# segments after a gap were kept.
netloss_shell_test() {
    local image before services line
    image=$(make_image ${P}netloss "netloss=50")
    python3 "$ROOT/scripts/testnet.py" tcp-echo:$NET_ECHO_PORT tcp-send:$NET_SEND_PORT:300000 \
            tcp-recv:$NET_RECV_PORT >"$WORK/${P}testnet.log" 2>&1 &
    services=$!
    host_service_wait "$WORK/${P}testnet.log" listening
    QEMU_EXTRA="-netdev user,id=net0 -device e1000,netdev=net0,mac=52:54:00:12:34:56"
    before=$failures
    SERIAL_SCRIPT=netloss_session
    boot ${P}netloss "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    kill $services 2>/dev/null
    wait $services 2>/dev/null
    local t="/system/$ARCH_NAME/test/sock"
    expect "  network:       TCP loses 1 segment in 50 (netloss)"
    expect_line "sock: answer: 'echo: hello-lossy'"
    compare "300,000 bytes from the Mac" "sock: received 300000 bytes, pattern ok" \
            "$(command_output "$t get 10.0.2.2 $NET_SEND_PORT 300000")"
    compare "300,000 bytes to the Mac" "sock: sent 300000 bytes" \
            "$(command_output "$t put 10.0.2.2 $NET_RECV_PORT 300000")"
    compare "the Mac received them" "tcp-recv: received 300000 bytes, pattern ok" \
            "$(grep '^tcp-recv:' "$WORK/${P}testnet.log")"
    compare "read slowly" "sock: received 300000 bytes, pattern ok" \
            "$(command_output "$t slowget 10.0.2.2 $NET_SEND_PORT 300000")"
    compare "over the loopback" "sock: received 300000 bytes, pattern ok" \
            "$(command_output "$t loop 300000")"
    line=$(command_output 'net' | grep '^tcp: ')
    echo "      $line"
    check "segments lost, sent again fast, kept after gaps" "not so: $line" \
          eval 'grep -Eq "after a timeout, [1-9][0-9]* fast; [1-9][0-9]* kept after a gap, .*, [1-9][0-9]* lost on purpose \(1 in 50\)" <<<"$line"'
    reject "panic"
    show_log_on_failure $before
}

# users_session: hashes, users and passwords (users_shell_test).
users_session() {
    local n=1 typed
    local -a typed_lines=("/system/$ARCH_NAME/test/crypto" 'useradd anna' 'useradd anna'
                          'useradd 9x' 'passwd anna' 'passwd anna' 'passwd nobody'
                          'ls -l /home /system/config/users /system/config/passwords' 'cat /system/config/users' 'id')
    local passwords=0
    prompt_wait $n
    for typed in "${typed_lines[@]}"; do
        serial_type "$typed\r"
        if [ "$typed" = 'passwd anna' ]; then     # twice the same, then two that differ
            passwords=$((passwords + 1))
            serial_wait "New password: " $passwords
            serial_type "$( [ $passwords = 1 ] && echo 'secret one' || echo 'first try')\r"
            serial_wait "Again: " $passwords
            serial_type "$( [ $passwords = 1 ] && echo 'secret one' || echo 'other try')\r"
        fi
        n=$((n + 1))
        prompt_wait $n 60
    done
}

# users_shell_test: SHA-256, HMAC and PBKDF2 against Python's hashlib,
# kernel random bytes, useradd and passwd; the host verifies the files.
users_shell_test() {
    local image before want got files
    image=$(make_image ${P}usershell "")
    before=$failures
    SERIAL_SCRIPT=users_session
    boot ${P}usershell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    want=$(python3 - <<'PY'
import hashlib, hmac
print("sha256(''):", hashlib.sha256(b"").hexdigest())
print("sha256('abc'):", hashlib.sha256(b"abc").hexdigest())
print("sha256(a million 'a'):", hashlib.sha256(b"a" * 1000000).hexdigest())
print("hmac('Jefe'):", hmac.new(b"Jefe", b"what do ya want for nothing?", "sha256").hexdigest())
print("hmac(131-byte key):", hmac.new(b"\xaa" * 131,
      b"Test Using Larger Than Block-Size Key - Hash Key First", "sha256").hexdigest())
print("pbkdf2(1):", hashlib.pbkdf2_hmac("sha256", b"password", b"salt", 1, 32).hex())
print("pbkdf2(4096, 40 bytes):", hashlib.pbkdf2_hmac("sha256", b"password", b"salt", 4096, 40).hex())
PY
)
    got=$(command_output "/system/$ARCH_NAME/test/crypto" | head -7 | sed 's/^crypto: //')
    compare "SHA-256, HMAC, PBKDF2 = Python's hashlib" "$want" "$got"
    expect_line "crypto: two random draws differ: yes"
    expect "crypto: a password hash (100000 iterations) took"
    reject "ChaCha20 self-test FAILED"
    expect_line "useradd: anna: user ID 1000, home /home/anna; set a password with: passwd anna"
    expect_line "useradd: anna: the user exists"
    expect_line "useradd: 9x: names are 1-31 of a-z 0-9 _ - (not starting with a digit or -)"
    expect_line "passwd: password for anna set"
    expect_line "passwd: the two differ; nothing changed"
    expect_line "passwd: nobody: no such user"
    reject "secret one"                             # passwords are never shown
    reject "first try"
    compare "ls -l: anna's home, the two files and their modes" "$(printf '%s\n' \
            'drwx------   1     0     0      <dir>  root/' \
            'drwxr-xr-x   1  1000  1000      <dir>  anna/' \
            '-rw-r--r--   1     0     0         26  /system/config/users' \
            '-rw-------   1     0     0        220  /system/config/passwords')" \
            "$(command_output 'ls -l /home /system/config/users /system/config/passwords')"
    compare "cat /system/config/users" "anna:1000:1000:/home/anna" "$(command_output 'cat /system/config/users')"
    compare "id" "uid=0(root) gid=0" "$(command_output 'id')"
    # The host recomputes anna's hash from the stored salt.
    files=$(python3 - "$image" <<'PY'
import hashlib, sys
sys.path.insert(0, "scripts")
import ritterfs as r
with open(sys.argv[1], "rb") as f:
    reader = r.Reader(r.Partition(f, 133120, 1961984))
    lines = reader.content(reader.lookup("/system/config/passwords")[1]).decode().splitlines()
line = [l for l in lines if l.startswith("anna:")][0]           # root's is there too
name, iterations, salt, digest = line.strip().split(":")
ok = name == "anna" and int(iterations) == 100000 and len(salt) == 32 and \
     hashlib.pbkdf2_hmac("sha256", b"secret one", bytes.fromhex(salt), 100000).hex() == digest
print("ok" if ok else "WRONG: " + line)
PY
)
    check "the stored password is PBKDF2 of 'secret one' with its random salt" "host: $files" \
          test "$files" = ok
    reject "panic"
    show_log_on_failure $before
}

# write_session: writing files from the shell (write_shell_test).
write_session() {
    local n=1 typed
    local -a typed_lines=('echo hello > /a.txt' 'echo more >> /a.txt' 'echo "and > quoted" >>/a.txt'
                          'cat /a.txt' 'cat < /a.txt' 'cat /test/text/lorem.txt > /big.txt'
                          'echo short > /short.txt' 'cat /test/text/lorem.txt > /short.txt'
                          'echo short > /short.txt' 'cat > /typed.txt' 'touch /t1 /t2' 'ls /t1'
                          'touch /test' 'echo x > /test' 'echo x > /.snapshots/a' 'echo x > ;'
                          'pwd > /p.txt' '> /nothing' 'cat < /nope'
                          "/system/$ARCH_NAME/test/fwrite" 'mem'
                          "/system/$ARCH_NAME/test/perm" 'id' 'ls -l /perm')
    prompt_wait $n
    for typed in "${typed_lines[@]}"; do
        serial_type "$typed\r"
        if [ "$typed" = 'cat > /typed.txt' ]; then
            sleep 1
            serial_type 'line one\r'
            sleep 0.5
            serial_type '\004'                     # Ctrl-D: the end of what cat reads
        fi
        n=$((n + 1))
        prompt_wait $n 60
    done
}

# write_shell_test: redirections and the fwrite test program; the host
# checks every file they wrote.
write_shell_test() {
    local image before host files
    image=$(make_image ${P}writeshell "")
    before=$failures
    SERIAL_SCRIPT=write_session
    boot ${P}writeshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    compare "echo >, >> and a quoted '>'" "$(printf 'hello\nmore\nand > quoted')" "$(command_output 'cat /a.txt')"
    compare "cat < FILE" "$(printf 'hello\nmore\nand > quoted')" "$(command_output 'cat < /a.txt')"
    compare "touch" "         0  /t1" "$(command_output 'ls /t1')"
    compare "touch of a folder: its time, nothing said (63m, POSIX)" "" "$(command_output 'touch /test')"
    expect_line "sh: /test: Is a directory"
    expect_line "sh: /.snapshots/a: Read-only file system"
    expect_line "sh: syntax error near ;"                       # (51a: echo x > ;)
    expect_line "sh: /nope: No such file or directory"
    expect_line "fwrite: close the big file: 0"
    expect_line "fwrite: 10485760 bytes written, 10485760 read back the same"
    expect_line "fwrite: read-write: '012abc6789'"
    expect_line "fwrite: hole: 1048579 bytes, the first 8 zero"
    expect_line "fwrite: appended twice, size: 8"
    expect_line "fwrite: truncated, size: 0"
    expect_line "fwrite: write to a read-only descriptor: -1, Bad file descriptor"
    expect_line "fwrite: read from a write-only descriptor: -1, Bad file descriptor"
    expect_line "fwrite: open a missing file without O_CREAT: -1, No such file or directory"
    expect_line "fwrite: open a directory for writing: -1, Is a directory"
    expect_line "fwrite: create in a missing directory: -1, No such file or directory"
    expect_line "fwrite: unknown flags: -1, Invalid argument"
    expect_line "fwrite: write after another removed it: -1, No such file or directory"
    # Permissions: root prepares /perm, the test program becomes user 1000.
    local perm_lines
    perm_lines=$(cat <<'LINES'
perm: setgid 1000: 0
perm: setuid 1000: 0
uid=1000 gid=1000
perm: id as the user (exit code): 0
perm: read root's 0600 file: -1, Permission denied
perm: read a 0644 file (bytes): 13
perm: open it for writing: -1, Permission denied
perm: create in root's directory: -1, Permission denied
perm: mkdir in root's directory: -1, Permission denied
perm: remove root's file: -1, Permission denied
perm: rename root's file: -1, Permission denied
perm: create in my directory: 3
perm: my new file: owner 1000, group 1000, mode 644
perm: chmod my file: 0
perm: chmod root's file: -1, Operation not permitted
perm: chown my file to root: -1, Operation not permitted
perm: stat through a 0700 directory: -1, Permission denied
perm: list a 0700 directory: -1, Permission denied
perm: cd into it: -1, Permission denied
perm: run a 0644 copy of echo: -1, Permission denied
an allowed program ran
perm: run a 0755 copy (exit code): 0
perm: copy root's secret: -1, Permission denied
perm: copy a readable file into my directory: 0
perm: the copy's owner: 1000
perm: copy a directory holding a root-only file: -1, Permission denied
perm: signal the root process 1: -1, Operation not permitted
perm: bind a port below 1024: -1, Permission denied
perm: bind a high port: 50000
perm: attribute on root's file: -1, Permission denied
perm: read an attribute of root's 0600 file: -1, Permission denied
perm: take a snapshot: -1, Operation not permitted
perm: back to root: -1, Operation not permitted
perm: switch the machine off: -1, Operation not permitted
perm: remove my file: 0
LINES
)
    compare "perm: what user 1000 may and may not do" "$perm_lines" \
            "$(command_output "/system/$ARCH_NAME/test/perm")"
    compare "id: the shell is still root" "uid=0(root) gid=0" "$(command_output 'id')"
    local echo_size
    echo_size=$($RFS ls "$image" $RFS_PART "/system/$ARCH_NAME/bin/echo" | awk '{print $1}')
    compare "ls -l /perm" "$(printf '%s\n' '-rw-------   1     0     0         10  secret' \
                                    '-rw-r--r--   1     0     0         13  open.txt' \
                                    'drwxr-xr-x   1  1000  1000      <dir>  user/' \
                                    'drwx------   1     0     0      <dir>  closed/'
                            printf -- '-rwxr-xr-x   1     0     0 %10d  echo-run\n' "$echo_size"
                            printf -- '-rw-r--r--   1     0     0 %10d  echo-norun\n' "$echo_size"
                            printf '%s' 'drwxr-xr-x   1     0     0      <dir>  mixed/')" \
            "$(command_output 'ls -l /perm')"
    reject "panic"
    files=$(python3 - "$image" "$DISK" <<'PY'
import struct, sys
sys.path.insert(0, "scripts")
import ritterfs as r
with open(sys.argv[2], "rb") as f:
    lorem = r.Reader(r.Partition(f, 133120, 1961984))
    lorem = lorem.content(lorem.lookup("/test/text/lorem.txt")[1])
with open(sys.argv[1], "rb") as f:
    part = r.Partition(f, 133120, 1961984)
    reader = r.Reader(part)
    def text(path):
        return reader.content(reader.lookup(path)[1])
    s, out, mask = 0x5249545445524653, bytearray(), (1 << 64) - 1
    for _ in range(10 * 1024 * 1024 // 8):
        s ^= (s << 13) & mask; s ^= s >> 7; s ^= (s << 17) & mask
        out += struct.pack("<Q", s)
    hole = reader.lookup("/fw/hole.bin")[1]
    checks = {
        "big.bin": text("/fw/big.bin") == bytes(out),
        "small.txt": text("/fw/small.txt") == b"012abc6789",
        "p.txt": text("/p.txt") == b"/\n",                   # (51c: pwd > FILE works)
        "nothing": text("/nothing") == b"",                  # (51c: > FILE alone, as POSIX)
        "log.txt": text("/fw/log.txt") == b"",
        "hole.bin": text("/fw/hole.bin") == bytes(1024 * 1024) + b"end" and
                    len(r.tree_blocks(part, hole)) < 10,      # the zeros are not stored
        "big.txt": text("/big.txt") == lorem,
        "short.txt": text("/short.txt") == b"short\n",
        "typed.txt": text("/typed.txt") == b"line one\n",
        "nothing": text("/nothing") == b"",
    }
print(" ".join(k for k, v in checks.items() if not v) or "all as written")
PY
)
    check "the host reads every written file as written" "host: wrong: $files" test "$files" = "all as written"
    host=$($RFS check "$image" $RFS_PART)
    check "host check after the writes: ok" "host: '$host'" \
          eval '[[ "$host" == *"all checksums ok, bitmap consistent" ]]'
    show_log_on_failure $before
}

