# fs_shell_test: mkdir, rmdir, rm, mv and cp typed into the shell; the
# host checks the result.
fs_shell_test() {
    local image before host same
    image=$(make_image ${P}fsshell "")
    before=$failures
    SERIAL_SCRIPT=fs_session
    boot ${P}fsshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    compare "mkdir" "" "$(command_output 'mkdir /work' 1)"
    expect_line "mkdir: /work: File exists"
    compare "mkdir -p, then ls" "     <dir>  c/" "$(command_output 'ls /work/a/b')"
    expect_line "cp: /test/data: Is a directory (use -r)"
    compare "cp -r copied /test/data" "$($RFS ls "$DISK" $RFS_PART /test/data)" \
            "$(command_output 'ls /work/data')"
    compare "mv renamed and moved into a directory" "$(printf '     <dir>  b/\n        21  hi.txt')" \
            "$(command_output 'ls /work/a')"
    compare "cat the moved file" "Hello from RitterFS!" "$(command_output 'cat /work/a/hi.txt')"
    expect_line "mv: /work -> /work/a/inside: Invalid argument"
    expect_line "rmdir: /work/a: Directory not empty"
    expect_line "rm: /work/a: Is a directory"
    compare "rm -r and rm, then ls /" "$(printf '    <link>  bin -> /system/%s/bin\n    <link>  etc -> /system/config\n    <link>  lib -> /system/%s/lib\n     <dir>  system/\n     <dir>  test/\n     <dir>  tmp/\n     <dir>  usr/\n     <dir>  home/\n     <dir>  work/\n     <dir>  boot/\n     <dir>  dev/\n     <dir>  volumes/' "$ARCH_NAME" "$ARCH_NAME")" \
            "$(command_output 'ls /')"
    expect_line "rm: /nope: No such file or directory"
    expect_line "rmdir: /test/hello.txt: Not a directory"
    expect_line "mkdir: /.snapshots/x: Read-only file system"
    expect_line "rm: /.snapshots/s/readme.txt: Read-only file system"
    expect_line "mv: /test and /test are the same file"
    # (68a) mv over an existing target replaces it, as POSIX's rename
    compare "(68a) a file moved over another replaces it" \
            "$($RFS ls "$DISK" $RFS_PART / | grep ' readme.txt$' | sed 's/readme.txt$/t.txt/')" \
            "$(command_output 'mkdir /work/m; cp /test/hello.txt /work/m/t.txt; cp /readme.txt /work/m/n.txt; mv /work/m/n.txt /work/m/t.txt; ls /work/m')"
    compare "(68a) a folder moved over an empty one replaces it" "     <dir>  in/" \
            "$(command_output 'mkdir -p /work/m/d1/in; mkdir -p /work/m/d2/d1; mv /work/m/d1 /work/m/d2; ls /work/m/d2/d1')"
    expect_line "mv: /work/m/d2 -> /work/m/e/d2: Directory not empty"
    expect_line "mv: /work/m/t.txt -> /work/m/f/t.txt: Is a directory"
    expect_line "mv: /work/m/g -> /work/m/h/g: Not a directory"
    expect_line "mv: /work/m/l and /work/m/h/g are the same file"
    reject "panic"
    # The host: the restored files are the originals; nothing else changed.
    same=$(python3 - "$image" "$DISK" <<'PY'
import sys
sys.path.insert(0, "scripts")
import ritterfs as r
def read(image, path):
    with open(image, "rb") as f:
        reader = r.Reader(r.Partition(f, 133120, 1961984))
        return reader.content(reader.lookup(path)[1])
pairs = [("/readme.txt", "/readme.txt"), ("/work/restored/large.bin", "/test/data/large.bin"),
         ("/work/restored/medium.bin", "/test/data/medium.bin"),
         ("/work/restored/sparse.bin", "/test/data/sparse.bin"),
         ("/work/a/hi.txt", "/test/hello.txt"), ("/work/m/t.txt", "/readme.txt"),
         ("/work/m/h/g", "/test/hello.txt")]
print(all(read(sys.argv[1], a) == read(sys.argv[2], b) for a, b in pairs))
PY
)
    check "restored from the snapshot and moved files are identical to the originals" \
          "host compared: '$same'" test "$same" = True
    host=$($RFS check "$image" $RFS_PART)
    check "host check after the session: ok, data shared by copies, 1 snapshot" "host: '$host'" \
          eval '[[ "$host" == *", copies: "*" blocks shared ("*", snapshots: 1 ("*"all checksums ok, bitmap consistent" ]]'
    check "/gone was created and removed again" "host ls /: $($RFS ls "$image" $RFS_PART / | tr '\n' '|')" \
          eval '! $RFS ls "$image" $RFS_PART / | grep -q gone'
    show_log_on_failure $before
}

# attr_session: attributes and find from the shell (attr_shell_test).
ATTR_TYPED=('attr /test/hello.txt' 'attr /test/hello.txt color=blue' 'attr /test/hello.txt lang=en'
            'attr /test/docs kind=folder' 'attr /test/hello.txt' 'attr /test/hello.txt color'
            'attr /test/hello.txt size' 'attr /nope x=1' 'attr /test/hello.txt -lang'
            'attr /test/hello.txt -lang' 'snapshot create s' 'attr /.snapshots/s/test/hello.txt'
            'attr /.snapshots/s/test/hello.txt x=1' 'find /test -name "*.txt"'
            'find /test -attr color' 'find /test -attr color=red' 'find / -attr kind=folder'
            'find /test -name "h*" -attr color=blue')
attr_session() {
    local n=1 typed
    prompt_wait $n
    for typed in "${ATTR_TYPED[@]}"; do
        serial_type "$typed\r"
        n=$((n + 1))
        prompt_wait $n 30
    done
}

# attr_shell_test: the programs attr and find, typed into the shell.
attr_shell_test() {
    local image before host want
    image=$(make_image ${P}attrshell "")
    before=$failures
    SERIAL_SCRIPT=attr_session
    boot ${P}attrshell "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    compare "attr (none yet)" "" "$(command_output 'attr /test/hello.txt' 1)"
    compare "attr lists two" "$(printf 'color=blue\nlang=en')" "$(command_output 'attr /test/hello.txt' 2)"
    compare "attr shows one" "color=blue" "$(command_output 'attr /test/hello.txt color')"
    expect_line "attr: /test/hello.txt: size: No such attribute"
    expect_line "attr: /nope: x: No such file or directory"
    compare "attr -lang removes it" "" "$(command_output 'attr /test/hello.txt -lang' 1)"
    compare "attr -lang again" "$(printf 'attr: /test/hello.txt: lang: No such attribute\nattr: exit code 1')" \
            "$(command_output 'attr /test/hello.txt -lang' 2)"
    compare "attr in a snapshot" "color=blue" "$(command_output 'attr /.snapshots/s/test/hello.txt')"
    expect_line "attr: /.snapshots/s/test/hello.txt: x: Read-only file system"
    # find -name: the host walks the same tree in the same order.
    want=$(python3 - "$image" <<'PY'
import fnmatch, sys
sys.path.insert(0, "scripts")
import ritterfs as r
with open(sys.argv[1], "rb") as f:
    reader = r.Reader(r.Partition(f, 133120, 1961984))
    def walk(path, oid):
        for name, child, typ in r.parse_directory(reader.content(reader.inodes[oid]), [], oid):
            if fnmatch.fnmatchcase(name, "*.txt"):
                print(f"{path}/{name}")
            if typ == r.TYPE_DIR:
                walk(f"{path}/{name}", child)
    walk("/test", reader.lookup("/test")[0])
PY
)
    compare "find -name '*.txt' = the host's walk" "$want" "$(command_output 'find /test -name "*.txt"')"
    compare "find -attr color" "/test/hello.txt" "$(command_output 'find /test -attr color')"
    compare "find -attr color=red (none)" "" "$(command_output 'find /test -attr color=red')"
    compare "find / -attr kind=folder" "/test/docs" "$(command_output 'find / -attr kind=folder')"
    compare "find -name and -attr together" "/test/hello.txt" \
            "$(command_output 'find /test -name "h*" -attr color=blue')"
    reject "panic"
    host=$($RFS check "$image" $RFS_PART)
    check "host check after the session: ok, 2 attributes on 2 objects, 1 snapshot" "host: '$host'" \
          eval '[[ "$host" == *", attributes: 2 on 2 objects, snapshots: 1 ("*"all checksums ok, bitmap consistent" ]]'
    show_log_on_failure $before
}

# snapshot_session_1 / _2: snapshots from the shell (snapshot_shell_test).
snapshot_session_1() {
    local n=1 typed
    prompt_wait $n
    for typed in 'snapshot' 'snapshot create one' 'snapshot' 'ls /.snapshots' \
                 'ls /.snapshots/one' 'cat /.snapshots/one/readme.txt' \
                 'snapshot create one' 'snapshot create a/b' 'snapshot delete nope' \
                 'ls /.snapshots/nope' 'cd /.snapshots/one/test' 'pwd' 'ls' \
                 "/.snapshots/one/system/$ARCH_NAME/bin/echo from the snapshot" 'cd /'; do
        serial_type "$typed\r"
        n=$((n + 1))
        prompt_wait $n 30
    done
}

snapshot_session_2() {
    local n=1 typed
    prompt_wait $n
    for typed in 'cat /readme.txt' 'cat /.snapshots/one/readme.txt' 'versions /readme.txt' \
                 'cd /test' 'versions hello.txt' 'versions /nope' 'versions /test' \
                 'versions /.snapshots/one/readme.txt' 'cd /' 'snapshot delete one' \
                 'ls /.snapshots' 'snapshot'; do
