# snapshot_shell_test: the snapshot program and /.snapshots, typed into the
# shell. The first boot takes snapshot 'one'; the host then changes
# /readme.txt; the second boot reads both versions and deletes 'one'.
snapshot_shell_test() {
    local image before host host_kept old_readme old_size new_size hello_size freed
    image=$(make_image ${P}snapshell "")
    old_readme=$($RFS cat "$image" $RFS_PART /readme.txt)
    old_size=$($RFS ls "$image" $RFS_PART /readme.txt | awk '{print $1}')
    before=$failures
    SERIAL_SCRIPT=snapshot_session_1
    boot ${P}snapshell-1 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect_line "no snapshots"
    # Logging in wrote before (root's password, root's home): the snapshot's
    # generation is whatever the file system had reached.
    local snap_gen
    snap_gen=$(sed -n "s/^snapshot 'one' taken at generation \([0-9][0-9]*\)$/\1/p" <<<"$TEXT")
    check "snapshot 'one' taken (generation ${snap_gen:-?})" "no 'snapshot 'one' taken' line" \
          test -n "$snap_gen"
    expect_line "$(printf '%-24s generation %s' one "$snap_gen")"
    compare "ls /.snapshots" "     <dir>  one/" "$(command_output 'ls /.snapshots')"
    compare "ls /.snapshots/one = host ls /" "$($RFS ls "$image" $RFS_PART /)" \
            "$(command_output 'ls /.snapshots/one')"
    compare "cat /.snapshots/one/readme.txt = host cat /readme.txt" "$old_readme" \
            "$(command_output 'cat /.snapshots/one/readme.txt')"
    expect_line "snapshot: one: File exists"
    expect_line "snapshot: a/b: Invalid argument"
    expect_line "snapshot: nope: No such file or directory"
    expect_line "ls: /.snapshots/nope: No such file or directory"
    compare "pwd in a snapshot" "/.snapshots/one/test" "$(command_output 'pwd')"
    compare "ls in /.snapshots/one/test = host ls /test" "$($RFS ls "$image" $RFS_PART /test)" \
            "$(command_output 'ls')"
    expect_line "from the snapshot"
    reject "panic"
    host=$($RFS check "$image" $RFS_PART)
    check "host check after 'snapshot create': ok, 1 snapshot" "host says '$host'" \
          eval '[[ "$host" == *"snapshots: 1 ("*"; all checksums ok, bitmap consistent" ]]'
    show_log_on_failure $before

    # The host changes /readme.txt; the snapshot keeps the old one.
    printf 'readme.txt, changed after snapshot one\n' >"$WORK/${P}snap-readme.txt"
    $RFS put "$image" $RFS_PART /readme.txt "$WORK/${P}snap-readme.txt" >/dev/null
    host=$($RFS check "$image" $RFS_PART)
    host_kept=$(sed -n 's/.*snapshots: 1 (\([0-9][0-9]*\) blocks kept only for them.*/\1/p' <<<"$host")
    before=$failures
    SERIAL_SCRIPT=snapshot_session_2
    boot ${P}snapshell-2 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    compare "cat /readme.txt (live, changed)" "readme.txt, changed after snapshot one" \
            "$(command_output 'cat /readme.txt')"
    compare "cat /.snapshots/one/readme.txt (the old one)" "$old_readme" \
            "$(command_output 'cat /.snapshots/one/readme.txt')"
    # File history: the snapshot's version, then the one now.
    new_size=$($RFS ls "$image" $RFS_PART /readme.txt | awk '{print $1}')
    hello_size=$($RFS ls "$image" $RFS_PART /test/hello.txt | awk '{print $1}')
    compare "versions /readme.txt" "$(printf '/readme.txt:\n  %-28s %10d bytes  %s\n  %-28s %10d bytes  %s' \
            "one (generation $snap_gen)" "$old_size" 'first version' now "$new_size" changed)" \
            "$(command_output 'versions /readme.txt')"
    compare "versions hello.txt (relative, unchanged)" "$(printf '/test/hello.txt:\n  %-28s %10d bytes  %s\n  %-28s %10d bytes  %s' \
            "one (generation $snap_gen)" "$hello_size" 'first version' now "$hello_size" unchanged)" \
            "$(command_output 'versions hello.txt')"
    compare "versions /nope" "$(printf '/nope:\n  %-28s (not there)\n  %-28s (not there)' \
            "one (generation $snap_gen)" now)" "$(command_output 'versions /nope')"
    expect_line "versions: /test: Is a directory"
    expect_line "versions: /.snapshots/one/readme.txt: give the path as it is now, not in a snapshot"
    freed=$(sed -n "s/^snapshot 'one' deleted, \([0-9][0-9]*\) block(s) free again$/\1/p" <<<"$TEXT")
    check "'snapshot delete one' freed the $freed blocks the host counted as kept for it" \
          "freed '${freed:-?}', host counted '${host_kept:-?}'" \
          eval '[ -n "$freed" ] && [ "$freed" -gt 0 ] && [ "$freed" = "$host_kept" ]'
    compare "ls /.snapshots after the delete" "" "$(command_output 'ls /.snapshots')"
    compare "snapshot (list) after the delete" "no snapshots" "$(command_output 'snapshot')"
    reject "panic"
    host=$($RFS check "$image" $RFS_PART)
    check "host check after the delete: ok, nothing held back" "host says '$host'" \
          eval '[[ "$host" == *"entries; all checksums ok, bitmap consistent" ]]'
    show_log_on_failure $before
}

# swap_session_1 / _2: the swap file from the shell (swap_shell_test).
swap_session_1() {
    local n=1 typed
    prompt_wait $n
    for typed in 'swap' 'swap on' 'swap make 1X' 'swap make 16M' 'swap' 'mem' \
                 'cat /system/swap' 'rm /system/swap' 'cp /system/swap /tmp/copy' \
                 'cp -r /system /tmp/system' 'ls /tmp/system' 'rm -r /tmp/system' \
                 'snapshot create keep' 'cat /.snapshots/keep/system/swap' \
                 'rm /system/config/swap' 'swap off' 'cat /system/config/swap' 'swap' 'swap on' \
                 'cat /system/config/swap'; do
        serial_type "$typed\r"
        n=$((n + 1))
        prompt_wait $n 120
    done
}

swap_session_2() {
    local n=1 typed
    prompt_wait $n
    for typed in 'swap' 'rm /system/swap' 'swap off' 'rm /system/swap' 'swap on' \
                 'head -c 100 /dev/zero > /system/swap' 'swap on' 'rm /system/swap' \
                 'head -c 8192 /dev/zero > /system/swap' 'snapshot create two' 'swap on' \
                 'snapshot delete two' 'snapshot delete keep' 'rm /system/swap' 'swap'; do
