# swap_session_3: paging out (35b) with memory=128: swaptest over more memory
# than the machine has (a child forked at the end reads it too), then a run
# killed with pages in swap.
swap_session_3() {
    local n=1 typed
    prompt_wait $n
    for typed in 'mem' 'swap make 192M' "/system/$ARCH_NAME/test/swaptest 144 2 fork" \
                 "/system/$ARCH_NAME/test/swaptest 144 3 shared" 'swap' \
                 "/system/$ARCH_NAME/test/swaptest 144 1000 &" 'sleep 60' 'swap' 'kill $!' \
                 'sleep 2' 'swap' 'swap off' 'mem'; do
        serial_type "$typed\r"
        n=$((n + 1))
        prompt_wait $n 1800                         # (x86's emulation: ~0.5 MB/s)
    done
}

# swap_shell_test (35a): swap's encryption checked against LibreSSL's
# aes-256-xts on the Mac (kernel/xts.c with common/aes.c); then the swap
# program on one image booted twice. The first boot makes /system/swap and
# turns swap on (the self-test writes and reads every slot), finds the file
# refused to programs (read, removed, copied; left out of a folder's copy),
# takes a snapshot that holds it and turns swap off and on again (the
# self-test writes in place under the snapshot). The host then finds the
# file fixed with every block written, and the whole file system intact;
# a boot with `scrub` too. The last boot turns swap on from
# /system/config/swap, and refuses files that cannot be fixed (a part
# block; blocks a snapshot shares). (35b) Then a machine using 128 MiB
# (memory=128, without the self-tests: swap's would write the whole file)
# runs swaptest over 144 MiB twice: pageout writes pages to swap and the
# reads bring them back, every word as written; (35c) a child forked then
# reads all 144 MiB (its entries name the parent's slots; the pages both
# hold go to swap once), writes its own round over it and reads that back,
# and the parent reads its own again after it; (35c-2) shared memory of
# 144 MiB that a forked child writes three times and the parent reads, every
# word as written, its pages in swap meanwhile; a run killed with pages in swap leaves its slots free, and
# swap off reads the rest back.
swap_shell_test() {
    local image before host key unit size iv blocks t runs
    NAME=${P}swap-xts
    before=$failures
    clang -O2 -Wall -Wextra -Werror -I"$ROOT/kernel" -I"$ROOT/common" -o "$WORK/xtstest" \
          "$ROOT/scripts/xtstest.c" "$ROOT/kernel/xts.c" "$ROOT/common/aes.c"
    check "xtstest built on the Mac" "clang failed" test -x "$WORK/xtstest"
    for t in 1 2 3 4 5 6; do
        key=$(openssl rand -hex 64)
        unit=$(( (RANDOM << 30 | RANDOM << 15 | RANDOM) * t ))
        size=$(( t == 1 ? 16 : t == 2 ? 80 : 4096 ))
        head -c $size /dev/urandom >"$WORK/xts-plain"
        iv=$(python3 -c "import sys; print(int(sys.argv[1]).to_bytes(16, 'little').hex())" $unit)
        openssl enc -aes-256-xts -K "$key" -iv "$iv" -nopad -in "$WORK/xts-plain" \
                -out "$WORK/xts-openssl"
        "$WORK/xtstest" e "$key" $unit <"$WORK/xts-plain" >"$WORK/xts-ours"
        "$WORK/xtstest" d "$key" $unit <"$WORK/xts-ours" >"$WORK/xts-back"
        check "XTS-AES-256, $size bytes of unit $unit: as LibreSSL's, and back" \
              "differs from openssl enc -aes-256-xts, or decrypts wrong" \
              eval 'cmp -s "$WORK/xts-openssl" "$WORK/xts-ours" && cmp -s "$WORK/xts-plain" "$WORK/xts-back"'
    done
    show_log_on_failure $before

    image=$(make_image ${P}swap "")
    before=$failures
    SERIAL_SCRIPT=swap_session_1
    boot ${P}swap-1 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    compare "swap (no file)" "swap: off; no /system/swap (swap make SIZE makes one)" \
            "$(command_output 'swap')"
    expect_line "swap: on: No such file or directory (no /system/swap: swap make SIZE makes one)"
    expect_line "swap: make 1X: not a size in MiB or GiB (512M, 4G)"
    expect_line "swap: /system/swap made: 16 MiB"
    runs=$(sed -n 's/^  swap: *on, \/system\/swap: 16 MiB (4096 pages in \([0-9][0-9]*\) run(s)), XTS-AES-256 with a new key$/\1/p' <<<"$TEXT" | head -1)
    check "swap on: 16 MiB, 4096 pages in ${runs:-?} run(s), XTS-AES-256 with a new key" \
          "no 'swap: on, /system/swap: 16 MiB (4096 pages in N run(s))' line" test -n "$runs"
    t=$(grep -c "^  swap: *self-test: 4096 of 4096 pages read back as written (0 writes failed), 0 readable on the disk$" <<<"$TEXT")
    check "the self-test read every slot back as written, none readable on the disk (twice)" \
          "$t of 2 self-test lines as wanted" test "$t" = 2
    compare "swap (on)" "swap: on, /system/swap: 16 MiB (4096 pages), 0 in use; since the boot 4096 pages written, 4096 read" \
            "$(command_output 'swap' 2)"
    expect_line "swap: 0 of 16 MiB used (0 of 4096 pages), 4096 pages written, 4096 read"
    expect_line "cat: /system/swap: Device or resource busy"
    expect_line "rm: /system/swap: Device or resource busy"
    expect_line "cp: /system/swap -> /tmp/copy: Operation not permitted"
    compare "a copy of /system leaves the swap file out" \
            "$($RFS ls "$image" $RFS_PART /system | grep -v '  swap$')" \
            "$(command_output 'ls /tmp/system')"
    expect_line "cat: /.snapshots/keep/system/swap: Device or resource busy"
    expect_line "  swap:          off"
    expect_line "swap: off; /system/swap: 16 MiB"
    expect_line "on = no"
    expect_line "swap: on, /system/swap: 16 MiB (4096 pages), 0 in use; since the boot 8192 pages written, 8192 read"
    expect_line "on = yes"
    # (37e-1b) the file removed, swap off wrote its default text; swap on
    # changed only the `on` line (the comments stay)
    compare "/system/config/swap after rm, swap off, swap on: the default text with on = yes" \
            "$(python3 "$ROOT/scripts/settingstext.py" SWAP | sed 's/^on = no$/on = yes/' | shasum -a 256)" \
            "$($RFS cat "$image" $RFS_PART /system/config/swap | shasum -a 256)"
    reject "panic"
    blocks=$(python3 "$ROOT/scripts/swapblocks.py" "$image" $RFS_PART /system/swap)
    compare "host: /system/swap fixed, every block written, in the kernel's runs" \
            "fixed: yes, 4096 blocks in ${runs:-?} run(s), 0 all zeros" "$blocks"
    host=$($RFS check "$image" $RFS_PART)
    check "host check: the rest intact, a snapshot holding the swap file" "host says '$host'" \
          eval '[[ "$host" == *"snapshots: 1 ("*"; all checksums ok, bitmap consistent" ]]'
    show_log_on_failure $before

    # A scrub verifies every block but the swap file's data (written in
    # place: no checksums to verify) and never moves the file.
    set_cmdline ${P}swap "scrub"
    before=$failures
    boot ${P}swap-scrub "$image" "RitterOS kernel: boot complete"
    expect "scrub:         verifying every copy of every block"
    expect "copies repaired, 0 not repairable"
    reject "damaged data"
    reject "PROBLEMS FOUND"
    reject "panic"
    show_log_on_failure $before
    set_cmdline ${P}swap ""

    # The second boot: on from /system/config/swap; files that cannot be
    # the swap file.
    before=$failures
    SERIAL_SCRIPT=swap_session_2
    boot ${P}swap-2 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect_line "  swap:          on, /system/swap: 16 MiB (4096 pages in ${runs:-?} run(s)), XTS-AES-256 with a new key"
    expect_line "  swap:          self-test: 4096 of 4096 pages read back as written (0 writes failed), 0 readable on the disk"
    expect "all checksums ok (both copies), bitmap consistent"
    compare "swap (on at the boot)" "swap: on, /system/swap: 16 MiB (4096 pages), 0 in use; since the boot 4096 pages written, 4096 read" \
            "$(command_output 'swap')"
    expect_line "rm: /system/swap: Device or resource busy"
    t=$(grep -c "^swap: on: Invalid argument (/system/swap has holes, a part block or blocks a snapshot shares)$" <<<"$TEXT")
    check "swap on refuses a part block and blocks a snapshot shares" "$t of 2 refusals" test "$t" = 2
    t=$(grep -c "^  swap:          /system/swap cannot be the swap file: holes, a part block, or blocks a snapshot or a copy shares$" <<<"$TEXT")
    check "the kernel says why (twice)" "$t of 2 kernel lines" test "$t" = 2
    t=$(sed -n "s/^snapshot 'keep' deleted, \([0-9][0-9]*\) block(s) free again$/\1/p" <<<"$TEXT")
    check "deleting the snapshot frees the removed swap file's blocks (${t:-?} >= 4096)" \
          "no 'snapshot 'keep' deleted, N block(s) free again' with N >= 4096" \
          eval '[ -n "$t" ] && [ "$t" -ge 4096 ]'
    compare "swap (the file removed)" "swap: off; no /system/swap (swap make SIZE makes one)" \
            "$(command_output 'swap' 2)"
    reject "PROBLEMS FOUND"
    reject "panic"
    host=$($RFS check "$image" $RFS_PART)
    check "host check after the second boot: ok, nothing held back" "host says '$host'" \
          eval '[[ "$host" == *"entries; all checksums ok, bitmap consistent" ]]'
    show_log_on_failure $before

    # (35b) Paging out.
    local saved_selftest=$SELFTEST written read used
    SELFTEST="lockcheck cpus=2"
    image=$(make_image ${P}swapout "memory=128")
    SELFTEST=$saved_selftest
    before=$failures
    SERIAL_SCRIPT=swap_session_3
    boot ${P}swap-3 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "(memory=: the rest unused)"
    expect_line "swap: /system/swap made: 192 MiB"
    t=$(command_output "/system/$ARCH_NAME/test/swaptest 144 2 fork" |
        grep -c "^swaptest: round [12]: 144 MiB written in [0-9.]* s, read back in [0-9.]* s: every word as written$")
    check "swaptest over 144 MiB with 128: both rounds read back every word as written" \
          "$t of 2 rounds as wanted" test "$t" = 2
    read used t <<<"$(sed -n 's/^swaptest: forked with \([0-9][0-9]*\) slots in use; the child read every word as written, wrote its own and read them back (\([0-9][0-9]*\) pages read back), then the parent too$/\1 \2/p' <<<"$TEXT")"
    check "forked over 144 MiB with ${used:-?} slots in use: the child read every word, wrote and read its own (${t:-?} pages read back), then the parent its own" \
          "no 'swaptest: forked with N slots in use; ... then the parent too' line with pages in swap" \
          eval '[ "${used:-0}" -gt 1000 ] && [ "${t:-0}" -gt 1000 ]'

    t=$(grep -c "^swaptest: shared: round [123]: the child wrote 144 MiB, the parent read every word as written$" <<<"$TEXT")
    check "shared memory over 144 MiB: three rounds the child wrote, the parent read every word" \
          "$t of 3 rounds as wanted" test "$t" = 3
    read written read <<<"$(sed -n 's/^swaptest: shared: done; meanwhile \([0-9][0-9]*\) pages written to swap, \([0-9][0-9]*\) read back$/\1 \2/p' <<<"$TEXT")"
    check "shared memory's pages went to swap and came back (${written:-?} written, ${read:-?} read)" \
          "no 'swaptest: shared: done' line with pages written and read" \
          eval '[ "${written:-0}" -gt 1000 ] && [ "${read:-0}" -gt 1000 ]'
    read written read <<<"$(sed -n 's/^swaptest: done; meanwhile \([0-9][0-9]*\) pages written to swap, \([0-9][0-9]*\) read back$/\1 \2/p' <<<"$TEXT")"
    check "pages went to swap and came back (${written:-?} written, ${read:-?} read)" \
          "no 'swaptest: done' line with pages written and read" \
          eval '[ "${written:-0}" -gt 1000 ] && [ "${read:-0}" -gt 1000 ]'
    # The other programs' pages (the shell's, login's...) may stay in swap
    # until they are used: fewer than 1000, where swaptest had tens of
    # thousands.
    used=$(command_output 'swap' 1 | sed -n 's/^swap: on, .*), \([0-9][0-9]*\) in use; .*/\1/p')
    check "swaptest ended: its slots free again (${used:-?} in use)" \
          "swap said '$(command_output 'swap' 1)'" eval '[ -n "$used" ] && [ "$used" -lt 1000 ]'
    used=$(command_output 'swap' 2 | sed -n 's/^swap: on, .*), \([0-9][0-9]*\) in use; .*/\1/p')
    check "a program starts while swaptest runs; it has pages in swap (${used:-?})" \
          "swap said '$(command_output 'swap' 2)'" eval '[ "${used:-0}" -gt 1000 ]'
    used=$(command_output 'swap' 3 | sed -n 's/^swap: on, .*), \([0-9][0-9]*\) in use; .*/\1/p')
    check "killed with pages in swap, it left its slots free (${used:-?} in use)" \
          "swap said '$(command_output 'swap' 3)'" eval '[ -n "$used" ] && [ "$used" -lt 1000 ]'
    t=$(sed -n 's/^  swap: *\([0-9][0-9]*\) pages read back from swap$/\1/p' <<<"$TEXT")
    check "swap off read the rest back (${t:-?} pages, as many as were in use)" \
          "no 'N pages read back from swap' line for the $used in use" test "${t:-x}" = "$used"
    expect_line "swap: off; /system/swap: 192 MiB"
    reject "could not be read back"
    reject "panic"
    reject "RitterOS crash"
    host=$($RFS check "$image" $RFS_PART)
    check "host check after paging out: ok" "host says '$host'" \
          eval '[[ "$host" == *"; all checksums ok, bitmap consistent" ]]'
    show_log_on_failure $before
}

# disk_tests: sections 2-7 for the architecture in QEMU_CMD; test names start
# with $P. Needs seed_normal from that architecture's normal boot.
disk_tests() {
    local image before seed_memtest total passed seed1 seed2 on_disk damaged kernel_crc
    local round log pid i start last commits host gen data_block medium_id repaired others

    # --- 2. memory test: every free page written and verified
    before=$failures
    boot ${P}memtest "$(make_image ${P}memtest "memtest")" "RitterOS kernel: boot complete"
    seed_memtest=$(sed -n 's/.*random seed: .* begins 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
    check "random seed differs from the normal boot ($seed_memtest vs $seed_normal)" \
          "random seeds '${seed_normal:-?}' and '${seed_memtest:-?}' should differ" \
          test -n "$seed_normal" -a -n "$seed_memtest" -a "$seed_normal" != "$seed_memtest"
    expect "memtest:       allocating and writing all"
    expect "memtest:       passed:"
    reject "panic"
    total=$(sed -n 's/.*allocating and writing all \([0-9]*\) free pages.*/\1/p' <<<"$TEXT")
    passed=$(sed -n 's/.*memtest: *passed: \([0-9]*\) pages.*/\1/p' <<<"$TEXT")
    check "all $total free pages written and verified (${BOOT_SECONDS}s)" \
          "${passed:-?} of ${total:-?} pages verified" \
          test -n "$total" -a "$total" = "$passed" -a "${total:-0}" -gt 1000000
    show_log_on_failure $before

    # --- 3. disk writes persist across boots
    # Two boots on one fresh image with "disktest": the second must find the
    # boot record the first one wrote; finally the record is checked in the
    # image file.
    image=$(make_image ${P}persist "disktest")
    before=$failures
    boot ${P}persist-1 "$image" "RitterOS kernel: boot complete"
    expect "disk test:     nvme0n1p2 (958 MiB), using LBA 1961855-1961983"
    expect "previous boot record: none"
    expect "wrote 64 KiB at LBA 1961855, flushed, read back: identical"
    expect "boot record #1 written: seed 0x"
    reject "panic"
    seed1=$(sed -n 's/.*boot record #1 written: seed 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
    show_log_on_failure $before

    before=$failures
    boot ${P}persist-2 "$image" "RitterOS kernel: boot complete"
    expect "previous boot record: boot #1, seed 0x$seed1"
    expect "boot record #2 written: seed 0x"
    reject "panic"
    seed2=$(sed -n 's/.*boot record #2 written: seed 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
    show_log_on_failure $before

    # Read the record straight from the image file: last sector of partition 2.
    on_disk=$(python3 - "$image" <<'PY'
import struct, sys
with open(sys.argv[1], "rb") as f:
    f.seek(2095103 * 512)
    magic, number, seed = struct.unpack("<8sQQ", f.read(24))
print(magic.decode("ascii", "replace"), number, "%016X" % seed)
PY
)
    check "image file holds boot record #2 with seed $seed2 (boot #1: $seed1)" \
          "image file holds '$on_disk', expected 'RTROSREC 2 $seed2'" \
          test -n "$seed1" -a -n "$seed2" -a "$seed1" != "$seed2" -a "$on_disk" = "RTROSREC 2 $seed2"

    # --- 4. damaged file system metadata
    # Corrupt the first copy of the object table: the kernel must still mount
    # (reading the second copy) and its check must name the damaged copy.
    image=$(make_image ${P}fsdamage "")
    damaged=$(python3 - "$image" <<'PY'
import sys
sys.path.insert(0, "scripts")
import ritterfs
with open(sys.argv[1], "r+b") as f:
    part = ritterfs.Partition(f, 133120, 1961984)
    sb, _ = ritterfs.mount(part)
    block = sb.table.root.address
    data = bytearray(part.read(block))
    data[300] ^= 0xFF
    part.write(block, bytes(data))
print(block)
PY
)
    before=$failures
    boot ${P}fsdamage "$image" "RitterOS kernel: boot complete"
    # The bootloader needs the object table too: it reads the second copy.
    kernel_file_checks "$image" " (damaged metadata copy skipped, second copy used)"
    expect "problem: object 1: copy at block $damaged has a bad checksum"
    # The kernel counts what the host's checker counts.
    local counts
    counts=$($RFS check "$image" $RFS_PART |
             sed -n 's/.*, \([0-9]*\) used, \([0-9]*\) objects, root directory: \([0-9]*\) entries.*/\2 objects, \1 blocks in use, root directory \3 entries/p')
    expect "check: ${counts:-?}: PROBLEMS FOUND"
    # Reads fall back to the intact second copy: every file is still correct.
    expect "RitterFS files: 309 verified against /test/manifest.txt (3384 KiB): all match"
    reject "panic"
    show_log_on_failure $before

    # --- 5. RitterFS writing
    image=$(make_image ${P}fswrite "fswrite")
    before=$failures
    boot ${P}fswrite "$image" "RitterOS kernel: boot complete"
    expect "write test:    uncommitted data reads back correctly"
    expect "write test:    commit 1 ok: generation 2"
    expect "write test:    commit 2 ok: generation 3"
    expect "write test:    commit 3 ok: generation 4"
    expect "write test:    commit 4 ok: generation 5"
    expect "write test:    commit 5 ok: generation 6"
    # Reuse: freed object IDs and a freed directory entry are taken again.
    expect_line "  write test:    reuse: 3 of 3 new objects took freed IDs; /work 88 -> 160 bytes, a new entry in a freed place: 160 bytes"
    # TRIM: the blocks freed by the commits are reported to the NVMe disk.
    local trimmed
    trimmed=$(sed -n 's/.*write test: *TRIM: \([0-9][0-9]*\) blocks freed by the commits reported to nvme0n1p2.*/\1/p' <<<"$TEXT")
    check "TRIM: $trimmed freed blocks reported to the disk (NVMe deallocate)" \
          "TRIM: '${trimmed:-?}' blocks reported (expected some)" test "${trimmed:-0}" -gt 0
    expect "/work/big.bin: 614400 bytes, tree height 2"
    expect "content correct"
    expect "write test:    /work/hello.txt correct, /work/many removed"
    expect "write test:    done"
    reject "PROBLEMS FOUND"
    reject "panic"
    kernel_crc=$(sed -n 's/.*big.bin: .*crc32c \([0-9A-F]*\),.*/\1/p' <<<"$TEXT")
    # The host reads what the kernel wrote and checks it independently.
    fswrite_host_check "$image" "$kernel_crc"
    show_log_on_failure $before

    # After a reboot without writing, the committed state is mounted and intact.
    set_cmdline ${P}fswrite ""
    before=$failures
    boot ${P}fswrite-reboot "$image" "RitterOS kernel: boot complete"
    expect "generation 6 (slot A)"
    expect "all checksums ok (both copies), bitmap consistent"
    expect "RitterFS files: 309 verified against /test/manifest.txt (3384 KiB): all match"
    show_log_on_failure $before

    # --- 5b. snapshots
    # The kernel takes 'before', changes files, reads the old state through the
    # snapshot, takes 'after' and deletes 'before'; the sweep must free exactly
    # the blocks the check counted as kept only for 'before'.
    image=$(make_image ${P}fssnap "fssnap")
    before=$failures
    boot ${P}fssnap "$image" "RitterOS kernel: boot complete"
    expect "snapshot test:   'before' taken at generation 2"
    expect "snapshot test:   in 'before' a.txt is version 1 and b.txt absent; live: a.txt version 2, b.txt there"
    expect "snapshot test:   a second 'before': refused (exists)"
    expect "snapshot test:   listed: 'before' at generation 2"
    expect "snapshot test:   listed: 'after' at generation 4"
    expect "snapshot test:   done ('after' stays)"
    reject "PROBLEMS FOUND"
    reject "panic"
    local kept_before swept kept_after host_kept
    kept_before=$(sed -n 's/.*snapshots: 1, their blocks checked; \([0-9][0-9]*\) block(s) kept only for them, 0 awaiting a sweep.*/\1/p' <<<"$TEXT" | head -1)
    kept_after=$(sed -n 's/.*snapshots: 1, their blocks checked; \([0-9][0-9]*\) block(s) kept only for them, 0 awaiting a sweep.*/\1/p' <<<"$TEXT" | tail -1)
    swept=$(sed -n "s/.*'before' deleted, the sweep freed \([0-9][0-9]*\) block(s).*/\1/p" <<<"$TEXT")
    check "the sweep freed the $swept blocks kept only for 'before'" \
          "kept for 'before': '${kept_before:-?}', swept: '${swept:-?}'" \
          eval '[ -n "$swept" ] && [ "$swept" -gt 0 ] && [ "$swept" = "$kept_before" ]'
    # The host walks the snapshot too and counts what the kernel counts.
    host=$($RFS check "$image" $RFS_PART)
    host_kept=$(sed -n 's/.*snapshots: 1 (\([0-9][0-9]*\) blocks kept only for them, 0 awaiting a sweep); all checksums ok, bitmap consistent$/\1/p' <<<"$host")
    check "host check ok, 1 snapshot with $host_kept blocks of its own, as the kernel says" \
          "host: '$host', kernel: '${kept_after:-?}' blocks kept" \
          eval '[ -n "$host_kept" ] && [ "$host_kept" = "$kept_after" ]'
    show_log_on_failure $before

    # The host changes a file the snapshot shares: its old blocks are held
    # back (deferred), the snapshot still shows the old content.
    printf 'version 3, from the host\n' >"$WORK/${P}snap-a.txt"
    $RFS put "$image" $RFS_PART /snap/a.txt "$WORK/${P}snap-a.txt" >/dev/null
    host=$(python3 - "$image" <<'PY'
import sys
sys.path.insert(0, "scripts")
import ritterfs as r
with open(sys.argv[1], "rb") as f:
    part = r.Partition(f, 133120, 1961984)
    ok, summary = r.check(part)
    sb, _ = r.mount(part)
    a = r.Reader(part)
    live = a.content(a.lookup("/snap/a.txt")[1])
    checker = r.Checker(part, sb)
    checker.run()
    kept = checker.kept
print("ok" if ok else "BAD", sb.deferred_blocks > 0, live == b"version 3, from the host\n", kept)
PY
)
    host_kept=${host##* }
    check "host put after the snapshot: check ok, frees held back, $host_kept blocks kept" \
          "host says '$host'" eval '[[ "$host" == "ok True True "* ]] && [ "$host_kept" -gt "${kept_after:-0}" ]'

    # A damaged block that only the snapshot uses: the host must notice (its
    # walk of the snapshot is real). On a copy; the image itself stays intact.
    cp "$image" "$WORK/${P}snap-damaged.img"
    host=$(python3 - "$WORK/${P}snap-damaged.img" <<'PY'
import sys
sys.path.insert(0, "scripts")
import ritterfs as r
with open(sys.argv[1], "r+b") as f:
    part = r.Partition(f, 133120, 1961984)
    sb, _ = r.mount(part)
    checker = r.Checker(part, sb)
    checker.run()
    block = min(set(checker.owner) - checker.live)
    data = bytearray(part.read(block))
    data[200] ^= 0xFF
    part.write(block, bytes(data))
    checker = r.Checker(part, sb)
    checker.run()
print(block, "|".join(checker.errors))
PY
)
    check "a damaged block only the snapshot uses is found by the host check" \
          "host says '$host'" eval '[[ "$host" == *"snapshot '"'"'after'"'"'"*"bad checksum"* ]]'

    # After a reboot the kernel checks the host's commit and agrees on it.
    set_cmdline ${P}fssnap ""
    before=$failures
    boot ${P}fssnap-reboot "$image" "RitterOS kernel: boot complete"
    expect "all checksums ok (both copies), bitmap consistent"
    expect_line "                 snapshots: 1, their blocks checked; $host_kept block(s) kept only for them, 0 awaiting a sweep"
    reject "PROBLEMS FOUND"
    show_log_on_failure $before

    # Snapshots from the shell.
    snapshot_shell_test
    # Swap: the swap file (35a).
    swap_shell_test
    # Attributes and search from the shell.
    attr_shell_test
    # File system management from the shell.
    fs_shell_test
    # Writing files from the shell.
    write_shell_test
    # Users and passwords.
    users_shell_test
    # The system's settings: /system/config.
    config_shell_test
    settings_test                       # (37e-1b)
    # The shell's ';' and '*'.
    syntax_shell_test
    # Local (Unix-domain) stream sockets.
    local_shell_test
