    exfat_format_test
    # Installing on another disk.
    osinstall_test

    # --- 5c. instant copies
    # The kernel copies a directory without its data, changes the copy apart
    # from the original, removes the original (a sweep frees what only it
    # used, the pin drops to 0) and copies once more; that copy stays.
    local shared pinned awaiting kernel_copies host_copies host_shared
    image=$(make_image ${P}fscopy "fscopy")
    before=$failures
    boot ${P}fscopy "$image" "RitterOS kernel: boot complete"
    expect "copy test:      /copy/src copied to /copy/dst: 300 KiB shared,"
    expect "(metadata), content identical"
    expect "copy test:      into itself, onto an existing name, from nothing: refused, nothing changed"
    expect "copy test:      the copy changed: the original is unchanged"
    expect "the sweep freed"
    expect "block(s); pinned generation now 0"
    expect "copy test:      done (/copy/dst and its copy /copy/again stay)"
    reject "PROBLEMS FOUND"
    reject "panic"
    # 300 KiB = 75 data blocks plus the index block's two copies.
    shared=$(sed -n 's/.*copies: \([0-9][0-9]*\) block(s) shared.*/\1/p' <<<"$TEXT" | head -1)
    check "the copy shares 77 blocks (75 data blocks, the index block twice)" \
          "the check says '${shared:-?}' blocks shared" test "${shared:-0}" = 77
    kernel_copies=$(sed -n 's/.*copies: \([0-9][0-9]*\) block(s) shared, generations up to \([0-9][0-9]*\) pinned, \([0-9][0-9]*\) awaiting a sweep.*/\1 \2 \3/p' <<<"$TEXT" | tail -1)
    host=$($RFS check "$image" $RFS_PART)
    host_copies=$(sed -n 's/.*copies: \([0-9][0-9]*\) blocks shared (generations up to \([0-9][0-9]*\) pinned, \([0-9][0-9]*\) awaiting a sweep); all checksums ok, bitmap consistent$/\1 \2 \3/p' <<<"$host")
    check "host check ok and agrees on the sharing (shared, pinned, awaiting: $host_copies)" \
          "host: '$host', kernel: '${kernel_copies:-?}'" \
          eval '[ -n "$host_copies" ] && [ "$host_copies" = "$kernel_copies" ]'
    show_log_on_failure $before

    # Without the pin the sharing is an error: both checks must say so (on a
    # copy of the image, from here on booted without "fscopy").
    set_cmdline ${P}fscopy ""
    cp "$image" "$WORK/${P}fscopy-nopin.img"
    python3 - "$WORK/${P}fscopy-nopin.img" <<'PY'
import sys
sys.path.insert(0, "scripts")
import ritterfs as r
with open(sys.argv[1], "r+b") as f:
    part = r.Partition(f, 133120, 1961984)
    sb, slot = r.mount(part)
    sb.pinned_generation = 0
    part.write_super(slot, sb.pack())
PY
    host=$(host_errors "$WORK/${P}fscopy-nopin.img")
    check "without the pin the host check finds the shared blocks" "host says '$(tr '\n' '|' <<<"$host")'" \
          eval '[[ "$host" == *"also used by"* ]]'
    before=$failures
    boot ${P}fscopy-nopin "$WORK/${P}fscopy-nopin.img" "RitterOS kernel: boot complete"
    expect "problem: block"
    expect "is used twice (again by object"
    expect "PROBLEMS FOUND"
    show_log_on_failure $before

    # The host replaces the copied file: the shared blocks stay (held back),
    # the original copy is intact; after a reboot the kernel agrees.
    python3 -c 'import sys; sys.stdout.write("replaced by the host\n")' >"$WORK/${P}copy-big.txt"
    $RFS put "$image" $RFS_PART /copy/again/big.bin "$WORK/${P}copy-big.txt" >/dev/null
    host=$($RFS check "$image" $RFS_PART)
    host_copies=$(sed -n 's/.*copies: \([0-9][0-9]*\) blocks shared (generations up to \([0-9][0-9]*\) pinned, \([0-9][0-9]*\) awaiting a sweep); all checksums ok, bitmap consistent$/\1 \2 \3/p' <<<"$host")
    host_shared=${host_copies%% *}
    NAME=${P}fscopy
    check "host put over the copy: check ok, nothing shared any more ($host_copies)" \
          "host: '$host'" eval '[ -n "$host_copies" ] && [ "$host_shared" = 0 ]'
    before=$failures
    boot ${P}fscopy-reboot "$image" "RitterOS kernel: boot complete"
    expect "all checksums ok (both copies), bitmap consistent"
    read shared pinned awaiting <<<"$host_copies"
    expect_line "                 copies: $shared block(s) shared, generations up to $pinned pinned, $awaiting awaiting a sweep"
    reject "PROBLEMS FOUND"
    show_log_on_failure $before

    # --- 5d. attributes
    # The kernel sets, replaces and removes attributes, refuses bad ones,
    # grows the table past a block, drops a removed file's attributes and
    # copies them with instant copies; /attr stays.
    local kernel_attrs host_attrs attr_image
    image=$(make_image ${P}fsattr "fsattr")
    before=$failures
    boot ${P}fsattr "$image" "RitterOS kernel: boot complete"
    expect "attribute test: a.txt color=blue, a 1000-byte note, b.txt color=red, d kind=folder: read back"
    expect "attribute test: replaced and removed: ok; bad keys, a too long value, no such object or key: refused"
    expect "more on b.txt, table"
    expect "bytes: all read back"
    expect "attribute test: b.txt removed, its attributes with it; c.txt took its object ID and has none"
    expect "attribute test: copies keep them: yes"
    expect "attribute test: done (/attr stays)"
    reject "PROBLEMS FOUND"
    reject "panic"
    kernel_attrs=$(sed -n 's/.*attributes: \([0-9][0-9]*\) on \([0-9][0-9]*\) object(s)$/\1 \2/p' <<<"$TEXT" | tail -1)
    host=$($RFS check "$image" $RFS_PART)
    host_attrs=$(sed -n 's/.*, attributes: \([0-9][0-9]*\) on \([0-9][0-9]*\) objects.*all checksums ok, bitmap consistent$/\1 \2/p' <<<"$host")
    check "host check ok, attributes as the kernel counts them ($host_attrs)" \
          "host: '$host', kernel: '${kernel_attrs:-?}'" \
          eval '[ -n "$host_attrs" ] && [ "$host_attrs" = "$kernel_attrs" ] && [ "$host_attrs" = "4 4" ]'
    show_log_on_failure $before

    # A host commit over a file with attributes keeps them.
    set_cmdline ${P}fsattr ""
    printf 'new content of a.txt\n' >"$WORK/${P}attr-a.txt"
    $RFS put "$image" $RFS_PART /attr/a.txt "$WORK/${P}attr-a.txt" >/dev/null
    host=$($RFS check "$image" $RFS_PART)
    NAME=${P}fsattr
    check "host put over /attr/a.txt: check ok, its attribute kept" "host: '$host'" \
          eval '[[ "$host" == *", attributes: 4 on 4 objects"*"all checksums ok, bitmap consistent" ]]'

    # An attribute of an object that does not exist (a valid commit, wrong
    # content): both checks must find it.
    attr_image="$WORK/${P}fsattr-bad.img"
    cp "$image" "$attr_image"
    python3 - "$attr_image" <<'PY'
import struct, sys
sys.path.insert(0, "scripts")
import ritterfs as r
with open(sys.argv[1], "r+b") as f:
    part = r.Partition(f, 133120, 1961984)
    reader = r.Reader(part)
    oid = reader.sb.attribute_object
    data = bytearray(reader.content(reader.inodes[oid]))
    pos = 0
    while struct.unpack_from("<Q", data, pos)[0] == 0:      # the first record in use
        pos += struct.unpack_from("<H", data, pos + 8)[0]
    struct.pack_into("<Q", data, pos, 999999)
    r.install(part, {}, objects={oid: bytes(data)})
PY
    host=$(host_errors "$attr_image")
    check "an attribute of a missing object: the host check finds it" \
          "host says '$(tr '\n' '|' <<<"$host")'" eval '[[ "$host" == *"of object 999999, which does not exist"* ]]'
    before=$failures
    boot ${P}fsattr-bad "$attr_image" "RitterOS kernel: boot complete"
    expect "of object 999999, which does not exist"
    expect "PROBLEMS FOUND"
    show_log_on_failure $before

    # After a reboot the kernel agrees with the host.
    before=$failures
    boot ${P}fsattr-reboot "$image" "RitterOS kernel: boot complete"
    expect "all checksums ok (both copies), bitmap consistent"
    expect_line "                 attributes: 4 on 4 object(s)"
    reject "PROBLEMS FOUND"
    show_log_on_failure $before

    # --- 5e. transactions: uncommitted changes thrown away
    image=$(make_image ${P}fstxn "fstxn")
    before=$failures
    boot ${P}fstxn "$image" "RitterOS kernel: boot complete"
    expect "transaction:    uncommitted: /txn/big.bin (100 KiB) there, an attribute set, /readme.txt gone: yes"
    expect "transaction:    aborted: all of it undone (generation 1,"
    expect "blocks used): yes"
    expect "transaction:    done (a commit after the abort: /txn/after.txt)"
    reject "PROBLEMS FOUND"
    reject "panic"
    host=$($RFS check "$image" $RFS_PART)
    check "host check after the abort and one commit: generation 2, ok, /readme.txt intact" \
          "host: '$host'" eval '[[ "$host" == "RitterFS check: generation 2 "*"all checksums ok, bitmap consistent" ]] &&
                              [ "$($RFS cat "$image" $RFS_PART /readme.txt)" = "$($RFS cat "$DISK" $RFS_PART /readme.txt)" ] &&
                              [ -n "$($RFS cat "$image" $RFS_PART /readme.txt)" ]'
    show_log_on_failure $before

    # --- 6. crash torture
    # Kill the VM (SIGKILL, like pulling the plug) at a random moment while it
    # is committing; the image must always hold a consistent file system: the
    # last reported generation, or one newer if the kill hit between the
    # superblock write and the log line.
    image=$(make_image ${P}torture "fstorture")
    for round in 1 2 3 4 5 6 7 8; do
        NAME="${P}torture round $round"
        log="$WORK/${P}torture-$round.log"
        rm -f "$log"
        ${QEMU_CMD//$DISK/$image} -display none -serial "file:$log" 2>/dev/null &
        pid=$!
        for ((i = 0; i < TIMEOUT * 4; i++)); do
            grep -qF "torture: started" "$log" 2>/dev/null && break
            sleep 0.25
        done
        sleep "$(python3 -c 'import random; print(round(random.uniform(0.3, 3.0), 2))')"
        kill -9 $pid 2>/dev/null
        wait $pid 2>/dev/null
        TEXT="$(perl -pe 's/[^\n]*\r(?=\e\[0K)//g; s/\e\[[0-9;]*[Hf]/\n/g; s/\e\[[0-9;?]*[A-Za-z]//g; s/\r//g' "$log")"
        start=$(sed -n 's/.*torture: started at generation \([0-9]*\).*/\1/p' <<<"$TEXT")
        # A kill can cut the last line short, even inside a number ("3275"
        # became "327"): only complete lines, ending in a line break, count.
        complete="$TEXT"
        [ -n "$(tail -c 1 "$log")" ] && complete=$(sed '$d' <<<"$TEXT")
        last=$(sed -n 's/.*torture: commit [0-9]* ok, generation \([0-9][0-9]*\).*/\1/p' <<<"$complete" | tail -1)
        last=${last:-$start}
        commits=$(grep -c "torture: commit .* ok" <<<"$TEXT")
        host=$(python3 "$ROOT/scripts/ritterfs.py" check "$image" 133120 1961984)
        gen=$(sed -n 's/^RitterFS check: generation \([0-9]*\).*/\1/p' <<<"$host")
        # The kernel's own check at mount verified the previous round's state.
        if [ -n "$last" ] && [[ "$host" == *"all checksums ok, bitmap consistent" ]] &&
           grep -qF "all checksums ok (both copies), bitmap consistent" <<<"$TEXT" &&
           ! grep -qF "torture: done" <<<"$TEXT" &&
           [ -n "$gen" ] && { [ "$gen" -eq "$last" ] || [ "$gen" -eq $((last + 1)) ]; }; then
            echo "PASS  $NAME: killed after $commits commits; disk consistent at generation $gen (last reported $last)"
        else
            echo "FAIL  $NAME: last reported generation '${last:-?}', host: $host," \
                 "kernel check: $(grep -c "all checksums ok" <<<"$TEXT"), finished: $(grep -c "torture: done" <<<"$TEXT")"
            failures=$((failures + 1))
        fi
    done

    # Finally a normal boot on the tortured image.
    set_cmdline ${P}torture ""
    before=$failures
    boot ${P}torture-final "$image" "RitterOS kernel: boot complete"
    expect "all checksums ok (both copies), bitmap consistent"
    expect "RitterFS files: 309 verified against /test/manifest.txt (3384 KiB): all match"
    show_log_on_failure $before

    # --- 7. scrub and repair
    # Repair in place: six metadata copies are fixed; the damaged file data is
    # reported with its path and stays the only problem left.
    image=$(make_image ${P}scrub "scrub")
    read data_block medium_id <<<"$(damage "$image" data)"
    before=$failures
    boot ${P}scrub "$image" "RitterOS kernel: boot complete"
    expect "PROBLEMS FOUND"
    expect "scrub:         verifying every copy of every block"
    expect "rewritten in place"
    expect "damaged data: /test/data/medium.bin block 5 (disk block $data_block): stored once, not repairable"
    expect "copies repaired, 1 not repairable"
    reject "LOST:"
    reject "panic"
    repaired=$(grep -c "repaired: .* rewritten in place" <<<"$TEXT")
    host=$(host_errors "$image")
    others=$(tail -n +2 <<<"$host" | grep -v "^object $medium_id block 5: " | grep -c .)
    check "6 metadata copies repaired in place; host finds only the lost data block" \
          "$repaired copies repaired; host errors: $(tail -n +2 <<<"$host" | tr '\n' '|')" \
          eval '[ "$repaired" -eq 6 ] && [ "$others" -eq 0 ] &&
                grep -q "^object $medium_id block 5: copy at block $data_block has a bad checksum" <<<"$host"'
    show_log_on_failure $before

    # Relocation: the same metadata damage, but blocks move through a commit.
    image=$(make_image ${P}relocate "scrub=relocate")
    damage "$image" >/dev/null
    before=$failures
    boot ${P}relocate "$image" "RitterOS kernel: boot complete"
    expect "will move to new places"
    expect "relocation of 6 block(s): ok, generation 2"
    expect "6 copies repaired, 0 not repairable"
    expect "all checksums ok (both copies), bitmap consistent"
    reject "panic"
    host=$(host_errors "$image")
    check "host checker finds no errors at generation 2" \
          "host says: $(tr '\n' '|' <<<"$host")" \
          test "$host" = "generation 2"
    show_log_on_failure $before

    kernel_tests
    usb_storage_test
    usb_boot_test
    usb_late_test
    usb_hotplug_test
    usb_hubplug_test
    sata_disk_test
    noruntime_test
}

# noruntime_test: "noruntime" on the command line, for firmware that fails
# at SetVirtualAddressMap (a real PC's AMI firmware hung there): the
# bootloader skips it and the kernel boots without UEFI runtime services.
# On x86 also at 1600x1200, as on the J1900: the console uses the whole
# width (175 columns; it once stopped at 160), checked pixel by pixel.
noruntime_test() {
    local image before=$failures
    image=$(make_image ${P}noruntime "noruntime video=1600x1200")
    boot ${P}noruntime "$image" "RitterOS kernel: boot complete"
    expect_line "RitterOS boot: runtime services not used (noruntime)"
    expect_line "  UEFI time:     unavailable"
    if [ "$ARCH_NAME" = x86_64 ]; then
        expect "  console:       175x75 characters, "
        check_screen ok 1600 1200
    fi
    expect "RitterOS kernel: boot complete"
    reject "runtime services moved"
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# usb_boot_session: commands typed on the serial port and on the USB
# keyboard (SERIAL_SCRIPT of the USB boot).
usb_boot_session() {
    local key
    prompt_wait 1 30
    serial_type 'cat /test/hello.txt\r'
    prompt_wait 2
    for key in e c h o spc u s b spc b o o t ret; do
        echo "sendkey $key" | nc -w 3 -U "$WORK/monitor.sock" >/dev/null 2>&1
    done
    prompt_wait 3
    serial_type "ls /system/$ARCH_NAME/bin\r"
    prompt_wait 4
    serial_type 'hello\r'
    prompt_wait 5
    # Unplug the stick the system runs from.
    echo "device_del stick" | nc -w 3 -U "$WORK/monitor.sock" >/dev/null 2>&1
    serial_wait "removed (its name stays reserved)" 1 10
}

# usb_boot_test: a machine without NVMe, only the RitterOS image as a USB
# stick (SuperSpeed port, boot index 0): the firmware boots from it, the
# bootloader loads the kernel from its RitterFS, and the kernel takes the
# stick's partition as its system partition (by the GPT GUID the bootloader
# passed on); the shell runs from it.
usb_boot_test() {
    local image before saved="$QEMU_CMD"
    image=$(make_image ${P}usbboot "")
    QEMU_CMD="${QEMU_CMD/-drive if=none,id=disk0,format=raw,file=$DISK -device nvme,drive=disk0,serial=RITTEROS0001,bootindex=0/}"
    # Like the Intel J1900 PC: an xHCI controller with MSI but no MSI-X.
    QEMU_CMD="${QEMU_CMD/-device qemu-xhci,id=xhci/-device qemu-xhci,id=xhci,msi=on,msix=off}"
    QEMU_EXTRA="-drive if=none,id=stick,format=raw,file=$image
                -device usb-storage,bus=xhci.0,port=3,drive=stick,bootindex=0,id=stick"
    before=$failures
    SERIAL_SCRIPT=usb_boot_session
    boot ${P}usbboot "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    QEMU_CMD="$saved"
    reject "NVMe controller"                # the machine has none
    expect "interrupts: MSI (no MSI-X), message 0x"
    expect_line "                 No-Op command: completed, 1 interrupt(s)"
    expect_line "RitterFS:  partition #2 of the boot disk, 'RitterOS', generation 1 (slot B)"
    expect "boot device:   PciRoot(0x0)/Pci("
    expect ")/USB(0x2,0x0)/HD(1,GPT,$(guid ESP_GUID),0x800,0x20000)"
    expect "class 0c.03.30)"                # the boot disk's controller: USB
    expect_line "  usb0 port 3:   USB 3 device connected, SuperSpeed (5 Gbit/s)"
    expect_line "  usbdisk0:      'QEMU' 'QEMU HARDDISK' rev 2.5+ on usb0 port 3, 2097152 blocks of 512 bytes (1024 MiB), bulk-only, LUN 0 of 1"
    expect_line "  system partition: usbdisk0p2, where the bootloader found the kernel"
    expect "all checksums ok (both copies), bitmap consistent"
    expect "RitterFS files: 309 verified against /test/manifest.txt (3384 KiB): all match"
    expect_line "  login:         /system/$ARCH_NAME/bin/login, process 1"
    expect_line "Hello from RitterFS!"
    expect_line "usb boot"                         # typed on the USB keyboard
    expect_line "Hello from user mode!"
    expect_line "  usbdisk0:      removed (its name stays reserved); it held the system partition: files cannot be read any more"
    compare "ls /system/$ARCH_NAME/bin vs host" \
            "$($RFS ls "$image" $RFS_PART /system/$ARCH_NAME/bin)" \
            "$(command_output "ls /system/$ARCH_NAME/bin")"
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# usb_sleep_session: (37g-6) the machine runs from a USB stick and sleeps
# at the end of its boot (sleeptest) and once more from the shell; files
# are read from the stick after each.
usb_sleep_session() {
    local n=1 asked=0
    prompt_wait $n 60
    answer_lines 'cat /test/hello.txt' "ls /system/$ARCH_NAME/apps" 'power sleep 3'
    # (37g-7) the hub's keyboard found again after the second sleep (its
    # third attach: the boot, each sleep) before output that is compared:
    # its lines came out in the middle of the listing
    serial_wait "kbd0:          USB keyboard on usb0 port 5.1.1" 3 30
    answer_lines 'cat /test/manifest.txt | wc -l' "ls /system/$ARCH_NAME/test" 'disks' 'usb'
}

# usb_sleep_test: (37g-6) S3 with the system on a USB stick, as the
# VivoBook runs: the controller loses every device in S3, and the stick
# must come back as the same disk (Linux's USB persist: the device reset,
# addressed again and compared with what it was), or the mounted system
# is gone and nothing can be read or started. x86 only (S3).
usb_sleep_test() {
    [ "$ARCH_NAME" = x86_64 ] || return 0
    local image before saved="$QEMU_CMD" lines
    image=$(make_image ${P}usbsleep "sleeptest")
    QEMU_CMD="${QEMU_CMD/-drive if=none,id=disk0,format=raw,file=$DISK -device nvme,drive=disk0,serial=RITTEROS0001,bootindex=0/}"
    QEMU_EXTRA="-drive if=none,id=stick,format=raw,file=$image
                -device usb-storage,bus=xhci.0,port=3,drive=stick,bootindex=0,id=stick,serial=SLEEPSTICK1"
    before=$failures
    SERIAL_SCRIPT=usb_sleep_session
    boot ${P}usbsleep "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    QEMU_CMD="$saved"
    lines=$($RFS cat "$image" $RFS_PART /test/manifest.txt | wc -l | tr -d ' ')
    compare "two sleeps, each woken by the RTC's alarm" 2 \
            "$(grep -cE "^sleep: awake after [34] s \(the RTC.s alarm\)" <<<"$TEXT")"
    compare "the stick kept as the same device over both sleeps" 2 \
            "$(grep -cF "usb0 port 3:   the same device after the sleep: kept (QEMU USB HARDDRIVE)" <<<"$TEXT")"
    # (37g-8) usb counts what was kept: the stick, at each sleep (the hubs
    # and what hangs behind them are always set up again, not counted)
    expect_line "  usb0:          over 2 sleep(s): 2 device(s) kept, 0 let go of"
    expect_line "Hello from RitterFS!"
    compare "after the sleeps the stick's files read: /test/manifest.txt's lines" "$lines" \
            "$(command_output 'cat /test/manifest.txt | wc -l' | tr -d ' ')"
    compare "after the sleeps ls /system/$ARCH_NAME/test vs host" \
            "$($RFS ls "$image" $RFS_PART /system/$ARCH_NAME/test)" \
            "$(command_output "ls /system/$ARCH_NAME/test")"
    reject "it held the system partition"
    reject "Input/output error"
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# sleep_wake_session: (37g-7) three sleeps without an alarm, each woken by
# QEMU's system_wakeup (its ACPI sets the power button's status then, as a
# laptop woken by its button): the power button (power_button = sleep),
# the lid closed through the EC model (lid = sleep), a minute without
# input (sleep_after = 1). Each wake waits for QEMU to say the machine is
# suspended first.
sleep_wake_session() {
    local n=1 k mon="$WORK/monitor.sock"
    prompt_wait $n 60
    for k in 1 2 3; do
        if [ $k = 1 ]; then
            echo system_powerdown | nc -w 3 -U "$mon" >/dev/null 2>&1
        elif [ $k = 2 ]; then
            echo "qom-set /machine/peripheral/ec0 query 16" | nc -w 3 -U "$mon" >/dev/null 2>&1
        fi
        serial_wait "until woken (the power button); _PTS" $k 90
        sleep_wake_up
        serial_wait "acpi: power sleep ended" $k 30
        sleep 3                             # (a press the wake left would sleep again here)
        if [ $k = 2 ]; then
            serial_type '\r'
            n=$((n + 1))
            prompt_wait $n
            answer_lines "/system/$ARCH_NAME/bin/power"
        fi
    done
    serial_type '\r'
    n=$((n + 1))
    prompt_wait $n
    answer_lines "/system/$ARCH_NAME/bin/power"
}

# QEMU's system_wakeup once the machine is suspended (at most 20 s).
sleep_wake_up() {
    local i
    for ((i = 0; i < 80; i++)); do
        echo "info status" | nc -w 3 -U "$WORK/monitor.sock" 2>/dev/null | grep -q suspended && break
        sleep 0.25
    done
    echo system_wakeup | nc -w 3 -U "$WORK/monitor.sock" >/dev/null 2>&1
}

# sleep_wake_test: (37g-7) sleeping without an alarm, as a laptop does:
# /system/config/power's power_button = sleep, lid = sleep and
# sleep_after = 1 each start `power sleep`; the wake (system_wakeup: the
# power button's status set, as the laptops' button sets it) neither
# sleeps the machine again nor counts as a press. Proven by a kernel
# whose SCI counted the waking press and whose wake kept it: a fourth
# sleep at once after the first. x86 only (S3).
sleep_wake_test() {
    [ "$ARCH_NAME" = x86_64 ] || return 0
    local image before aml="$WORK/${P}sleepwake"
    rm -rf "$aml" && mkdir -p "$aml"
    if ! ( cd "$aml" && "$ROOT/tools/local/bin/iasl" -p ec "$ROOT/scripts/aml/ec.asl" >iasl.txt 2>&1 ); then
        check "iasl compiles scripts/aml/ec.asl" "$(tail -3 "$aml/iasl.txt")" false
        return
    fi
    image=$(make_image ${P}sleepwake "")
    printf 'power_button = sleep\nlid = sleep\nsleep_after = 1   # (the test)\n' >"$WORK/${P}sleepwake-power"
    $RFS put "$image" $RFS_PART /system/config/power "$WORK/${P}sleepwake-power" >/dev/null || exit 1
    before=$failures
    SERIAL_SCRIPT=sleep_wake_session
    QEMU_EXTRA="-device ritterec,id=ec0 -acpitable file=$aml/ec.aml"
    boot ${P}sleepwake "$image" "RitterOS kernel: boot complete"
    QEMU_EXTRA=
    SERIAL_SCRIPT=
    expect_line "  power:         power_button = sleep (/system/config/power)"
    expect_line "  power:         lid = sleep (/system/config/power)"
    expect_line "  power:         sleep_after = 1 (minutes; /system/config/power): the machine sleeps without input"
    check "the press started power sleep" "$(grep -a '^acpi: the power button' <<<"$TEXT")" \
          eval 'grep -aqE "^acpi: the power button: power_button = sleep: /system/$ARCH_NAME/bin/power sleep, process [0-9]+$" <<<"$TEXT"'
    check "the lid closed started power sleep" "$(grep -a '^acpi: the lid' <<<"$TEXT")" \
          eval 'grep -aqE "^acpi: the lid: closed \(lid = sleep\): /system/$ARCH_NAME/bin/power sleep, process [0-9]+$" <<<"$TEXT"'
    check "a minute without input started power sleep" "$(grep -a '^acpi: 1 minute' <<<"$TEXT")" \
          eval 'grep -aqE "^acpi: 1 minute without input \(sleep_after\): /system/$ARCH_NAME/bin/power sleep, process [0-9]+$" <<<"$TEXT"'
    compare "three sleeps until woken, no more (the waking press did nothing)" 3 \
            "$(grep -cF "sleep: S3 (sleep types 1, 1) until woken (the power button); _PTS none" <<<"$TEXT")"
    compare "power sleep said so each time" 3 \
            "$(grep -cxF "power: sleeping until woken (the power button)" <<<"$TEXT")"
    compare "three wakes by the power button's status, every driver back" 3 \
            "$(grep -cE "^sleep: awake after [0-9]+ s \(the power button\); 2 of 2 cores back, .*, 0 failed$" <<<"$TEXT")"
    compare "power sleep ended three times" 3 "$(grep -cxF "acpi: power sleep ended (exit code 0)" <<<"$TEXT")"
    check "power: one press, none left over from the wakes" "$(grep -a '^events: ' <<<"$TEXT" | tail -1)" \
          eval 'grep -aqE "^events: .*; the power button \(fixed; keyboards. Power key\): 1 presses, power_button = sleep \(/system/config/power\); the lid: 1 changes, lid = sleep \(/system/config/power\);" <<<"$(grep -a "^events: " <<<"$TEXT" | tail -1)"'
    reject "powering off"
    reject "sleep: not asleep"
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# usb_late_session: the shell runs from the stick on the second controller;
# the USB keyboard (skipped by the first look too) types.
usb_late_session() {
    local key
    prompt_wait 1 30
    serial_type 'cat /test/hello.txt\r'
    prompt_wait 2
    for key in e c h o spc l a t e spc k e y s ret; do
        echo "sendkey $key" | nc -w 3 -U "$WORK/monitor.sock" >/dev/null 2>&1
    done
    prompt_wait 3
}

# usb_late_test: like the AMD laptop: its RitterOS stick is on a second
# xHCI controller (usb1), and "usblate": the controllers' first look at
# their ports finds nothing, as when a USB 3 link comes up late after the
# controller's reset. Its NVMe drive holds a copy of a stick image, with
# the same GPT GUIDs (48b: the laptop took it as the system while its
# stick was still coming up). The kernel must set up both controllers,
# wait for the stick and take it, not the copy (reported as one); the USB
# keyboard on usb0 is set up afterwards by its hot plug thread and types.
usb_late_test() {
    local image before saved="$QEMU_CMD" copy copied
    image=$(make_image ${P}usblate "usblate")
    copy="$WORK/${P}usblate-copy.img"
    rm -f "$copy"
    cp -c "$image" "$copy" || exit 1
    QEMU_CMD="${QEMU_CMD/-drive if=none,id=disk0,format=raw,file=$DISK -device nvme,drive=disk0,serial=RITTEROS0001,bootindex=0/}"
    QEMU_EXTRA="-drive if=none,id=copy,format=raw,file=$copy -device nvme,drive=copy,serial=COPY0001
                -device qemu-xhci,id=xhci2
                -drive if=none,id=stick,format=raw,file=$image
                -device usb-storage,bus=xhci2.0,port=2,drive=stick,bootindex=0,id=stick"
    before=$failures
    SERIAL_SCRIPT=usb_late_session
    boot ${P}usblate "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    QEMU_CMD="$saved"
    expect "class 0c.03.30)"                # the boot disk's controller: USB
    check "two xHCI controllers set up (usb0, usb1)" \
          "$(grep -c '^  xHCI: .*, usb[01]$' <<<"$TEXT") controller line(s)" \
          test "$(grep -c '^  xHCI: .*, usb[01]$' <<<"$TEXT")" = 2
    expect_line "  system partition: not found yet; waiting for USB disks (at most 10 s)"
    expect_line "  usb1 port 2:   USB 3 device connected, SuperSpeed (5 Gbit/s)"
    expect "  usbdisk0:      'QEMU' 'QEMU HARDDISK' rev 2.5+ on usb1 port 2, "
    expect "  system partition: found after "
    expect_line "  system partition: usbdisk0p2, where the bootloader found the kernel"
    expect_line "  system partition: nvme0n1p2 has the same GPT GUID as usbdisk0p2 (a copied disk?); using usbdisk0p2"
    expect "all checksums ok (both copies), bitmap consistent"
    expect_line "  login:         /system/$ARCH_NAME/bin/login, process 1"
    # The first start wrote root's password to the stick, not to the copy.
    copied=$($RFS ls "$copy" $RFS_PART /system/config | awk '{print $2}' | tr '\n' ' ')
    check "the stick took root's password, the copy did not" \
          "the copy's /system/config: $copied" \
          eval '$RFS cat "$image" $RFS_PART /system/config/passwords >/dev/null 2>&1 &&
                ! $RFS cat "$copy" $RFS_PART /system/config/passwords >/dev/null 2>&1' 
    expect_line "Hello from RitterFS!"
    expect_line "late keys"                         # typed on the USB keyboard
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# no_serial_test: a PC without a serial port (QEMU -serial none: COM1's
# ports read 0xFF, which looks like "ready to send" and "data received"
# forever). The bootloader and the kernel must notice that there is no UART
# and boot to the shell anyway; with no log, the screen is the only witness:
# screenshots until the console shows the finished boot. x86 only: ARM's
# virt machine always has its PL011.
no_serial_test() {
    local image mon="$WORK/monitor.sock" i ok=0
    NAME=noserial
    image=$(make_image noserial "")
    rm -f "$mon" "$WORK/$NAME.ppm"
    ${QEMU_CMD//$DISK/$image} -display none -serial none \
        -monitor "unix:$mon,server,nowait" 2>"$WORK/$NAME.stderr" &
    local pid=$!
    for ((i = 0; i < TIMEOUT; i++)); do
        sleep 1
        kill -0 $pid 2>/dev/null || break
        echo "screendump $WORK/$NAME.ppm" | nc -w 3 -U "$mon" >/dev/null 2>&1
        sleep 0.5
        if python3 "$ROOT/scripts/check_screen.py" "$WORK/$NAME.ppm" 1280 800 ok \
                >/dev/null 2>&1; then
            ok=1
            break
        fi
    done
    kill $pid 2>/dev/null
    wait $pid 2>/dev/null
    check "boot completes without a serial port (screen, after ${i}s)" \
          "no finished boot on the screen after ${i}s (see $WORK/$NAME.ppm)" [ $ok = 1 ]
    check_screen ok 1280 800
}

# ps2_session: the USB keyboard test's lines, typed on the PS/2 keyboard
# (SERIAL_SCRIPT of the ps2 boot).
ps2_session() {
    local n=1 typed key
    prompt_wait $n 30
    for typed in "${USB_KEYBOARD_INPUT[@]}"; do
        for key in $typed; do
            echo "sendkey ${key/_1000/ 1000}" | nc -w 3 -U "$WORK/monitor.sock" >/dev/null 2>&1
            [[ "$key" == *_1000 ]] && sleep 1.2
        done
        n=$((n + 1))
        prompt_wait $n
    done
}

# ps2_test: a machine without a USB keyboard, like a laptop: QEMU's sendkey
# then reaches the PS/2 keyboard, which becomes kbd0. The same lines as on
# the USB keyboard: Shift and punctuation, Backspace, Ctrl-C, Caps Lock, a
# key held for a second (the keyboard repeats it itself; only RitterOS's own
# repeat may count). x86 only: ARM machines have no i8042.
ps2_test() {
    local image before=$failures saved="$QEMU_CMD" repeated
    image=$(make_image ps2 "")
    QEMU_CMD="${QEMU_CMD/ -device usb-kbd,bus=xhci.0,port=1.1.1/}"
    SERIAL_SCRIPT=ps2_session
    boot ps2 "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_CMD="$saved"
    expect "  kbd0:          PS/2 keyboard on the i8042 (I/O 0x60/0x64), IRQ 1 -> GSI 1 (IO APIC), vector 0x"
    expect_line "  input:         serial0 and kbd0"
    reject "USB keyboard on"
    expect_line "ritteros:/$ echo USB keyboard!"
    expect_line "USB keyboard!"                 # Shift and punctuation
    expect_line "x"                             # "xyz", 2 x Backspace
    expect_line "ritteros:/$ qw^C"
    expect_line "AB c"                          # Caps Lock on for "ab"
    repeated=$(grep -E "^x{4,}$" <<<"$TEXT" | head -1)
    check "a PS/2 key held for 1 s repeated: ${#repeated} characters (expected 8-30)" \
          "a PS/2 key held for 1 s gave '${repeated:-nothing}' (expected 8-30 x)" \
          test "${#repeated}" -ge 8 -a "${#repeated}" -le 30
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# sata_boot_session: a command in the shell of the SATA boot.
sata_boot_session() {
    prompt_wait 1 30
    serial_type "ls /system/$ARCH_NAME/bin\r"
    prompt_wait 2
}

# sata_boot_test: a machine without NVMe, the RitterOS image on a SATA disk
# (port 0 of the q35 machine's AHCI controller, boot index 0): the firmware
# boots from it, the kernel finds its system partition sata0p2 by the
# bootloader's GUID, all files verified through AHCI, the shell runs.
# x86 only: QEMU's ARM firmware has no AHCI driver and cannot boot from it.
sata_boot_test() {
    local image before=$failures saved="$QEMU_CMD" commands interrupts
    image=$(make_image sataboot "fswrite")
    QEMU_CMD="${QEMU_CMD/-drive if=none,id=disk0,format=raw,file=$DISK -device nvme,drive=disk0,serial=RITTEROS0001,bootindex=0/}"
    QEMU_EXTRA="-drive if=none,id=sata0,format=raw,file=$image
                -device ide-hd,drive=sata0,bus=ide.0,bootindex=0"
    SERIAL_SCRIPT=sata_boot_session
    boot sataboot "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    QEMU_EXTRA=
    QEMU_CMD="$saved"
    reject "NVMe controller"                # the machine has none
    expect "boot device:   PciRoot(0x0)/Pci(0x1f,0x2)/Sata(0x0,0xffff,0x0)/HD(1,GPT,$(guid ESP_GUID),0x800,0x20000)"
    expect "boot disk:     controller 00:1f.2 (8086:2922, class 01.06.01)"
    expect_line "  AHCI:          00:1f.2, version 1.0, ahci0, 6 port(s) of 6, 64-bit addressing"
    expect "interrupts: MSI, message 0x"
    expect_line "  sata0:         'QEMU HARDDISK' serial 'QM00001' firmware '2.5+' on ahci0 port 0 (1.5 Gbit/s)"
    expect_line "                 2097152 blocks of 512 bytes (1024 MiB), rotation unknown, 48-bit addresses, TRIM"
    # The write test on the SATA disk: TRIM through DATA SET MANAGEMENT.
    expect "write test:    done"
    local trimmed host
    trimmed=$(sed -n 's/.*write test: *TRIM: \([0-9][0-9]*\) blocks freed by the commits reported to sata0p2.*/\1/p' <<<"$TEXT")
    check "SATA TRIM: $trimmed freed blocks reported to the disk" \
          "SATA TRIM: '${trimmed:-?}' blocks reported (expected some)" test "${trimmed:-0}" -gt 0
    host=$($RFS check "$image" $RFS_PART | tail -1)
    check "host check of the SATA disk after the writes: $host" "host check: $host" \
          eval '[[ "$host" == *"all checksums ok, bitmap consistent" ]]'
    expect "GPT:           sata0: protective MBR, disk GUID $(guid DISK_GUID)"
    expect_line "  system partition: sata0p2, where the bootloader found the kernel"
    expect "all checksums ok (both copies), bitmap consistent"
    expect "RitterFS files: 309 verified against /test/manifest.txt (3384 KiB): all match"
    expect_line "  login:         /system/$ARCH_NAME/bin/login, process 1"
    compare "ls /system/$ARCH_NAME/bin vs host" \
            "$($RFS ls "$image" $RFS_PART /system/$ARCH_NAME/bin)" \
            "$(command_output "ls /system/$ARCH_NAME/bin")"
    # One command at a time, each ends with an interrupt (MSI).
    read -r commands interrupts <<<"$(sed -n 's/.*ahci0: *\([0-9][0-9]*\) commands, \([0-9][0-9]*\) interrupts.*/\1 \2/p' <<<"$TEXT")"
    check "AHCI: $commands commands, $interrupts interrupts" \
          "AHCI: '${commands:-?}' commands, '${interrupts:-?}' interrupts (expected 1000+ and as many interrupts)" \
          eval '[ "${commands:-0}" -ge 1000 ] && [ "${interrupts:-0}" -ge "$commands" ]'
    reject "failed (status"
    reject "timed out (status"
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# sata_disk_test: two SATA disks (fresh RitterOS images) next to the NVMe
# boot disk: x86 on the q35 machine's built-in AHCI controller, ARM on an
# ich9-ahci card. The kernel reads their GPT, checks their RitterFS, and
# "satadisktest" writes a test pattern and a boot record at the end of each,
# which the host then finds in the disk files.
sata_disk_test() {
    local image disk1 disk2 before records seed on_disk bus1 bus2
    image=$(make_image ${P}satadisk "satadisktest")
    disk1=$(make_image ${P}satadisk1 "")
    disk2=$(make_image ${P}satadisk2 "")
    if [ "$ARCH_NAME" = aarch64 ]; then
        bus1="-device ich9-ahci,id=ahci -device ide-hd,drive=d1,bus=ahci.0"
        bus2="-device ide-hd,drive=d2,bus=ahci.1"
    else
        bus1="-device ide-hd,drive=d1,bus=ide.0"
        bus2="-device ide-hd,drive=d2,bus=ide.1"
    fi
    QEMU_EXTRA="-drive if=none,id=d1,format=raw,file=$disk1 $bus1
                -drive if=none,id=d2,format=raw,file=$disk2 $bus2"
    before=$failures
    boot ${P}satadisk "$image" "RitterOS kernel: boot complete"
    QEMU_EXTRA=
    expect "interrupts: MSI, message 0x"
    expect_line "  sata0:         'QEMU HARDDISK' serial 'QM00001' firmware '2.5+' on ahci0 port 0 (1.5 Gbit/s)"
    expect_line "  sata1:         'QEMU HARDDISK' serial 'QM00003' firmware '2.5+' on ahci0 port 1 (1.5 Gbit/s)"
    expect "GPT:           sata0: protective MBR, disk GUID $(guid DISK_GUID)"
    expect "GPT:           sata1: protective MBR, disk GUID $(guid DISK_GUID)"
    expect_line "  system partition: nvme0n1p2, where the bootloader found the kernel"
    expect_line "  system partition: sata0p2 has the same GPT GUID as nvme0n1p2 (a copied disk?); using nvme0n1p2"
    expect_line "  RitterOS partition: sata0p2, 1961984 blocks"
    expect_line "  RitterOS partition: sata1p2, 1961984 blocks"
    local checks
    checks=$(grep -c "all checksums ok (both copies), bitmap consistent" <<<"$TEXT")
    check "RitterFS checked on the boot disk and both SATA disks: $checks" \
          "RitterFS checked $checks time(s), expected 3" test "$checks" = 3
    expect_line "  disk test:     sata0p2 (958 MiB), using LBA 1961855-1961983"
    expect_line "  disk test:     sata1p2 (958 MiB), using LBA 1961855-1961983"
    records=$(grep -c "wrote 64 KiB at LBA 1961855, flushed, read back: identical" <<<"$TEXT")
    check "both SATA disks: 64 KiB written, flushed, read back identical" \
          "write test passed on $records disk(s), expected 2" test "$records" = 2
    reject "failed (status"
    reject "timed out (status"
    reject "panic"
    # The host finds the boot records in the disk files.
    seed=$(sed -n 's/.*boot record #1 written: seed 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT" | head -1)
    on_disk=$(python3 - "$disk1" "$disk2" <<'PY'
import struct, sys
for path in sys.argv[1:]:
    with open(path, "rb") as f:
        f.seek(2095103 * 512)
        magic, number, seed = struct.unpack("<8sQQ", f.read(24))
    print(magic.decode("ascii", "replace"), number, "%016X" % seed)
PY
)
    check "both SATA disk files hold boot record #1 with seed $seed" \
          "disk files hold '$(tr '\n' '|' <<<"$on_disk")', expected 'RTROSREC 1 $seed' twice" \
          test -n "$seed" -a "$on_disk" = "RTROSREC 1 $seed"$'\n'"RTROSREC 1 $seed"
    show_log_on_failure $before
}

# usb_hotplug_session: devices plugged in and out through QEMU's monitor
# while the shell runs (SERIAL_SCRIPT of the usbhotplug boot).
usb_hotplug_session() {
    local key mon="$WORK/monitor.sock" stick="$WORK/${P}hotstick.img"
    # QEMU's answers are kept: a refused command shows there.
    monitor() { echo "$1" | nc -w 3 -U "$mon" >>"$WORK/${NAME}-monitor.txt" 2>&1; }
    # Several commands over one connection, a pause after each: separate
    # connections in quick succession can stall QEMU's monitor (it takes
    # one client at a time; seen at drive_add and device_add after 45b).
    monitors() {
        local c
        for c in "$@"; do echo "$c"; sleep 0.5; done | nc -w 3 -U "$mon" >>"$WORK/${NAME}-monitor.txt" 2>&1
    }
    prompt_wait 1 30
    # A keyboard without a serial number on bus port 3 (xHCI port 7): typed
    # on, unplugged, then plugged into bus port 4 (xHCI port 8).
    monitor "device_add usb-kbd,bus=xhci.0,port=3,id=hotkbd,serial="
    serial_wait "USB keyboard on usb0 port 7" 1 10
    for key in e c h o spc h o t ret; do
        monitor "sendkey $key"
    done
    prompt_wait 2
    monitor "device_del hotkbd"
    serial_wait "removed (its name stays reserved)" 1 10
    monitor "device_add usb-kbd,bus=xhci.0,port=4,id=hotkbd2,serial="
    serial_wait "USB keyboard on usb0 port 8" 1 10
    # A stick with a serial number: plugged in on bus port 2, unplugged,
    # plugged in again on bus port 3 (another socket; port 1 has the hubs).
    monitors "drive_add 0 if=none,id=hotdisk,file=$stick,format=raw" \
             "device_add usb-storage,bus=xhci.0,port=2,drive=hotdisk,id=hotstick,serial=RITTERSTICK1"
    serial_wait "all checksums ok (both copies), bitmap consistent" 2 20
    monitor "device_del hotstick"
    serial_wait "removed (its name stays reserved)" 2 10      # the keyboard, then the stick
    # A copy of the image file: QEMU may still hold the first one's lock.
    monitors "drive_add 0 if=none,id=hotdisk2,file=$stick.2,format=raw" \
             "device_add usb-storage,bus=xhci.0,port=3,drive=hotdisk2,id=hotstick2,serial=RITTERSTICK1"
    serial_wait "all checksums ok (both copies), bitmap consistent" 3 20
    serial_type 'usb\r'
    prompt_wait 3
}

# usb_hotplug_test: USB devices plugged in and unplugged while RitterOS
# runs. New devices get the next name, devices plugged in again their old
# one (devname.c): a keyboard without serial number by its IDs, in another
# socket; a stick by its serial number, in another socket.
usb_hotplug_test() {
    local image before=$failures kbd
    image=$(make_image ${P}usbhotplug "")
    rm -f "$WORK/${P}hotstick.img" "$WORK/${P}hotstick.img.2" "$WORK/${P}usbhotplug-monitor.txt"
    cp "$(make_image ${P}hotstick "")" "$WORK/${P}hotstick.img"
    cp "$WORK/${P}hotstick.img" "$WORK/${P}hotstick.img.2"
    [ "$ARCH_NAME" = x86_64 ] && kbd=kbd2 || kbd=kbd1     # x86 also has PS/2 (kbd1)
    SERIAL_SCRIPT=usb_hotplug_session
    boot ${P}usbhotplug "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    # Devices plugged in at the prompt log right after it, on its line.
    expect "  usb0 port 7:   USB 2 device connected, port reset, high speed (480 Mbit/s)"
    expect_line "  $kbd:          USB keyboard on usb0 port 7, boot protocol, reports from endpoint 0x81, US layout"
    expect_line "hot"                               # typed on the new keyboard
    expect "  usb0 port 7:   device disconnected (QEMU USB Keyboard)"
    expect_line "  $kbd:          removed (its name stays reserved)"
    expect_line "  $kbd:          USB keyboard on usb0 port 8, boot protocol, reports from endpoint 0x81, US layout"
    expect_line "  usbdisk0:      'QEMU' 'QEMU HARDDISK' rev 2.5+ on usb0 port 2, 2097152 blocks of 512 bytes (1024 MiB), bulk-only, LUN 0 of 1"
    expect_line "  RitterOS partition: usbdisk0p2, 1961984 blocks"
    expect_line "  usb0 port 2:   device disconnected (QEMU USB HARDDRIVE)"
    expect_line "  usbdisk0:      removed (its name stays reserved)"
    expect_line "  usbdisk0:      'QEMU' 'QEMU HARDDISK' rev 2.5+ on usb0 port 3, 2097152 blocks of 512 bytes (1024 MiB), bulk-only, LUN 0 of 1, back again"
    reject "usbdisk1"
    # usb lists what is plugged in now: the two hubs, the boot keyboard,
    # the keyboard on port 8 and the stick on port 3.
    expect_line "5 USB device(s):"
    expect_line "    usb0 port 8      0627:0001  high speed (480 Mbit/s)  HID keyboard (boot interface), 'QEMU' 'QEMU USB Keyboard'"
    expect_line "    usb0 port 3      46f4:0001  SuperSpeed (5 Gbit/s)    mass storage (bulk-only), 'QEMU' 'QEMU USB HARDDRIVE'"
    reject "Disable Slot"
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# usb_hubplug_session: devices plugged in and out behind hubs (SERIAL_SCRIPT
# of the usbhubplug boot).
usb_hubplug_session() {
    local key mon="$WORK/monitor.sock" stick="$WORK/${P}hubstick.img"
    monitor() { echo "$1" | nc -w 3 -U "$mon" >>"$WORK/${NAME}-monitor.txt" 2>&1; }
    # Several commands over one connection, a pause after each: separate
    # connections in quick succession can stall QEMU's monitor (it takes
    # one client at a time; seen at drive_add and device_add after 45b).
    monitors() {
        local c
        for c in "$@"; do echo "$c"; sleep 0.5; done | nc -w 3 -U "$mon" >>"$WORK/${NAME}-monitor.txt" 2>&1
    }
    prompt_wait 1 30
    # A keyboard behind the first hub (bus port 1.2 = usb0 port 5.2).
    monitor "device_add usb-kbd,bus=xhci.0,port=1.2,id=hubkbd"
    serial_wait "USB keyboard on usb0 port 5.2" 1 10
    monitors "sendkey e" "sendkey c" "sendkey h" "sendkey o" "sendkey spc" "sendkey h" "sendkey u" \
             "sendkey b" "sendkey ret"
    prompt_wait 2
    monitor "device_del hubkbd"
    serial_wait "removed (its name stays reserved)" 1 10
    # A stick behind the same hub.
    monitors "drive_add 0 if=none,id=hubdisk,file=$stick,format=raw" \
             "device_add usb-storage,bus=xhci.0,port=1.3,drive=hubdisk,id=hubstick,serial=HUBSTICK"
    serial_wait "all checksums ok (both copies), bitmap consistent" 2 30
    monitor "device_del hubstick"
    serial_wait "removed (its name stays reserved)" 2 10
    # A hub plugged in, a keyboard behind it, then the whole hub unplugged.
    monitor "device_add usb-hub,bus=xhci.0,port=2,id=newhub"
    serial_wait "hub: 8 ports" 3 15             # two hubs at the boot, then this one
    monitor "device_add usb-kbd,bus=xhci.0,port=2.1,id=newhubkbd"
    serial_wait "USB keyboard on usb0 port 6.1" 1 10
    monitor "device_del newhub"
    serial_wait "device disconnected (QEMU USB Hub)" 1 10
    serial_type 'usb\r'
    prompt_wait 3
}

# usb_hubplug_test: hot plug behind hubs: the hub's status change endpoint
# reports the port, the usb thread attaches or detaches the device; a hub
# that goes takes everything behind it along (the device first).
usb_hubplug_test() {
    local image before=$failures kbd kbd2
    image=$(make_image ${P}usbhubplug "")
    rm -f "$WORK/${P}hubstick.img" "$WORK/${P}usbhubplug-monitor.txt"
    cp "$(make_image ${P}hubstick "")" "$WORK/${P}hubstick.img"
    if [ "$ARCH_NAME" = x86_64 ]; then kbd=kbd2 kbd2=kbd3; else kbd=kbd1 kbd2=kbd2; fi
    SERIAL_SCRIPT=usb_hubplug_session
    boot ${P}usbhubplug "$image" "RitterOS kernel: boot complete"
    SERIAL_SCRIPT=
    expect "  usb0 port 5.2: device connected (hub port 2), port reset, full speed (12 Mbit/s)"
    expect_line "  $kbd:          USB keyboard on usb0 port 5.2, boot protocol, reports from endpoint 0x81, US layout"
    expect_line "hub"                               # typed on the keyboard behind the hub
    expect "  usb0 port 5.2: device disconnected (QEMU USB Keyboard)"
    expect_line "  usbdisk0:      'QEMU' 'QEMU HARDDISK' rev 2.5+ on usb0 port 5.3, 2097152 blocks of 512 bytes (1024 MiB), bulk-only, LUN 0 of 1"
    expect_line "  RitterOS partition: usbdisk0p2, 1961984 blocks"
    expect "  usb0 port 5.3: device disconnected (QEMU USB HARDDRIVE)"
    expect "  usb0 port 6:   USB 2 device connected, port reset, full speed (12 Mbit/s)"
    expect_line "  $kbd2:          USB keyboard on usb0 port 6.1, boot protocol, reports from endpoint 0x81, US layout"
    # The hub goes: first the keyboard behind it, then the hub.
    local order
    order=$(grep -nE "usb0 port 6\.1: device disconnected|usb0 port 6: +device disconnected" <<<"$TEXT" | cut -d: -f1 | tr '\n' ' ' | sed 's/ $//')
    check "unplugging the hub: the keyboard behind it first, then the hub" \
          "unplugging the hub: disconnect lines at '${order:-none}'" \
          eval '[ "$(wc -w <<<"$order")" -eq 2 ] && [ "${order%% *}" -lt "${order##* }" ]'
    expect_line "3 USB device(s):"
    reject "Disable Slot"
    reject "panic"
    reject "RitterOS crash"
    show_log_on_failure $before
}

# usb_storage_test: two USB sticks, fresh RitterOS images: one on a USB 3
# port (SuperSpeed), one behind the first hub (full speed). The kernel reads
# their partitions and checks their RitterFS; "usbdisktest" writes a test
# pattern and a boot record at the end of each, which the host then finds
# in the image files.
usb_storage_test() {
    local image stick1 stick2 before records saved="$QEMU_CMD"
    image=$(make_image ${P}usbstorage "usbdisktest")
    stick1=$(make_image ${P}stick1 "")
    stick2=$(make_image ${P}stick2 "")
    # An xHCI controller without MSI or MSI-X: the driver polls.
    QEMU_CMD="${QEMU_CMD/-device qemu-xhci,id=xhci/-device qemu-xhci,id=xhci,msi=off,msix=off}"
    QEMU_EXTRA="-drive if=none,id=stick1,format=raw,file=$stick1
                -device usb-storage,bus=xhci.0,port=2,drive=stick1
                -drive if=none,id=stick2,format=raw,file=$stick2
                -device usb-storage,bus=xhci.0,port=1.2,drive=stick2
                -device ich9-usb-ehci1"
    before=$failures
    boot ${P}usbstorage "$image" "RitterOS kernel: boot complete"
    QEMU_EXTRA=
    QEMU_CMD="$saved"
    expect_line "                 interrupts: none (no MSI or MSI-X): events polled while waiting and every tick"
    # An Intel EHCI controller next to xHCI (as on real Intel PCs): taken
    # from the firmware and stopped, which QEMU's firmware does not use.
    expect "(8086:293a), USB 2 controller without a driver: not used by the firmware, stopped"
    expect_line "  usb0 port 2:   USB 3 device connected, SuperSpeed (5 Gbit/s)"
    expect_line "                 device 46f4:0001, USB 3.00, class 00 (see interfaces), version 0.00"
    expect_line "                 interface 0: mass storage (bulk-only), class 08.06.50, 2 endpoint(s)"
    expect_line "                     SuperSpeed companion: bursts of 16 packets"
    expect_line "  usb0 port 5.2: device connected (hub port 2), port reset, full speed (12 Mbit/s)"
    expect_line "  usbdisk0:      'QEMU' 'QEMU HARDDISK' rev 2.5+ on usb0 port 2, 2097152 blocks of 512 bytes (1024 MiB), bulk-only, LUN 0 of 1"
    expect_line "  usbdisk1:      'QEMU' 'QEMU HARDDISK' rev 2.5+ on usb0 port 5.2, 2097152 blocks of 512 bytes (1024 MiB), bulk-only, LUN 0 of 1"
    expect "GPT:           usbdisk0: protective MBR, disk GUID $(guid DISK_GUID)"
    expect "GPT:           usbdisk1: protective MBR, disk GUID $(guid DISK_GUID)"
    expect_line "  RitterOS partition: usbdisk0p2, 1961984 blocks"
    expect_line "  RitterOS partition: usbdisk1p2, 1961984 blocks"
    # The sticks are copies of the boot disk: same partition GUID. The
    # disk on the controller the firmware booted from (NVMe) wins.
    expect_line "  system partition: nvme0n1p2, where the bootloader found the kernel"
    expect_line "  system partition: usbdisk0p2 has the same GPT GUID as nvme0n1p2 (a copied disk?); using nvme0n1p2"
    expect_line "  system partition: usbdisk1p2 has the same GPT GUID as nvme0n1p2 (a copied disk?); using nvme0n1p2"
    expect "  RitterFS:      usbdisk0p2 'RitterOS'"
    expect "  RitterFS:      usbdisk1p2 'RitterOS'"
    # The full check of the boot disk and of both sticks, every block read.
    local checks
    checks=$(grep -c "all checksums ok (both copies), bitmap consistent" <<<"$TEXT")
    check "RitterFS checked on the boot disk and both sticks: $checks" \
          "RitterFS checked $checks time(s), expected 3" test "$checks" = 3
    expect_line "  disk test:     usbdisk0p2 (958 MiB), using LBA 1961855-1961983"
    expect_line "  disk test:     usbdisk1p2 (958 MiB), using LBA 1961855-1961983"
    records=$(grep -c "wrote 64 KiB at LBA 1961855, flushed, read back: identical" <<<"$TEXT")
    check "both sticks: 64 KiB written, flushed, read back identical" \
          "write test passed on $records stick(s), expected 2" test "$records" = 2
    reject "failed (sense key"
    reject "panic"
    # The host finds the boot records in the stick files.
    local seed on_disk
    seed=$(sed -n 's/.*boot record #1 written: seed 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT" | head -1)
    on_disk=$(python3 - "$stick1" "$stick2" <<'PY'
import struct, sys
for path in sys.argv[1:]:
    with open(path, "rb") as f:
        f.seek(2095103 * 512)
        magic, number, seed = struct.unpack("<8sQQ", f.read(24))
    print(magic.decode("ascii", "replace"), number, "%016X" % seed)
PY
)
    check "both stick files hold boot record #1 with seed $seed" \
          "stick files hold '$(tr '\n' '|' <<<"$on_disk")', expected 'RTROSREC 1 $seed' twice" \
          test -n "$seed" -a "$on_disk" = "RTROSREC 1 $seed"$'\n'"RTROSREC 1 $seed"
    show_log_on_failure $before
}

# expect_mkdisk TEXT: mkdisk's last output ($out) ends with TEXT.
expect_mkdisk() {
    local want="$1"                 # eval runs inside check(), where $1 is another
    check "mkdisk: ...$want" "mkdisk says '$out', expected '...$want'" eval '[[ "$out" == *"$want" ]]'
}

# kernel_tests: section 8, the kernel file on RitterFS, for $ARCH_NAME.
kernel_tests() {
    local path="/system/$ARCH_NAME/kernel.elf" image before put out host block
    local changed="$WORK/${P}kernel-changed.elf"

    # --- 8. updating the kernel: the host installs a changed kernel file
    # (the same ELF file with bytes appended, which loading ignores) with one
    # copy-on-write commit; the bootloader must load it from generation 2.
    image=$(make_image ${P}kupdate "")
    { cat "build/system/$ARCH_NAME/kernel.elf"; echo "RitterOS update test"; } >"$changed"
    put=$($RFS put "$image" $RFS_PART "$path" "$changed")
    before=$failures
    boot ${P}kupdate "$image" "RitterOS kernel: boot complete"
    check "host installed the changed kernel: $(tr '\n' ' ' <<<"$put")" \
          "host put says: $(tr '\n' '|' <<<"$put")" \
          eval '[[ "$put" == "$path: written"*"generation 2 (slot A)"*"all checksums ok, bitmap consistent" ]]'
    kernel_file_checks "$image"
    expect "kernel file:   $path on RitterFS, $(wc -c <"$changed" | tr -d ' ') bytes, file system generation 2"
    expect "all checksums ok (both copies), bitmap consistent"
    expect "RitterOS kernel: boot complete"
    reject "problem:"
    reject "panic"
    show_log_on_failure $before
    # mkdisk (as run by make) puts the built kernel back, and only once.
    out=$(python3 scripts/mkdisk.py --arch $ARCH_NAME "$image" "$WORK/esp-${P}kupdate" build/system)
    expect_mkdisk "RitterFS kept, installed $path (generation 3)"
    out=$(python3 scripts/mkdisk.py --arch $ARCH_NAME "$image" "$WORK/esp-${P}kupdate" build/system)
    expect_mkdisk "RitterFS kept, /system up to date"
    host=$($RFS check "$image" $RFS_PART)
    check "host check after the reinstall: ${host#RitterFS check: }" "host check: $host" \
          eval '[[ "$host" == *"generation 3 (slot B)"*"all checksums ok, bitmap consistent" ]] &&
                $RFS cat "$image" $RFS_PART "$path" | cmp -s - "build/system/$ARCH_NAME/kernel.elf"'

    # A RitterFS without /system: the bootloader stops and says why.
    mkdir -p "$WORK/no-system"
    image=$(make_image ${P}knone "" "$WORK/no-system")
    before=$failures
    boot ${P}knone "$image" "ERROR:"
    expect_line "RitterFS:  partition #2 of the boot disk, 'RitterOS', generation 1 (slot B)"
    expect "Kernel:    $path: file not found"
    expect "ERROR: Reading the kernel failed, status 0x800000000000000E"
    reject "RitterOS kernel started"
    show_log_on_failure $before

    # A damaged block of the kernel file (data is stored once): the bootloader
    # refuses to start a kernel that is not exactly what was written.
    image=$(make_image ${P}kdamage "")
    block=$(python3 - "$image" "$path" <<'PY'
import sys
sys.path.insert(0, "scripts")
import ritterfs as r
with open(sys.argv[1], "r+b") as f:
    part = r.Partition(f, 133120, 1961984)
    oid, inode = r.Reader(part).lookup(sys.argv[2])
    ptr = inode.root                                    # down the tree to data block 7
    for level in range(inode.height, 0, -1):
        i = (7 >> (7 * (level - 1))) & 127
        ptr = r.Pointer.unpack(part.read(ptr.address)[i * 32:(i + 1) * 32])
    block = ptr.address
    data = bytearray(part.read(block))
    data[100] ^= 0x01                                   # one bit
    part.write(block, bytes(data))
print(oid, block)
PY
)
    before=$failures
    boot ${P}kdamage "$image" "ERROR:"
    expect "Kernel:    $path: a block of the file is damaged (checksum) or unreadable"
    expect "ERROR: Reading the kernel failed, status 0x800000000000001B"
    reject "RitterOS kernel started"
    host=$(host_errors "$image")
    check "host finds the same damage: object ${block% *} block 7 (disk block ${block#* })" \
          "host says: $(tr '\n' '|' <<<"$host")" \
          eval 'grep -q "^object ${block% *} block 7: copy at block ${block#* } has a bad checksum" <<<"$host"'
    show_log_on_failure $before
}

# --- 9. crash tests --------------------------------------------------------------

# crash KIND EXPECTED...: boot with crash=KIND in a smaller screen mode than
# the firmware's ($FIRMWARE_MODE) and check the report.
crash() {
    local kind="$1"
    shift
    local image
    image=$(make_image "${P}crash-$kind" "crash=$kind video=1024x768")

    before=$failures
    boot "${P}crash-$kind" "$image" "System halted."
    expect "command line:  crash=$kind video=1024x768"
    expect "firmware mode $FIRMWARE_MODE, using 1024x768 (video=)"
    for s in "$@"; do
        expect "$s"
    done
    expect "System halted."
    reject "no exception happened"
    check_screen crash 1024 768
    show_log_on_failure $before
}

# The crash tests shared by both architectures: double frees and a heap
# overflow, found by the kernel's own checks.
software_crashes() {
    crash doublefree "=== RitterOS panic: pmm: double free of page 0x"
    crash heapdouble "=== RitterOS panic: heap: double free of 0xFFFF8"
    crash heapoverflow "=== RitterOS panic: heap: corrupted free slot 0xFFFF8"
    crash spinlock "=== RitterOS panic: spinlock 'crash test' taken twice (deadlock)"   # (65a-2)
    crash locksleep "=== RitterOS panic: mutex 'crash test' taken while holding spinlock 'crash test' (1 held, thread 'main') ==="   # (65a-5)
    crash lockorder "=== RitterOS panic: lock order: 'crash A' taken while holding 'crash B', but 'crash B' was taken while holding 'crash A' before ==="
}

