      "/system/x86_64/kernel.elf on the disk differs from build/system/x86_64/kernel.elf" \
      eval '$RFS cat "$DISK" $RFS_PART /system/x86_64/kernel.elf | cmp -s - build/system/x86_64/kernel.elf'
expect "3 segments, "
expect "virtual 0xFFFFFFFF80000000"
expect "Paging:    direct map of 0-0x17FFFFFFF at 0xFFFF800000000000"
expect "Cmdline:   selftest"
expect "RitterOS boot: exited boot services"
expect "RitterOS boot: runtime services moved to 0xFFFF8"
expect "firmware calls: own tables, physical memory also at 0 - 0x"
expect "(checked)"
reject "(WRONG)"
expect "RitterOS boot: switching to the kernel's page tables, jumping to 0xFFFFFFFF80000000"
expect "kernel image:  0xFFFFFFFF80000000 - "
expect "RitterOS kernel started"
expect "RitterOS cs=0x0008 ds=0x0010 ss=0x0010 tr=0x0028, GDT at 0xFFFFFFFF80"
expect "256 vectors: exceptions 0-31, interrupts 32-255"
expect "paging:        CR3 0x"
expect "kernel 0xFFFFFFFF80000000 - 0xFFFFFFFF8"
expect "direct map 0xFFFF800000000000 - 0xFFFF80017FFFFFFF (physical 0 - 0x000000017FFFFFFF)"
expect "lower half     0x0000000000100000  not mapped"
expect "framebuffer    0xFFFF800080000000  read write -, 2 MiB page, physical 0x0000000080000000"
expect "NX on"
expect "NULL page      0x0000000000000000  not mapped"
expect "kernel code    0xFFFFFFFF80000000  read - execute, 4 KiB page"
expect "kernel rodata  0xFFFFFFFF80"
expect "stack guard    0xFFFFFFFF80"
expect "RitterOS: breakpoint (#BP) at RIP 0xFFFFFFFF80"
expect "APIC:          Local APIC 0x00000000FEE00000 (id 0, version 0x14), 2 core(s), 8259 PICs masked"   # (65c-2: two cores)
expect "(bus / 16, measured with the PIT), vector 0x20 every"
expect "time stamp counter "; expect " MHz (measured with the PIT)"
# The q35 machine's AHCI controller, no disks; its empty CD drive is skipped.
expect_line "  AHCI:          00:1f.2, version 1.0, ahci0, 6 port(s) of 6, 64-bit addressing"
expect_line "  ahci0 port 2:  1.5 Gbit/s, CD/DVD drive (ATAPI) (not supported)"
expect_line "  ahci0:         0 commands, 0 interrupts"
expect "Graphics:  30 modes, firmware mode 1280x800, using it (native)"
expect "framebuffer:   1280x800"
expect "boot device:   PciRoot(0x0)/Pci(0x2,0x0)/NVMe(0x1,"
expect "system:      QEMU Standard PC (Q35 + ICH9, 2009)"
# PCI scan: the q35 chipset, the VGA framebuffer BAR, the NVMe boot disk, USB.
expect "PCI:           ECAM 0x00000000E0000000, buses 0-255, 8 devices"
expect "00:00.0 8086:29c0  host bridge"
expect "00:01.0 1234:1111  VGA display controller"
expect "BAR0 mem32 0x80000000, 16384 KiB, prefetchable"
expect "00:02.0 1b36:0010  NVMe controller"
expect "00:03.0 1af4:1005  unclassified device      Red Hat (virtio)"
expect "00:1f.2 8086:2922  SATA controller (AHCI)"
expect "00:04.0 1b36:000d  USB controller           Red Hat (QEMU)"
# (64t) The processor's clock setting, not used on QEMU; (37e-1b) a new
# disk has no settings files: the defaults, then the kernel writes its files.
expect "cpu:           clock = performance (the default: no /system/config/cpu): not used, this processor's clock is the firmware's"
expect_line "  settings:      missing, written with their defaults: cpu, power, displays, swap (/system/config)"
expect "xHCI:          00:04.0, version 1.00, registers 0xFFFF80"
# xHCI's vector: after the serial port (0x30), ACPI's SCI (0x31, 37c-2), NVMe
# (0x32) and AHCI (0x33).
expect "interrupts: MSI-X entry 0 of 16, message 0x34 to 0x00000000FEE00000"
expect "  user mode:     ring 3; system calls by SYSCALL, entry 0xFFFFFFFF80"
expect "; FP/SIMD: x87 and SSE (FXSAVE, 512 bytes per program)"
expect "boot disk:     controller 00:02.0 (1b36:0010, class 01.08.02)"
expect "NVMe:          00:02.0, version 1."
expect "IO APIC 0x00000000FEC00000 (id 0), 24 inputs from GSI 0, all masked"
expect "serial0:       16550 UART COM1 at I/O 0x3f8, IRQ 4 -> GSI 4 (IO APIC), vector 0x30: receiving"
expect "interrupts: MSI-X entry 0 of 65, message 0x32 to 0x00000000FEE00000"
# The i8042 also has a PS/2 mouse on port 2 (QEMU's q35 always does).
expect "PS/2 mouse on the i8042 (port 2) with a wheel, IRQ 12 -> GSI 12 (IO APIC)"
terminal_checks x86_64 1280 800 "$image"
boot_checks "$WORK/normal-before.img"
check_screen ok 1280 800
seed_normal=$(sed -n 's/.*random seed: .* begins 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
uptime_normal=$(sed -n 's/^  uptime: *\([0-9][0-9]*\.[0-9][0-9]\) s since the timer started.*/\1/p' <<<"$TEXT")
python3 "$ROOT/scripts/ppm2png.py" "$WORK/normal.ppm" "$ROOT/build/screen.png" 2>/dev/null
echo "      normal boot took ${BOOT_SECONDS}s, screenshot: build/screen.png"
show_log_on_failure $before
quick_boot_test "$uptime_normal"
edid_host_test                          # (65e-34: on the Mac, once)
atomhost_host_test                      # (37g-5a: on the Mac, once)
avxas_host_test                         # (32c: on the Mac, once)
neonas_host_test                        # (32f: on the Mac, once)
draw_host_test                          # (41b: on the Mac, once)
ttf_host_test                           # (41c: on the Mac, once)
pngenc_host_test                        # (41h-2: on the Mac, once)

power_test "rebooting: ACPI reset register, I/O port 0xcf9 = 0x0f" \
           "powering off: ACPI S5, PM1a control port 0x604, sleep type 0"
power_button_test                       # (37c-2a)
cstates_test                            # (37d)
screen_off_test                         # (37e)
no_serial_test
ps2_test
ps2mouse_test
sata_boot_test
programs_test "page fault (access not allowed, write)" \
              "CPU exception 13, general protection fault (#GP)" 11
disk_tests

FIRMWARE_MODE=1280x800
crash ud "CPU exception 6, invalid opcode (#UD)"
crash de "CPU exception 0, divide error (#DE)"
crash gp "CPU exception 13, general protection fault (#GP)" \
         "error code 0x0428: GDT entry 133"     # (65c: 5 slots + a TSS per core, 64 cores)
crash pf "CPU exception 14, page fault (#PF)" \
         "error code 0x0002: page not present, write, kernel mode" \
         "fault address (CR2) 0x0000700000001000"
crash df "CPU exception 8, double fault (#DF)" \
         "RSP    0x0000700000002000"
# The double-fault handler must run on the IST1 stack: [top - 16 KiB, top).
df_top=$(sed -n 's/.*#DF stack 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
df_rsp=$(sed -n 's/.*handler running on stack 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
check "handler stack 0x$df_rsp is inside the IST1 stack (top 0x$df_top)" \
      "handler stack 0x${df_rsp:-?} not inside the IST1 stack (top 0x${df_top:-?})" \
      eval '[ -n "$df_top" ] && [ -n "$df_rsp" ] &&
            (( 16#$df_rsp < 16#$df_top && 16#$df_rsp >= 16#$df_top - 16384 ))'

crash null "CPU exception 14, page fault (#PF)" \
           "error code 0x0000: page not present, read, kernel mode" \
           "fault address (CR2) 0x0000000000000000"
crash wp "CPU exception 14, page fault (#PF)" \
         "error code 0x0003: protection violation, write, kernel mode"
crash nx "CPU exception 14, page fault (#PF)" \
         "error code 0x0011: protection violation, read (instruction fetch), kernel mode"
crash stack "CPU exception 8, double fault (#DF)"
# A stack overflow must end in the guard page: CR2 in [guard, guard + 4 KiB).
guard=$(sed -n 's/.*guard page at 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
cr2=$(sed -n 's/.*last page fault address (CR2) 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
check "overflow hit the guard page (CR2 0x$cr2, guard 0x$guard)" \
      "CR2 0x${cr2:-?} not in the guard page at 0x${guard:-?}" \
      eval '[ -n "$guard" ] && [ -n "$cr2" ] && (( 16#$cr2 >= 16#$guard && 16#$cr2 < 16#$guard + 4096 ))'
software_crashes

}

