screen_off_test                         # (37e)
programs_test "data abort (EC 0x24), protection violation (permission fault, level 3), write" \
              "undefined instruction (EC 0x00)" 4
disk_tests

FIRMWARE_MODE=800x600
crash ud "CPU exception, undefined instruction (EC 0x00, synchronous)"
crash align "CPU exception, data abort (EC 0x25, synchronous)" \
            "alignment fault, read"
crash pc "CPU exception, PC alignment fault (EC 0x22, synchronous)" \
         "instruction address not a multiple of 4"
# The PC that faulted is the misaligned one (2 mod 4; the last hex digit is
# enough, and bash arithmetic would see the full address as negative).
pc=$(sed -n 's/^  PC     0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
check "faulting PC 0x$pc is 2 mod 4" "faulting PC 0x${pc:-?} should be 2 mod 4" \
      eval '[ -n "$pc" ] && (( 16#${pc: -1} % 4 == 2 ))'
crash sp "CPU exception, SP alignment fault (EC 0x26, synchronous)"
crash pf "CPU exception, data abort (EC 0x25, synchronous)" \
         "page not present (translation fault, level 0), write" \
         "fault address (FAR) 0x0000700000001000"
crash null "CPU exception, data abort (EC 0x25, synchronous)" \
           "page not present (translation fault, level 0), read" \
           "fault address (FAR) 0x0000000000000000"
crash wp "CPU exception, data abort (EC 0x25, synchronous)" \
         "protection violation (permission fault, level 3), write"
crash nx "CPU exception, instruction abort (EC 0x21, synchronous)" \
         "protection violation (permission fault, level 3), instruction fetch"
crash stack "CPU exception, data abort (EC 0x25, synchronous)" \
            "page not present (translation fault, level 3), write"
# The overflow must hit the guard page and be handled on the exception stack.
guard=$(sed -n 's/.*guard page at 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
far=$(sed -n 's/.*fault address (FAR) 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
read -r est_lo est_hi <<<"$(sed -n 's/.*exception stack SP_EL1 0x\([0-9A-F]*\) - 0x\([0-9A-F]*\).*/\1 \2/p' <<<"$TEXT")"
handler=$(sed -n 's/.*handler running on stack 0x\([0-9A-F]*\).*/\1/p' <<<"$TEXT")
check "overflow hit the guard page (FAR 0x$far), handled on the exception stack (0x$handler)" \
      "FAR 0x${far:-?}, guard 0x${guard:-?}, handler stack 0x${handler:-?}" \
      eval '[ -n "$guard" ] && [ -n "$far" ] && [ -n "$handler" ] && [ -n "$est_lo" ] &&
            (( 16#$far >= 16#$guard && 16#$far < 16#$guard + 4096 )) &&
            (( 16#$handler >= 16#$est_lo && 16#$handler <= 16#$est_hi ))'
software_crashes

# A USB HID mouse (deterministic here: ARM virt has no i8042 PS/2 mouse).
mouse_usb_test

}

# ==================================================================================
# The halves: one (TEST_ARCH=x86 or arm), or both side by side
# ==================================================================================

# half x86|arm: run one half's tests; its time, the slowest boots, and its
# result (the last line: "<arch>: N failure(s)" or "<arch>: all checks
# passed"). Exit status 0 if all passed.
half() {
    arch_setup "$1"
    rm -f "$WORK/times.txt"
    local start=$(date +%s)
    "$1_tests"
    echo "      $ARCH_NAME: $(($(date +%s) - start)) s; the slowest boots:"
    sort -rn "$WORK/times.txt" 2>/dev/null | head -10 | awk '{printf "        %4d s  %s\n", $1, $2}'
    if [ $failures -ne 0 ]; then
        echo "$ARCH_NAME: $failures check(s) failed."
        return 1
    fi
    echo "$ARCH_NAME: all checks passed."
}

if [ -n "${ONLY:-}" ]; then
    # Dev only: run one test function on one architecture (ONLY=name
    # ONLY_ARCH=x86|arm make test; a function that takes arguments with
    # them: ONLY='programs_test "a" "b" 11'). Not used by a normal run; the
    # complete both-arch run below validates the real path.
    arch_setup "${ONLY_ARCH:-x86}"
    eval "$ONLY"
    if [ $failures -ne 0 ]; then
        echo "$ONLY: $failures check(s) failed."
        exit 1
    fi
    echo "$ONLY ($ARCH_NAME): all checks passed."
elif [ "$TEST_ARCH" = both ]; then
    mkdir -p "$ROOT/build/test"
    # (an old half's output must never stand in for this run's: 55a's change
    # left "$DISK" here, the halves never started, and the old files were shown)
    rm -f "$ROOT/build/test/x86_64.out" "$ROOT/build/test/aarch64.out"
    start=$(date +%s)
    TEST_ARCH=x86 bash "$0" "$QEMU_X86" "$QEMU_ARM" "$DISK_X86" "$DISK_ARM" >"$ROOT/build/test/x86_64.out" 2>&1 &
    x86=$!
    TEST_ARCH=arm bash "$0" "$QEMU_X86" "$QEMU_ARM" "$DISK_X86" "$DISK_ARM" >"$ROOT/build/test/aarch64.out" 2>&1 &
    arm=$!
    wait $x86
    x86_status=$?
    wait $arm
    arm_status=$?
    cat "$ROOT/build/test/x86_64.out" "$ROOT/build/test/aarch64.out"
    echo "      both halves: $(($(date +%s) - start)) s"
    if [ $x86_status -ne 0 ] || [ $arm_status -ne 0 ]; then
        failed=$(cat "$ROOT/build/test/x86_64.out" "$ROOT/build/test/aarch64.out" |
                 sed -n 's/^[a-z0-9_]*: \([0-9][0-9]*\) check(s) failed\.$/\1/p' | awk '{n += $1} END {print n + 0}')
        if [ "$failed" -eq 0 ]; then
            echo "A half ended early (x86_64: exit $x86_status, aarch64: exit $arm_status)."
        else
            echo "$failed check(s) failed."
        fi
        exit 1
    fi
    echo "All checks passed."
else
    half "$TEST_ARCH" || exit 1
fi
